IN_STRICT = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "strict_zn_transfer_holdout.csv"
IN_P8_RANKING = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase8_Benchmark" / "cv_model_ranking.csv"
IN_P8_SUMMARY = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase8_Benchmark" / "cv_model_summary.csv"
IN_P8_PRIMARY = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase8_Benchmark" / "primary_group_test_metrics.csv"
IN_P8_STRICT = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase8_Benchmark" / "strict_zn_transfer_metrics.csv"

MODELS_DIR = PROJECT_ROOT / "04_Models" / "Tuned"
METRICS_DIR = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase9_Tuning"
PRED_DIR = PROJECT_ROOT / "05_Results" / "Predictions" / "Phase9_Tuning"
FIG_DIR = PROJECT_ROOT / "06_Figures" / "Draft_Figures" / "Phase9_Tuning"

OUT_SEARCH_RESULTS = METRICS_DIR / "hyperparameter_search_results.csv"
OUT_BEST_PARAMS = METRICS_DIR / "best_hyperparameters.csv"
OUT_PRIMARY_METRICS = METRICS_DIR / "tuned_primary_group_test_metrics.csv"
OUT_STRICT_METRICS = METRICS_DIR / "tuned_strict_zn_transfer_metrics.csv"
