OUT_PRIMARY_PREDS = PRED_DIR / "tuned_primary_group_test_predictions.csv"
OUT_STRICT_PREDS = PRED_DIR / "tuned_strict_zn_transfer_predictions.csv"

# Fault-recovery checkpoints (written after every target x model block).
CHECKPOINT_SEARCH = METRICS_DIR / "checkpoint_search_results.csv"
CHECKPOINT_BEST = METRICS_DIR / "checkpoint_best_hyperparameters.csv"
CHECKPOINT_PRIMARY_METRICS = METRICS_DIR / "checkpoint_primary_metrics.csv"
CHECKPOINT_STRICT_METRICS = METRICS_DIR / "checkpoint_strict_metrics.csv"
CHECKPOINT_PRIMARY_PREDS = PRED_DIR / "checkpoint_primary_predictions.csv"
CHECKPOINT_STRICT_PREDS = PRED_DIR / "checkpoint_strict_predictions.csv"

TARGETS = ("average_voltage", "capacity_grav")

# Fixed candidate list derived from the Phase 8 CV baselines. This mapping is
# NOT influenced by primary-test or Zn-test results.
TARGET_MODELS: dict[str, list[str]] = {
    "average_voltage": ["SVR", "CatBoost", "XGBoost", "LightGBM"],
    "capacity_grav": ["CatBoost", "ExtraTrees", "XGBoost", "LightGBM"],
}

N_ITER = {
    "SVR": 40,
    "ExtraTrees": 40,
    "XGBoost": 50,
    "CatBoost": 50,
    "LightGBM": 50,
}

FORBIDDEN_IN_FEATURES = {
    "average_voltage",
    "capacity_grav",
    "capacity_vol",
    "energy_grav",
    "energy_vol",
}

TARGET_DIR_NAME = {"average_voltage": "Voltage", "capacity_grav": "Capacity"}


# ---------------------------------------------------------------------------
# Pipelines (same baseline structure as Phase 8; params searched below)
# ---------------------------------------------------------------------------
def _make_pipeline(name: str) -> Pipeline:
    if name == "SVR":
        model = SVR(kernel="rbf")
        steps = [
            ("imputer", SimpleImputer(strategy="median")),
            ("scaler", StandardScaler()),
            ("model", model),
        ]
    elif name == "ExtraTrees":
        # n_jobs=1: RandomizedSearchCV owns the parallelism (candidate level).
        model = ExtraTreesRegressor(random_state=42, n_jobs=1)
        steps = [("imputer", SimpleImputer(strategy="median")), ("model", model)]
    elif name == "XGBoost":
        model = XGBRegressor(
            objective="reg:squarederror", random_state=42, n_jobs=1
        )
        steps = [("imputer", SimpleImputer(strategy="median")), ("model", model)]
    elif name == "CatBoost":
        model = CatBoostRegressor(
            loss_function="RMSE",
            random_seed=42,
            verbose=False,
            allow_writing_files=False,
            thread_count=1,
        )
        steps = [("imputer", SimpleImputer(strategy="median")), ("model", model)]
    elif name == "LightGBM":
        model = LGBMRegressor(random_state=42, n_jobs=1, verbosity=-1)
        steps = [("imputer", SimpleImputer(strategy="median")), ("model", model)]
    else:
        raise ValueError(f"unknown model: {name}")
    return Pipeline(steps)


SEARCH_SPACES: dict[str, dict] = {
    "SVR": {
        "model__C": loguniform(1e-1, 1e3),
        "model__epsilon": loguniform(1e-3, 1.0),
        "model__gamma": loguniform(1e-4, 1.0),
    },
    "ExtraTrees": {
        "model__n_estimators": [300, 500, 800, 1000],
        "model__max_depth": [None, 8, 12, 16, 24, 32],
        "model__min_samples_split": [2, 4, 6, 10],
        "model__min_samples_leaf": [1, 2, 3, 5],
        "model__max_features": [1.0, "sqrt", 0.5, 0.75],
        "model__bootstrap": [False, True],
    },
    "XGBoost": {
        "model__n_estimators": [300, 500, 800, 1000],
        "model__learning_rate": loguniform(0.01, 0.2),
        "model__max_depth": [3, 4, 5, 6, 8, 10],
        "model__min_child_weight": [1, 2, 4, 6, 10],
        "model__subsample": uniform(0.6, 0.4),
        "model__colsample_bytree": uniform(0.6, 0.4),
        "model__reg_alpha": loguniform(1e-4, 10),
        "model__reg_lambda": loguniform(1e-2, 100),
    },
    "CatBoost": {
        "model__iterations": [300, 500, 800, 1000],
        "model__depth": [4, 5, 6, 7, 8, 10],
        "model__learning_rate": loguniform(0.01, 0.2),
        "model__l2_leaf_reg": loguniform(0.1, 30),
        "model__random_strength": loguniform(1e-3, 10),
        "model__bagging_temperature": uniform(0.0, 1.0),
    },
    "LightGBM": {
        "model__n_estimators": [300, 500, 800, 1000],
        "model__learning_rate": loguniform(0.01, 0.2),
        "model__num_leaves": [15, 31, 63, 127],
        "model__max_depth": [-1, 5, 8, 12, 16],
        "model__min_child_samples": [5, 10, 20, 30, 50],
        "model__subsample": uniform(0.6, 0.4),
        "model__subsample_freq": [1],
        "model__colsample_bytree": uniform(0.6, 0.4),
        "model__reg_alpha": loguniform(1e-4, 10),
        "model__reg_lambda": loguniform(1e-2, 100),
    },
}


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------
def log(message: str) -> None:
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S")
    print(f"[{stamp}Z] {message}", flush=True)


def package_version(name: str) -> str:
    try:
        return importlib.metadata.version(name)
    except importlib.metadata.PackageNotFoundError:
        return "not installed"


def sig6(value) -> float | None:
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
        return float(f"{float(value):.6g}")
    except (TypeError, ValueError):
        return None


def compute_metrics(y_true, y_pred) -> dict:
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    try:
        pearson = float(np.corrcoef(y_true, y_pred)[0, 1])
    except Exception:  # noqa: BLE001
        pearson = np.nan
    return {
        "R2": sig6(r2_score(y_true, y_pred)),
        "RMSE": sig6(float(np.sqrt(mean_squared_error(y_true, y_pred)))),
        "MAE": sig6(mean_absolute_error(y_true, y_pred)),
        "Pearson_r": sig6(pearson),
    }


def atomic_to_csv(df: pd.DataFrame, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    df.to_csv(tmp, index=False, encoding="utf-8-sig")
    os.replace(tmp, path)
    log(f"Saved {len(df)} rows -> {path}")


def save_figure(fig, path: Path) -> None:
    fig.tight_layout()
    fig.savefig(path.with_suffix(".png"), dpi=600)
    fig.savefig(path.with_suffix(".pdf"))
    plt.close(fig)
    log(f"  saved figure: {path.name}.png/.pdf")


def read_required(path: Path) -> pd.DataFrame:
    if not path.is_file():
        log(f"ERROR: required input file not found: {path}")
        sys.exit(1)
    return pd.read_csv(path, low_memory=False)


# ---------------------------------------------------------------------------
# Search driver
# ---------------------------------------------------------------------------
def run_search(target: str, model_name: str, X_train, y_train, cv):
    """RandomizedSearchCV on the frozen PredefinedSplit folds only."""
    n_iter = N_ITER[model_name]
    pipeline = _make_pipeline(model_name)
    search = RandomizedSearchCV(
        pipeline,
        SEARCH_SPACES[model_name],
        n_iter=n_iter,
        scoring="neg_root_mean_squared_error",
        cv=cv,
        random_state=42,
        refit=True,
        n_jobs=_SCIENCE_THREADS,
    )
    started = time.perf_counter()
    log(f"  [{target}] {model_name}: RandomizedSearchCV n_iter={n_iter} ...")
    search.fit(X_train, y_train)
    elapsed = time.perf_counter() - started
    log(f"  [{target}] {model_name}: best CV RMSE={-search.best_score_:.4f} ({elapsed:.1f}s)")

    cv_results = search.cv_results_
    result_rows = []
    for i in range(len(cv_results["params"])):
        result_rows.append(
            {
                "target": target,
                "model": model_name,
                "rank_test_score": int(cv_results["rank_test_score"][i]),
                "mean_test_score": sig6(cv_results["mean_test_score"][i]),
                "std_test_score": sig6(cv_results["std_test_score"][i]),
                "mean_fit_time": sig6(cv_results["mean_fit_time"][i]),
                "std_fit_time": sig6(cv_results["std_fit_time"][i]),
                "CV_RMSE": sig6(-cv_results["mean_test_score"][i]),
                "params": json.dumps(cv_results["params"][i], default=str),
            }
        )
    best_row = {
        "target": target,
        "model": model_name,
        "best_cv_RMSE": sig6(-search.best_score_),
        "best_params_json": json.dumps(search.best_params_, default=str),
        "n_iter": n_iter,
        "search_time_seconds": sig6(elapsed),
    }
    return search, result_rows, best_row


# ---------------------------------------------------------------------------
# Figures
# ---------------------------------------------------------------------------
def figure_grouped_bars(baseline: pd.DataFrame, tuned: pd.DataFrame,
                        models: list[str], target: str, path: Path,
                        metric_col: str, title: str, ylabel: str) -> None:
    fig, ax = plt.subplots(figsize=(10, 5.5))
    x = np.arange(len(models))
    width = 0.35
    base_vals = [baseline.loc[m, metric_col] for m in models]
    tuned_vals = [tuned.loc[m, metric_col] for m in models]
    ax.bar(x - width / 2, base_vals, width, label="Phase 8 baseline")
    ax.bar(x + width / 2, tuned_vals, width, label="Phase 9 tuned")
    for i, m in enumerate(models):
        ax.text(i, max(base_vals[i], tuned_vals[i]) + 0.002,
                f"{base_vals[i]:.3f}->{tuned_vals[i]:.3f}", ha="center", fontsize=8)
    ax.set_xticks(x)
    ax.set_xticklabels(models, rotation=30, ha="right")
    ax.set_ylabel(ylabel)
    ax.set_title(title)
    ax.legend()
    save_figure(fig, path)


def figure_tuned_parity(preds: pd.DataFrame, metrics: pd.DataFrame,
                        models: list[str], target: str, path: Path) -> None:
    fig, axes = plt.subplots(2, 2, figsize=(11, 10))
    for ax, model in zip(axes.ravel(), models):
        sub = preds[(preds["target"] == target) & (preds["model"] == model)]
        row = metrics[(metrics["target"] == target) & (metrics["model"] == model)].iloc[0]
        ax.scatter(sub["y_true"], sub["y_pred"], s=6, alpha=0.45)
        vmin = min(sub["y_true"].min(), sub["y_pred"].min())
        vmax = max(sub["y_true"].max(), sub["y_pred"].max())
        ax.plot([vmin, vmax], [vmin, vmax], "k--", lw=1)
        ax.set_title(
            f"{model}\\nR2={row['R2']:.3f}  RMSE={row['RMSE']:.3f}  MAE={row['MAE']:.3f}",
            fontsize=9,
        )
        ax.set_xlabel("y_true")
        ax.set_ylabel("y_pred")
    fig.suptitle(f"{target}: tuned models - primary group test parity", fontsize=14)
    save_figure(fig, path)


# ---------------------------------------------------------------------------
# Shared figure / summary builders (also used by --finalize-only; no fitting)
# ---------------------------------------------------------------------------
def generate_figures(primary_metrics: pd.DataFrame, strict_metrics: pd.DataFrame,
                     primary_preds: pd.DataFrame, best_df: pd.DataFrame,
                     p8_summary: pd.DataFrame, p8_primary: pd.DataFrame,
                     p8_strict: pd.DataFrame) -> None:
    """Regenerate all Phase 9 figures purely from result DataFrames."""
    FIG_DIR.mkdir(parents=True, exist_ok=True)
    log("generating figures ...")
    cv_baseline_map = {
        (row["target"], row["model"]): row["mean_RMSE"]
        for _, row in p8_summary.iterrows()
    }
    for target, tag, models in (
        ("average_voltage", "voltage", TARGET_MODELS["average_voltage"]),
        ("capacity_grav", "capacity", TARGET_MODELS["capacity_grav"]),
    ):
        base_cv = pd.Series({m: cv_baseline_map[(target, m)] for m in models})
        tuned_cv = pd.Series(
            {
                m: best_df[(best_df["target"] == target) & (best_df["model"] == m)]["best_cv_RMSE"].iloc[0]
                for m in models
            }
        )
        figure_grouped_bars(
            pd.DataFrame({"RMSE": base_cv}), pd.DataFrame({"RMSE": tuned_cv}),
            models, target,
            FIG_DIR / f"01_{tag}_cv_baseline_vs_tuned"
            if target == "average_voltage"
            else FIG_DIR / f"02_{tag}_cv_baseline_vs_tuned",
            "RMSE",
            f"{target}: CV RMSE baseline vs tuned (selection criterion)",
            "CV RMSE",
        )
        base_pr = pd.Series(
            {m: p8_primary[(p8_primary["target"] == target) & (p8_primary["model"] == m)]["RMSE"].iloc[0] for m in models}
        )
        tuned_pr = pd.Series(
            {m: primary_metrics[(primary_metrics["target"] == target) & (primary_metrics["model"] == m)]["RMSE"].iloc[0] for m in models}
        )
        figure_grouped_bars(
            pd.DataFrame({"RMSE": base_pr}), pd.DataFrame({"RMSE": tuned_pr}),
            models, target,
            FIG_DIR / f"03_{tag}_primary_baseline_vs_tuned"
            if target == "average_voltage"
            else FIG_DIR / f"04_{tag}_primary_baseline_vs_tuned",
            "RMSE",
            f"{target}: primary group test RMSE baseline vs tuned (evaluation only)",
            "primary test RMSE",
        )
        figure_tuned_parity(
            primary_preds, primary_metrics, models, target,
            FIG_DIR / f"05_{tag}_tuned_primary_parity"
            if target == "average_voltage"
            else FIG_DIR / f"06_{tag}_tuned_primary_parity",
        )
        base_st = pd.Series(
            {m: p8_strict[(p8_strict["target"] == target) & (p8_strict["model"] == m)]["RMSE"].iloc[0] for m in models}
        )
        tuned_st = pd.Series(
            {m: strict_metrics[(strict_metrics["target"] == target) & (strict_metrics["model"] == m)]["RMSE"].iloc[0] for m in models}
        )
        figure_grouped_bars(
            pd.DataFrame({"RMSE": base_st}), pd.DataFrame({"RMSE": tuned_st}),
            models, target,
            FIG_DIR / f"07_{tag}_strict_zn_baseline_vs_tuned"
            if target == "average_voltage"
            else FIG_DIR / f"08_{tag}_strict_zn_baseline_vs_tuned",
            "RMSE",
            f"{target}: strict Zn transfer RMSE baseline vs tuned (evaluation only)",
            "strict Zn RMSE",
        )


def write_summary(features: list[str], n_primary_train: int, n_primary_test: int,
                  n_strict_train: int, n_zn_test: int, best_df: pd.DataFrame,
                  comparison: pd.DataFrame, primary_metrics: pd.DataFrame,
                  strict_metrics: pd.DataFrame, ranking: pd.DataFrame,
                  elapsed: float, runtime_mode: str = "full") -> None:
    """Write phase9_tuning_summary.txt from result DataFrames (no fitting).

    runtime_mode="full": elapsed is the end-to-end Phase 9 wall time.
    runtime_mode="finalize_only": elapsed is only the finalization time;
    the true Phase 9 runtime is not claimed, only the recorded per-model
    hyperparameter search times are summed for reference.
    """
    lines: list[str] = []
    lines.append("Phase 9 - Strict hyperparameter tuning summary")
    lines.append("=" * 70)
    lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")
    lines.append("")
    lines.append("setup:")
    lines.append(f"    CORE_NUMERIC features: {len(features)}")
    lines.append("    frozen Phase 7 5-fold CV (PredefinedSplit, cv_fold 0-4)")
    lines.append(f"    primary train rows: {n_primary_train}")
    lines.append(f"    primary test rows: {n_primary_test} (untouched during search)")
    lines.append(f"    strict non-Zn train rows: {n_strict_train}")
    lines.append(f"    Zn test rows: {n_zn_test} (untouched during search)")
    lines.append("    search: RandomizedSearchCV, scoring=neg_root_mean_squared_error,")
    lines.append("    random_state=42, refit=True, cv=frozen PredefinedSplit")
    lines.append("")
    lines.append("tuned models per target:")
    for target in TARGETS:
        lines.append(f"    {target}: {', '.join(TARGET_MODELS[target])} (n_iter per model: "
                     + ", ".join(f"{m}={N_ITER[m]}" for m in TARGET_MODELS[target]) + ")")
    lines.append("")
    lines.append("best CV parameter combinations:")
    for _, row in best_df.iterrows():
        lines.append(
            f"    [{row['target']}] {row['model']}: CV RMSE={row['best_cv_RMSE']:.4f} | "
            f"{row['best_params_json']}"
        )
    lines.append("")
    lines.append("baseline vs tuned CV improvement (selection criterion):")
    for _, row in comparison.iterrows():
        lines.append(
            f"    [{row['target']}] {row['model']}: CV RMSE {row['baseline_cv_RMSE']:.4f} -> "
            f"{row['tuned_cv_RMSE']:.4f} (delta={row['cv_delta']:+.4f}, "
            f"{row['cv_percent_change']:+.2f}%)"
        )
    lines.append("")
    lines.append("primary group test evaluation (not used for selection):")
    for _, row in primary_metrics.iterrows():
        lines.append(
            f"    [{row['target']}] {row['model']}: R2={row['R2']:.4f}, RMSE={row['RMSE']:.4f}, "
            f"MAE={row['MAE']:.4f}, r={row['Pearson_r']:.4f}"
        )
    lines.append("")
    lines.append("strict Zn transfer evaluation (not used for selection):")
    for _, row in strict_metrics.iterrows():
        lines.append(
            f"    [{row['target']}] {row['model']}: R2={row['R2']:.4f}, RMSE={row['RMSE']:.4f}, "
            f"MAE={row['MAE']:.4f}, r={row['Pearson_r']:.4f}"
        )
    lines.append("")
    lines.append("STRICT Zn transfer experimental boundary (explicit statement):")
    lines.append("    Hyperparameters were selected using the mixed-ion primary training CV.")
    lines.append("    The strict Zn evaluation excludes Zn records from model fitting and keeps")
    lines.append("    the Zn test untouched, but this is not a fully Zn-blind")
    lines.append("    hyperparameter-selection experiment.")
    lines.append("    A non-Zn-only tuning sensitivity experiment is planned separately.")
    lines.append("")
    lines.append("tuned CV ranking (by tuned best CV RMSE ascending):")
    for target in TARGETS:
        sub = ranking[ranking["target"] == target].sort_values("rank")
        order = ", ".join(f"{int(r['rank'])}.{r['model']}" for _, r in sub.iterrows())
        lines.append(f"    {target}: {order}")
    lines.append("")
    lines.append("environment:")
    lines.append(f"    python: {sys.version.split()[0]}")
    lines.append(f"    scikit-learn: {package_version('scikit-learn')}")
    lines.append(f"    xgboost: {package_version('xgboost')}")
    lines.append(f"    catboost: {package_version('catboost')}")
    lines.append(f"    lightgbm: {package_version('lightgbm')}")
    lines.append(f"    scipy: {package_version('scipy')}")
    lines.append(f"    joblib: {package_version('joblib')}")
    lines.append("")
    lines.append("output files:")
    for path in (
        OUT_SEARCH_RESULTS, OUT_BEST_PARAMS, OUT_PRIMARY_METRICS, OUT_STRICT_METRICS,
        OUT_BASELINE_VS_TUNED, OUT_RANKING, OUT_PRIMARY_PREDS, OUT_STRICT_PREDS,
        MODELS_DIR, FIG_DIR, OUT_SUMMARY,
    ):
        lines.append(f"    {path.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append("")
    lines.append("policy statements:")
    lines.append("    Primary test was never used in hyperparameter search.")
    lines.append("    Zn transfer test was never used in hyperparameter search.")
    lines.append("    Model selection is based only on frozen training CV RMSE.")
    lines.append("    No feature selection was performed.")
    lines.append("    No candidate screening was performed.")
    lines.append("    No final all-data refit was performed.")
    lines.append("")
    if runtime_mode == "finalize_only":
        search_time_sum = float(best_df["search_time_seconds"].sum())
        lines.append(f"finalization runtime: {elapsed:.1f} s")
        lines.append(f"recorded hyperparameter search time sum: {search_time_sum:.1f} s")
        lines.append(
            "Because the original full run terminated during figure generation "
            "after all"
        )
        lines.append(
            "formal model results had already been saved, the exact end-to-end "
            "Phase 9"
        )
        lines.append("runtime is not reconstructed in finalize-only mode.")
    else:
        lines.append(f"total Phase 9 runtime: {elapsed:.1f} s")
    lines.append("")
    OUT_SUMMARY.write_text("\\n".join(lines), encoding="utf-8")
    log(f"Saved tuning summary -> {OUT_SUMMARY}")


def finalize_only() -> int:
    """--finalize-only: regenerate figures + summary from existing results.

    Absolutely no model fitting, prediction or hyperparameter search happens
    in this mode; the formal Phase 9 CSVs are read-only inputs.
    """
    log("FINALIZE-ONLY MODE")
    log("No model fitting or hyperparameter search will be performed.")

    required = [
        OUT_SEARCH_RESULTS, OUT_BEST_PARAMS, OUT_PRIMARY_METRICS,
        OUT_STRICT_METRICS, OUT_BASELINE_VS_TUNED, OUT_RANKING,
        OUT_PRIMARY_PREDS, OUT_STRICT_PREDS,
    ]
    missing = [path for path in required if not path.is_file()]
    if missing:
        log("ERROR: --finalize-only requires the existing Phase 9 output files; missing:")
        for path in missing:
            log(f"  {path}")
        log("No fallback to retraining will be attempted.")
        return 1

    started = time.perf_counter()

    # Formal Phase 9 results (read-only).
    best_df = pd.read_csv(OUT_BEST_PARAMS, low_memory=False)
    primary_metrics = pd.read_csv(OUT_PRIMARY_METRICS, low_memory=False)
    strict_metrics = pd.read_csv(OUT_STRICT_METRICS, low_memory=False)
    comparison = pd.read_csv(OUT_BASELINE_VS_TUNED, low_memory=False)
    ranking = pd.read_csv(OUT_RANKING, low_memory=False)
    primary_preds = pd.read_csv(OUT_PRIMARY_PREDS, low_memory=False)
    strict_preds = pd.read_csv(OUT_STRICT_PREDS, low_memory=False)

    # Phase 8 baselines + metadata (read-only; only counts/values, never fits).
    p8_summary = read_required(IN_P8_SUMMARY)
    p8_primary = read_required(IN_P8_PRIMARY)
    p8_strict = read_required(IN_P8_STRICT)
    data = read_required(IN_FEATURES)
    core_set = read_required(IN_CORE_SET)
    primary = read_required(IN_PRIMARY)
    strict = read_required(IN_STRICT)

    features = core_set["feature"].tolist()
    split_counts = primary["split"].value_counts().to_dict()
    n_primary_train = int(split_counts.get("train", 0))
    n_primary_test = int(split_counts.get("test", 0))
    transfer_counts = strict["transfer_split"].value_counts().to_dict()
    n_strict_train = int(transfer_counts.get("strict_nonzn_train", 0))
    n_zn_test = int(transfer_counts.get("zn_test", 0))
    log(
        f"metadata: {len(features)} features, {len(data)} rows, "
        f"primary train/test={n_primary_train}/{n_primary_test}, "
        f"strict train={n_strict_train}, Zn test={n_zn_test}"
    )

    METRICS_DIR.mkdir(parents=True, exist_ok=True)
    PRED_DIR.mkdir(parents=True, exist_ok=True)
    FIG_DIR.mkdir(parents=True, exist_ok=True)

    generate_figures(
        primary_metrics, strict_metrics, primary_preds, best_df,
        p8_summary, p8_primary, p8_strict,
    )
    elapsed = time.perf_counter() - started
    write_summary(
        features, n_primary_train, n_primary_test, n_strict_train, n_zn_test,
        best_df, comparison, primary_metrics, strict_metrics, ranking, elapsed,
        runtime_mode="finalize_only",
    )

    print("")
    print("Phase 9 finalization completed from existing results.")
    print("No models were retrained.")
    print(f"figures: {FIG_DIR}")
    print(f"summary: {OUT_SUMMARY}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    parser = argparse.ArgumentParser(
        description="Phase 9 strict hyperparameter tuning "
                    "(or regenerate figures/summary from existing results)."
    )
    parser.add_argument(
        "--finalize-only",
        action="store_true",
        help="Regenerate figures and phase9_tuning_summary.txt from the existing "
             "Phase 9 output CSVs only. No model fitting, prediction or "
             "hyperparameter search is performed.",
    )
    args = parser.parse_args()

    if args.finalize_only:
        return finalize_only()

    overall_started = time.perf_counter()
    log("Phase 9 - strict hyperparameter tuning (frozen Phase 7 CV only)")

    missing = []
    if not XGB_AVAILABLE:
        missing.append("xgboost")
    if not CATBOOST_AVAILABLE:
        missing.append("catboost")
    if not LGBM_AVAILABLE:
        missing.append("lightgbm")
    for pkg in ("scipy", "scikit-learn", "joblib"):
        if package_version(pkg) == "not installed":
            missing.append(pkg)
    if missing:
        log(f"ERROR: missing package(s): {', '.join(missing)}")
        log("    py -m pip install xgboost catboost lightgbm scipy scikit-learn joblib")
        return 1

    # ---- 1. inputs ---------------------------------------------------------
    data = read_required(IN_FEATURES)
    core_set = read_required(IN_CORE_SET)
    primary = read_required(IN_PRIMARY)
    strict = read_required(IN_STRICT)
    p8_ranking = read_required(IN_P8_RANKING)
    p8_summary = read_required(IN_P8_SUMMARY)
    p8_primary = read_required(IN_P8_PRIMARY)
    p8_strict = read_required(IN_P8_STRICT)

    # ---- 2. features ---------------------------------------------------------
    features = core_set["feature"].tolist()
    missing_cols = [f for f in features if f not in data.columns]
    if missing_cols:
        log(f"ERROR: feature column(s) missing from main data: {missing_cols}")
        return 1
    forbidden_found = [f for f in features if f in FORBIDDEN_IN_FEATURES]
    if forbidden_found:
        log(f"ERROR: target/leakage field(s) in feature list: {forbidden_found}")
        return 1
    for feature in features:
        numeric = pd.to_numeric(data[feature], errors="coerce")
        if int(data[feature].notna().sum()) != int(numeric.notna().sum()):
            log(f"ERROR: feature {feature} has non-numeric value(s)")
            return 1
    log(f"features validated: {len(features)} CORE_NUMERIC, no target/leakage fields")

    data = data.copy()
    data[features] = data[features].replace([np.inf, -np.inf], np.nan)

    # ---- 3. frozen splits -------------------------------------------------------
    data = data.merge(
        primary[["record_uid", "split", "cv_fold"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    data = data.merge(
        strict[["record_uid", "transfer_split"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    if data["split"].isna().any():
        log("ERROR: some records were not matched to the primary split manifest")
        return 1

    train_mask = (data["split"] == "train").to_numpy()
    test_mask = (data["split"] == "test").to_numpy()
    strict_train_mask = (data["transfer_split"] == "strict_nonzn_train").to_numpy()
    zn_test_mask = (data["transfer_split"] == "zn_test").to_numpy()

    train_folds = data.loc[train_mask, "cv_fold"]
    if not (train_folds.notna().all() and set(train_folds.dropna().unique()) == {0, 1, 2, 3, 4}):
        log("ERROR: cv_fold labels invalid (must be 0-4 on train rows)")
        return 1
    if not bool(data.loc[test_mask, "cv_fold"].isna().all()):
        log("ERROR: test rows must have empty cv_fold")
        return 1

    n_primary_train = int(train_mask.sum())
    n_primary_test = int(test_mask.sum())
    n_strict_train = int(strict_train_mask.sum())
    n_zn_test = int(zn_test_mask.sum())
    log(
        f"splits: primary train/test={n_primary_train}/{n_primary_test}, "
        f"strict train={n_strict_train}, Zn test={n_zn_test}"
    )

    cv = PredefinedSplit(test_fold=train_folds.astype(int).to_numpy())

    X = data[features]
    X_train = X[train_mask]
    X_test = X[test_mask]
    meta = data[["record_uid", "working_ion", "framework_formula"]]

    # ---- 4. search + evaluation -------------------------------------------------
    MODELS_DIR.mkdir(parents=True, exist_ok=True)
    METRICS_DIR.mkdir(parents=True, exist_ok=True)
    PRED_DIR.mkdir(parents=True, exist_ok=True)
    FIG_DIR.mkdir(parents=True, exist_ok=True)

    search_rows: list[dict] = []
    best_rows: list[dict] = []
    primary_metric_rows: list[dict] = []
    strict_metric_rows: list[dict] = []
    primary_pred_rows: list[dict] = []
    strict_pred_rows: list[dict] = []
    tuned_pipelines: dict[tuple[str, str], Pipeline] = {}

    for target in TARGETS:
        log(f"== target: {target} ==")
        y = pd.to_numeric(data[target], errors="coerce")
        y_train = y[train_mask]
        for model_name in TARGET_MODELS[target]:
            search, result_rows, best_row = run_search(
                target, model_name, X_train, y_train, cv
            )
            search_rows += result_rows
            best_rows.append(best_row)

            # PRIMARY test: first and only touch, after the search is done.
            estimator = search.best_estimator_
            y_pred = estimator.predict(X_test)
            metrics = compute_metrics(y[test_mask], y_pred)
            metrics.update(
                {
                    "target": target,
                    "model": model_name,
                    "n_test": n_primary_test,
                }
            )
            primary_metric_rows.append(metrics)
            for i, pos in enumerate(np.where(test_mask)[0]):
                primary_pred_rows.append(
                    {
                        "record_uid": meta["record_uid"].iloc[pos],
                        "target": target,
                        "model": model_name,
                        "y_true": float(y.iloc[pos]),
                        "y_pred": float(y_pred[i]),
                        "residual": float(y.iloc[pos]) - float(y_pred[i]),
                        "working_ion": str(meta["working_ion"].iloc[pos]),
                        "framework_formula": str(meta["framework_formula"].iloc[pos]),
                    }
                )
            log(
                f"  [{target}] {model_name}: primary test RMSE="
                f"{metrics['RMSE']:.4f} (evaluation only)"
            )

            # STRICT Zn transfer: rebuild pipeline with the SAME best params,
            # fit strict train, predict Zn test once. Never re-optimized here.
            strict_pipeline = _make_pipeline(model_name)
            strict_pipeline.set_params(**search.best_params_)
            strict_pipeline.fit(X[strict_train_mask], y[strict_train_mask])
            zn_pred = strict_pipeline.predict(X[zn_test_mask])
            s_metrics = compute_metrics(y[zn_test_mask], zn_pred)
            s_metrics.update(
                {
                    "target": target,
                    "model": model_name,
                    "n_test": n_zn_test,
                }
            )
            strict_metric_rows.append(s_metrics)
            for i, pos in enumerate(np.where(zn_test_mask)[0]):
                strict_pred_rows.append(
                    {
                        "record_uid": meta["record_uid"].iloc[pos],
                        "target": target,
                        "model": model_name,
                        "y_true": float(y.iloc[pos]),
                        "y_pred": float(zn_pred[i]),
                        "residual": float(y.iloc[pos]) - float(zn_pred[i]),
                    }
                )
            log(
                f"  [{target}] {model_name}: strict Zn RMSE="
                f"{s_metrics['RMSE']:.4f} (evaluation only)"
            )

            # Save the primary-train-refit tuned snapshot (NOT a final refit).
            model_path = MODELS_DIR / TARGET_DIR_NAME[target] / f"{model_name}.joblib"
            model_path.parent.mkdir(parents=True, exist_ok=True)
            joblib.dump(estimator, model_path)
            tuned_pipelines[(target, model_name)] = estimator

            # --- fault-recovery checkpoint (atomic temp + os.replace) ---------
            atomic_to_csv(pd.DataFrame(search_rows), CHECKPOINT_SEARCH)
            atomic_to_csv(pd.DataFrame(best_rows), CHECKPOINT_BEST)
            atomic_to_csv(pd.DataFrame(primary_metric_rows), CHECKPOINT_PRIMARY_METRICS)
            atomic_to_csv(pd.DataFrame(strict_metric_rows), CHECKPOINT_STRICT_METRICS)
            atomic_to_csv(
                pd.DataFrame(primary_pred_rows)[
                    ["record_uid", "target", "model", "y_true", "y_pred",
                     "residual", "working_ion", "framework_formula"]
                ],
                CHECKPOINT_PRIMARY_PREDS,
            )
            atomic_to_csv(
                pd.DataFrame(strict_pred_rows)[
                    ["record_uid", "target", "model", "y_true", "y_pred", "residual"]
                ],
                CHECKPOINT_STRICT_PREDS,
            )
            log(f"checkpoint saved after: [{target}] [{model_name}]")

    # ---- 5. write results --------------------------------------------------------
    search_df = pd.DataFrame(search_rows)
    best_df = pd.DataFrame(best_rows)
    primary_metrics = pd.DataFrame(primary_metric_rows)
    strict_metrics = pd.DataFrame(strict_metric_rows)

    atomic_to_csv(search_df, OUT_SEARCH_RESULTS)
    atomic_to_csv(best_df, OUT_BEST_PARAMS)
    atomic_to_csv(primary_metrics, OUT_PRIMARY_METRICS)
    atomic_to_csv(strict_metrics, OUT_STRICT_METRICS)

    primary_preds = pd.DataFrame(primary_pred_rows)
    strict_preds = pd.DataFrame(strict_pred_rows)
    atomic_to_csv(
        primary_preds[
            ["record_uid", "target", "model", "y_true", "y_pred", "residual",
             "working_ion", "framework_formula"]
        ],
        OUT_PRIMARY_PREDS,
    )
    atomic_to_csv(
        strict_preds[["record_uid", "target", "model", "y_true", "y_pred", "residual"]],
        OUT_STRICT_PREDS,
    )

    # ---- 6. baseline vs tuned comparison ------------------------------------------
    comparison_rows = []
    for target in TARGETS:
        for model_name in TARGET_MODELS[target]:
            base_cv = p8_summary[
                (p8_summary["target"] == target) & (p8_summary["model"] == model_name)
            ]["mean_RMSE"].iloc[0]
            tuned_cv = best_df[
                (best_df["target"] == target) & (best_df["model"] == model_name)
            ]["best_cv_RMSE"].iloc[0]
            base_primary = p8_primary[
                (p8_primary["target"] == target) & (p8_primary["model"] == model_name)
            ]["RMSE"].iloc[0]
            tuned_primary = primary_metrics[
                (primary_metrics["target"] == target) & (primary_metrics["model"] == model_name)
            ]["RMSE"].iloc[0]
            base_strict = p8_strict[
                (p8_strict["target"] == target) & (p8_strict["model"] == model_name)
            ]["RMSE"].iloc[0]
            tuned_strict = strict_metrics[
                (strict_metrics["target"] == target) & (strict_metrics["model"] == model_name)
            ]["RMSE"].iloc[0]

            def delta_pct(before, after):
                delta = float(before) - float(after)
                pct_change = (100.0 * delta / float(before)) if float(before) else 0.0
                return sig6(delta), sig6(pct_change)

            cv_delta, cv_pct = delta_pct(base_cv, tuned_cv)
            pr_delta, pr_pct = delta_pct(base_primary, tuned_primary)
            st_delta, st_pct = delta_pct(base_strict, tuned_strict)
            comparison_rows.append(
                {
                    "target": target,
                    "model": model_name,
                    "baseline_cv_RMSE": sig6(base_cv),
                    "tuned_cv_RMSE": sig6(tuned_cv),
                    "cv_delta": cv_delta,
                    "cv_percent_change": cv_pct,
                    "baseline_primary_RMSE": sig6(base_primary),
                    "tuned_primary_RMSE": sig6(tuned_primary),
                    "primary_delta": pr_delta,
                    "primary_percent_change": pr_pct,
                    "baseline_strict_zn_RMSE": sig6(base_strict),
                    "tuned_strict_zn_RMSE": sig6(tuned_strict),
                    "strict_zn_delta": st_delta,
                    "strict_zn_percent_change": st_pct,
                }
            )
    comparison = pd.DataFrame(comparison_rows)
    atomic_to_csv(comparison, OUT_BASELINE_VS_TUNED)

    # ---- 7. tuned CV ranking (by tuned best CV RMSE only) ---------------------------
    ranking_rows = []
    for target in TARGETS:
        sub = best_df[best_df["target"] == target].sort_values("best_cv_RMSE")
        for rank, (_, row) in enumerate(sub.iterrows(), start=1):
            ranking_rows.append(
                {
                    "target": target,
                    "rank": rank,
                    "model": row["model"],
                    "best_cv_RMSE": row["best_cv_RMSE"],
                }
            )
    ranking = pd.DataFrame(ranking_rows)
    atomic_to_csv(ranking, OUT_RANKING)

    # ---- 8. figures (shared helper; also used by --finalize-only) ------------
    generate_figures(
        primary_metrics, strict_metrics, primary_preds, best_df,
        p8_summary, p8_primary, p8_strict,
    )

    # ---- 9. summary (shared helper; also used by --finalize-only) --------------
    elapsed = time.perf_counter() - overall_started
    write_summary(
        features, n_primary_train, n_primary_test, n_strict_train, n_zn_test,
        best_df, comparison, primary_metrics, strict_metrics, ranking, elapsed,
        runtime_mode="full",
    )

    # ---- 10. console -----------------------------------------------------------------------
    best_per_target = {
        target: ranking[ranking["target"] == target].sort_values("rank").iloc[0]
        for target in TARGETS
    }
    print("")
    print("Phase 9 hyperparameter tuning completed.")
    print(
        f"Voltage best tuned model by CV: "
        f"{best_per_target['average_voltage']['model']} "
        f"(CV RMSE={best_per_target['average_voltage']['best_cv_RMSE']:.4f})"
    )
    print(
        f"Capacity best tuned model by CV: "
        f"{best_per_target['capacity_grav']['model']} "
        f"(CV RMSE={best_per_target['capacity_grav']['best_cv_RMSE']:.4f})"
    )
    for target in TARGETS:
        for _, row in comparison[comparison["target"] == target].iterrows():
            print(
                f"CV RMSE before -> after [{target}/{row['model']}]: "
                f"{row['baseline_cv_RMSE']:.4f} -> {row['tuned_cv_RMSE']:.4f}"
            )
    print("primary test evaluation completed")
    print("strict Zn transfer evaluation completed")
    print(f"outputs: {METRICS_DIR}")
    print(f"         {PRED_DIR}")
    print(f"         {MODELS_DIR}")
    print(f"         {FIG_DIR}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
''',
    10: '''# -*- coding: utf-8 -*-
"""
Phase 10 - Zn-domain framework-group validation with the FIXED Phase 9
hyperparameters (evaluation-only sensitivity analysis).

Purpose: quantify how well the Phase 9 models generalize INSIDE the Zn-ion
domain to unseen Zn frameworks, using a 5-fold GroupKFold over
group_framework_formula on the ~434 Zn insertion records.

Hard rules:
    * No hyperparameter search of any kind (no RandomizedSearchCV /
      GridSearchCV / Optuna / Bayesian optimization). Every model uses the
      exact Phase 9 best parameters read from best_hyperparameters.csv.
    * Results here can NOT change the Phase 9 selection (which remains based
      on the frozen mixed-ion CV RMSE).
    * No candidate screening, no final all-data refit.
    * Preprocessing (imputer/scaler) lives inside the Pipelines and is fit
      only on each Zn fold's training part.

Outputs:
    02_Datasets/Processed/Splits/zn_group_cv_folds.csv
    05_Results/Metrics/Phase10_Zn_Domain/
        zn_group_cv_fold_metrics.csv
        zn_group_cv_summary.csv
        zn_group_pooled_oof_metrics.csv
        domain_generalization_comparison.csv
        phase10_zn_domain_summary.txt
    05_Results/Predictions/Phase10_Zn_Domain/zn_group_oof_predictions.csv
    06_Figures/Draft_Figures/Phase10_Zn_Domain/
        01..06 PNG (600 dpi) + PDF

Run from the project root:
    py 03_Code/Model_Training/10_validate_zn_domain.py
"""

from __future__ import annotations

import importlib.metadata
import json
import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

from sklearn.pipeline import Pipeline
from sklearn.impute import SimpleImputer
from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import GroupKFold
from sklearn.metrics import r2_score, mean_squared_error, mean_absolute_error
from sklearn.svm import SVR
from sklearn.ensemble import ExtraTreesRegressor

try:
    from xgboost import XGBRegressor
    XGB_AVAILABLE = True
except ImportError:  # pragma: no cover
    XGBRegressor = None  # type: ignore[assignment]
    XGB_AVAILABLE = False

try:
    from catboost import CatBoostRegressor
    CATBOOST_AVAILABLE = True
except ImportError:  # pragma: no cover
    CatBoostRegressor = None  # type: ignore[assignment]
    CATBOOST_AVAILABLE = False

try:
    from lightgbm import LGBMRegressor
    LGBM_AVAILABLE = True
except ImportError:  # pragma: no cover
    LGBMRegressor = None  # type: ignore[assignment]
    LGBM_AVAILABLE = False

# ---------------------------------------------------------------------------
# Paths
# ---------------------------------------------------------------------------
PROJECT_ROOT = Path(_SCIENCE_WORK_ROOT)

IN_ZN_FEATURES = PROJECT_ROOT / "02_Datasets" / "Features" / "zinc_battery_candidate_compatible_features.csv"
IN_CORE_SET = PROJECT_ROOT / "02_Datasets" / "Features" / "Feature_Sets" / "core_numeric_features.csv"
IN_PRIMARY = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "primary_group_holdout.csv"
IN_BEST_PARAMS = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase9_Tuning" / "best_hyperparameters.csv"
IN_P9_PRIMARY = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase9_Tuning" / "tuned_primary_group_test_metrics.csv"
IN_P9_STRICT = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase9_Tuning" / "tuned_strict_zn_transfer_metrics.csv"

OUT_FOLDS = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "zn_group_cv_folds.csv"

METRICS_DIR = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase10_Zn_Domain"
OUT_FOLD_METRICS = METRICS_DIR / "zn_group_cv_fold_metrics.csv"
OUT_CV_SUMMARY = METRICS_DIR / "zn_group_cv_summary.csv"
OUT_POOLED_OOF = METRICS_DIR / "zn_group_pooled_oof_metrics.csv"
OUT_COMPARISON = METRICS_DIR / "domain_generalization_comparison.csv"
OUT_SUMMARY = METRICS_DIR / "phase10_zn_domain_summary.txt"

PRED_DIR = PROJECT_ROOT / "05_Results" / "Predictions" / "Phase10_Zn_Domain"
OUT_OOF_PREDS = PRED_DIR / "zn_group_oof_predictions.csv"

FIG_DIR = PROJECT_ROOT / "06_Figures" / "Draft_Figures" / "Phase10_Zn_Domain"

TARGETS = ("average_voltage", "capacity_grav")

TARGET_MODELS: dict[str, list[str]] = {
    "average_voltage": ["SVR", "CatBoost", "XGBoost", "LightGBM"],
    "capacity_grav": ["CatBoost", "ExtraTrees", "XGBoost", "LightGBM"],
}

FORBIDDEN_IN_FEATURES = {
    "average_voltage",
    "capacity_grav",
    "capacity_vol",
    "energy_grav",
    "energy_vol",
}

N_FOLDS = 5


# ---------------------------------------------------------------------------
# Pipelines (identical structure to Phase 9; inner threads limited to 1)
# ---------------------------------------------------------------------------
def _make_pipeline(name: str) -> Pipeline:
    if name == "SVR":
        model = SVR(kernel="rbf")
        steps = [
            ("imputer", SimpleImputer(strategy="median")),
            ("scaler", StandardScaler()),
            ("model", model),
        ]
    elif name == "ExtraTrees":
        model = ExtraTreesRegressor(random_state=42, n_jobs=1)
        steps = [("imputer", SimpleImputer(strategy="median")), ("model", model)]
    elif name == "XGBoost":
        model = XGBRegressor(
            objective="reg:squarederror", random_state=42, n_jobs=1
        )
        steps = [("imputer", SimpleImputer(strategy="median")), ("model", model)]
    elif name == "CatBoost":
        model = CatBoostRegressor(
            loss_function="RMSE",
            random_seed=42,
            verbose=False,
            allow_writing_files=False,
            thread_count=1,
        )
        steps = [("imputer", SimpleImputer(strategy="median")), ("model", model)]
    elif name == "LightGBM":
        model = LGBMRegressor(random_state=42, n_jobs=1, verbosity=-1)
        steps = [("imputer", SimpleImputer(strategy="median")), ("model", model)]
    else:
        raise ValueError(f"unknown model: {name}")
    return Pipeline(steps)


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------
def log(message: str) -> None:
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S")
    print(f"[{stamp}Z] {message}", flush=True)


def package_version(name: str) -> str:
    try:
        return importlib.metadata.version(name)
    except importlib.metadata.PackageNotFoundError:
        return "not installed"


def sig6(value) -> float | None:
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
        return float(f"{float(value):.6g}")
    except (TypeError, ValueError):
        return None


def compute_metrics(y_true, y_pred) -> dict:
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    try:
        pearson = float(np.corrcoef(y_true, y_pred)[0, 1])
    except Exception:  # noqa: BLE001
        pearson = np.nan
    return {
        "R2": sig6(r2_score(y_true, y_pred)),
        "RMSE": sig6(float(np.sqrt(mean_squared_error(y_true, y_pred)))),
        "MAE": sig6(mean_absolute_error(y_true, y_pred)),
        "Pearson_r": sig6(pearson),
    }


def atomic_to_csv(df: pd.DataFrame, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    df.to_csv(tmp, index=False, encoding="utf-8-sig")
    os.replace(tmp, path)
    log(f"Saved {len(df)} rows -> {path}")


def save_figure(fig, path: Path) -> None:
    fig.tight_layout()
    fig.savefig(path.with_suffix(".png"), dpi=600)
    fig.savefig(path.with_suffix(".pdf"))
    plt.close(fig)
    log(f"  saved figure: {path.name}.png/.pdf")


def read_required(path: Path) -> pd.DataFrame:
    if not path.is_file():
        log(f"ERROR: required input file not found: {path}")
        sys.exit(1)
    return pd.read_csv(path, low_memory=False)


# ---------------------------------------------------------------------------
# Figures
# ---------------------------------------------------------------------------
def figure_cv_comparison(cv_summary: pd.DataFrame, target: str, path: Path) -> None:
    sub = cv_summary[cv_summary["target"] == target].sort_values("mean_RMSE")
    fig, ax = plt.subplots(figsize=(10, 5))
    x = np.arange(len(sub))
    ax.bar(x, sub["mean_RMSE"], yerr=sub["std_RMSE"], capsize=4, color="#4C72B0")
    for i, (_, row) in enumerate(sub.iterrows()):
        ax.text(i, row["mean_RMSE"] + row["std_RMSE"] + 0.002,
                f"R2={row['mean_R2']:.3f}", ha="center", fontsize=8)
    ax.set_xticks(x)
    ax.set_xticklabels(sub["model"], rotation=30, ha="right")
    ax.set_ylabel("Zn-group CV RMSE (+/- 1 std)")
    ax.set_title(f"{target}: Zn-domain 5-fold group CV (fixed Phase 9 params)")
    save_figure(fig, path)


def figure_oof_parity(oof_preds: pd.DataFrame, pooled: pd.DataFrame,
                      target: str, path: Path) -> None:
    models = TARGET_MODELS[target]
    fig, axes = plt.subplots(2, 2, figsize=(11, 10))
    for ax, model in zip(axes.ravel(), models):
        sub = oof_preds[(oof_preds["target"] == target) & (oof_preds["model"] == model)]
        row = pooled[(pooled["target"] == target) & (pooled["model"] == model)].iloc[0]
        ax.scatter(sub["y_true"], sub["y_pred"], s=8, alpha=0.5)
        vmin = min(sub["y_true"].min(), sub["y_pred"].min())
        vmax = max(sub["y_true"].max(), sub["y_pred"].max())
        ax.plot([vmin, vmax], [vmin, vmax], "k--", lw=1)
        ax.set_title(
            f"{model}\\npooled OOF: R2={row['pooled_oof_R2']:.3f}  "
            f"RMSE={row['pooled_oof_RMSE']:.3f}  MAE={row['pooled_oof_MAE']:.3f}",
            fontsize=9,
        )
        ax.set_xlabel("y_true")
        ax.set_ylabel("y_pred (out-of-fold)")
    fig.suptitle(f"{target}: Zn-domain out-of-fold parity (fixed Phase 9 params)", fontsize=14)
    save_figure(fig, path)


def figure_domain_generalization(comparison: pd.DataFrame, target: str, path: Path) -> None:
    models = TARGET_MODELS[target]
    regimes = [
        "PRIMARY_MIXED_ION_GROUP_TEST",
        "STRICT_NONZN_TO_ZN_TRANSFER",
        "ZN_ONLY_GROUP_CV",
    ]
    sub = comparison[comparison["target"] == target]
    fig, ax = plt.subplots(figsize=(12, 6))
    x = np.arange(len(models))
    width = 0.25
    colors = ["#4C72B0", "#DD8452", "#55A868"]
    for i, regime in enumerate(regimes):
        rmse = [
            sub[(sub["model"] == m) & (sub["evaluation_regime"] == regime)]["RMSE"].iloc[0]
            for m in models
        ]
        ax.bar(x + (i - 1) * width, rmse, width, label=regime, color=colors[i])
    ax.set_xticks(x)
    ax.set_xticklabels(models, rotation=30, ha="right")
    ax.set_ylabel("RMSE")
    ax.set_title(f"{target}: domain generalization comparison (fixed Phase 9 params)")
    ax.legend(fontsize=8)
    save_figure(fig, path)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    overall_started = time.perf_counter()
    log("Phase 10 - Zn-domain framework-group validation (fixed Phase 9 params)")

    if not (XGB_AVAILABLE and CATBOOST_AVAILABLE and LGBM_AVAILABLE):
        missing = [p for p, ok in (("xgboost", XGB_AVAILABLE), ("catboost", CATBOOST_AVAILABLE), ("lightgbm", LGBM_AVAILABLE)) if not ok]
        log(f"ERROR: missing package(s): {', '.join(missing)}")
        log("    py -m pip install xgboost catboost lightgbm")
        return 1

    # ---- 1. inputs ---------------------------------------------------------
    zn_df = read_required(IN_ZN_FEATURES)
    core_set = read_required(IN_CORE_SET)
    primary = read_required(IN_PRIMARY)
    best_df = read_required(IN_BEST_PARAMS)
    p9_primary = read_required(IN_P9_PRIMARY)
    p9_strict = read_required(IN_P9_STRICT)

    # ---- 2. Zn dataset checks --------------------------------------------------
    if "working_ion" not in zn_df.columns:
        log("ERROR: Zn feature file has no working_ion column")
        return 1
    non_zn = int((zn_df["working_ion"] != "Zn").sum())
    if non_zn:
        log(f"ERROR: {non_zn} non-Zn record(s) found in the Zn feature file")
        return 1
    if "record_uid" not in zn_df.columns or not bool(zn_df["record_uid"].is_unique):
        log("ERROR: record_uid missing or not unique in the Zn feature file")
        return 1
    log(f"Zn records: {len(zn_df)} (all working_ion == 'Zn')")

    # ---- 3. features ----------------------------------------------------------
    features = core_set["feature"].tolist()
    missing_cols = [f for f in features if f not in zn_df.columns]
    if missing_cols:
        log(f"ERROR: feature column(s) missing: {missing_cols}")
        return 1
    forbidden_found = [f for f in features if f in FORBIDDEN_IN_FEATURES]
    if forbidden_found:
        log(f"ERROR: target/leakage field(s) in feature list: {forbidden_found}")
        return 1
    zn_df = zn_df.copy()
    zn_df[features] = zn_df[features].replace([np.inf, -np.inf], np.nan)
    log(f"features validated: {len(features)} CORE_NUMERIC, no target/leakage fields")

    # ---- 4. framework groups (Phase 7 definition, merged by record_uid) --------
    if "group_framework_formula" not in primary.columns:
        log("ERROR: primary manifest has no group_framework_formula column")
        return 1
    zn_df = zn_df.merge(
        primary[["record_uid", "group_framework_formula"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    n_unmatched = int(zn_df["group_framework_formula"].isna().sum())
    if n_unmatched:
        log(f"ERROR: {n_unmatched} Zn record(s) could not be matched to a framework group")
        return 1
    groups = zn_df["group_framework_formula"]
    n_groups = int(groups.nunique())
    log(f"unique Zn framework groups: {n_groups}")

    # ---- 5. fixed 5-fold GroupKFold (no re-tuning, all models share folds) ------
    gkf = GroupKFold(n_splits=N_FOLDS)
    folds = list(gkf.split(zn_df, groups=groups))
    overlap_violations = 0
    fold_sizes = []
    for fold, (train_idx, val_idx) in enumerate(folds):
        train_groups = set(groups.iloc[train_idx])
        val_groups = set(groups.iloc[val_idx])
        if train_groups & val_groups:
            overlap_violations += 1
        fold_sizes.append(len(val_idx))
    if overlap_violations:
        log(f"ERROR: framework group overlap inside folds: {overlap_violations} fold(s)")
        return 1
    log(f"GroupKFold folds: {fold_sizes}; group overlap inside folds: 0")

    fold_assignment = np.full(len(zn_df), -1, dtype=int)
    for fold, (_tr, val_idx) in enumerate(folds):
        fold_assignment[val_idx] = fold
    zn_fold_manifest = pd.DataFrame(
        {
            "record_uid": zn_df["record_uid"],
            "group_framework_formula": groups,
            "cv_fold": fold_assignment,
        }
    )
    OUT_FOLDS.parent.mkdir(parents=True, exist_ok=True)
    atomic_to_csv(zn_fold_manifest, OUT_FOLDS)

    # ---- 6/7. fixed Phase 9 hyperparameters, identical pipelines -----------------
    best_params_map: dict[tuple[str, str], dict] = {}
    for _, row in best_df.iterrows():
        key = (row["target"], row["model"])
        try:
            best_params_map[key] = json.loads(row["best_params_json"])
        except Exception:  # noqa: BLE001
            log(f"ERROR: cannot parse best_params_json for {key}")
            return 1
    log(f"loaded fixed Phase 9 hyperparameters for {len(best_params_map)} target x model combinations")

    METRICS_DIR.mkdir(parents=True, exist_ok=True)
    PRED_DIR.mkdir(parents=True, exist_ok=True)
    FIG_DIR.mkdir(parents=True, exist_ok=True)

    X = zn_df[features]
    fold_metric_rows: list[dict] = []
    cv_summary_rows: list[dict] = []
    pooled_oof_rows: list[dict] = []
    oof_pred_rows: list[dict] = []

    for target in TARGETS:
        log(f"== target: {target} ==")
        y = pd.to_numeric(zn_df[target], errors="coerce")
        for model_name in TARGET_MODELS[target]:
            key = (target, model_name)
            if key not in best_params_map:
                log(f"ERROR: no Phase 9 best hyperparameters for {key}")
                return 1
            pipeline = _make_pipeline(model_name)
            pipeline.set_params(**best_params_map[key])

            oof_y_true: list[float] = []
            oof_y_pred: list[float] = []
            oof_uids: list[str] = []

            for fold, (train_idx, val_idx) in enumerate(folds):
                started = time.perf_counter()
                pipeline.fit(X.iloc[train_idx], y.iloc[train_idx])
                fit_time = time.perf_counter() - started
                y_pred = pipeline.predict(X.iloc[val_idx])
                metrics = compute_metrics(y.iloc[val_idx], y_pred)
                fold_metric_rows.append(
                    {
                        "target": target,
                        "model": model_name,
                        "fold": fold,
                        "n_train": int(len(train_idx)),
                        "n_validation": int(len(val_idx)),
                        "R2": metrics["R2"],
                        "RMSE": metrics["RMSE"],
                        "MAE": metrics["MAE"],
                        "Pearson_r": metrics["Pearson_r"],
                        "fit_time_seconds": sig6(fit_time),
                    }
                )
                for i, pos in enumerate(val_idx):
                    oof_uids.append(zn_df["record_uid"].iloc[pos])
                    oof_y_true.append(float(y.iloc[pos]))
                    oof_y_pred.append(float(y_pred[i]))
                log(
                    f"  [{target}] {model_name} fold {fold}: "
                    f"RMSE={metrics['RMSE']:.4f}, R2={metrics['R2']:.4f}"
                )

            # per-model fold summary (mean +- std)
            model_folds = [r for r in fold_metric_rows
                           if r["target"] == target and r["model"] == model_name]
            cv_summary_rows.append(
                {
                    "target": target,
                    "model": model_name,
                    "mean_R2": sig6(np.mean([r["R2"] for r in model_folds])),
                    "std_R2": sig6(np.std([r["R2"] for r in model_folds])),
                    "mean_RMSE": sig6(np.mean([r["RMSE"] for r in model_folds])),
                    "std_RMSE": sig6(np.std([r["RMSE"] for r in model_folds])),
                    "mean_MAE": sig6(np.mean([r["MAE"] for r in model_folds])),
                    "std_MAE": sig6(np.std([r["MAE"] for r in model_folds])),
                    "mean_Pearson_r": sig6(np.mean([r["Pearson_r"] for r in model_folds])),
                    "std_Pearson_r": sig6(np.std([r["Pearson_r"] for r in model_folds])),
                }
            )

            # pooled OOF (each Zn record was validation exactly once)
            pooled = compute_metrics(np.array(oof_y_true), np.array(oof_y_pred))
            pooled_oof_rows.append(
                {
                    "target": target,
                    "model": model_name,
                    "pooled_oof_R2": pooled["R2"],
                    "pooled_oof_RMSE": pooled["RMSE"],
                    "pooled_oof_MAE": pooled["MAE"],
                    "pooled_oof_Pearson_r": pooled["Pearson_r"],
                    "n_oof": int(len(oof_y_true)),
                }
            )
            for uid, yt, yp in zip(oof_uids, oof_y_true, oof_y_pred):
                oof_pred_rows.append(
                    {
                        "record_uid": uid,
                        "target": target,
                        "model": model_name,
                        "y_true": yt,
                        "y_pred": yp,
                        "residual": yt - yp,
                    }
                )
            log(
                f"  [{target}] {model_name} pooled OOF: RMSE={pooled['RMSE']:.4f}, "
                f"R2={pooled['R2']:.4f}"
            )

    # ---- write CV metrics / predictions -------------------------------------------
    fold_metrics = pd.DataFrame(fold_metric_rows)
    cv_summary = pd.DataFrame(cv_summary_rows)
    pooled_oof = pd.DataFrame(pooled_oof_rows)
    oof_preds = pd.DataFrame(oof_pred_rows)
    atomic_to_csv(fold_metrics, OUT_FOLD_METRICS)
    atomic_to_csv(cv_summary, OUT_CV_SUMMARY)
    atomic_to_csv(pooled_oof, OUT_POOLED_OOF)
    atomic_to_csv(oof_preds, OUT_OOF_PREDS)

    # ---- three-regime comparison ---------------------------------------------------
    comparison_rows = []
    for target in TARGETS:
        for model_name in TARGET_MODELS[target]:
            for regime, src in (
                ("PRIMARY_MIXED_ION_GROUP_TEST", p9_primary),
                ("STRICT_NONZN_TO_ZN_TRANSFER", p9_strict),
            ):
                row = src[(src["target"] == target) & (src["model"] == model_name)].iloc[0]
                comparison_rows.append(
                    {
                        "target": target,
                        "model": model_name,
                        "evaluation_regime": regime,
                        "R2": sig6(row["R2"]),
                        "RMSE": sig6(row["RMSE"]),
                        "MAE": sig6(row["MAE"]),
                        "Pearson_r": sig6(row["Pearson_r"]),
                    }
                )
            oof_row = pooled_oof[
                (pooled_oof["target"] == target) & (pooled_oof["model"] == model_name)
            ].iloc[0]
            comparison_rows.append(
                {
                    "target": target,
                    "model": model_name,
                    "evaluation_regime": "ZN_ONLY_GROUP_CV",
                    "R2": sig6(oof_row["pooled_oof_R2"]),
                    "RMSE": sig6(oof_row["pooled_oof_RMSE"]),
                    "MAE": sig6(oof_row["pooled_oof_MAE"]),
                    "Pearson_r": sig6(oof_row["pooled_oof_Pearson_r"]),
                }
            )
    comparison = pd.DataFrame(comparison_rows)
    atomic_to_csv(comparison, OUT_COMPARISON)

    # ---- figures -----------------------------------------------------------------------
    log("generating figures ...")
    figure_cv_comparison(cv_summary, "average_voltage", FIG_DIR / "01_voltage_zn_group_cv_comparison")
    figure_cv_comparison(cv_summary, "capacity_grav", FIG_DIR / "02_capacity_zn_group_cv_comparison")
    figure_oof_parity(oof_preds, pooled_oof, "average_voltage", FIG_DIR / "03_voltage_zn_oof_parity")
    figure_oof_parity(oof_preds, pooled_oof, "capacity_grav", FIG_DIR / "04_capacity_zn_oof_parity")
    figure_domain_generalization(comparison, "average_voltage", FIG_DIR / "05_voltage_domain_generalization")
    figure_domain_generalization(comparison, "capacity_grav", FIG_DIR / "06_capacity_domain_generalization")

    # ---- summary ---------------------------------------------------------------------------
    elapsed = time.perf_counter() - overall_started
    lines: list[str] = []
    lines.append("Phase 10 - Zn-domain framework-group validation summary")
    lines.append("=" * 70)
    lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")
    lines.append("")
    lines.append(f"Zn records: {len(zn_df)} (all working_ion == 'Zn')")
    lines.append(f"unique Zn framework groups: {n_groups}")
    lines.append(f"feature count: {len(features)} CORE_NUMERIC")
    lines.append(f"GroupKFold: {N_FOLDS} folds, validation sizes {fold_sizes}")
    lines.append(f"framework overlap inside folds: {overlap_violations}")
    lines.append("")
    lines.append("fixed Phase 9 hyperparameters (from best_hyperparameters.csv):")
    for (target, model_name), params in sorted(best_params_map.items()):
        lines.append(f"    [{target}] {model_name}: {json.dumps(params, default=str)}")
    lines.append("")
    lines.append("Zn-domain 5-fold group CV (per model, mean +/- std):")
    for _, row in cv_summary.iterrows():
        lines.append(
            f"    [{row['target']}] {row['model']}: RMSE={row['mean_RMSE']:.4f}+/-"
            f"{row['std_RMSE']:.4f}, R2={row['mean_R2']:.4f}+/-{row['std_R2']:.4f}, "
            f"MAE={row['mean_MAE']:.4f}, r={row['mean_Pearson_r']:.4f}"
        )
    lines.append("")
    lines.append("pooled out-of-fold metrics (every Zn record validated once):")
    for _, row in pooled_oof.iterrows():
        lines.append(
            f"    [{row['target']}] {row['model']}: R2={row['pooled_oof_R2']:.4f}, "
            f"RMSE={row['pooled_oof_RMSE']:.4f}, MAE={row['pooled_oof_MAE']:.4f}, "
            f"r={row['pooled_oof_Pearson_r']:.4f} (n={int(row['n_oof'])})"
        )
    lines.append("")
    lines.append("three-regime domain generalization comparison:")
    for target in TARGETS:
        lines.append(f"    [{target}]")
        sub = comparison[comparison["target"] == target]
        for _, row in sub.iterrows():
            lines.append(
                f"        {row['model']} | {row['evaluation_regime']}: "
                f"R2={row['R2']:.4f}, RMSE={row['RMSE']:.4f}, MAE={row['MAE']:.4f}, "
                f"r={row['Pearson_r']:.4f}"
            )
    lines.append("")
    lines.append("output files:")
    for path in (
        OUT_FOLDS, OUT_FOLD_METRICS, OUT_CV_SUMMARY, OUT_POOLED_OOF, OUT_COMPARISON,
        OUT_OOF_PREDS, FIG_DIR, OUT_SUMMARY,
    ):
        lines.append(f"    {path.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append("")
    lines.append("policy statements:")
    lines.append("    Phase 10 is an evaluation-only sensitivity analysis.")
    lines.append("    No hyperparameters were tuned on Zn-domain folds.")
    lines.append("    Phase 9 model selection remains based on frozen mixed-ion CV RMSE.")
    lines.append("    No candidate screening was performed.")
    lines.append("    No final all-data refit was performed.")
    lines.append("")
    lines.append(f"runtime: {elapsed:.1f} s")
    lines.append("")
    OUT_SUMMARY.write_text("\\n".join(lines), encoding="utf-8")
    log(f"Saved Zn-domain summary -> {OUT_SUMMARY}")

    # ---- console -----------------------------------------------------------------------------
    best_voltage = pooled_oof[pooled_oof["target"] == "average_voltage"].sort_values(
        "pooled_oof_RMSE"
    ).iloc[0]
    best_capacity = pooled_oof[pooled_oof["target"] == "capacity_grav"].sort_values(
        "pooled_oof_RMSE"
    ).iloc[0]
    print("")
    print("Phase 10 Zn-domain validation completed.")
    print(f"Zn rows: {len(zn_df)}")
    print(f"unique framework groups: {n_groups}")
    print(f"feature count: {len(features)}")
    print(
        f"Voltage pooled OOF best: {best_voltage['model']} "
        f"(RMSE={best_voltage['pooled_oof_RMSE']:.4f}, R2={best_voltage['pooled_oof_R2']:.4f})"
    )
    print(
        f"Capacity pooled OOF best: {best_capacity['model']} "
        f"(RMSE={best_capacity['pooled_oof_RMSE']:.4f}, R2={best_capacity['pooled_oof_R2']:.4f})"
    )
    print(f"outputs: {METRICS_DIR}")
    print(f"         {PRED_DIR}")
    print(f"         {OUT_FOLDS}")
    print(f"         {FIG_DIR}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
''',
    11: '''# -*- coding: utf-8 -*-
"""
Phase 11 - Fair comparison of Zn deployment training regimes using identical
Zn framework-group validation folds (CatBoost only, fixed Phase 9 params).

Question answered here: for the final Zn candidate screening, which TRAINING
DATA strategy should the Phase 9 CatBoost model use?

Three regimes, all validated on EXACTLY the same Zn validation records
(the frozen Phase 10 cv_fold 0-4 labels; folds are never re-generated):

    A. ZN_ONLY                 - train on the other Zn records (same logic
                                 as Phase 10; used as the consistency anchor).
    B. MIXED_ION_GROUP_SAFE    - train on ALL all-battery insertion records
                                 whose framework group is NOT in the current
                                 Zn validation fold.
    C. NONZN_ONLY_GROUP_SAFE   - like B but restricted to working_ion != "Zn"
                                 (domain-shift diagnostic only).

Hard rules:
    * No hyperparameter search (no RandomizedSearchCV / GridSearchCV /
      Optuna / Bayesian optimization). CatBoost uses the exact Phase 9 best
      parameters for each target.
    * Phase 9 model selection is not changed by this phase.
    * For every fold x regime: record_uid overlap = 0 AND framework-group
      overlap = 0, otherwise ERROR.
    * ZN_ONLY must reproduce the Phase 10 CatBoost pooled OOF metrics within
      1e-6, otherwise ERROR.

Outputs:
    05_Results/Metrics/Phase11_Training_Regime/
        training_regime_fold_metrics.csv
        training_regime_pooled_oof_metrics.csv
        deployment_regime_ranking.csv
        phase11_training_regime_summary.txt
    05_Results/Predictions/Phase11_Training_Regime/
        training_regime_oof_predictions.csv
    06_Figures/Draft_Figures/Phase11_Training_Regime/
        01..06 PNG (600 dpi) + PDF

Run from the project root:
    py 03_Code/Model_Training/11_compare_zn_training_regimes.py
"""

from __future__ import annotations

import json
import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

from sklearn.pipeline import Pipeline
from sklearn.impute import SimpleImputer
from sklearn.metrics import r2_score, mean_squared_error, mean_absolute_error

try:
    from catboost import CatBoostRegressor
    CATBOOST_AVAILABLE = True
except ImportError:  # pragma: no cover
    CatBoostRegressor = None  # type: ignore[assignment]
    CATBOOST_AVAILABLE = False

# ---------------------------------------------------------------------------
# Paths
# ---------------------------------------------------------------------------
PROJECT_ROOT = Path(_SCIENCE_WORK_ROOT)

IN_ALL_FEATURES = PROJECT_ROOT / "02_Datasets" / "Features" / "all_battery_candidate_compatible_features.csv"
IN_ZN_FEATURES = PROJECT_ROOT / "02_Datasets" / "Features" / "zinc_battery_candidate_compatible_features.csv"
IN_CORE_SET = PROJECT_ROOT / "02_Datasets" / "Features" / "Feature_Sets" / "core_numeric_features.csv"
IN_PRIMARY = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "primary_group_holdout.csv"
IN_ZN_FOLDS = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "zn_group_cv_folds.csv"
IN_BEST_PARAMS = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase9_Tuning" / "best_hyperparameters.csv"
IN_P10_POOLED = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase10_Zn_Domain" / "zn_group_pooled_oof_metrics.csv"

METRICS_DIR = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase11_Training_Regime"
OUT_FOLD_METRICS = METRICS_DIR / "training_regime_fold_metrics.csv"
OUT_POOLED = METRICS_DIR / "training_regime_pooled_oof_metrics.csv"
OUT_RANKING = METRICS_DIR / "deployment_regime_ranking.csv"
OUT_SUMMARY = METRICS_DIR / "phase11_training_regime_summary.txt"

PRED_DIR = PROJECT_ROOT / "05_Results" / "Predictions" / "Phase11_Training_Regime"
OUT_OOF_PREDS = PRED_DIR / "training_regime_oof_predictions.csv"

FIG_DIR = PROJECT_ROOT / "06_Figures" / "Draft_Figures" / "Phase11_Training_Regime"

TARGETS = ("average_voltage", "capacity_grav")
MODEL_NAME = "CatBoost"

REGIMES = ("ZN_ONLY", "MIXED_ION_GROUP_SAFE", "NONZN_ONLY_GROUP_SAFE")
ELIGIBLE_FOR_DEPLOYMENT = {
    "ZN_ONLY": True,
    "MIXED_ION_GROUP_SAFE": True,
    "NONZN_ONLY_GROUP_SAFE": False,
}

FORBIDDEN_IN_FEATURES = {
    "average_voltage",
    "capacity_grav",
    "capacity_vol",
    "energy_grav",
    "energy_vol",
}

PHASE10_TOLERANCE = 1e-6


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------
def log(message: str) -> None:
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S")
    print(f"[{stamp}Z] {message}", flush=True)


def sig6(value) -> float | None:
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
        return float(f"{float(value):.6g}")
    except (TypeError, ValueError):
        return None


def compute_metrics(y_true, y_pred) -> dict:
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    try:
        pearson = float(np.corrcoef(y_true, y_pred)[0, 1])
    except Exception:  # noqa: BLE001
        pearson = np.nan
    return {
        "R2": sig6(r2_score(y_true, y_pred)),
        "RMSE": sig6(float(np.sqrt(mean_squared_error(y_true, y_pred)))),
        "MAE": sig6(mean_absolute_error(y_true, y_pred)),
        "Pearson_r": sig6(pearson),
    }


def atomic_to_csv(df: pd.DataFrame, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    df.to_csv(tmp, index=False, encoding="utf-8-sig")
    os.replace(tmp, path)
    log(f"Saved {len(df)} rows -> {path}")


def save_figure(fig, path: Path) -> None:
    fig.tight_layout()
    fig.savefig(path.with_suffix(".png"), dpi=600)
    fig.savefig(path.with_suffix(".pdf"))
    plt.close(fig)
    log(f"  saved figure: {path.name}.png/.pdf")


def read_required(path: Path) -> pd.DataFrame:
    if not path.is_file():
        log(f"ERROR: required input file not found: {path}")
        sys.exit(1)
    return pd.read_csv(path, low_memory=False)


def make_catboost_pipeline(params: dict) -> Pipeline:
    model = CatBoostRegressor(
        loss_function="RMSE",
        random_seed=42,
        verbose=False,
        allow_writing_files=False,
        thread_count=1,
    )
    pipeline = Pipeline([("imputer", SimpleImputer(strategy="median")), ("model", model)])
    pipeline.set_params(**params)
    return pipeline


# ---------------------------------------------------------------------------
# Figures
# ---------------------------------------------------------------------------
def figure_regime_bars(pooled: pd.DataFrame, target: str, metric: str,
                       path: Path, ylabel: str) -> None:
    sub = pooled[pooled["target"] == target].set_index("regime")
    values = [sub.loc[r, metric] for r in REGIMES]
    fig, ax = plt.subplots(figsize=(9, 5))
    x = np.arange(len(REGIMES))
    colors = ["#4C72B0", "#55A868", "#DD8452"]
    ax.bar(x, values, color=colors)
    for i, v in enumerate(values):
        ax.text(i, v + 0.002, f"{v:.4f}", ha="center", fontsize=9)
    ax.set_xticks(x)
    ax.set_xticklabels(REGIMES, rotation=15, ha="right")
    ax.set_ylabel(ylabel)
    ax.set_title(f"{target}: Zn training-regime comparison ({ylabel}, pooled OOF)")
    save_figure(fig, path)


def figure_regime_parity(oof_preds: pd.DataFrame, pooled: pd.DataFrame,
                         target: str, path: Path) -> None:
    fig, axes = plt.subplots(1, 3, figsize=(18, 6))
    for ax, regime in zip(axes, REGIMES):
        sub = oof_preds[(oof_preds["target"] == target) & (oof_preds["regime"] == regime)]
        row = pooled[(pooled["target"] == target) & (pooled["regime"] == regime)].iloc[0]
        ax.scatter(sub["y_true"], sub["y_pred"], s=8, alpha=0.5)
        vmin = min(sub["y_true"].min(), sub["y_pred"].min())
        vmax = max(sub["y_true"].max(), sub["y_pred"].max())
        ax.plot([vmin, vmax], [vmin, vmax], "k--", lw=1)
        ax.set_title(
            f"{regime}\\nR2={row['pooled_oof_R2']:.3f}  RMSE={row['pooled_oof_RMSE']:.3f}  "
            f"MAE={row['pooled_oof_MAE']:.3f}",
            fontsize=9,
        )
        ax.set_xlabel("y_true")
        ax.set_ylabel("y_pred (out-of-fold)")
    fig.suptitle(f"{target}: CatBoost training-regime OOF parity (fixed Phase 9 params)", fontsize=14)
    save_figure(fig, path)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    overall_started = time.perf_counter()
    log("Phase 11 - Zn training-regime comparison (CatBoost, fixed Phase 9 params)")

    if not CATBOOST_AVAILABLE:
        log("ERROR: catboost is not installed. Install with: py -m pip install catboost")
        return 1

    # ---- 1. inputs ---------------------------------------------------------
    all_df = read_required(IN_ALL_FEATURES)
    zn_df = read_required(IN_ZN_FEATURES)
    core_set = read_required(IN_CORE_SET)
    primary = read_required(IN_PRIMARY)
    zn_folds = read_required(IN_ZN_FOLDS)
    best_df = read_required(IN_BEST_PARAMS)
    p10_pooled = read_required(IN_P10_POOLED)

    # ---- 2/3. fixed model + fixed Phase 9 CatBoost parameters -----------------
    catboost_params: dict[str, dict] = {}
    for target in TARGETS:
        rows = best_df[(best_df["target"] == target) & (best_df["model"] == MODEL_NAME)]
        if rows.empty:
            log(f"ERROR: no Phase 9 best hyperparameters for {target} + {MODEL_NAME}")
            return 1
        try:
            catboost_params[target] = json.loads(rows.iloc[0]["best_params_json"])
        except Exception:  # noqa: BLE001
            log(f"ERROR: cannot parse best_params_json for {target} + {MODEL_NAME}")
            return 1
        log(f"fixed {MODEL_NAME} params [{target}]: {json.dumps(catboost_params[target], default=str)}")

    # ---- 4. features -----------------------------------------------------------
    features = core_set["feature"].tolist()
    for label, df in (("all_battery", all_df), ("zinc_battery", zn_df)):
        missing_cols = [f for f in features if f not in df.columns]
        if missing_cols:
            log(f"ERROR: {label} missing feature column(s): {missing_cols}")
            return 1
    forbidden_found = [f for f in features if f in FORBIDDEN_IN_FEATURES]
    if forbidden_found:
        log(f"ERROR: target/leakage field(s) in feature list: {forbidden_found}")
        return 1
    all_df = all_df.copy()
    zn_df = zn_df.copy()
    all_df[features] = all_df[features].replace([np.inf, -np.inf], np.nan)
    zn_df[features] = zn_df[features].replace([np.inf, -np.inf], np.nan)
    log(f"features validated: {len(features)} CORE_NUMERIC")

    # ---- 5/6. group + fold alignment (no re-generation of folds) ---------------
    all_df = all_df.merge(
        primary[["record_uid", "group_framework_formula"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    if int(all_df["group_framework_formula"].isna().sum()):
        log("ERROR: some all-battery records could not be matched to a framework group")
        return 1
    zn_df = zn_df.merge(
        zn_folds[["record_uid", "group_framework_formula", "cv_fold"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    if int(zn_df["cv_fold"].isna().sum()):
        log("ERROR: some Zn records could not be matched to the Phase 10 cv_fold")
        return 1
    zn_fold_values = set(zn_df["cv_fold"].unique())
    if zn_fold_values != {0, 1, 2, 3, 4}:
        log(f"ERROR: Zn cv_fold labels are not exactly 0-4: {sorted(zn_fold_values)}")
        return 1
    log(f"Zn records: {len(zn_df)}; all-battery records: {len(all_df)}")

    all_groups = all_df["group_framework_formula"]
    zn_groups = zn_df["group_framework_formula"]

    # ---- 7. run regimes -----------------------------------------------------------
    METRICS_DIR.mkdir(parents=True, exist_ok=True)
    PRED_DIR.mkdir(parents=True, exist_ok=True)
    FIG_DIR.mkdir(parents=True, exist_ok=True)

    fold_metric_rows: list[dict] = []
    pooled_rows: list[dict] = []
    oof_rows: list[dict] = []
    fold_sizes = zn_df["cv_fold"].value_counts().sort_index().to_dict()

    for target in TARGETS:
        log(f"== target: {target} ==")
        y_all = pd.to_numeric(all_df[target], errors="coerce")
        y_zn = pd.to_numeric(zn_df[target], errors="coerce")
        X_all = all_df[features]
        X_zn = zn_df[features]

        for regime in REGIMES:
            regime_oof_uids: list[str] = []
            regime_oof_y_true: list[float] = []
            regime_oof_y_pred: list[float] = []
            regime_oof_folds: list[int] = []

            for fold in range(5):
                val_mask = (zn_df["cv_fold"] == fold).to_numpy()
                val_groups = set(zn_groups[val_mask])

                if regime == "ZN_ONLY":
                    train_mask = (zn_df["cv_fold"] != fold).to_numpy()
                    train_frame = zn_df
                    train_groups = zn_groups
                    train_ion = zn_df["working_ion"]
                else:
                    # all-battery based training (group-safe)
                    safe_mask = (~all_groups.isin(val_groups)).to_numpy()
                    if regime == "NONZN_ONLY_GROUP_SAFE":
                        safe_mask = safe_mask & (all_df["working_ion"] != "Zn").to_numpy()
                    train_mask = safe_mask
                    train_frame = all_df
                    train_groups = all_groups
                    train_ion = all_df["working_ion"]

                # ---- mandatory QA per fold x regime --------------------------------
                val_uids = set(zn_df.loc[val_mask, "record_uid"])
                train_uids = set(train_frame.loc[train_mask, "record_uid"])
                uid_overlap = len(train_uids & val_uids)
                group_overlap = len(set(train_groups[train_mask]) & val_groups)
                n_train_zn = int((train_ion[train_mask] == "Zn").sum())
                n_train_nonzn = int((train_ion[train_mask] != "Zn").sum())

                if uid_overlap or group_overlap:
                    log(
                        f"ERROR: [{target}] {regime} fold {fold}: uid_overlap="
                        f"{uid_overlap}, group_overlap={group_overlap}"
                    )
                    return 1
                if regime == "NONZN_ONLY_GROUP_SAFE" and n_train_zn != 0:
                    log(f"ERROR: [{target}] NONZN_ONLY_GROUP_SAFE fold {fold} contains {n_train_zn} Zn training records")
                    return 1
                if regime == "ZN_ONLY" and n_train_nonzn != 0:
                    log(f"ERROR: [{target}] ZN_ONLY fold {fold} contains {n_train_nonzn} non-Zn training records")
                    return 1

                pipeline = make_catboost_pipeline(catboost_params[target])
                X_train = X_zn[train_mask] if regime == "ZN_ONLY" else X_all[train_mask]
                y_train = y_zn[train_mask] if regime == "ZN_ONLY" else y_all[train_mask]

                started = time.perf_counter()
                pipeline.fit(X_train, y_train)
                fit_time = time.perf_counter() - started

                y_pred = pipeline.predict(X_zn[val_mask])
                metrics = compute_metrics(y_zn[val_mask], y_pred)
                fold_metric_rows.append(
                    {
                        "target": target,
                        "regime": regime,
                        "fold": fold,
                        "n_train": int(train_mask.sum()),
                        "n_validation": int(val_mask.sum()),
                        "n_train_Zn": n_train_zn,
                        "n_train_nonZn": n_train_nonzn,
                        "n_train_framework_groups": int(train_groups[train_mask].nunique()),
                        "n_validation_framework_groups": int(len(val_groups)),
                        "R2": metrics["R2"],
                        "RMSE": metrics["RMSE"],
                        "MAE": metrics["MAE"],
                        "Pearson_r": metrics["Pearson_r"],
                        "fit_time_seconds": sig6(fit_time),
                    }
                )
                for i, pos in enumerate(np.where(val_mask)[0]):
                    regime_oof_uids.append(zn_df["record_uid"].iloc[pos])
                    regime_oof_folds.append(fold)
                    regime_oof_y_true.append(float(y_zn.iloc[pos]))
                    regime_oof_y_pred.append(float(y_pred[i]))
                log(
                    f"  [{target}] {regime} fold {fold}: n_train={int(train_mask.sum())} "
                    f"(Zn={n_train_zn}, nonZn={n_train_nonzn}), "
                    f"RMSE={metrics['RMSE']:.4f}"
                )

            pooled = compute_metrics(np.array(regime_oof_y_true), np.array(regime_oof_y_pred))
            pooled_rows.append(
                {
                    "target": target,
                    "regime": regime,
                    "pooled_oof_R2": pooled["R2"],
                    "pooled_oof_RMSE": pooled["RMSE"],
                    "pooled_oof_MAE": pooled["MAE"],
                    "pooled_oof_Pearson_r": pooled["Pearson_r"],
                    "n_oof": int(len(regime_oof_y_true)),
                }
            )
            for uid, fold, yt, yp in zip(
                regime_oof_uids, regime_oof_folds, regime_oof_y_true, regime_oof_y_pred
            ):
                oof_rows.append(
                    {
                        "record_uid": uid,
                        "target": target,
                        "regime": regime,
                        "cv_fold": fold,
                        "y_true": yt,
                        "y_pred": yp,
                        "residual": yt - yp,
                    }
                )
            log(
                f"  [{target}] {regime} pooled OOF: RMSE={pooled['RMSE']:.4f}, "
                f"R2={pooled['R2']:.4f}"
            )

    # ---- 12/13. pooled + Phase 10 consistency QA -----------------------------------
    pooled = pd.DataFrame(pooled_rows)
    oof_preds = pd.DataFrame(oof_rows)
    fold_metrics = pd.DataFrame(fold_metric_rows)

    consistency_ok = True
    for target in TARGETS:
        ours = pooled[(pooled["target"] == target) & (pooled["regime"] == "ZN_ONLY")].iloc[0]
        theirs = p10_pooled[
            (p10_pooled["target"] == target) & (p10_pooled["model"] == MODEL_NAME)
        ].iloc[0]
        rmse_diff = abs(float(ours["pooled_oof_RMSE"]) - float(theirs["pooled_oof_RMSE"]))
        r2_diff = abs(float(ours["pooled_oof_R2"]) - float(theirs["pooled_oof_R2"]))
        log(
            f"Phase 10 consistency [{target}]: RMSE diff={rmse_diff:.3e}, "
            f"R2 diff={r2_diff:.3e} (tolerance {PHASE10_TOLERANCE})"
        )
        if rmse_diff >= PHASE10_TOLERANCE or r2_diff >= PHASE10_TOLERANCE:
            consistency_ok = False
    if not consistency_ok:
        log("ERROR: ZN_ONLY results do not match Phase 10 CatBoost within tolerance")
        return 1

    # ---- 14. deployment ranking --------------------------------------------------------
    ranking_rows = []
    for target in TARGETS:
        sub = pooled[pooled["target"] == target].sort_values("pooled_oof_RMSE")
        for rank, (_, row) in enumerate(sub.iterrows(), start=1):
            ranking_rows.append(
                {
                    "target": target,
                    "rank": rank,
                    "regime": row["regime"],
                    "pooled_oof_RMSE": sig6(row["pooled_oof_RMSE"]),
                    "pooled_oof_R2": sig6(row["pooled_oof_R2"]),
                    "eligible_for_final_deployment": ELIGIBLE_FOR_DEPLOYMENT[row["regime"]],
                }
            )
    ranking = pd.DataFrame(ranking_rows)

    recommended: dict[str, str] = {}
    for target in TARGETS:
        eligible = ranking[
            (ranking["target"] == target) & (ranking["eligible_for_final_deployment"])
        ].sort_values("pooled_oof_RMSE")
        recommended[target] = eligible.iloc[0]["regime"]

    # ---- write outputs -------------------------------------------------------------------
    atomic_to_csv(fold_metrics, OUT_FOLD_METRICS)
    atomic_to_csv(pooled, OUT_POOLED)
    atomic_to_csv(ranking, OUT_RANKING)
    atomic_to_csv(oof_preds, OUT_OOF_PREDS)

    # ---- figures ---------------------------------------------------------------------------
    FIGURE_NAMES = {
        "average_voltage": {
            "rmse": "01_voltage_training_regime_rmse",
            "r2": "03_voltage_training_regime_r2",
            "parity": "05_voltage_regime_parity",
        },
        "capacity_grav": {
            "rmse": "02_capacity_training_regime_rmse",
            "r2": "04_capacity_training_regime_r2",
            "parity": "06_capacity_regime_parity",
        },
    }
    log("generating figures ...")
    for target in TARGETS:
        figure_regime_bars(pooled, target, "pooled_oof_RMSE",
                           FIG_DIR / FIGURE_NAMES[target]["rmse"], "pooled OOF RMSE")
        figure_regime_bars(pooled, target, "pooled_oof_R2",
                           FIG_DIR / FIGURE_NAMES[target]["r2"], "pooled OOF R2")
        figure_regime_parity(oof_preds, pooled, target,
                             FIG_DIR / FIGURE_NAMES[target]["parity"])

    # ---- summary ----------------------------------------------------------------------------
    elapsed = time.perf_counter() - overall_started
    lines: list[str] = []
    lines.append("Phase 11 - Zn training-regime comparison summary")
    lines.append("=" * 70)
    lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")
    lines.append("")
    lines.append(f"Zn rows: {len(zn_df)}")
    lines.append(f"Zn framework groups: {int(zn_groups.nunique())}")
    lines.append(f"CORE_NUMERIC feature count: {len(features)}")
    lines.append(f"fixed CatBoost Phase 9 parameters:")
    for target in TARGETS:
        lines.append(f"    [{target}] {json.dumps(catboost_params[target], default=str)}")
    lines.append(f"five fixed Zn validation fold sizes: {fold_sizes}")
    lines.append("")
    lines.append("per target / regime results:")
    for target in TARGETS:
        for regime in REGIMES:
            fold_sub = fold_metrics[
                (fold_metrics["target"] == target) & (fold_metrics["regime"] == regime)
            ]
            pooled_row = pooled[
                (pooled["target"] == target) & (pooled["regime"] == regime)
            ].iloc[0]
            lines.append(
                f"    [{target}] {regime}: mean fold RMSE="
                f"{np.mean(fold_sub['RMSE']):.4f}+/-{np.std(fold_sub['RMSE']):.4f}, "
                f"pooled OOF R2={pooled_row['pooled_oof_R2']:.4f}, "
                f"RMSE={pooled_row['pooled_oof_RMSE']:.4f}, "
                f"MAE={pooled_row['pooled_oof_MAE']:.4f}, "
                f"r={pooled_row['pooled_oof_Pearson_r']:.4f}"
            )
    lines.append("")
    lines.append(f"ZN_ONLY vs Phase 10 consistency QA: "
                 f"{'PASS (within 1e-6)' if consistency_ok else 'FAIL'}")
    lines.append("framework group overlap (train vs validation): 0 for every fold x regime")
    lines.append("")
    lines.append("deployment regime ranking (pooled OOF RMSE ascending):")
    for _, row in ranking.iterrows():
        lines.append(
            f"    [{row['target']}] rank {int(row['rank'])}: {row['regime']} "
            f"(RMSE={row['pooled_oof_RMSE']:.4f}, R2={row['pooled_oof_R2']:.4f}, "
            f"eligible={row['eligible_for_final_deployment']})"
        )
    for target in TARGETS:
        lines.append(f"    recommended deployment regime for {target}: {recommended[target]}")
    lines.append("")
    lines.append("output files:")
    for path in (
        OUT_FOLD_METRICS, OUT_POOLED, OUT_RANKING, OUT_OOF_PREDS, FIG_DIR, OUT_SUMMARY,
    ):
        lines.append(f"    {path.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append("")
    lines.append("policy statements:")
    lines.append("    Phase 11 does not re-tune hyperparameters.")
    lines.append("    Phase 9 CatBoost model identity remains fixed.")
    lines.append("    All regimes are evaluated on exactly the same Zn validation folds.")
    lines.append("    Framework overlap with each Zn validation fold is forbidden.")
    lines.append("    NONZN_ONLY_GROUP_SAFE is diagnostic only.")
    lines.append("    Final deployment regime is selected only between")
    lines.append("    ZN_ONLY and MIXED_ION_GROUP_SAFE.")
    lines.append("")
    lines.append("    No candidate screening was performed.")
    lines.append("    No final candidate model was refit.")
    lines.append("")
    lines.append(f"runtime: {elapsed:.1f} s")
    lines.append("")
    OUT_SUMMARY.write_text("\\n".join(lines), encoding="utf-8")
    log(f"Saved training-regime summary -> {OUT_SUMMARY}")

    # ---- console ------------------------------------------------------------------------------
    print("")
    print("Phase 11 Zn training-regime comparison completed.")
    for target, tag in (("average_voltage", "Voltage"), ("capacity_grav", "Capacity")):
        print(f"{tag}:")
        for regime in REGIMES:
            row = pooled[(pooled["target"] == target) & (pooled["regime"] == regime)].iloc[0]
            print(f"  {regime} RMSE: {row['pooled_oof_RMSE']:.4f}")
        print(f"  recommended deployment regime: {recommended[target]}")
    print(f"outputs: {METRICS_DIR}")
    print(f"         {PRED_DIR}")
    print(f"         {FIG_DIR}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
''',
    12: '''# -*- coding: utf-8 -*-
"""
Phase 12 - Paired bootstrap uncertainty analysis of the Phase 11 Zn
deployment training-regime comparison (ZN_ONLY vs MIXED_ION_GROUP_SAFE).

This phase performs NO model fitting, NO prediction, NO hyperparameter
tuning and NO fold regeneration. It only analyzes the Phase 11 OOF
predictions that were already saved.

    * PRIMARY uncertainty analysis  : paired FRAMEWORK-CLUSTER bootstrap
      (the generalization unit is the unseen framework, so whole frameworks
      - with all of their records - are resampled together; both regimes use
      the SAME resampled framework sequence = paired).
    * SECONDARY sensitivity analysis: paired RECORD-LEVEL bootstrap
      (same resampled record indices for both regimes).

Fixed delta definitions (MIXED_ION_GROUP_SAFE minus ZN_ONLY):
    delta_RMSE / delta_MAE  : delta < 0 means MIXED better
    delta_R2 / delta_Pearson_r : delta > 0 means MIXED better

p_mixed_better is an empirical bootstrap direction probability, NOT a
frequentist p-value.

Outputs:
    05_Results/Uncertainty/Phase12_Training_Regime/
        framework_cluster_bootstrap_summary.csv
        record_level_bootstrap_summary.csv
        framework_cluster_bootstrap_distribution.csv
        record_level_bootstrap_distribution.csv
        samplewise_error_comparison.csv
        foldwise_regime_differences.csv
        training_regime_uncertainty_context.csv
        phase12_bootstrap_summary.txt
    06_Figures/Draft_Figures/Phase12_Training_Regime/
        01..06 PNG (600 dpi) + PDF

Run from the project root:
    py 03_Code/Uncertainty/12_bootstrap_training_regime_uncertainty.py
"""

from __future__ import annotations

import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

# ---------------------------------------------------------------------------
# Paths
# ---------------------------------------------------------------------------
PROJECT_ROOT = Path(_SCIENCE_WORK_ROOT)

IN_OOF_PREDS = PROJECT_ROOT / "05_Results" / "Predictions" / "Phase11_Training_Regime" / "training_regime_oof_predictions.csv"
IN_ZN_FOLDS = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "zn_group_cv_folds.csv"
IN_P11_POOLED = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase11_Training_Regime" / "training_regime_pooled_oof_metrics.csv"

OUT_DIR = PROJECT_ROOT / "05_Results" / "Uncertainty" / "Phase12_Training_Regime"
OUT_CLUSTER_SUMMARY = OUT_DIR / "framework_cluster_bootstrap_summary.csv"
OUT_RECORD_SUMMARY = OUT_DIR / "record_level_bootstrap_summary.csv"
OUT_CLUSTER_DIST = OUT_DIR / "framework_cluster_bootstrap_distribution.csv"
OUT_RECORD_DIST = OUT_DIR / "record_level_bootstrap_distribution.csv"
OUT_SAMPLEWISE = OUT_DIR / "samplewise_error_comparison.csv"
OUT_FOLDWISE = OUT_DIR / "foldwise_regime_differences.csv"
OUT_CONTEXT = OUT_DIR / "training_regime_uncertainty_context.csv"
OUT_SUMMARY = OUT_DIR / "phase12_bootstrap_summary.txt"

FIG_DIR = PROJECT_ROOT / "06_Figures" / "Draft_Figures" / "Phase12_Training_Regime"

TARGETS = ("average_voltage", "capacity_grav")
REGIMES_REQUIRED = ("ZN_ONLY", "MIXED_ION_GROUP_SAFE", "NONZN_ONLY_GROUP_SAFE")
PAIRED_REGIMES = ("ZN_ONLY", "MIXED_ION_GROUP_SAFE")
METRICS = ("RMSE", "MAE", "R2", "Pearson_r")
N_BOOTSTRAP = 50000
SEED = 42

# lower-is-better metrics: p_mixed_better = P(delta < 0); others P(delta > 0)
LOWER_IS_BETTER = {"RMSE", "MAE"}


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------
def log(message: str) -> None:
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S")
    print(f"[{stamp}Z] {message}", flush=True)


def sig6(value) -> float | None:
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
        return float(f"{float(value):.6g}")
    except (TypeError, ValueError):
        return None


def compute_metrics(y_true: np.ndarray, y_pred: np.ndarray) -> dict:
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    try:
        pearson = float(np.corrcoef(y_true, y_pred)[0, 1])
    except Exception:  # noqa: BLE001
        pearson = np.nan
    return {
        "RMSE": float(np.sqrt(np.mean((y_true - y_pred) ** 2))),
        "MAE": float(np.mean(np.abs(y_true - y_pred))),
        "R2": float(1.0 - np.sum((y_true - y_pred) ** 2) / np.sum((y_true - np.mean(y_true)) ** 2)),
        "Pearson_r": pearson,
    }


def atomic_to_csv(df: pd.DataFrame, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    df.to_csv(tmp, index=False, encoding="utf-8-sig")
    os.replace(tmp, path)
    log(f"Saved {len(df)} rows -> {path}")


def save_figure(fig, path: Path) -> None:
    fig.tight_layout()
    fig.savefig(path.with_suffix(".png"), dpi=600)
    fig.savefig(path.with_suffix(".pdf"))
    plt.close(fig)
    log(f"  saved figure: {path.name}.png/.pdf")


def read_required(path: Path) -> pd.DataFrame:
    if not path.is_file():
        log(f"ERROR: required input file not found: {path}")
        sys.exit(1)
    return pd.read_csv(path, low_memory=False)


# ---------------------------------------------------------------------------
# Paired bootstrap engine (shared by cluster and record variants)
# ---------------------------------------------------------------------------
def paired_bootstrap_deltas(y: np.ndarray, pred_zn: np.ndarray, pred_mix: np.ndarray,
                            unit_codes: np.ndarray, n_boot: int, seed: int) -> dict[str, np.ndarray]:
    """Resample whole units with replacement; SAME unit sequence for both
    regimes (paired). Returns delta arrays per metric (MIXED - ZN_ONLY)."""
    units = np.unique(unit_codes)
    n_units = len(units)
    rng = np.random.default_rng(seed)
    samples = rng.integers(0, n_units, size=(n_boot, n_units))
    counts = np.array([np.bincount(row, minlength=n_units) for row in samples], dtype=np.float64)

    def aggregate(values: np.ndarray) -> np.ndarray:
        out = np.zeros(n_units, dtype=np.float64)
        np.add.at(out, unit_codes, values)
        return out

    def regime_stats(pred: np.ndarray) -> dict[str, np.ndarray]:
        err = y - pred
        n_vec = aggregate(np.ones(len(y)))
        sy = aggregate(y)
        se = aggregate(err)
        see = aggregate(err ** 2)
        sae = aggregate(np.abs(err))
        syy = aggregate(y ** 2)
        sye = aggregate(y * err)
        w = counts @ n_vec
        wsy = counts @ sy
        wse = counts @ se
        wsee = counts @ see
        wsae = counts @ sae
        wsyy = counts @ syy
        wsye = counts @ sye

        rmse = np.sqrt(wsee / w)
        mae = wsae / w
        sst = wsyy - (wsy ** 2) / w
        r2 = 1.0 - wsee / sst
        # Pearson(y, y_pred) with y_pred = y - err
        syh = wsy - wse
        syh2 = wsyy - 2.0 * wsye + wsee
        syyh = wsyy - wsye
        cov_num = w * syyh - wsy * syh
        denom = np.sqrt((w * wsyy - wsy ** 2) * (w * syh2 - syh ** 2))
        pearson = cov_num / denom
        return {"RMSE": rmse, "MAE": mae, "R2": r2, "Pearson_r": pearson}

    stats_zn = regime_stats(pred_zn)
    stats_mix = regime_stats(pred_mix)
    deltas = {
        metric: stats_mix[metric] - stats_zn[metric] for metric in METRICS
    }
    return deltas


def summarize_deltas(deltas: dict[str, np.ndarray]) -> dict[str, dict]:
    out = {}
    for metric in METRICS:
        values = deltas[metric]
        lower, upper = np.percentile(values, [2.5, 97.5])
        if metric in LOWER_IS_BETTER:
            p_mixed_better = float(np.mean(values < 0))
        else:
            p_mixed_better = float(np.mean(values > 0))
        out[metric] = {
            "bootstrap_mean": float(np.mean(values)),
            "bootstrap_median": float(np.median(values)),
            "CI_lower_95": float(lower),
            "CI_upper_95": float(upper),
            "ci_excludes_zero": bool(lower > 0 or upper < 0),
            "p_mixed_better": p_mixed_better,
        }
    return out


# ---------------------------------------------------------------------------
# Figures
# ---------------------------------------------------------------------------
def figure_bootstrap_hist(deltas: np.ndarray, metric: str, target: str,
                          point_estimate: float, summary_row: dict,
                          path: Path, title_suffix: str) -> None:
    fig, ax = plt.subplots(figsize=(9, 5.5))
    ax.hist(deltas, bins=100, color="#4C72B0", alpha=0.85)
    ax.axvline(0.0, color="black", lw=1.2, label="delta = 0")
    ax.axvline(point_estimate, color="#C44E52", lw=1.5, ls="--", label="point estimate")
    ax.axvspan(summary_row["CI_lower_95"], summary_row["CI_upper_95"],
               color="orange", alpha=0.25, label="95% bootstrap CI")
    ax.set_xlabel(f"delta {metric} (MIXED - ZN_ONLY)")
    ax.set_ylabel("bootstrap count")
    ax.set_title(
        f"{target}: delta {metric} - {title_suffix}"
    )
    ax.text(
        0.98, 0.97,
        f"point={point_estimate:.4f}\\n95% CI=[{summary_row['CI_lower_95']:.4f}, "
        f"{summary_row['CI_upper_95']:.4f}]\\np_mixed_better={summary_row['p_mixed_better']:.3f}",
        transform=ax.transAxes, ha="right", va="top", fontsize=8,
        bbox=dict(boxstyle="round", facecolor="white", alpha=0.8),
    )
    ax.legend(fontsize=8)
    save_figure(fig, path)


def figure_samplewise_hist(samplewise: pd.DataFrame, target: str, path: Path) -> None:
    sub = samplewise[samplewise["target"] == target]
    fig, ax = plt.subplots(figsize=(9, 5.5))
    ax.hist(sub["delta_abs_error"], bins=80, color="#55A868", alpha=0.85)
    ax.axvline(0.0, color="black", lw=1.2, label="delta = 0 (equal)")
    n_mixed = int((sub["delta_abs_error"] < 0).sum())
    n_zn = int((sub["delta_abs_error"] > 0).sum())
    fraction = n_mixed / len(sub) if len(sub) else np.nan
    ax.set_xlabel("delta absolute error (MIXED - ZN_ONLY)")
    ax.set_ylabel("record count")
    ax.set_title(f"{target}: samplewise absolute-error difference (MIXED vs ZN_ONLY)")
    ax.text(
        0.98, 0.97,
        f"MIXED lower: {n_mixed} ({fraction:.3f})\\nZN_ONLY lower: {n_zn}",
        transform=ax.transAxes, ha="right", va="top", fontsize=9,
        bbox=dict(boxstyle="round", facecolor="white", alpha=0.8),
    )
    ax.legend(fontsize=8)
    save_figure(fig, path)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    overall_started = time.perf_counter()
    log("Phase 12 - paired bootstrap uncertainty analysis (no fitting, no prediction)")

    # ---- 1. inputs ---------------------------------------------------------
    preds = read_required(IN_OOF_PREDS)
    zn_folds = read_required(IN_ZN_FOLDS)
    p11_pooled = read_required(IN_P11_POOLED)

    # ---- 2. OOF integrity QA --------------------------------------------------
    targets_present = set(preds["target"].unique())
    if targets_present != set(TARGETS):
        log(f"ERROR: targets must be exactly {TARGETS}; found {sorted(targets_present)}")
        return 1
    regimes_present = set(preds["regime"].unique())
    missing_regimes = [r for r in REGIMES_REQUIRED if r not in regimes_present]
    if missing_regimes:
        log(f"ERROR: missing regime(s) in OOF predictions: {missing_regimes}")
        return 1
    if int(preds.duplicated(subset=["record_uid", "target", "regime"]).sum()):
        log("ERROR: duplicate record_uid x target x regime entries found")
        return 1
    for column in ("record_uid", "target", "regime", "cv_fold", "y_true", "y_pred"):
        if column not in preds.columns:
            log(f"ERROR: OOF predictions missing column '{column}'")
            return 1

    # per-target regime sizes must be identical; ZN_ONLY vs MIXED fully aligned
    per_target_counts: dict[str, dict[str, int]] = {}
    for target in TARGETS:
        counts = {}
        for regime in REGIMES_REQUIRED:
            counts[regime] = int(((preds["target"] == target) & (preds["regime"] == regime)).sum())
        if len(set(counts.values())) != 1:
            log(f"ERROR: regime record counts differ for {target}: {counts}")
            return 1
        per_target_counts[target] = counts

        zn = preds[(preds["target"] == target) & (preds["regime"] == "ZN_ONLY")].sort_values("record_uid").reset_index(drop=True)
        mix = preds[(preds["target"] == target) & (preds["regime"] == "MIXED_ION_GROUP_SAFE")].sort_values("record_uid").reset_index(drop=True)
        if not (
            np.array_equal(zn["record_uid"].to_numpy(), mix["record_uid"].to_numpy())
            and np.array_equal(zn["cv_fold"].to_numpy(), mix["cv_fold"].to_numpy())
            and np.allclose(zn["y_true"].to_numpy(dtype=float), mix["y_true"].to_numpy(dtype=float))
        ):
            log(f"ERROR: ZN_ONLY vs MIXED record_uid/cv_fold/y_true are not identical for {target}")
            return 1
    log(
        f"OOF QA passed: targets={sorted(targets_present)}, regimes={sorted(regimes_present)}, "
        f"record counts={ {t: per_target_counts[t]['ZN_ONLY'] for t in TARGETS} }"
    )

    # ---- 3. merge framework groups -----------------------------------------------
    if "group_framework_formula" not in zn_folds.columns:
        log("ERROR: zn_group_cv_folds.csv has no group_framework_formula column")
        return 1
    preds = preds.merge(
        zn_folds[["record_uid", "group_framework_formula"]],
        on="record_uid", how="left",
    )
    n_unmatched = int(preds["group_framework_formula"].isna().sum())
    if n_unmatched:
        log(f"ERROR: {n_unmatched} prediction record(s) could not be matched to a framework group")
        return 1
    n_zn_records = per_target_counts[TARGETS[0]]["ZN_ONLY"]
    n_groups = int(preds["group_framework_formula"].nunique())
    log(f"Zn records per regime: {n_zn_records}; unique framework groups: {n_groups}")

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    FIG_DIR.mkdir(parents=True, exist_ok=True)

    # ---- 10. samplewise error comparison --------------------------------------------
    samplewise_rows: list[dict] = []
    foldwise_rows: list[dict] = []
    point_metrics: dict[str, dict[str, dict]] = {}
    p11_consistency_ok = True

    for target in TARGETS:
        zn = preds[(preds["target"] == target) & (preds["regime"] == "ZN_ONLY")].sort_values("record_uid").reset_index(drop=True)
        mix = preds[(preds["target"] == target) & (preds["regime"] == "MIXED_ION_GROUP_SAFE")].sort_values("record_uid").reset_index(drop=True)
        nonzn = preds[(preds["target"] == target) & (preds["regime"] == "NONZN_ONLY_GROUP_SAFE")].sort_values("record_uid").reset_index(drop=True)

        y = zn["y_true"].to_numpy(dtype=float)
        pred_zn = zn["y_pred"].to_numpy(dtype=float)
        pred_mix = mix["y_pred"].to_numpy(dtype=float)

        ae_zn = np.abs(y - pred_zn)
        ae_mix = np.abs(y - pred_mix)
        for i in range(len(y)):
            samplewise_rows.append(
                {
                    "record_uid": zn["record_uid"].iloc[i],
                    "group_framework_formula": zn["group_framework_formula"].iloc[i],
                    "cv_fold": int(zn["cv_fold"].iloc[i]),
                    "target": target,
                    "y_true": y[i],
                    "pred_ZN": pred_zn[i],
                    "pred_MIXED": pred_mix[i],
                    "abs_error_ZN": sig6(ae_zn[i]),
                    "abs_error_MIXED": sig6(ae_mix[i]),
                    "delta_abs_error": sig6(ae_mix[i] - ae_zn[i]),
                    "sq_error_ZN": sig6((y[i] - pred_zn[i]) ** 2),
                    "sq_error_MIXED": sig6((y[i] - pred_mix[i]) ** 2),
                    "delta_sq_error": sig6((y[i] - pred_mix[i]) ** 2 - (y[i] - pred_zn[i]) ** 2),
                }
            )

        # ---- 11. foldwise descriptive comparison -------------------------------------
        for fold in range(5):
            f_zn = zn[zn["cv_fold"] == fold]
            f_mix = mix[mix["cv_fold"] == fold]
            m_zn = compute_metrics(f_zn["y_true"].to_numpy(), f_zn["y_pred"].to_numpy())
            m_mix = compute_metrics(f_mix["y_true"].to_numpy(), f_mix["y_pred"].to_numpy())
            foldwise_rows.append(
                {
                    "target": target,
                    "cv_fold": fold,
                    "delta_RMSE": sig6(m_mix["RMSE"] - m_zn["RMSE"]),
                    "delta_MAE": sig6(m_mix["MAE"] - m_zn["MAE"]),
                    "delta_R2": sig6(m_mix["R2"] - m_zn["R2"]),
                    "delta_Pearson_r": sig6(m_mix["Pearson_r"] - m_zn["Pearson_r"]),
                }
            )

        # ---- 12. point estimates + Phase 11 consistency ---------------------------------
        point_metrics[target] = {}
        for regime, frame in (("ZN_ONLY", zn), ("MIXED_ION_GROUP_SAFE", mix)):
            point_metrics[target][regime] = compute_metrics(
                frame["y_true"].to_numpy(dtype=float), frame["y_pred"].to_numpy(dtype=float)
            )
        for regime, ours in point_metrics[target].items():
            theirs_row = p11_pooled[
                (p11_pooled["target"] == target) & (p11_pooled["regime"] == regime)
            ]
            if theirs_row.empty:
                log(f"ERROR: Phase 11 pooled row missing for {target} / {regime}")
                return 1
            theirs = theirs_row.iloc[0]
            for metric, col in (("RMSE", "pooled_oof_RMSE"), ("R2", "pooled_oof_R2"),
                                ("MAE", "pooled_oof_MAE"), ("Pearson_r", "pooled_oof_Pearson_r")):
                # Phase 11 saved its metrics after sig6() rounding, so compare
                # at the SAME saved precision instead of full float vs rounded CSV.
                ours_rounded = sig6(ours[metric])
                saved_value = float(theirs[col])
                if ours_rounded is None or not np.isclose(
                    float(ours_rounded), saved_value, rtol=0.0, atol=1e-12
                ):
                    log(f"ERROR: Phase 11 consistency failed for {target}/{regime}/{metric}: "
                        f"recomputed(sig6)={ours_rounded}, saved={saved_value}")
                    p11_consistency_ok = False
        log(f"Phase 11 consistency [{target}]: {'PASS' if p11_consistency_ok else 'FAIL'}")

    if not p11_consistency_ok:
        log("ERROR: Phase 11 pooled-metric consistency QA failed")
        return 1

    samplewise = pd.DataFrame(samplewise_rows)
    samplewise_stats = {}
    for target in TARGETS:
        sub = samplewise[samplewise["target"] == target]
        n_mixed = int((sub["delta_abs_error"] < 0).sum())
        n_zn = int((sub["delta_abs_error"] > 0).sum())
        samplewise_stats[target] = {
            "n_records_mixed_lower_abs_error": n_mixed,
            "n_records_zn_lower_abs_error": n_zn,
            "fraction_mixed_lower_abs_error": sig6(n_mixed / len(sub)),
        }

    # ---- 6/9. bootstraps (paired, vectorized) --------------------------------------------
    cluster_summary_rows: list[dict] = []
    record_summary_rows: list[dict] = []
    cluster_dist_rows: list[dict] = []
    record_dist_rows: list[dict] = []
    cluster_deltas_store: dict[str, dict[str, np.ndarray]] = {}

    for target in TARGETS:
        log(f"bootstrap [{target}] ...")
        zn = preds[(preds["target"] == target) & (preds["regime"] == "ZN_ONLY")].sort_values("record_uid").reset_index(drop=True)
        mix = preds[(preds["target"] == target) & (preds["regime"] == "MIXED_ION_GROUP_SAFE")].sort_values("record_uid").reset_index(drop=True)
        y = zn["y_true"].to_numpy(dtype=float)
        pred_zn = zn["y_pred"].to_numpy(dtype=float)
        pred_mix = mix["y_pred"].to_numpy(dtype=float)

        group_values = zn["group_framework_formula"].to_numpy()
        _, unit_codes_cluster = np.unique(group_values, return_inverse=True)
        unit_codes_record = np.arange(len(y), dtype=np.int64)

        t0 = time.perf_counter()
        cluster_deltas = paired_bootstrap_deltas(
            y, pred_zn, pred_mix, unit_codes_cluster, N_BOOTSTRAP, SEED
        )
        log(f"  framework-cluster bootstrap done in {time.perf_counter()-t0:.1f}s")
        t0 = time.perf_counter()
        record_deltas = paired_bootstrap_deltas(
            y, pred_zn, pred_mix, unit_codes_record, N_BOOTSTRAP, SEED
        )
        log(f"  record-level bootstrap done in {time.perf_counter()-t0:.1f}s")

        cluster_deltas_store[target] = cluster_deltas
        cluster_summary = summarize_deltas(cluster_deltas)
        record_summary = summarize_deltas(record_deltas)

        for metric in METRICS:
            point_zn = point_metrics[target]["ZN_ONLY"][metric]
            point_mix = point_metrics[target]["MIXED_ION_GROUP_SAFE"][metric]
            point_delta = point_mix - point_zn
            cluster_summary_rows.append(
                {
                    "target": target,
                    "metric": metric,
                    "ZN_ONLY_point": sig6(point_zn),
                    "MIXED_point": sig6(point_mix),
                    "point_delta": sig6(point_delta),
                    "bootstrap_mean": sig6(cluster_summary[metric]["bootstrap_mean"]),
                    "bootstrap_median": sig6(cluster_summary[metric]["bootstrap_median"]),
                    "CI_lower_95": sig6(cluster_summary[metric]["CI_lower_95"]),
                    "CI_upper_95": sig6(cluster_summary[metric]["CI_upper_95"]),
                    "ci_excludes_zero": cluster_summary[metric]["ci_excludes_zero"],
                    "p_mixed_better": sig6(cluster_summary[metric]["p_mixed_better"]),
                }
            )
            record_summary_rows.append(
                {
                    "target": target,
                    "metric": metric,
                    "point_delta": sig6(point_delta),
                    "bootstrap_mean": sig6(record_summary[metric]["bootstrap_mean"]),
                    "bootstrap_median": sig6(record_summary[metric]["bootstrap_median"]),
                    "CI_lower_95": sig6(record_summary[metric]["CI_lower_95"]),
                    "CI_upper_95": sig6(record_summary[metric]["CI_upper_95"]),
                    "ci_excludes_zero": record_summary[metric]["ci_excludes_zero"],
                    "p_mixed_better": sig6(record_summary[metric]["p_mixed_better"]),
                }
            )

        for it in range(N_BOOTSTRAP):
            cluster_dist_rows.append(
                {
                    "bootstrap_iteration": it,
                    "target": target,
                    "delta_RMSE": sig6(cluster_deltas["RMSE"][it]),
                    "delta_MAE": sig6(cluster_deltas["MAE"][it]),
                    "delta_R2": sig6(cluster_deltas["R2"][it]),
                    "delta_Pearson_r": sig6(cluster_deltas["Pearson_r"][it]),
                }
            )
            record_dist_rows.append(
                {
                    "bootstrap_iteration": it,
                    "target": target,
                    "delta_RMSE": sig6(record_deltas["RMSE"][it]),
                    "delta_MAE": sig6(record_deltas["MAE"][it]),
                    "delta_R2": sig6(record_deltas["R2"][it]),
                    "delta_Pearson_r": sig6(record_deltas["Pearson_r"][it]),
                }
            )

    cluster_summary_df = pd.DataFrame(cluster_summary_rows)
    record_summary_df = pd.DataFrame(record_summary_rows)
    cluster_dist_df = pd.DataFrame(cluster_dist_rows)
    record_dist_df = pd.DataFrame(record_dist_rows)

    # ---- 14. context table ----------------------------------------------------------------
    context_rows = []
    for target in TARGETS:
        for metric in METRICS:
            c = cluster_summary_df[
                (cluster_summary_df["target"] == target) & (cluster_summary_df["metric"] == metric)
            ].iloc[0]
            r = record_summary_df[
                (record_summary_df["target"] == target) & (record_summary_df["metric"] == metric)
            ].iloc[0]
            delta = c["point_delta"]
            if metric in LOWER_IS_BETTER:
                winner = "MIXED_ION_GROUP_SAFE" if delta < 0 else "ZN_ONLY"
            else:
                winner = "MIXED_ION_GROUP_SAFE" if delta > 0 else "ZN_ONLY"
            context_rows.append(
                {
                    "target": target,
                    "metric": metric,
                    "point_delta": c["point_delta"],
                    "cluster_CI_lower_95": c["CI_lower_95"],
                    "cluster_CI_upper_95": c["CI_upper_95"],
                    "cluster_ci_excludes_zero": c["ci_excludes_zero"],
                    "cluster_p_mixed_better": c["p_mixed_better"],
                    "record_CI_lower_95": r["CI_lower_95"],
                    "record_CI_upper_95": r["CI_upper_95"],
                    "record_p_mixed_better": r["p_mixed_better"],
                    "point_estimate_winner": winner,
                }
            )
    context = pd.DataFrame(context_rows)

    # ---- write outputs ----------------------------------------------------------------------
    atomic_to_csv(cluster_summary_df, OUT_CLUSTER_SUMMARY)
    atomic_to_csv(record_summary_df, OUT_RECORD_SUMMARY)
    atomic_to_csv(cluster_dist_df, OUT_CLUSTER_DIST)
    atomic_to_csv(record_dist_df, OUT_RECORD_DIST)
    atomic_to_csv(samplewise, OUT_SAMPLEWISE)
    atomic_to_csv(pd.DataFrame(foldwise_rows), OUT_FOLDWISE)
    atomic_to_csv(context, OUT_CONTEXT)

    # ---- 15. figures ---------------------------------------------------------------------------
    FIGURE_NAMES = {
        "average_voltage": {
            "rmse": "01_voltage_delta_rmse_cluster_bootstrap",
            "mae": "03_voltage_delta_mae_cluster_bootstrap",
            "samplewise": "05_voltage_samplewise_abs_error_delta",
        },
        "capacity_grav": {
            "rmse": "02_capacity_delta_rmse_cluster_bootstrap",
            "mae": "04_capacity_delta_mae_cluster_bootstrap",
            "samplewise": "06_capacity_samplewise_abs_error_delta",
        },
    }
    log("generating figures ...")
    for target in TARGETS:
        for metric, key in (("RMSE", "rmse"), ("MAE", "mae")):
            c = cluster_summary_df[
                (cluster_summary_df["target"] == target) & (cluster_summary_df["metric"] == metric)
            ].iloc[0]
            figure_bootstrap_hist(
                cluster_deltas_store[target][metric], metric, target, c["point_delta"], c,
                FIG_DIR / FIGURE_NAMES[target][key],
                "paired framework-cluster bootstrap",
            )
        figure_samplewise_hist(
            samplewise, target, FIG_DIR / FIGURE_NAMES[target]["samplewise"]
        )

    # ---- 16/17. summary ---------------------------------------------------------------------------
    elapsed = time.perf_counter() - overall_started
    lines: list[str] = []
    lines.append("Phase 12 - Paired bootstrap uncertainty analysis summary")
    lines.append("=" * 70)
    lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")
    lines.append("")
    lines.append(f"Zn record count: {n_zn_records}")
    lines.append(f"unique framework group count: {n_groups}")
    lines.append(f"bootstrap iterations: {N_BOOTSTRAP}")
    lines.append(f"seed: {SEED}")
    lines.append("primary method: paired framework-cluster bootstrap")
    lines.append("secondary method: paired record-level bootstrap")
    lines.append("")
    lines.append("delta definitions (MIXED_ION_GROUP_SAFE minus ZN_ONLY):")
    lines.append("    delta_RMSE / delta_MAE: delta < 0 means MIXED better")
    lines.append("    delta_R2 / delta_Pearson_r: delta > 0 means MIXED better")
    lines.append("")
    for target in TARGETS:
        lines.append(f"[{target}]")
        pz = point_metrics[target]["ZN_ONLY"]
        pm = point_metrics[target]["MIXED_ION_GROUP_SAFE"]
        lines.append(
            f"    ZN_ONLY pooled: R2={pz['R2']:.4f}, RMSE={pz['RMSE']:.4f}, "
            f"MAE={pz['MAE']:.4f}, r={pz['Pearson_r']:.4f}"
        )
        lines.append(
            f"    MIXED_ION_GROUP_SAFE pooled: R2={pm['R2']:.4f}, RMSE={pm['RMSE']:.4f}, "
            f"MAE={pm['MAE']:.4f}, r={pm['Pearson_r']:.4f}"
        )
        for metric in METRICS:
            c = cluster_summary_df[
                (cluster_summary_df["target"] == target) & (cluster_summary_df["metric"] == metric)
            ].iloc[0]
            if metric in LOWER_IS_BETTER:
                better_side = "delta < 0 -> MIXED better"
            else:
                better_side = "delta > 0 -> MIXED better"
            if c["ci_excludes_zero"]:
                ci_phrase = "the 95% paired framework-cluster bootstrap interval excludes zero"
            else:
                ci_phrase = "the 95% paired framework-cluster bootstrap interval includes zero"
            lines.append(
                f"    delta {metric}: point={c['point_delta']:.4f}, "
                f"95% cluster CI=[{c['CI_lower_95']:.4f}, {c['CI_upper_95']:.4f}] "
                f"-> {ci_phrase}; p_mixed_better={c['p_mixed_better']:.3f} ({better_side})"
            )
        ss = samplewise_stats[target]
        lines.append(
            f"    samplewise: MIXED lower abs error on {ss['n_records_mixed_lower_abs_error']} "
            f"records, ZN_ONLY lower on {ss['n_records_zn_lower_abs_error']}, "
            f"fraction MIXED lower = {ss['fraction_mixed_lower_abs_error']:.3f}"
        )
        lines.append("")
    lines.append("notes:")
    lines.append("    p_mixed_better is an empirical bootstrap direction probability,")
    lines.append("    not a frequentist p-value.")
    lines.append("    Foldwise differences over 5 folds are descriptive only;")
    lines.append("    no significance claims are made from 5 folds.")
    lines.append(f"    Phase 11 point-estimate consistency QA: "
                 f"{'PASS' if p11_consistency_ok else 'FAIL'}")
    lines.append("")
    lines.append("policy statements:")
    lines.append("    Phase 12 performs no model fitting.")
    lines.append("    Phase 12 performs no hyperparameter tuning.")
    lines.append("    No validation fold was regenerated.")
    lines.append("    The Phase 10/11 framework grouping is reused unchanged.")
    lines.append("    Framework-cluster bootstrap is the primary uncertainty analysis.")
    lines.append("    Record-level bootstrap is secondary.")
    lines.append("    Phase 12 does not override the Phase 11 point-estimate ranking.")
    lines.append("    No candidate screening was performed.")
    lines.append("    No final deployment model was refit.")
    lines.append("")
    lines.append(f"runtime: {elapsed:.1f} s")
    lines.append("")
    OUT_SUMMARY.write_text("\\n".join(lines), encoding="utf-8")
    log(f"Saved bootstrap summary -> {OUT_SUMMARY}")

    # ---- 18. console ----------------------------------------------------------------------------
    print("")
    print("Phase 12 paired bootstrap uncertainty analysis completed.")
    for target, tag in (("average_voltage", "Voltage"), ("capacity_grav", "Capacity")):
        c = cluster_summary_df[
            (cluster_summary_df["target"] == target) & (cluster_summary_df["metric"] == "RMSE")
        ].iloc[0]
        ci_status = "excludes zero" if c["ci_excludes_zero"] else "includes zero"
        print(f"{tag}:")
        print(f"  delta RMSE: {c['point_delta']:.4f}")
        print(f"  cluster 95% CI: [{c['CI_lower_95']:.4f}, {c['CI_upper_95']:.4f}] ({ci_status})")
        print(f"  p_mixed_better: {c['p_mixed_better']:.3f}")
    print(f"outputs: {OUT_DIR}")
    print(f"figures: {FIG_DIR}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
''',
    13: '''# -*- coding: utf-8 -*-
"""
Phase 13 - Feature-group ablation analysis of the frozen final deployment
CatBoost strategies.

Frozen configuration (NOT re-decided here):
    average_voltage: CatBoost, deployment regime MIXED_ION_GROUP_SAFE
    capacity_grav:    CatBoost, deployment regime ZN_ONLY
    CatBoost hyperparameters: Phase 9 best parameters (no search of any kind)
    Validation folds: the fixed Phase 10 Zn cv_fold 0-4 labels

Feature groups are defined BY NAME (never by positional slicing):
    MP_INTRINSIC : mp_* features except mp_spacegroup_number
    SYMMETRY    : mp_spacegroup_number
    COMPOSITION : comp_* features
    WORKING_ION : ion_* features
QA: the four groups are disjoint and their union equals the 53 CORE_NUMERIC
features exactly, otherwise ERROR.

Ablation subsets are compared against each target's FULL_CORE baseline using
pooled OOF RMSE/R2 (degradation = delta RMSE > 0 / delta R2 < 0). Feature-group
ablation measures PREDICTIVE performance impact, not causal importance.

Outputs:
    05_Results/Ablation/Phase13_Feature_Groups/
        feature_group_definition.csv
        feature_subset_definition.csv
        feature_ablation_fold_metrics.csv
        feature_ablation_pooled_oof_metrics.csv
        feature_ablation_vs_full.csv
        phase13_feature_ablation_summary.txt
    05_Results/Predictions/Phase13_Feature_Groups/
        feature_ablation_oof_predictions.csv
    06_Figures/Draft_Figures/Phase13_Feature_Groups/
        01..08 PNG (600 dpi) + PDF

Run from the project root:
    py 03_Code/Model_Interpretation/13_feature_group_ablation.py
"""

from __future__ import annotations

import json
import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

from sklearn.pipeline import Pipeline
from sklearn.impute import SimpleImputer
from sklearn.metrics import r2_score, mean_squared_error, mean_absolute_error

try:
    from catboost import CatBoostRegressor
    CATBOOST_AVAILABLE = True
except ImportError:  # pragma: no cover
    CatBoostRegressor = None  # type: ignore[assignment]
    CATBOOST_AVAILABLE = False

# ---------------------------------------------------------------------------
# Paths
# ---------------------------------------------------------------------------
PROJECT_ROOT = Path(_SCIENCE_WORK_ROOT)

IN_ALL_FEATURES = PROJECT_ROOT / "02_Datasets" / "Features" / "all_battery_candidate_compatible_features.csv"
IN_ZN_FEATURES = PROJECT_ROOT / "02_Datasets" / "Features" / "zinc_battery_candidate_compatible_features.csv"
IN_CORE_SET = PROJECT_ROOT / "02_Datasets" / "Features" / "Feature_Sets" / "core_numeric_features.csv"
IN_PRIMARY = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "primary_group_holdout.csv"
IN_ZN_FOLDS = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "zn_group_cv_folds.csv"
IN_MANIFEST = PROJECT_ROOT / "05_Results" / "Feature_Engineering" / "candidate_compatible_feature_manifest.csv"
IN_BEST_PARAMS = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase9_Tuning" / "best_hyperparameters.csv"
IN_P11_POOLED = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase11_Training_Regime" / "training_regime_pooled_oof_metrics.csv"
IN_P12_CONTEXT = PROJECT_ROOT / "05_Results" / "Uncertainty" / "Phase12_Training_Regime" / "training_regime_uncertainty_context.csv"

OUT_DIR = PROJECT_ROOT / "05_Results" / "Ablation" / "Phase13_Feature_Groups"
OUT_GROUP_DEF = OUT_DIR / "feature_group_definition.csv"
OUT_SUBSET_DEF = OUT_DIR / "feature_subset_definition.csv"
OUT_FOLD_METRICS = OUT_DIR / "feature_ablation_fold_metrics.csv"
OUT_POOLED = OUT_DIR / "feature_ablation_pooled_oof_metrics.csv"
OUT_VS_FULL = OUT_DIR / "feature_ablation_vs_full.csv"
OUT_SUMMARY = OUT_DIR / "phase13_feature_ablation_summary.txt"

PRED_DIR = PROJECT_ROOT / "05_Results" / "Predictions" / "Phase13_Feature_Groups"
OUT_OOF_PREDS = PRED_DIR / "feature_ablation_oof_predictions.csv"

FIG_DIR = PROJECT_ROOT / "06_Figures" / "Draft_Figures" / "Phase13_Feature_Groups"

TARGETS = ("average_voltage", "capacity_grav")
MODEL_NAME = "CatBoost"
DEPLOYMENT_REGIME = {
    "average_voltage": "MIXED_ION_GROUP_SAFE",
    "capacity_grav": "ZN_ONLY",
}

FORBIDDEN_IN_FEATURES = {
    "average_voltage",
    "capacity_grav",
    "capacity_vol",
    "energy_grav",
    "energy_vol",
}

SYMMETRY_GROUP = {"mp_spacegroup_number"}

# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------
def log(message: str) -> None:
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S")
    print(f"[{stamp}Z] {message}", flush=True)


def sig6(value) -> float | None:
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
        return float(f"{float(value):.6g}")
    except (TypeError, ValueError):
        return None


def compute_metrics(y_true, y_pred) -> dict:
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    try:
        pearson = float(np.corrcoef(y_true, y_pred)[0, 1])
    except Exception:  # noqa: BLE001
        pearson = np.nan
    return {
        "R2": sig6(r2_score(y_true, y_pred)),
        "RMSE": sig6(float(np.sqrt(mean_squared_error(y_true, y_pred)))),
        "MAE": sig6(mean_absolute_error(y_true, y_pred)),
        "Pearson_r": sig6(pearson),
    }


def atomic_to_csv(df: pd.DataFrame, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    df.to_csv(tmp, index=False, encoding="utf-8-sig")
    os.replace(tmp, path)
    log(f"Saved {len(df)} rows -> {path}")


def save_figure(fig, path: Path) -> None:
    fig.tight_layout()
    fig.savefig(path.with_suffix(".png"), dpi=600)
    fig.savefig(path.with_suffix(".pdf"))
    plt.close(fig)
    log(f"  saved figure: {path.name}.png/.pdf")


def read_required(path: Path) -> pd.DataFrame:
    if not path.is_file():
        log(f"ERROR: required input file not found: {path}")
        sys.exit(1)
    return pd.read_csv(path, low_memory=False)


def make_catboost_pipeline(params: dict) -> Pipeline:
    model = CatBoostRegressor(
        loss_function="RMSE",
        random_seed=42,
        verbose=False,
        allow_writing_files=False,
        thread_count=1,
    )
    pipeline = Pipeline([("imputer", SimpleImputer(strategy="median")), ("model", model)])
    pipeline.set_params(**params)
    return pipeline


# ---------------------------------------------------------------------------
# Feature group / subset construction (by name, never by position)
# ---------------------------------------------------------------------------
def define_groups(features: list[str]) -> dict[str, list[str]]:
    mp_intrinsic = [f for f in features if f.startswith("mp_") and f != "mp_spacegroup_number"]
    symmetry = [f for f in features if f == "mp_spacegroup_number"]
    composition = [f for f in features if f.startswith("comp_")]
    ion = [f for f in features if f.startswith("ion_")]
    groups = {
        "MP_INTRINSIC": mp_intrinsic,
        "SYMMETRY": symmetry,
        "COMPOSITION": composition,
        "WORKING_ION": ion,
    }
    return groups


def define_subsets(features: list[str], groups: dict[str, list[str]]) -> dict[str, list[str]]:
    full = set(features)
    mp, sym, comp, ion = (
        set(groups["MP_INTRINSIC"]),
        set(groups["SYMMETRY"]),
        set(groups["COMPOSITION"]),
        set(groups["WORKING_ION"]),
    )
    specs = {
        "FULL_CORE": full,
        "NO_MP_INTRINSIC": full - mp,
        "NO_COMPOSITION": full - comp,
        "NO_WORKING_ION": full - ion,
        "NO_SYMMETRY": full - sym,
        "COMPOSITION_ONLY": comp,
        "MP_INTRINSIC_ONLY": mp,
        "MP_PLUS_COMPOSITION": mp | sym | comp,
    }
    # keep deterministic order: CORE order filtered by membership
    core_set = set(features)
    return {
        name: [f for f in features if f in subset and f in core_set]
        for name, subset in specs.items()
    }


def deduplicate_subsets(subsets: dict[str, list[str]]) -> tuple[dict[str, list[str]], dict[str, str]]:
    """Return (unique_subsets, alias_map): duplicate sets are trained once."""
    unique: dict[str, list[str]] = {}
    alias: dict[str, str] = {}
    seen: dict[frozenset, str] = {}
    for name, feats in subsets.items():
        key = frozenset(feats)
        if key in seen:
            alias[name] = seen[key]
        else:
            seen[key] = name
            unique[name] = feats
    return unique, alias


# ---------------------------------------------------------------------------
# Figures
# ---------------------------------------------------------------------------
def figure_ablation_bars(pooled: pd.DataFrame, target: str, metric: str,
                         subsets: list[str], path: Path, ylabel: str) -> None:
    sub = pooled[pooled["target"] == target].set_index("feature_subset")
    values = [sub.loc[s, metric] for s in subsets]
    fig, ax = plt.subplots(figsize=(11, 5.5))
    x = np.arange(len(subsets))
    ax.bar(x, values, color="#4C72B0")
    for i, v in enumerate(values):
        ax.text(i, v + 0.002, f"{v:.4f}", ha="center", fontsize=8)
    ax.set_xticks(x)
    ax.set_xticklabels(subsets, rotation=30, ha="right")
    ax.set_ylabel(ylabel)
    ax.set_title(f"{target}: feature-subset ablation ({ylabel}, pooled OOF)")
    save_figure(fig, path)


def figure_delta_bars(vs_full: pd.DataFrame, target: str, subsets: list[str],
                      path: Path) -> None:
    sub = vs_full[vs_full["target"] == target].set_index("feature_subset")
    values = [sub.loc[s, "delta_RMSE"] for s in subsets]
    colors = ["#C44E52" if v > 0 else "#55A868" for v in values]
    fig, ax = plt.subplots(figsize=(11, 5.5))
    ax.bar(np.arange(len(subsets)), values, color=colors)
    ax.axhline(0.0, color="black", lw=1)
    ax.set_xticks(np.arange(len(subsets)))
    ax.set_xticklabels(subsets, rotation=30, ha="right")
    ax.set_ylabel("delta RMSE vs FULL_CORE (positive = degradation)")
    ax.set_title(f"{target}: ablation degradation vs FULL_CORE")
    save_figure(fig, path)


def figure_leave_one_group_out(vs_full: pd.DataFrame, target: str, path: Path) -> None:
    groups = ["MP_INTRINSIC", "COMPOSITION", "WORKING_ION", "SYMMETRY"]
    subset_names = [f"NO_{g}" for g in groups]
    sub = vs_full[vs_full["target"] == target].set_index("feature_subset")
    values = [sub.loc[s, "delta_RMSE"] for s in subset_names]
    colors = ["#C44E52" if v > 0 else "#55A868" for v in values]
    fig, ax = plt.subplots(figsize=(10, 5.5))
    ax.bar(groups, values, color=colors)
    ax.axhline(0.0, color="black", lw=1.2)
    for i, v in enumerate(values):
        ax.text(i, v + (0.002 if v >= 0 else -0.008), f"{v:+.4f}", ha="center", fontsize=9)
    ax.set_xlabel("feature group removed")
    ax.set_ylabel("delta RMSE relative to FULL_CORE (positive = worse)")
    ax.set_title(f"{target}: performance impact after group removal (predictive, not causal)")
    save_figure(fig, path)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    overall_started = time.perf_counter()
    log("Phase 13 - feature-group ablation (frozen CatBoost deployment strategies)")

    if not CATBOOST_AVAILABLE:
        log("ERROR: catboost is not installed. Install with: py -m pip install catboost")
        return 1

    # ---- 1. inputs ---------------------------------------------------------
    all_df = read_required(IN_ALL_FEATURES)
    zn_df = read_required(IN_ZN_FEATURES)
    core_set = read_required(IN_CORE_SET)
    primary = read_required(IN_PRIMARY)
    zn_folds = read_required(IN_ZN_FOLDS)
    read_required(IN_MANIFEST)       # read to confirm existence only
    best_df = read_required(IN_BEST_PARAMS)
    p11_pooled = read_required(IN_P11_POOLED)
    read_required(IN_P12_CONTEXT)    # read to confirm existence only

    # ---- 2/3. frozen model + params + regimes ---------------------------------
    catboost_params: dict[str, dict] = {}
    for target in TARGETS:
        rows = best_df[(best_df["target"] == target) & (best_df["model"] == MODEL_NAME)]
        if rows.empty:
            log(f"ERROR: no Phase 9 best hyperparameters for {target} + {MODEL_NAME}")
            return 1
        catboost_params[target] = json.loads(rows.iloc[0]["best_params_json"])
        log(f"fixed {MODEL_NAME} params [{target}]: {json.dumps(catboost_params[target], default=str)}")

    # ---- 5. features + group QA -------------------------------------------------
    features = core_set["feature"].tolist()
    if len(features) != 53:
        log(f"ERROR: CORE_NUMERIC must contain exactly 53 features; found {len(features)}")
        return 1
    forbidden_found = [f for f in features if f in FORBIDDEN_IN_FEATURES]
    if forbidden_found:
        log(f"ERROR: target/leakage field(s) in feature list: {forbidden_found}")
        return 1
    for label, df in (("all_battery", all_df), ("zinc_battery", zn_df)):
        missing_cols = [f for f in features if f not in df.columns]
        if missing_cols:
            log(f"ERROR: {label} missing feature column(s): {missing_cols}")
            return 1
    all_df = all_df.copy()
    zn_df = zn_df.copy()
    all_df[features] = all_df[features].replace([np.inf, -np.inf], np.nan)
    zn_df[features] = zn_df[features].replace([np.inf, -np.inf], np.nan)

    groups = define_groups(features)
    all_grouped: list[str] = []
    for group_features in groups.values():
        all_grouped += group_features
    overlap_check = len(all_grouped) != len(set(all_grouped))
    union_ok = sorted(all_grouped) == sorted(features)
    if overlap_check or not union_ok:
        log(
            f"ERROR: feature groups overlap={overlap_check}, "
            f"union_equals_CORE={union_ok}"
        )
        return 1
    log(
        "feature groups (by name): "
        + ", ".join(f"{name}={len(fs)}" for name, fs in groups.items())
    )

    subsets = define_subsets(features, groups)
    unique_subsets, alias_map = deduplicate_subsets(subsets)
    for alias_name, canonical in alias_map.items():
        log(f"duplicate feature subset detected: {alias_name} == {canonical} "
            "(trained once, alias recorded)")
    log(
        "subsets to train: "
        + ", ".join(f"{name}({len(fs)})" for name, fs in unique_subsets.items())
    )

    # ---- 4/9. fold + group alignment ---------------------------------------------
    all_df = all_df.merge(
        primary[["record_uid", "group_framework_formula"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    zn_df = zn_df.merge(
        zn_folds[["record_uid", "group_framework_formula", "cv_fold"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    if int(all_df["group_framework_formula"].isna().sum()) or int(zn_df["cv_fold"].isna().sum()):
        log("ERROR: unmatched records after group/fold merge")
        return 1
    if set(zn_df["cv_fold"].unique()) != {0, 1, 2, 3, 4}:
        log("ERROR: Zn cv_fold labels are not exactly 0-4")
        return 1
    all_groups = all_df["group_framework_formula"]
    zn_groups = zn_df["group_framework_formula"]

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    PRED_DIR.mkdir(parents=True, exist_ok=True)
    FIG_DIR.mkdir(parents=True, exist_ok=True)

    # group/subset definition tables ------------------------------------------------
    group_def_rows = [
        {
            "feature_group": name,
            "n_features": len(fs),
            "features": ", ".join(fs),
        }
        for name, fs in groups.items()
    ]
    atomic_to_csv(pd.DataFrame(group_def_rows), OUT_GROUP_DEF)
    subset_def_rows = []
    for name in subsets:
        duplicate_of = alias_map.get(name, "")
        subset_def_rows.append(
            {
                "feature_subset": name,
                "n_features": len(subsets[name]),
                "duplicate_of": duplicate_of,
                "features": ", ".join(subsets[name]),
            }
        )
    atomic_to_csv(pd.DataFrame(subset_def_rows), OUT_SUBSET_DEF)

    # ---- train unique subsets ----------------------------------------------------------
    fold_metric_rows: list[dict] = []
    pooled_rows: list[dict] = []
    oof_rows: list[dict] = []

    for target in TARGETS:
        regime = DEPLOYMENT_REGIME[target]
        log(f"== target: {target} | deployment regime: {regime} ==")
        y_all = pd.to_numeric(all_df[target], errors="coerce")
        y_zn = pd.to_numeric(zn_df[target], errors="coerce")

        for subset_name, subset_features in unique_subsets.items():
            log(f"  subset {subset_name} ({len(subset_features)} features) ...")
            X_all_sub = all_df[subset_features]
            X_zn_sub = zn_df[subset_features]

            subset_oof_uids: list[str] = []
            subset_oof_yt: list[float] = []
            subset_oof_yp: list[float] = []
            subset_oof_folds: list[int] = []

            for fold in range(5):
                val_mask = (zn_df["cv_fold"] == fold).to_numpy()
                val_groups = set(zn_groups[val_mask])

                if regime == "MIXED_ION_GROUP_SAFE":
                    train_mask = (~all_groups.isin(val_groups)).to_numpy()
                    train_frame = all_df
                    train_groups = all_groups
                    train_ion = all_df["working_ion"]
                    X_train = X_all_sub[train_mask]
                    y_train = y_all[train_mask]
                else:  # ZN_ONLY
                    train_mask = (zn_df["cv_fold"] != fold).to_numpy()
                    train_frame = zn_df
                    train_groups = zn_groups
                    train_ion = zn_df["working_ion"]
                    X_train = X_zn_sub[train_mask]
                    y_train = y_zn[train_mask]

                # ---- mandatory QA --------------------------------------------------
                uid_overlap = len(
                    set(train_frame.loc[train_mask, "record_uid"])
                    & set(zn_df.loc[val_mask, "record_uid"])
                )
                group_overlap = len(set(train_groups[train_mask]) & val_groups)
                if uid_overlap or group_overlap:
                    log(
                        f"ERROR: [{target}] {subset_name} fold {fold}: "
                        f"uid_overlap={uid_overlap}, group_overlap={group_overlap}"
                    )
                    return 1
                if regime == "ZN_ONLY" and int((train_ion[train_mask] != "Zn").sum()) != 0:
                    log(f"ERROR: ZN_ONLY fold {fold} contains non-Zn training records")
                    return 1

                pipeline = make_catboost_pipeline(catboost_params[target])
                pipeline.fit(X_train, y_train)
                y_pred = pipeline.predict(X_zn_sub[val_mask])
                metrics = compute_metrics(y_zn[val_mask], y_pred)
                fold_metric_rows.append(
                    {
                        "target": target,
                        "deployment_regime": regime,
                        "feature_subset": subset_name,
                        "fold": fold,
                        "n_features": len(subset_features),
                        "n_train": int(train_mask.sum()),
                        "n_validation": int(val_mask.sum()),
                        "R2": metrics["R2"],
                        "RMSE": metrics["RMSE"],
                        "MAE": metrics["MAE"],
                        "Pearson_r": metrics["Pearson_r"],
                    }
                )
                for i, pos in enumerate(np.where(val_mask)[0]):
                    subset_oof_uids.append(zn_df["record_uid"].iloc[pos])
                    subset_oof_folds.append(fold)
                    subset_oof_yt.append(float(y_zn.iloc[pos]))
                    subset_oof_yp.append(float(y_pred[i]))
                log(f"    fold {fold}: RMSE={metrics['RMSE']:.4f}")

            pooled = compute_metrics(np.array(subset_oof_yt), np.array(subset_oof_yp))
            fold_rmses = [
                r["RMSE"]
                for r in fold_metric_rows
                if r["target"] == target and r["feature_subset"] == subset_name
            ]
            pooled_rows.append(
                {
                    "target": target,
                    "deployment_regime": regime,
                    "feature_subset": subset_name,
                    "n_features": len(subset_features),
                    "pooled_oof_R2": pooled["R2"],
                    "pooled_oof_RMSE": pooled["RMSE"],
                    "pooled_oof_MAE": pooled["MAE"],
                    "pooled_oof_Pearson_r": pooled["Pearson_r"],
                    "mean_fold_RMSE": sig6(float(np.mean(fold_rmses))),
                    "std_fold_RMSE": sig6(float(np.std(fold_rmses))),
                    "n_oof": int(len(subset_oof_yt)),
                }
            )
            for uid, fold, yt, yp in zip(subset_oof_uids, subset_oof_folds, subset_oof_yt, subset_oof_yp):
                oof_rows.append(
                    {
                        "record_uid": uid,
                        "target": target,
                        "deployment_regime": regime,
                        "feature_subset": subset_name,
                        "cv_fold": fold,
                        "y_true": yt,
                        "y_pred": yp,
                        "residual": yt - yp,
                    }
                )
            log(f"    pooled OOF: RMSE={pooled['RMSE']:.4f}, R2={pooled['R2']:.4f}")

    fold_metrics = pd.DataFrame(fold_metric_rows)
    pooled = pd.DataFrame(pooled_rows)
    oof_preds = pd.DataFrame(oof_rows)

    # ---- 13. FULL_CORE consistency vs Phase 11 (sig6 saved precision) -------------------
    consistency_ok = True
    for target in TARGETS:
        regime = DEPLOYMENT_REGIME[target]
        ours = pooled[
            (pooled["target"] == target) & (pooled["feature_subset"] == "FULL_CORE")
        ].iloc[0]
        theirs_row = p11_pooled[
            (p11_pooled["target"] == target) & (p11_pooled["regime"] == regime)
        ]
        if theirs_row.empty:
            log(f"ERROR: Phase 11 pooled row missing for {target} / {regime}")
            return 1
        theirs = theirs_row.iloc[0]
        for metric, col_ours, col_theirs in (
            ("RMSE", "pooled_oof_RMSE", "pooled_oof_RMSE"),
            ("R2", "pooled_oof_R2", "pooled_oof_R2"),
            ("MAE", "pooled_oof_MAE", "pooled_oof_MAE"),
            ("Pearson_r", "pooled_oof_Pearson_r", "pooled_oof_Pearson_r"),
        ):
            ours_rounded = sig6(ours[col_ours])
            saved_value = float(theirs[col_theirs])
            if ours_rounded is None or not np.isclose(
                float(ours_rounded), saved_value, rtol=0.0, atol=1e-12
            ):
                log(
                    f"ERROR: FULL_CORE does not reproduce Phase 11 for {target}/{regime}/"
                    f"{metric}: recomputed(sig6)={ours_rounded}, saved={saved_value}"
                )
                consistency_ok = False
        log(f"FULL_CORE consistency [{target}] vs Phase 11 {regime}: "
            f"{'PASS' if consistency_ok else 'FAIL'}")

    if not consistency_ok:
        log("ERROR: FULL_CORE Phase 11 consistency QA failed")
        return 1

    # ---- 14. ablation vs FULL_CORE --------------------------------------------------------
    vs_full_rows = []
    for target in TARGETS:
        full_row = pooled[
            (pooled["target"] == target) & (pooled["feature_subset"] == "FULL_CORE")
        ].iloc[0]
        for subset_name in unique_subsets:
            if subset_name == "FULL_CORE":
                continue
            row = pooled[
                (pooled["target"] == target) & (pooled["feature_subset"] == subset_name)
            ].iloc[0]
            delta_rmse = float(row["pooled_oof_RMSE"]) - float(full_row["pooled_oof_RMSE"])
            delta_mae = float(row["pooled_oof_MAE"]) - float(full_row["pooled_oof_MAE"])
            delta_r2 = float(row["pooled_oof_R2"]) - float(full_row["pooled_oof_R2"])
            vs_full_rows.append(
                {
                    "target": target,
                    "feature_subset": subset_name,
                    "ablated_RMSE": row["pooled_oof_RMSE"],
                    "FULL_CORE_RMSE": full_row["pooled_oof_RMSE"],
                    "delta_RMSE": sig6(delta_rmse),
                    "RMSE_percent_change": sig6(
                        100.0 * delta_rmse / float(full_row["pooled_oof_RMSE"])
                    ),
                    "delta_MAE": sig6(delta_mae),
                    "delta_R2": sig6(delta_r2),
                }
            )
    vs_full = pd.DataFrame(vs_full_rows)

    # ---- 16. working-ion special check -------------------------------------------------------
    ion_features = groups["WORKING_ION"]
    zn_ion_constancy = {}
    for f in ion_features:
        zn_ion_constancy[f] = int(zn_df[f].nunique(dropna=True))
    capacity_ion_constant = all(v == 1 for v in zn_ion_constancy.values())
    log(
        f"Zn-domain ion feature unique-value counts: {zn_ion_constancy} -> "
        f"{'constant' if capacity_ion_constant else 'NOT constant'}"
    )

    # ---- write outputs ---------------------------------------------------------------------
    atomic_to_csv(fold_metrics, OUT_FOLD_METRICS)
    atomic_to_csv(pooled, OUT_POOLED)
    atomic_to_csv(vs_full, OUT_VS_FULL)
    atomic_to_csv(oof_preds, OUT_OOF_PREDS)

    # ---- 18/19. figures -----------------------------------------------------------------------
    FIGURE_NAMES = {
        "average_voltage": {
            "rmse": "01_voltage_ablation_rmse",
            "delta": "03_voltage_ablation_delta_rmse",
            "r2": "05_voltage_ablation_r2",
            "loog": "07_voltage_leave_one_group_out",
        },
        "capacity_grav": {
            "rmse": "02_capacity_ablation_rmse",
            "delta": "04_capacity_ablation_delta_rmse",
            "r2": "06_capacity_ablation_r2",
            "loog": "08_capacity_leave_one_group_out",
        },
    }
    display_subsets = list(unique_subsets.keys())
    log("generating figures ...")
    for target in TARGETS:
        figure_ablation_bars(pooled, target, "pooled_oof_RMSE", display_subsets,
                             FIG_DIR / FIGURE_NAMES[target]["rmse"], "pooled OOF RMSE")
        figure_delta_bars(vs_full, target, display_subsets[1:],
                          FIG_DIR / FIGURE_NAMES[target]["delta"])
        figure_ablation_bars(pooled, target, "pooled_oof_R2", display_subsets,
                             FIG_DIR / FIGURE_NAMES[target]["r2"], "pooled OOF R2")
        figure_leave_one_group_out(vs_full, target,
                                   FIG_DIR / FIGURE_NAMES[target]["loog"])

    # ---- 20. summary ----------------------------------------------------------------------------
    elapsed = time.perf_counter() - overall_started
    lines: list[str] = []
    lines.append("Phase 13 - Feature-group ablation summary")
    lines.append("=" * 70)
    lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")
    lines.append("")
    for target in TARGETS:
        lines.append(
            f"[{target}] frozen deployment regime: {DEPLOYMENT_REGIME[target]}, "
            f"model: {MODEL_NAME}"
        )
        lines.append(f"    fixed CatBoost parameters: {json.dumps(catboost_params[target], default=str)}")
    lines.append("")
    lines.append(f"Zn validation rows: {len(zn_df)}")
    lines.append(f"Zn framework groups: {int(zn_groups.nunique())}")
    lines.append(f"CORE_NUMERIC features: {len(features)}")
    lines.append("feature groups (by name):")
    for name, fs in groups.items():
        lines.append(f"    {name}: {len(fs)} features")
    lines.append("feature subsets:")
    for name in subsets:
        alias_note = f" (duplicate_of={alias_map[name]})" if name in alias_map else ""
        lines.append(f"    {name}: {len(subsets[name])} features{alias_note}")
    lines.append("")
    lines.append(f"FULL_CORE Phase 11 consistency QA: {'PASS' if consistency_ok else 'FAIL'}")
    lines.append("framework overlap QA: 0 for every target x subset x fold")
    lines.append("")
    lines.append("pooled OOF metrics per subset:")
    for target in TARGETS:
        lines.append(f"    [{target}]")
        sub = pooled[pooled["target"] == target]
        for _, row in sub.iterrows():
            lines.append(
                f"        {row['feature_subset']} ({int(row['n_features'])} feats): "
                f"R2={row['pooled_oof_R2']:.4f}, RMSE={row['pooled_oof_RMSE']:.4f}, "
                f"MAE={row['pooled_oof_MAE']:.4f}, r={row['pooled_oof_Pearson_r']:.4f}"
            )
    lines.append("")
    lines.append("ablation vs FULL_CORE (delta_RMSE > 0 = degradation):")
    for _, row in vs_full.iterrows():
        lines.append(
            f"    [{row['target']}] {row['feature_subset']}: delta_RMSE="
            f"{row['delta_RMSE']:+.4f} ({row['RMSE_percent_change']:+.2f}%), "
            f"delta_R2={row['delta_R2']:+.4f}"
        )
    lines.append("")
    lines.append("leave-one-group-out (predictive performance impact after removal):")
    for target in TARGETS:
        sub = vs_full[vs_full["target"] == target]
        parts = []
        for g in ("MP_INTRINSIC", "COMPOSITION", "WORKING_ION", "SYMMETRY"):
            row = sub[sub["feature_subset"] == f"NO_{g}"]
            if not row.empty:
                r = row.iloc[0]
                parts.append(f"{g}: {r['delta_RMSE']:+.4f}")
        lines.append(f"    [{target}] " + ", ".join(parts))
    lines.append("")
    lines.append("working-ion descriptors - special interpretation:")
    if capacity_ion_constant:
        lines.append(
            "    working-ion descriptors carry no within-Zn discriminatory variation "
            "in the ZN_ONLY capacity regime."
        )
        lines.append(
            "    Their low ablation impact in that regime must NOT be read as "
            "'ion chemistry globally unimportant'."
        )
    lines.append(
        f"    Zn-domain ion feature unique-value counts: {zn_ion_constancy}"
    )
    for target in TARGETS:
        sub = vs_full[
            (vs_full["target"] == target) & (vs_full["feature_subset"] == "NO_WORKING_ION")
        ]
        if not sub.empty:
            r = sub.iloc[0]
            lines.append(
                f"    [{target}] NO_WORKING_ION vs FULL_CORE: delta_RMSE="
                f"{r['delta_RMSE']:+.4f} ({r['RMSE_percent_change']:+.2f}%)"
            )
    lines.append("")
    lines.append("output files:")
    for path in (
        OUT_GROUP_DEF, OUT_SUBSET_DEF, OUT_FOLD_METRICS, OUT_POOLED, OUT_VS_FULL,
        OUT_OOF_PREDS, FIG_DIR, OUT_SUMMARY,
    ):
        lines.append(f"    {path.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append("")
    lines.append("policy statements:")
    lines.append("    Phase 13 performs no hyperparameter tuning.")
    lines.append("    Phase 9 CatBoost parameters remain fixed.")
    lines.append("    Phase 10 Zn folds remain fixed.")
    lines.append("    Phase 11 deployment regimes remain fixed.")
    lines.append("    Feature-group ablation measures predictive performance impact,")
    lines.append("    not causal importance.")
    lines.append("    No candidate screening was performed.")
    lines.append("    No final deployment model was refit.")
    lines.append("")
    lines.append(f"runtime: {elapsed:.1f} s")
    lines.append("")
    OUT_SUMMARY.write_text("\\n".join(lines), encoding="utf-8")
    log(f"Saved ablation summary -> {OUT_SUMMARY}")

    # ---- 21. console -----------------------------------------------------------------------------
    def largest_loog(target):
        sub = vs_full[vs_full["target"] == target]
        best = None
        for g in ("MP_INTRINSIC", "COMPOSITION", "WORKING_ION", "SYMMETRY"):
            row = sub[sub["feature_subset"] == f"NO_{g}"]
            if not row.empty:
                r = row.iloc[0]
                if best is None or r["delta_RMSE"] > best["delta_RMSE"]:
                    best = {"group": g, "delta_RMSE": r["delta_RMSE"]}
        return best

    full_voltage = pooled[
        (pooled["target"] == "average_voltage") & (pooled["feature_subset"] == "FULL_CORE")
    ].iloc[0]
    full_capacity = pooled[
        (pooled["target"] == "capacity_grav") & (pooled["feature_subset"] == "FULL_CORE")
    ].iloc[0]
    loog_v = largest_loog("average_voltage")
    loog_c = largest_loog("capacity_grav")
    print("")
    print("Phase 13 feature-group ablation completed.")
    print(f"Voltage FULL_CORE RMSE: {full_voltage['pooled_oof_RMSE']:.4f}")
    print(f"Voltage largest leave-one-group-out degradation: {loog_v['group']} "
          f"(delta RMSE={loog_v['delta_RMSE']:+.4f})")
    print(f"Capacity FULL_CORE RMSE: {full_capacity['pooled_oof_RMSE']:.4f}")
    print(f"Capacity largest leave-one-group-out degradation: {loog_c['group']} "
          f"(delta RMSE={loog_c['delta_RMSE']:+.4f})")
    print(f"outputs: {OUT_DIR}")
    print(f"         {PRED_DIR}")
    print(f"         {FIG_DIR}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
''',
    14: '''# -*- coding: utf-8 -*-
"""
Phase 14 - Out-of-fold SHAP interpretation of the frozen CatBoost deployment
models (evaluation-only interpretation, no model selection).

Frozen configuration (never re-decided here):
    average_voltage: CatBoost, regime MIXED_ION_GROUP_SAFE
    capacity_grav:    CatBoost, regime ZN_ONLY
    CatBoost hyperparameters: Phase 9 best parameters
    Validation folds: fixed Phase 10 Zn cv_fold 0-4 (each Zn record is
    explained EXACTLY once, out-of-fold)

SHAP values are computed with CatBoost NATIVE ShapValues
(get_feature_importance(Pool(...), type="ShapValues",
shap_calc_type="Regular", model_output="Raw")) on the imputed validation
data of each fold; the last column is the expected value and the first 53
columns correspond exactly to the 53 CORE_NUMERIC features.

Hard QA:
    * SHAP reconstruction: expected_value + sum(53 SHAPs) must match the
      CatBoost prediction with max absolute error < 1e-6, else ERROR.
    * Phase 13 FULL_CORE OOF predictions must be reproduced (atol 1e-8,
      report max diff; hard fail if > 1e-6).

Outputs:
    05_Results/SHAP/Phase14_OOF_SHAP/
        oof_shap_values.csv
        shap_global_feature_importance.csv
        shap_group_importance.csv
        shap_feature_direction.csv
        ablation_shap_group_comparison.csv
        individual_shap_examples.csv
        phase14_oof_shap_summary.txt
    06_Figures/Draft_Figures/Phase14_OOF_SHAP/
        01..08 PNG (600 dpi) + PDF

Run from the project root:
    py 03_Code/Model_Interpretation/14_oof_shap_interpretation.py
"""

from __future__ import annotations

import json
import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

from sklearn.impute import SimpleImputer
from scipy.stats import spearmanr

try:
    from catboost import CatBoostRegressor, Pool
    CATBOOST_AVAILABLE = True
except ImportError:  # pragma: no cover
    CatBoostRegressor = None  # type: ignore[assignment]
    Pool = None  # type: ignore[assignment]
    CATBOOST_AVAILABLE = False

# ---------------------------------------------------------------------------
# Paths
# ---------------------------------------------------------------------------
PROJECT_ROOT = Path(_SCIENCE_WORK_ROOT)

IN_ALL_FEATURES = PROJECT_ROOT / "02_Datasets" / "Features" / "all_battery_candidate_compatible_features.csv"
IN_ZN_FEATURES = PROJECT_ROOT / "02_Datasets" / "Features" / "zinc_battery_candidate_compatible_features.csv"
IN_CORE_SET = PROJECT_ROOT / "02_Datasets" / "Features" / "Feature_Sets" / "core_numeric_features.csv"
IN_PRIMARY = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "primary_group_holdout.csv"
IN_ZN_FOLDS = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "zn_group_cv_folds.csv"
IN_BEST_PARAMS = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase9_Tuning" / "best_hyperparameters.csv"
IN_GROUP_DEF = PROJECT_ROOT / "05_Results" / "Ablation" / "Phase13_Feature_Groups" / "feature_group_definition.csv"
IN_P13_POOLED = PROJECT_ROOT / "05_Results" / "Ablation" / "Phase13_Feature_Groups" / "feature_ablation_pooled_oof_metrics.csv"
IN_P13_PREDS = PROJECT_ROOT / "05_Results" / "Predictions" / "Phase13_Feature_Groups" / "feature_ablation_oof_predictions.csv"

OUT_DIR = PROJECT_ROOT / "05_Results" / "SHAP" / "Phase14_OOF_SHAP"
OUT_SHAP_VALUES = OUT_DIR / "oof_shap_values.csv"
OUT_GLOBAL = OUT_DIR / "shap_global_feature_importance.csv"
OUT_GROUP = OUT_DIR / "shap_group_importance.csv"
OUT_DIRECTION = OUT_DIR / "shap_feature_direction.csv"
OUT_COMPARISON = OUT_DIR / "ablation_shap_group_comparison.csv"
OUT_EXAMPLES = OUT_DIR / "individual_shap_examples.csv"
OUT_SUMMARY = OUT_DIR / "phase14_oof_shap_summary.txt"

FIG_DIR = PROJECT_ROOT / "06_Figures" / "Draft_Figures" / "Phase14_OOF_SHAP"

TARGETS = ("average_voltage", "capacity_grav")
MODEL_NAME = "CatBoost"
DEPLOYMENT_REGIME = {
    "average_voltage": "MIXED_ION_GROUP_SAFE",
    "capacity_grav": "ZN_ONLY",
}
FORBIDDEN_IN_FEATURES = {
    "average_voltage",
    "capacity_grav",
    "capacity_vol",
    "energy_grav",
    "energy_vol",
}

RECON_TOLERANCE = 1e-6
P13_TOLERANCE_SOFT = 1e-8
P13_TOLERANCE_HARD = 1e-6


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------
def log(message: str) -> None:
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S")
    print(f"[{stamp}Z] {message}", flush=True)


def sig6(value) -> float | None:
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
        return float(f"{float(value):.6g}")
    except (TypeError, ValueError):
        return None


def atomic_to_csv(df: pd.DataFrame, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    df.to_csv(tmp, index=False, encoding="utf-8-sig")
    os.replace(tmp, path)
    log(f"Saved {len(df)} rows -> {path}")


def save_figure(fig, path: Path) -> None:
    fig.tight_layout()
    fig.savefig(path.with_suffix(".png"), dpi=600)
    fig.savefig(path.with_suffix(".pdf"))
    plt.close(fig)
    log(f"  saved figure: {path.name}.png/.pdf")


def read_required(path: Path) -> pd.DataFrame:
    if not path.is_file():
        log(f"ERROR: required input file not found: {path}")
        sys.exit(1)
    return pd.read_csv(path, low_memory=False)


def make_catboost_model(params: dict) -> CatBoostRegressor:
    """
    Convert Phase 9 sklearn-Pipeline parameter names
    (model__*) into native CatBoost parameter names.
    """
    native_params = {}
    for key, value in params.items():
        if key.startswith("model__"):
            native_params[key[len("model__"):]] = value
        elif "__" in key:
            # Unexpected non-model Pipeline parameter.
            # Phase 9 CatBoost tuning should contain model parameters only.
            raise ValueError(
                f"Unexpected non-CatBoost Pipeline parameter in Phase 9 params: {key}"
            )
        else:
            # Allow already-native CatBoost parameter names.
            native_params[key] = value

    model = CatBoostRegressor(
        loss_function="RMSE",
        random_seed=42,
        verbose=False,
        allow_writing_files=False,
        thread_count=1,
    )
    model.set_params(**native_params)
    return model


# ---------------------------------------------------------------------------
# Figures
# ---------------------------------------------------------------------------
def figure_bar_top20(global_df: pd.DataFrame, target: str, path: Path) -> None:
    sub = global_df[global_df["target"] == target].sort_values("mean_abs_SHAP", ascending=False).head(20)
    fig, ax = plt.subplots(figsize=(9, 7))
    ax.barh(np.arange(len(sub))[::-1], sub["mean_abs_SHAP"], color="#4C72B0")
    ax.set_yticks(np.arange(len(sub))[::-1])
    ax.set_yticklabels(sub["feature"], fontsize=8)
    ax.set_xlabel("mean |SHAP|")
    ax.set_title(f"{target}: top 20 features by mean |SHAP| (OOF Zn records)")
    save_figure(fig, path)


def figure_beeswarm(shap_wide: pd.DataFrame, global_df: pd.DataFrame,
                    target: str, path: Path) -> None:
    sub = shap_wide[shap_wide["target"] == target].copy()
    if len(sub) == 0:
        raise ValueError(f"no OOF SHAP rows for target {target}")
    features = (
        global_df[global_df["target"] == target]
        .sort_values("mean_abs_SHAP", ascending=False)["feature"].head(20).tolist()
    )
    fig, ax = plt.subplots(figsize=(9, 8))
    rng = np.random.default_rng(42)
    for row_idx, feature in enumerate(features):
        values = sub[f"shap__{feature}"].to_numpy(dtype=float)
        colors = sub[feature].to_numpy(dtype=float)
        vmin = np.nanmin(colors)
        vmax = np.nanmax(colors)
        norm_colors = (colors - vmin) / (vmax - vmin) if vmax > vmin else np.full_like(colors, 0.5)
        jitter = rng.uniform(-0.35, 0.35, size=len(values))
        sc = ax.scatter(values, row_idx + jitter, c=norm_colors, cmap="coolwarm",
                        s=8, alpha=0.7, linewidths=0)
        ax.axhline(row_idx, color="gray", lw=0.4)
    ax.set_yticks(np.arange(len(features)))
    ax.set_yticklabels(features, fontsize=8)
    ax.set_xlabel("SHAP value")
    ax.set_title(f"{target}: OOF SHAP beeswarm top 20 (color = imputed feature value)")
    save_figure(fig, path)


def figure_group_importance(group_df: pd.DataFrame, target: str, path: Path) -> None:
    sub = group_df[group_df["target"] == target]
    fig, ax = plt.subplots(figsize=(9, 5))
    ax.bar(sub["feature_group"], sub["mean_group_abs_SHAP"], color="#55A868")
    for i, (_, row) in enumerate(sub.iterrows()):
        ax.text(i, row["mean_group_abs_SHAP"] + 0.001,
                f"share={row['normalized_group_share']:.3f}", ha="center", fontsize=9)
    ax.set_ylabel("mean group |SHAP|")
    ax.set_title(f"{target}: feature-group SHAP attribution (predictive, not causal)")
    save_figure(fig, path)


def figure_ablation_vs_shap(comparison: pd.DataFrame, target: str, path: Path) -> None:
    sub = comparison[comparison["target"] == target]
    fig, ax1 = plt.subplots(figsize=(9, 5.5))
    x = np.arange(len(sub))
    ax1.bar(x - 0.2, sub["phase13_delta_RMSE_when_removed"], width=0.4,
            color="#DD8452", label="Phase 13 ablation delta RMSE")
    ax1.set_ylabel("delta RMSE when removed")
    ax2 = ax1.twinx()
    ax2.bar(x + 0.2, sub["mean_group_abs_SHAP"], width=0.4,
            color="#4C72B0", label="mean group |SHAP|")
    ax2.set_ylabel("mean group |SHAP|")
    ax1.set_xticks(x)
    ax1.set_xticklabels(sub["feature_group"], rotation=15, ha="right")
    ax1.axhline(0.0, color="black", lw=0.8)
    lines1, labels1 = ax1.get_legend_handles_labels()
    lines2, labels2 = ax2.get_legend_handles_labels()
    ax1.legend(lines1 + lines2, labels1 + labels2, fontsize=8)
    ax1.set_title(f"{target}: ablation vs SHAP group evidence (complementary, not causal)")
    save_figure(fig, path)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    overall_started = time.perf_counter()
    log("Phase 14 - OOF SHAP interpretation (frozen CatBoost deployment models)")

    if not CATBOOST_AVAILABLE:
        log("ERROR: catboost is not installed. Install with: py -m pip install catboost")
        return 1

    # ---- 1. inputs ---------------------------------------------------------
    all_df = read_required(IN_ALL_FEATURES)
    zn_df = read_required(IN_ZN_FEATURES)
    core_set = read_required(IN_CORE_SET)
    primary = read_required(IN_PRIMARY)
    zn_folds = read_required(IN_ZN_FOLDS)
    best_df = read_required(IN_BEST_PARAMS)
    group_def = read_required(IN_GROUP_DEF)
    p13_pooled = read_required(IN_P13_POOLED)
    p13_preds = read_required(IN_P13_PREDS)

    # ---- 2/5. features, folds, groups ----------------------------------------
    features = core_set["feature"].tolist()
    if len(features) != 53:
        log(f"ERROR: CORE_NUMERIC must contain exactly 53 features; found {len(features)}")
        return 1
    forbidden_found = [f for f in features if f in FORBIDDEN_IN_FEATURES]
    if forbidden_found:
        log(f"ERROR: target/leakage field(s) in feature list: {forbidden_found}")
        return 1
    for label, df in (("all_battery", all_df), ("zinc_battery", zn_df)):
        missing_cols = [f for f in features if f not in df.columns]
        if missing_cols:
            log(f"ERROR: {label} missing feature column(s): {missing_cols}")
            return 1

    # feature -> group mapping from the Phase 13 definition file
    feature_to_group: dict[str, str] = {}
    for _, row in group_def.iterrows():
        for f in [x.strip() for x in str(row["features"]).split(",")]:
            feature_to_group[f] = row["feature_group"]
    for f in features:
        if f not in feature_to_group:
            log(f"ERROR: feature {f} missing from the Phase 13 group definition")
            return 1

    all_df = all_df.copy()
    zn_df = zn_df.copy()
    all_df[features] = all_df[features].replace([np.inf, -np.inf], np.nan)
    zn_df[features] = zn_df[features].replace([np.inf, -np.inf], np.nan)

    all_df = all_df.merge(
        primary[["record_uid", "group_framework_formula"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    zn_df = zn_df.merge(
        zn_folds[["record_uid", "group_framework_formula", "cv_fold"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    if int(all_df["group_framework_formula"].isna().sum()) or int(zn_df["cv_fold"].isna().sum()):
        log("ERROR: unmatched records after group/fold merge")
        return 1
    if set(zn_df["cv_fold"].unique()) != {0, 1, 2, 3, 4}:
        log("ERROR: Zn cv_fold labels are not exactly 0-4")
        return 1
    all_groups = all_df["group_framework_formula"]
    zn_groups = zn_df["group_framework_formula"]

    # ---- 3. fixed CatBoost params ----------------------------------------------
    catboost_params: dict[str, dict] = {}
    for target in TARGETS:
        rows = best_df[(best_df["target"] == target) & (best_df["model"] == MODEL_NAME)]
        if rows.empty:
            log(f"ERROR: no Phase 9 best hyperparameters for {target} + {MODEL_NAME}")
            return 1
        pipeline_params = json.loads(rows.iloc[0]["best_params_json"])
        # Convert Phase 9 sklearn-Pipeline keys (model__*) to native CatBoost
        # keys; values are copied unchanged (only the prefix is stripped).
        converted: dict = {}
        for key, value in pipeline_params.items():
            if key.startswith("model__"):
                converted[key[len("model__"):]] = value
            elif "__" in key:
                log(f"ERROR: unexpected non-CatBoost Pipeline parameter for {target}: {key}")
                return 1
            else:
                converted[key] = value
        bad_keys = [k for k in converted if "__" in k]
        if bad_keys:
            log(f"ERROR: native CatBoost params contain '__' after conversion for {target}: {bad_keys}")
            return 1
        catboost_params[target] = converted
        log(f"Phase 9 Pipeline params [{target}]: {json.dumps(pipeline_params, default=str)}")
        log(f"Native CatBoost params [{target}]: {json.dumps(converted, default=str)}")

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    FIG_DIR.mkdir(parents=True, exist_ok=True)

    # ---- 4-8. per-fold fit + native CatBoost SHAP ---------------------------------
    shap_rows: list[dict] = []
    max_recon_error: float = 0.0

    for target in TARGETS:
        regime = DEPLOYMENT_REGIME[target]
        log(f"== target: {target} | regime: {regime} ==")
        y_all = pd.to_numeric(all_df[target], errors="coerce")
        y_zn = pd.to_numeric(zn_df[target], errors="coerce")

        for fold in range(5):
            val_mask = (zn_df["cv_fold"] == fold).to_numpy()
            val_groups = set(zn_groups[val_mask])

            if regime == "MIXED_ION_GROUP_SAFE":
                train_mask = (~all_groups.isin(val_groups)).to_numpy()
                X_train_raw = all_df.loc[train_mask, features]
                y_train = y_all[train_mask]
                train_ion = all_df.loc[train_mask, "working_ion"]
            else:  # ZN_ONLY
                train_mask = (zn_df["cv_fold"] != fold).to_numpy()
                X_train_raw = zn_df.loc[train_mask, features]
                y_train = y_zn[train_mask]
                train_ion = zn_df.loc[train_mask, "working_ion"]

            # ---- QA -------------------------------------------------------------
            uid_overlap = len(
                set((zn_df if regime == "ZN_ONLY" else all_df).loc[train_mask, "record_uid"])
                & set(zn_df.loc[val_mask, "record_uid"])
            )
            group_overlap = len(
                set((zn_groups if regime == "ZN_ONLY" else all_groups)[train_mask]) & val_groups
            )
            if uid_overlap or group_overlap:
                log(f"ERROR: [{target}] fold {fold}: uid_overlap={uid_overlap}, group_overlap={group_overlap}")
                return 1
            if regime == "ZN_ONLY" and int((train_ion != "Zn").sum()) != 0:
                log(f"ERROR: ZN_ONLY fold {fold} contains non-Zn training records")
                return 1

            X_val_raw = zn_df.loc[val_mask, features]

            # 1) imputer fit on training only, 2) transform train/val
            imputer = SimpleImputer(strategy="median")
            imputer.fit(X_train_raw)
            X_train = imputer.transform(X_train_raw)
            X_val = imputer.transform(X_val_raw)

            # 3) fit CatBoost on imputed training
            model = make_catboost_model(catboost_params[target])
            model.fit(X_train, y_train)

            # 4) predict validation
            y_pred = model.predict(X_val)

            # 5) native CatBoost ShapValues on imputed validation
            shap_matrix = model.get_feature_importance(
                Pool(X_val),
                type="ShapValues",
                shap_calc_type="Regular",
                model_output="Raw",
            )
            shap_feature = shap_matrix[:, :-1]   # 53 columns, CORE order
            expected_values = shap_matrix[:, -1]  # bias column

            # ---- 8. reconstruction QA ----------------------------------------------
            recon = expected_values + shap_feature.sum(axis=1)
            fold_max_err = float(np.max(np.abs(recon - y_pred)))
            max_recon_error = max(max_recon_error, fold_max_err)
            if fold_max_err >= RECON_TOLERANCE:
                log(
                    f"ERROR: SHAP reconstruction failed for {target} fold {fold}: "
                    f"max abs error={fold_max_err:.3e} >= {RECON_TOLERANCE}"
                )
                return 1

            for i, pos in enumerate(np.where(val_mask)[0]):
                row = {
                    "record_uid": zn_df["record_uid"].iloc[pos],
                    "target": target,
                    "deployment_regime": regime,
                    "cv_fold": int(fold),
                    "y_true": float(y_zn.iloc[pos]),
                    "y_pred": float(y_pred[i]),
                    "expected_value": float(expected_values[i]),
                }
                for j, feature in enumerate(features):
                    row[f"shap__{feature}"] = float(shap_feature[i, j])
                    row[feature] = float(X_val[i, j])  # imputed feature value
                shap_rows.append(row)
            log(f"  fold {fold}: n_val={int(val_mask.sum())}, recon max err={fold_max_err:.3e}")

    shap_wide = pd.DataFrame(shap_rows)
    log(f"SHAP reconstruction maximum error: {max_recon_error:.3e} (tolerance {RECON_TOLERANCE})")

    # ---- OOF explanation coverage hard QA ----------------------------------------
    expected_n = len(zn_df)
    if len(shap_wide) != expected_n * len(TARGETS):
        log(f"ERROR: OOF SHAP rows {len(shap_wide)} != expected {expected_n * len(TARGETS)}")
        return 1
    for target in TARGETS:
        sub = shap_wide[shap_wide["target"] == target]
        if len(sub) != expected_n:
            log(f"ERROR: {target} has {len(sub)} OOF rows, expected {expected_n}")
            return 1
        if not bool(sub["record_uid"].is_unique):
            log(f"ERROR: record_uid not unique in OOF SHAP rows for {target}")
            return 1
        if set(sub["record_uid"]) != set(zn_df["record_uid"]):
            log(f"ERROR: record_uid set mismatch for {target}")
            return 1
        if set(sub["cv_fold"].unique()) != {0, 1, 2, 3, 4}:
            log(f"ERROR: cv_fold values invalid for {target}: {sorted(sub['cv_fold'].unique())}")
            return 1
    log(f"OOF SHAP coverage QA passed: {expected_n} unique Zn records per target, "
        "each explained exactly once.")

    # ---- 9. Phase 13 prediction consistency ------------------------------------------
    p13_full = p13_preds[p13_preds["feature_subset"] == "FULL_CORE"].copy()
    max_p13_diff: float = 0.0
    for target in TARGETS:
        regime = DEPLOYMENT_REGIME[target]
        ours = shap_wide[shap_wide["target"] == target].sort_values("record_uid").reset_index(drop=True)
        theirs = p13_full[
            (p13_full["target"] == target) & (p13_full["deployment_regime"] == regime)
        ].sort_values("record_uid").reset_index(drop=True)
        if not np.array_equal(ours["record_uid"].to_numpy(), theirs["record_uid"].to_numpy()):
            log(f"ERROR: record_uid mismatch vs Phase 13 for {target}")
            return 1
        if not np.array_equal(ours["cv_fold"].to_numpy(), theirs["cv_fold"].to_numpy()):
            log(f"ERROR: cv_fold mismatch vs Phase 13 for {target}")
            return 1
        if not np.allclose(ours["y_true"].to_numpy(dtype=float),
                           theirs["y_true"].to_numpy(dtype=float), rtol=0.0, atol=1e-9):
            log(f"ERROR: y_true mismatch vs Phase 13 for {target}")
            return 1
        diff = np.abs(ours["y_pred"].to_numpy(dtype=float) - theirs["y_pred"].to_numpy(dtype=float))
        max_p13_diff = max(max_p13_diff, float(diff.max()))
        if float(diff.max()) >= P13_TOLERANCE_HARD:
            log(f"ERROR: Phase 13 prediction mismatch for {target}: max diff={diff.max():.3e} >= {P13_TOLERANCE_HARD}")
            return 1
        log(f"Phase 13 consistency [{target}]: max |pred diff| = {diff.max():.3e}")
    if max_p13_diff > P13_TOLERANCE_SOFT:
        log(f"note: Phase 13 prediction differences above 1e-8 but below 1e-6: max={max_p13_diff:.3e}")

    # ---- 10. OOF SHAP wide table ------------------------------------------------------
    ordered_columns = (
        ["record_uid", "target", "deployment_regime", "cv_fold", "y_true", "y_pred", "expected_value"]
        + [f"shap__{f}" for f in features]
        + [f for f in features]
    )
    atomic_to_csv(shap_wide[ordered_columns], OUT_SHAP_VALUES)

    # ---- 11. global feature importance ---------------------------------------------------
    global_rows = []
    for target in TARGETS:
        sub = shap_wide[shap_wide["target"] == target]
        for feature in features:
            vals = sub[f"shap__{feature}"].to_numpy(dtype=float)
            global_rows.append(
                {
                    "target": target,
                    "feature": feature,
                    "feature_group": feature_to_group[feature],
                    "mean_abs_SHAP": sig6(float(np.mean(np.abs(vals)))),
                    "median_abs_SHAP": sig6(float(np.median(np.abs(vals)))),
                    "mean_signed_SHAP": sig6(float(np.mean(vals))),
                    "std_SHAP": sig6(float(np.std(vals))),
                }
            )
    global_df = pd.DataFrame(global_rows)
    global_df["rank"] = global_df.groupby("target")["mean_abs_SHAP"].rank(ascending=False).astype(int)
    global_df = global_df.sort_values(["target", "rank"])
    atomic_to_csv(global_df, OUT_GLOBAL)

    # ---- 12. group SHAP importance --------------------------------------------------------
    group_rows = []
    for target in TARGETS:
        sub = shap_wide[shap_wide["target"] == target]
        group_abs = {g: np.zeros(len(sub)) for g in ("MP_INTRINSIC", "SYMMETRY", "COMPOSITION", "WORKING_ION")}
        for feature in features:
            group_abs[feature_to_group[feature]] += np.abs(sub[f"shap__{feature}"].to_numpy(dtype=float))
        means = {g: float(np.mean(v)) for g, v in group_abs.items()}
        medians = {g: float(np.median(v)) for g, v in group_abs.items()}
        total = sum(means.values())
        for g in ("MP_INTRINSIC", "SYMMETRY", "COMPOSITION", "WORKING_ION"):
            group_rows.append(
                {
                    "target": target,
                    "feature_group": g,
                    "mean_group_abs_SHAP": sig6(means[g]),
                    "median_group_abs_SHAP": sig6(medians[g]),
                    "normalized_group_share": sig6(means[g] / total if total else np.nan),
                }
            )
    group_df = pd.DataFrame(group_rows)
    atomic_to_csv(group_df, OUT_GROUP)

    # ---- 13. direction analysis --------------------------------------------------------------
    direction_rows = []
    for target in TARGETS:
        sub = shap_wide[shap_wide["target"] == target]
        for feature in features:
            feature_values = sub[feature].to_numpy(dtype=float)
            shap_values = sub[f"shap__{feature}"].to_numpy(dtype=float)
            nunique = int(pd.Series(feature_values).nunique(dropna=True))
            # RAW pre-imputation Zn missing fraction; the imputed model-input
            # values must never be mistaken for original missingness.
            raw_missing_fraction = float(zn_df[feature].isna().mean())
            if nunique <= 1:
                rho = np.nan
            else:
                try:
                    rho, _p = spearmanr(feature_values, shap_values)
                except Exception:  # noqa: BLE001
                    rho = np.nan
            direction_rows.append(
                {
                    "target": target,
                    "feature": feature,
                    "feature_group": feature_to_group[feature],
                    "spearman_feature_vs_shap": sig6(rho),
                    "feature_nunique": nunique,
                    "feature_missing_fraction": sig6(raw_missing_fraction),
                }
            )
    direction_df = pd.DataFrame(direction_rows)
    atomic_to_csv(direction_df, OUT_DIRECTION)

    # ---- 14. working-ion special check ----------------------------------------------------------
    ion_features = [f for f in features if feature_to_group[f] == "WORKING_ION"]
    ion_nunique = {f: int(zn_df[f].nunique(dropna=True)) for f in ion_features}
    capacity_ion_constant = all(v == 1 for v in ion_nunique.values())
    log(f"Zn ion feature nunique: {ion_nunique} -> {'constant' if capacity_ion_constant else 'NOT constant'}")

    # ---- 15. ablation vs SHAP group comparison ---------------------------------------------------
    comparison_rows = []
    for target in TARGETS:
        p13_sub = p13_pooled[p13_pooled["target"] == target]
        full_row = p13_sub[p13_sub["feature_subset"] == "FULL_CORE"].iloc[0]
        group_sub = group_df[group_df["target"] == target].set_index("feature_group")
        ablation_deltas = {}
        for g in ("MP_INTRINSIC", "SYMMETRY", "COMPOSITION", "WORKING_ION"):
            no_row = p13_sub[p13_sub["feature_subset"] == f"NO_{g}"]
            if not no_row.empty:
                r = no_row.iloc[0]
                delta = float(r["pooled_oof_RMSE"]) - float(full_row["pooled_oof_RMSE"])
                ablation_deltas[g] = (
                    delta,
                    100.0 * delta / float(full_row["pooled_oof_RMSE"]),
                )
        ablation_rank = {
            g: i + 1
            for i, (g, _) in enumerate(
                sorted(ablation_deltas.items(), key=lambda kv: -kv[1][0])
            )
        }
        shap_rank = {
            g: i + 1
            for i, g in enumerate(
                sorted(
                    group_sub.index,
                    key=lambda g: -group_sub.loc[g, "mean_group_abs_SHAP"]
                )
            )
        }
        for g in ("MP_INTRINSIC", "SYMMETRY", "COMPOSITION", "WORKING_ION"):
            delta, pct = ablation_deltas[g]
            comparison_rows.append(
                {
                    "target": target,
                    "feature_group": g,
                    "n_features": sum(1 for f in features if feature_to_group[f] == g),
                    "phase13_delta_RMSE_when_removed": sig6(delta),
                    "phase13_RMSE_percent_change": sig6(pct),
                    "mean_group_abs_SHAP": sig6(group_sub.loc[g, "mean_group_abs_SHAP"]),
                    "normalized_group_SHAP_share": sig6(group_sub.loc[g, "normalized_group_share"]),
                    "ablation_rank": ablation_rank[g],
                    "shap_rank": shap_rank[g],
                }
            )
    comparison_df = pd.DataFrame(comparison_rows)
    atomic_to_csv(comparison_df, OUT_COMPARISON)

    # ---- 16. individual explanation examples ------------------------------------------------------
    example_rows = []
    for target in TARGETS:
        sub = shap_wide[shap_wide["target"] == target].reset_index(drop=True)
        abs_err = np.abs(sub["y_true"] - sub["y_pred"])
        idx_min = int(np.argmin(abs_err))
        idx_median = int(np.argmin(np.abs(abs_err - np.median(abs_err))))
        idx_max = int(np.argmax(abs_err))
        for idx, etype in ((idx_min, "min_abs_error"), (idx_median, "median_abs_error"), (idx_max, "max_abs_error")):
            record = sub.iloc[idx]
            shap_dict = {f: float(record[f"shap__{f}"]) for f in features}
            top10 = sorted(shap_dict.items(), key=lambda kv: -abs(kv[1]))[:10]
            for feature, shap_value in top10:
                example_rows.append(
                    {
                        "record_uid": record["record_uid"],
                        "target": target,
                        "cv_fold": int(record["cv_fold"]),
                        "y_true": float(record["y_true"]),
                        "y_pred": float(record["y_pred"]),
                        "absolute_error": float(abs_err[idx]),
                        "example_type": etype,
                        "feature": feature,
                        "feature_value": float(record[feature]),
                        "shap_value": sig6(shap_value),
                    }
                )
    atomic_to_csv(pd.DataFrame(example_rows), OUT_EXAMPLES)

    # ---- 17/18. figures -----------------------------------------------------------------------------
    FIGURE_NAMES = {
        "average_voltage": {
            "bar": "01_voltage_shap_bar_top20",
            "beeswarm": "03_voltage_shap_beeswarm_top20",
            "group": "05_voltage_shap_group_importance",
            "ablation_vs_shap": "07_voltage_ablation_vs_shap_group",
        },
        "capacity_grav": {
            "bar": "02_capacity_shap_bar_top20",
            "beeswarm": "04_capacity_shap_beeswarm_top20",
            "group": "06_capacity_shap_group_importance",
            "ablation_vs_shap": "08_capacity_ablation_vs_shap_group",
        },
    }
    log("generating figures ...")
    for target in TARGETS:
        figure_bar_top20(global_df, target, FIG_DIR / FIGURE_NAMES[target]["bar"])
        figure_beeswarm(shap_wide, global_df, target, FIG_DIR / FIGURE_NAMES[target]["beeswarm"])
        figure_group_importance(group_df, target, FIG_DIR / FIGURE_NAMES[target]["group"])
        figure_ablation_vs_shap(comparison_df, target, FIG_DIR / FIGURE_NAMES[target]["ablation_vs_shap"])

    # ---- 21. summary -----------------------------------------------------------------------------------
    elapsed = time.perf_counter() - overall_started
    lines: list[str] = []
    lines.append("Phase 14 - OOF SHAP interpretation summary")
    lines.append("=" * 70)
    lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")
    lines.append("")
    lines.append(f"Zn records: {len(zn_df)}")
    lines.append(f"Zn framework groups: {int(zn_groups.nunique())}")
    lines.append(f"CORE features: {len(features)}")
    lines.append("frozen model: CatBoost")
    for target in TARGETS:
        lines.append(
            f"    [{target}] deployment regime: {DEPLOYMENT_REGIME[target]}, "
            f"params: {json.dumps(catboost_params[target], default=str)}"
        )
    lines.append("Phase 10 fixed Zn folds reused (cv_fold 0-4); each Zn record explained exactly once")
    lines.append("framework overlap between training and validation: 0 (all folds)")
    lines.append(f"SHAP reconstruction maximum error: {max_recon_error:.3e} (tolerance 1e-6)")
    lines.append(f"Phase 13 prediction consistency maximum difference: {max_p13_diff:.3e}")
    lines.append("")
    for target, tag in (("average_voltage", "Voltage"), ("capacity_grav", "Capacity")):
        lines.append(f"{tag} top 15 mean |SHAP| features:")
        sub = global_df[global_df["target"] == target].sort_values("rank").head(15)
        for _, row in sub.iterrows():
            lines.append(
                f"    {int(row['rank'])}. {row['feature']} ({row['feature_group']}): "
                f"mean|SHAP|={row['mean_abs_SHAP']:.4f}"
            )
        lines.append("")
    lines.append("feature-group SHAP attribution and Phase 13 ablation:")
    for target in TARGETS:
        lines.append(f"    [{target}]")
        sub = comparison_df[comparison_df["target"] == target]
        for _, row in sub.iterrows():
            lines.append(
                f"        {row['feature_group']}: mean|SHAP|={row['mean_group_abs_SHAP']:.4f} "
                f"(share={row['normalized_group_SHAP_share']:.3f}), "
                f"ablation delta RMSE={row['phase13_delta_RMSE_when_removed']:+.4f} "
                f"(SHAP rank={row['shap_rank']}, ablation rank={row['ablation_rank']})"
            )
    lines.append("")
    lines.append("working-ion interpretation:")
    if capacity_ion_constant:
        lines.append(
            "    capacity ZN_ONLY: all ion_* features are constant across the 434 Zn "
            "records, so their SHAP contribution carries no within-Zn "
            "discriminatory variation."
        )
    cap_ion_shap = global_df[
        (global_df["target"] == "capacity_grav")
        & (global_df["feature_group"] == "WORKING_ION")
    ]
    for _, row in cap_ion_shap.iterrows():
        lines.append(
            f"    capacity ion feature {row['feature']}: mean|SHAP|={row['mean_abs_SHAP']:.4f}"
        )
    lines.append(
        "    voltage MIXED_ION_GROUP_SAFE: working-ion SHAP is interpreted as the "
        "predictive contribution in the cross-ion model."
    )
    lines.append("")
    lines.append("symmetry results:")
    for target, tag in (("average_voltage", "Voltage"), ("capacity_grav", "Capacity")):
        sub = comparison_df[comparison_df["target"] == target]
        sym = sub[sub["feature_group"] == "SYMMETRY"].iloc[0]
        lines.append(
            f"    {tag}: SYMMETRY mean|SHAP|={sym['mean_group_abs_SHAP']:.4f}, "
            f"ablation delta RMSE={sym['phase13_delta_RMSE_when_removed']:+.4f}"
        )
    lines.append("")
    lines.append("notes:")
    lines.append("    feature_missing_fraction in shap_feature_direction.csv is the")
    lines.append("    raw pre-imputation Zn missing fraction (imputed values are never")
    lines.append("    reported as original missingness).")
    lines.append("")
    lines.append("output files:")
    for path in (
        OUT_SHAP_VALUES, OUT_GLOBAL, OUT_GROUP, OUT_DIRECTION, OUT_COMPARISON,
        OUT_EXAMPLES, FIG_DIR, OUT_SUMMARY,
    ):
        lines.append(f"    {path.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append("")
    lines.append("policy statements:")
    lines.append("    Phase 14 performs no hyperparameter tuning.")
    lines.append("    Phase 9 CatBoost parameters remain fixed.")
    lines.append("    Phase 10 Zn validation folds remain fixed.")
    lines.append("    Phase 11 deployment regimes remain fixed.")
    lines.append("    SHAP values are computed only for held-out OOF Zn records.")
    lines.append("    Each Zn record is explained exactly once.")
    lines.append("    Framework overlap between training and validation is zero.")
    lines.append("    SHAP attribution is predictive, not causal.")
    lines.append("    No candidate screening was performed.")
    lines.append("    No final all-data deployment model was refit.")
    lines.append("")
    lines.append(f"runtime: {elapsed:.1f} s")
    lines.append("")
    OUT_SUMMARY.write_text("\\n".join(lines), encoding="utf-8")
    log(f"Saved SHAP summary -> {OUT_SUMMARY}")

    # ---- 23. console -------------------------------------------------------------------------------------
    def top_features(target, k=5):
        sub = global_df[global_df["target"] == target].sort_values("rank")
        return ", ".join(sub["feature"].head(k).tolist())

    def top_group(target):
        sub = group_df[group_df["target"] == target]
        return sub.loc[sub["mean_group_abs_SHAP"].idxmax(), "feature_group"]

    print("")
    print("Phase 14 OOF SHAP interpretation completed.")
    print(f"Voltage top 5 SHAP features: {top_features('average_voltage')}")
    print(f"Voltage top SHAP group: {top_group('average_voltage')}")
    print(f"Capacity top 5 SHAP features: {top_features('capacity_grav')}")
    print(f"Capacity top SHAP group: {top_group('capacity_grav')}")
    print(f"SHAP reconstruction maximum error: {max_recon_error:.3e}")
    print(f"Phase13 consistency maximum difference: {max_p13_diff:.3e}")
    print(f"outputs: {OUT_DIR}")
    print(f"figures: {FIG_DIR}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
''',
    15: '''# -*- coding: utf-8 -*-
"""
Phase 15 - Final deployment model refit.

Freezes the deployment policy decided in Phases 9-14 and refits the final
models on ALL eligible training records. No model selection, no tuning, no
validation folds, no candidate ranking/screening happen here.

Frozen deployment policy:
    average_voltage:
        model = CatBoost, feature set = 53 CORE_NUMERIC
        development validation regime = MIXED_ION_GROUP_SAFE
        final training regime = MIXED_ION_ALL_INSERTION
        -> refit on ALL 6847 all-battery insertion records
    capacity_grav:
        model = CatBoost, feature set = 53 CORE_NUMERIC
        development validation regime = ZN_ONLY
        final training regime = ZN_ONLY_ALL_ZN_INSERTION
        -> refit on ALL 434 Zn insertion records

Important naming note: the final Voltage strategy is NOT called
MIXED_ION_GROUP_SAFE (there is no validation group at final refit); its
final name is MIXED_ION_ALL_INSERTION. Capacity final name is
ZN_ONLY_ALL_ZN_INSERTION.

The final training regime is a DEVELOPMENT DECISION based on Phase 11 point
estimates and Phase 12 uncertainty results; it is NOT an independent
external-validation winner.

This phase:
    * fits two final sklearn Pipelines (imputer + CatBoost), imputer fit on
      the final training data only (candidates never participate in the fit)
    * saves the FULL pipelines as joblib artifacts
    * reload-QA checks the saved artifacts (atol 1e-12)
    * candidate inference dry-run (first 20 rows) - formal candidate
      predictions are NOT produced here
    * writes deployment manifests (CSV + JSON) and QA reports

Outputs:
    04_Models/Deployment/Voltage/final_voltage_catboost_pipeline.joblib
    04_Models/Deployment/Capacity/final_capacity_catboost_pipeline.joblib
    04_Models/Deployment/deployment_model_manifest.csv
    04_Models/Deployment/deployment_model_manifest.json
    05_Results/Model_Preparation/Phase15_Final_Refit/
        final_refit_training_summary.csv
        final_refit_feature_missingness.csv
        final_refit_candidate_compatibility.csv
        phase15_final_refit_summary.txt

Run from the project root:
    py 03_Code/Model_Training/15_final_deployment_refit.py
"""

from __future__ import annotations

import hashlib
import importlib.metadata
import json
import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

import joblib

from sklearn.pipeline import Pipeline
from sklearn.impute import SimpleImputer

try:
    from catboost import CatBoostRegressor
    CATBOOST_AVAILABLE = True
except ImportError:  # pragma: no cover
    CatBoostRegressor = None  # type: ignore[assignment]
    CATBOOST_AVAILABLE = False

# ---------------------------------------------------------------------------
# Paths
# ---------------------------------------------------------------------------
PROJECT_ROOT = Path(_SCIENCE_WORK_ROOT)

IN_ALL = PROJECT_ROOT / "02_Datasets" / "Features" / "all_battery_candidate_compatible_features.csv"
IN_ZN = PROJECT_ROOT / "02_Datasets" / "Features" / "zinc_battery_candidate_compatible_features.csv"
IN_CAND = PROJECT_ROOT / "02_Datasets" / "Features" / "zinc_candidates_candidate_compatible_features.csv"
IN_CORE = PROJECT_ROOT / "02_Datasets" / "Features" / "Feature_Sets" / "core_numeric_features.csv"
IN_BEST = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase9_Tuning" / "best_hyperparameters.csv"
IN_P11 = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase11_Training_Regime" / "training_regime_pooled_oof_metrics.csv"
IN_P12 = PROJECT_ROOT / "05_Results" / "Uncertainty" / "Phase12_Training_Regime" / "framework_cluster_bootstrap_summary.csv"
IN_P13 = PROJECT_ROOT / "05_Results" / "Ablation" / "Phase13_Feature_Groups" / "feature_ablation_pooled_oof_metrics.csv"
IN_P14 = PROJECT_ROOT / "05_Results" / "SHAP" / "Phase14_OOF_SHAP" / "shap_global_feature_importance.csv"

DEPLOY_DIR = PROJECT_ROOT / "04_Models" / "Deployment"
VOLTAGE_DIR = DEPLOY_DIR / "Voltage"
CAPACITY_DIR = DEPLOY_DIR / "Capacity"
OUT_VOLTAGE_MODEL = VOLTAGE_DIR / "final_voltage_catboost_pipeline.joblib"
OUT_CAPACITY_MODEL = CAPACITY_DIR / "final_capacity_catboost_pipeline.joblib"
OUT_MANIFEST_CSV = DEPLOY_DIR / "deployment_model_manifest.csv"
OUT_MANIFEST_JSON = DEPLOY_DIR / "deployment_model_manifest.json"

RESULT_DIR = PROJECT_ROOT / "05_Results" / "Model_Preparation" / "Phase15_Final_Refit"
OUT_TRAIN_SUMMARY = RESULT_DIR / "final_refit_training_summary.csv"
OUT_MISSINGNESS = RESULT_DIR / "final_refit_feature_missingness.csv"
OUT_COMPAT = RESULT_DIR / "final_refit_candidate_compatibility.csv"
OUT_SUMMARY = RESULT_DIR / "phase15_final_refit_summary.txt"

TARGETS = ("average_voltage", "capacity_grav")
MODEL_NAME = "CatBoost"

DEPLOYMENT_POLICY = {
    "average_voltage": {
        "development_validation_regime": "MIXED_ION_GROUP_SAFE",
        "final_training_regime": "MIXED_ION_ALL_INSERTION",
        "working_ion_scope": "all working ions (mixed-ion)",
    },
    "capacity_grav": {
        "development_validation_regime": "ZN_ONLY",
        "final_training_regime": "ZN_ONLY_ALL_ZN_INSERTION",
        "working_ion_scope": "Zn only",
    },
}

DEVELOPMENT_DECISION_NOTE = (
    "Regime frozen using Phase 11-14 development evidence; "
    "not an independent external-validation decision."
)

FORBIDDEN_IN_FEATURES = {
    "average_voltage",
    "capacity_grav",
    "capacity_vol",
    "energy_grav",
    "energy_vol",
    # battery-pair / reaction-derived leakage fields (defensive; CORE never has them)
    "adj_pairs",
    "max_voltage_step",
    "num_steps",
    "max_delta_volume",
    "fracA_charge",
    "fracA_discharge",
    "stability_charge",
    "stability_discharge",
    "reaction",
}


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------
def log(message: str) -> None:
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S")
    print(f"[{stamp}Z] {message}", flush=True)


def sig6(value) -> float | None:
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
        return float(f"{float(value):.6g}")
    except (TypeError, ValueError):
        return None


def package_version(name: str) -> str:
    try:
        return importlib.metadata.version(name)
    except importlib.metadata.PackageNotFoundError:
        return "not installed"


def atomic_to_csv(df: pd.DataFrame, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    df.to_csv(tmp, index=False, encoding="utf-8-sig")
    os.replace(tmp, path)
    log(f"Saved {len(df)} rows -> {path}")


def read_required(path: Path) -> pd.DataFrame:
    if not path.is_file():
        log(f"ERROR: required input file not found: {path}")
        sys.exit(1)
    return pd.read_csv(path, low_memory=False)


def sha256_of_lines(lines: list[str]) -> str:
    payload = "\\n".join(lines)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def make_pipeline(best_params: dict) -> Pipeline:
    model = CatBoostRegressor(
        loss_function="RMSE",
        random_seed=42,
        verbose=False,
        allow_writing_files=False,
        thread_count=_SCIENCE_THREADS,
    )
    pipeline = Pipeline(
        [("imputer", SimpleImputer(strategy="median")), ("model", model)]
    )
    # Phase 9 saved sklearn Pipeline parameter names (model__*): keep the
    # prefix and use pipeline.set_params directly. Values are unchanged.
    pipeline.set_params(**best_params)
    return pipeline


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    overall_started = time.perf_counter()
    log("Phase 15 - final deployment refit (frozen deployment policy)")

    if not CATBOOST_AVAILABLE:
        log("ERROR: catboost is not installed. Install with: py -m pip install catboost")
        return 1

    # ---- 1. inputs ---------------------------------------------------------
    all_df = read_required(IN_ALL)
    zn_df = read_required(IN_ZN)
    cand_df = read_required(IN_CAND)
    core_set = read_required(IN_CORE)
    best_df = read_required(IN_BEST)
    read_required(IN_P11)   # Phase 11-14 evidence files: read to confirm
    read_required(IN_P12)   # existence; they never influence the fit.
    read_required(IN_P13)
    read_required(IN_P14)

    # ---- 2. features --------------------------------------------------------
    features = core_set["feature"].tolist()
    if len(features) != 53:
        log(f"ERROR: CORE_NUMERIC must contain exactly 53 features; found {len(features)}")
        return 1
    forbidden_found = [f for f in features if f in FORBIDDEN_IN_FEATURES]
    charge_like = [f for f in features if f.startswith("charge_")]
    if forbidden_found or charge_like:
        log(f"ERROR: forbidden fields in feature set: {forbidden_found} charge_*={charge_like}")
        return 1
    log(f"feature set: {len(features)} CORE_NUMERIC features; no target/leakage fields")

    # ---- candidate compatibility QA (pre-fit) ---------------------------------
    compat_rows: list[dict] = []
    for label, df in (("all_battery", all_df), ("zinc_battery", zn_df), ("candidates", cand_df)):
        missing_cols = [f for f in features if f not in df.columns]
        projected_ok = list(df[features].columns) == features if not missing_cols else False
        compat_rows.append(
            {
                "check": f"{label}_53_features_present",
                "value": len(features) - len(missing_cols),
                "status": "PASS" if not missing_cols else "FAIL",
                "details": f"missing: {missing_cols or 'none'}",
            }
        )
        compat_rows.append(
            {
                "check": f"{label}_feature_order_compatible",
                "value": bool(projected_ok),
                "status": "PASS" if projected_ok else "FAIL",
                "details": f"list(df[features].columns) == features",
            }
        )
        if missing_cols or not projected_ok:
            log(f"ERROR: {label} feature schema incompatible")
            return 1

    n_candidates = len(cand_df)
    if n_candidates != 6874:
        log(f"WARNING: candidate pool has {n_candidates} rows (previous expectation was 6874)")
    compat_rows.append(
        {
            "check": "candidate_row_count",
            "value": n_candidates,
            "status": "PASS",
            "details": "actual count recorded; no candidate records are deleted",
        }
    )
    compat_rows.append(
        {
            "check": "forbidden_features_absent_from_model_set",
            "value": len(forbidden_found) + len(charge_like),
            "status": "PASS",
            "details": "targets/leakage/charge_*/battery-pair fields absent",
        }
    )

    # In-memory only: +-inf -> NaN (raw CSVs are never modified).
    all_df = all_df.copy()
    zn_df = zn_df.copy()
    cand_df = cand_df.copy()
    all_df[features] = all_df[features].replace([np.inf, -np.inf], np.nan)
    zn_df[features] = zn_df[features].replace([np.inf, -np.inf], np.nan)
    cand_df[features] = cand_df[features].replace([np.inf, -np.inf], np.nan)

    # ---- fingerprints --------------------------------------------------------
    feature_schema_sha256 = sha256_of_lines(features)
    log(f"feature schema SHA256: {feature_schema_sha256}")

    # ---- Phase 9 best params (model__* format kept as-is) ------------------------
    best_params: dict[str, dict] = {}
    for target in TARGETS:
        rows = best_df[(best_df["target"] == target) & (best_df["model"] == MODEL_NAME)]
        if rows.empty:
            log(f"ERROR: no Phase 9 best hyperparameters for {target} + {MODEL_NAME}")
            return 1
        best_params[target] = json.loads(rows.iloc[0]["best_params_json"])

    # ---- 3. fit, save, reload-QA, dry-run ----------------------------------------
    training_summary_rows: list[dict] = []
    model_paths: dict[str, Path] = {}
    training_uid_hashes: dict[str, str] = {}
    n_train_map: dict[str, int] = {}

    DEPLOY_DIR.mkdir(parents=True, exist_ok=True)
    RESULT_DIR.mkdir(parents=True, exist_ok=True)

    # ---------- Voltage -----------------------------------------------------------
    target = "average_voltage"
    log(f"== {target}: final training regime {DEPLOYMENT_POLICY[target]['final_training_regime']} ==")
    X = all_df[features]
    y = pd.to_numeric(all_df[target], errors="coerce")
    if int(y.isna().sum()):
        log(f"ERROR: {target} target has {int(y.isna().sum())} missing value(s)")
        return 1
    n_train = len(all_df)
    n_unique_uid = int(all_df["record_uid"].nunique())
    n_framework = int(all_df["framework_formula"].nunique(dropna=True)) if "framework_formula" in all_df.columns else 0
    ion_dist = all_df["working_ion"].value_counts(dropna=False).to_dict()
    training_summary_rows.append(
        {
            "target": target,
            "final_training_regime": DEPLOYMENT_POLICY[target]["final_training_regime"],
            "n_train": n_train,
            "n_unique_record_uid": n_unique_uid,
            "n_framework_groups": n_framework,
            "working_ion_distribution": json.dumps({str(k): int(v) for k, v in ion_dist.items()}, default=str),
            "target_min": sig6(float(y.min())),
            "target_median": sig6(float(y.median())),
            "target_mean": sig6(float(y.mean())),
            "target_max": sig6(float(y.max())),
        }
    )
    log(f"voltage training: n={n_train}, unique uid={n_unique_uid}, frameworks={n_framework}")

    pipeline_v = make_pipeline(best_params[target])
    pipeline_v.fit(X, y)
    VOLTAGE_DIR.mkdir(parents=True, exist_ok=True)
    joblib.dump(pipeline_v, OUT_VOLTAGE_MODEL)
    model_paths[target] = OUT_VOLTAGE_MODEL
    training_uid_hashes[target] = sha256_of_lines(sorted(all_df["record_uid"].astype(str).tolist()))
    n_train_map[target] = n_train

    # reload QA (first 10 rows of the training data)
    reloaded_v = joblib.load(OUT_VOLTAGE_MODEL)
    pred_orig_v = pipeline_v.predict(X.head(10))
    pred_reload_v = reloaded_v.predict(X.head(10))
    if not np.allclose(pred_orig_v, pred_reload_v, rtol=0, atol=1e-12):
        log(f"ERROR: voltage reload QA failed (max diff "
            f"{float(np.max(np.abs(pred_orig_v - pred_reload_v))):.3e})")
        return 1
    log("voltage pipeline saved + reload QA passed (atol 1e-12)")

    # ---------- Capacity ----------------------------------------------------------
    target = "capacity_grav"
    log(f"== {target}: final training regime {DEPLOYMENT_POLICY[target]['final_training_regime']} ==")
    if int((zn_df["working_ion"] != "Zn").sum()):
        log("ERROR: capacity training data contains non-Zn records")
        return 1
    X = zn_df[features]
    y = pd.to_numeric(zn_df[target], errors="coerce")
    if int(y.isna().sum()):
        log(f"ERROR: {target} target has {int(y.isna().sum())} missing value(s)")
        return 1
    n_train = len(zn_df)
    n_unique_uid = int(zn_df["record_uid"].nunique())
    n_framework = int(zn_df["framework_formula"].nunique(dropna=True)) if "framework_formula" in zn_df.columns else 0
    training_summary_rows.append(
        {
            "target": target,
            "final_training_regime": DEPLOYMENT_POLICY[target]["final_training_regime"],
            "n_train": n_train,
            "n_unique_record_uid": n_unique_uid,
            "n_framework_groups": n_framework,
            "working_ion_distribution": json.dumps(
                {str(k): int(v) for k, v in zn_df["working_ion"].value_counts(dropna=False).items()},
                default=str,
            ),
            "target_min": sig6(float(y.min())),
            "target_median": sig6(float(y.median())),
            "target_mean": sig6(float(y.mean())),
            "target_max": sig6(float(y.max())),
        }
    )
    log(f"capacity training: n={n_train}, unique uid={n_unique_uid}, frameworks={n_framework}")

    pipeline_c = make_pipeline(best_params[target])
    pipeline_c.fit(X, y)
    CAPACITY_DIR.mkdir(parents=True, exist_ok=True)
    joblib.dump(pipeline_c, OUT_CAPACITY_MODEL)
    model_paths[target] = OUT_CAPACITY_MODEL
    training_uid_hashes[target] = sha256_of_lines(sorted(zn_df["record_uid"].astype(str).tolist()))
    n_train_map[target] = n_train

    reloaded_c = joblib.load(OUT_CAPACITY_MODEL)
    pred_orig_c = pipeline_c.predict(X.head(10))
    pred_reload_c = reloaded_c.predict(X.head(10))
    if not np.allclose(pred_orig_c, pred_reload_c, rtol=0, atol=1e-12):
        log(f"ERROR: capacity reload QA failed (max diff "
            f"{float(np.max(np.abs(pred_orig_c - pred_reload_c))):.3e})")
        return 1
    log("capacity pipeline saved + reload QA passed (atol 1e-12)")

    # ---------- candidate inference dry-run (NOT formal screening) -----------------
    dry_head = cand_df[features].head(20)
    dry_voltage_ok = True
    dry_capacity_ok = True
    try:
        dry_v = pipeline_v.predict(dry_head)
        if not np.all(np.isfinite(dry_v)):
            dry_voltage_ok = False
    except Exception as exc:  # noqa: BLE001
        log(f"ERROR: voltage candidate dry-run raised: {type(exc).__name__}: {exc}")
        dry_voltage_ok = False
    try:
        dry_c = pipeline_c.predict(dry_head)
        if not np.all(np.isfinite(dry_c)):
            dry_capacity_ok = False
    except Exception as exc:  # noqa: BLE001
        log(f"ERROR: capacity candidate dry-run raised: {type(exc).__name__}: {exc}")
        dry_capacity_ok = False
    if not (dry_voltage_ok and dry_capacity_ok):
        log("ERROR: candidate dry-run produced non-finite values or raised")
        return 1
    log("candidate inference dry-run passed (first 20 rows, finite values)")

    compat_rows.append(
        {
            "check": "candidate_prediction_dry_run_voltage",
            "value": "finite",
            "status": "PASS" if dry_voltage_ok else "FAIL",
            "details": "pipeline_v.predict(candidates[features].head(20))",
        }
    )
    compat_rows.append(
        {
            "check": "candidate_prediction_dry_run_capacity",
            "value": "finite",
            "status": "PASS" if dry_capacity_ok else "FAIL",
            "details": "pipeline_c.predict(candidates[features].head(20))",
        }
    )
    compat_rows.append(
        {
            "check": "feature_schema_hash_match",
            "value": feature_schema_sha256,
            "status": "PASS",
            "details": "both models share the identical 53-feature schema hash",
        }
    )
    compat_rows.append(
        {
            "check": "candidate_rows_retained",
            "value": n_candidates,
            "status": "PASS",
            "details": "no candidate records were removed",
        }
    )

    # ---- 6/13/14. manifests ------------------------------------------------------
    versions = {
        "python": sys.version.split()[0],
        "numpy": package_version("numpy"),
        "pandas": package_version("pandas"),
        "scikit-learn": package_version("scikit-learn"),
        "catboost": package_version("catboost"),
        "joblib": package_version("joblib"),
    }
    created_utc = datetime.now(timezone.utc).isoformat()

    manifest_rows = []
    for target in TARGETS:
        manifest_rows.append(
            {
                "target": target,
                "model": MODEL_NAME,
                "feature_set": "CORE_NUMERIC",
                "n_features": len(features),
                "development_validation_regime": DEPLOYMENT_POLICY[target]["development_validation_regime"],
                "final_training_regime": DEPLOYMENT_POLICY[target]["final_training_regime"],
                "n_train": n_train_map[target],
                "n_unique_record_uid": int(
                    all_df["record_uid"].nunique() if target == "average_voltage" else zn_df["record_uid"].nunique()
                ),
                "n_framework_groups": int(
                    all_df["framework_formula"].nunique(dropna=True)
                    if target == "average_voltage" and "framework_formula" in all_df.columns
                    else zn_df["framework_formula"].nunique(dropna=True)
                    if "framework_formula" in zn_df.columns
                    else 0
                ),
                "working_ion_scope": DEPLOYMENT_POLICY[target]["working_ion_scope"],
                "phase9_params_json": json.dumps(best_params[target], default=str),
                "feature_schema_sha256": feature_schema_sha256,
                "training_record_uid_sha256": training_uid_hashes[target],
                "model_file": model_paths[target].relative_to(PROJECT_ROOT).as_posix(),
                "imputer_strategy": "median",
                "random_seed": 42,
                "development_decision_note": DEVELOPMENT_DECISION_NOTE,
                "created_utc": created_utc,
            }
        )
    manifest_df = pd.DataFrame(manifest_rows)
    atomic_to_csv(manifest_df, OUT_MANIFEST_CSV)

    json_manifest = {
        "created_utc": created_utc,
        "feature_set": {
            "name": "CORE_NUMERIC",
            "n_features": len(features),
            "features": features,
            "feature_schema_sha256": feature_schema_sha256,
        },
        "models": {
            "average_voltage": {
                "model": MODEL_NAME,
                "development_validation_regime": DEPLOYMENT_POLICY["average_voltage"]["development_validation_regime"],
                "final_training_regime": DEPLOYMENT_POLICY["average_voltage"]["final_training_regime"],
                "working_ion_scope": DEPLOYMENT_POLICY["average_voltage"]["working_ion_scope"],
                "n_train": n_train_map["average_voltage"],
                "training_record_uid_sha256": training_uid_hashes["average_voltage"],
                "phase9_params": best_params["average_voltage"],
                "model_file": OUT_VOLTAGE_MODEL.relative_to(PROJECT_ROOT).as_posix(),
            },
            "capacity_grav": {
                "model": MODEL_NAME,
                "development_validation_regime": DEPLOYMENT_POLICY["capacity_grav"]["development_validation_regime"],
                "final_training_regime": DEPLOYMENT_POLICY["capacity_grav"]["final_training_regime"],
                "working_ion_scope": DEPLOYMENT_POLICY["capacity_grav"]["working_ion_scope"],
                "n_train": n_train_map["capacity_grav"],
                "training_record_uid_sha256": training_uid_hashes["capacity_grav"],
                "phase9_params": best_params["capacity_grav"],
                "model_file": OUT_CAPACITY_MODEL.relative_to(PROJECT_ROOT).as_posix(),
            },
        },
        "hashes": {
            "feature_schema_sha256": feature_schema_sha256,
            "voltage_training_record_uid_sha256": training_uid_hashes["average_voltage"],
            "capacity_training_record_uid_sha256": training_uid_hashes["capacity_grav"],
        },
        "versions": versions,
        "deployment_policy": {
            "target": {
                "average_voltage": "CatBoost + 53 CORE_NUMERIC, final regime MIXED_ION_ALL_INSERTION",
                "capacity_grav": "CatBoost + 53 CORE_NUMERIC, final regime ZN_ONLY_ALL_ZN_INSERTION",
            },
            "development_decision_note": DEVELOPMENT_DECISION_NOTE,
        },
        "input_file_paths": {
            "all_battery_features": IN_ALL.relative_to(PROJECT_ROOT).as_posix(),
            "zinc_battery_features": IN_ZN.relative_to(PROJECT_ROOT).as_posix(),
            "candidate_features": IN_CAND.relative_to(PROJECT_ROOT).as_posix(),
            "core_feature_set": IN_CORE.relative_to(PROJECT_ROOT).as_posix(),
            "phase9_best_hyperparameters": IN_BEST.relative_to(PROJECT_ROOT).as_posix(),
        },
        "output_model_paths": {
            "voltage": OUT_VOLTAGE_MODEL.relative_to(PROJECT_ROOT).as_posix(),
            "capacity": OUT_CAPACITY_MODEL.relative_to(PROJECT_ROOT).as_posix(),
        },
    }
    OUT_MANIFEST_JSON.write_text(json.dumps(json_manifest, indent=2), encoding="utf-8")
    log(f"Saved deployment manifests -> {OUT_MANIFEST_CSV} / {OUT_MANIFEST_JSON}")

    # ---- 7/8. reports -------------------------------------------------------------
    atomic_to_csv(pd.DataFrame(training_summary_rows), OUT_TRAIN_SUMMARY)

    missingness_rows = []
    for dataset_label, df in (("voltage_training", all_df), ("capacity_training", zn_df), ("candidate_pool", cand_df)):
        for feature in features:
            missing = int(df[feature].isna().sum())
            missingness_rows.append(
                {
                    "feature": feature,
                    "dataset": dataset_label,
                    "missing_count": missing,
                    "missing_fraction": sig6(missing / len(df)),
                }
            )
    atomic_to_csv(pd.DataFrame(missingness_rows), OUT_MISSINGNESS)
    atomic_to_csv(pd.DataFrame(compat_rows), OUT_COMPAT)

    # ---- 9. summary ----------------------------------------------------------------
    elapsed = time.perf_counter() - overall_started
    lines: list[str] = []
    lines.append("Phase 15 - Final deployment refit")
    lines.append("=" * 70)
    lines.append(f"generated (UTC): {created_utc}")
    lines.append("")
    lines.append("Voltage:")
    lines.append("    CatBoost")
    lines.append("    53 CORE_NUMERIC")
    lines.append(f"    final training regime = {DEPLOYMENT_POLICY['average_voltage']['final_training_regime']}")
    lines.append(f"    n_train actual value = {n_train_map['average_voltage']}")
    lines.append("")
    lines.append("Capacity:")
    lines.append("    CatBoost")
    lines.append("    53 CORE_NUMERIC")
    lines.append(f"    final training regime = {DEPLOYMENT_POLICY['capacity_grav']['final_training_regime']}")
    lines.append(f"    n_train actual value = {n_train_map['capacity_grav']}")
    lines.append("")
    lines.append(f"Candidate pool:")
    lines.append(f"    actual row count: {n_candidates}")
    lines.append(f"    schema compatible: yes")
    lines.append(f"    dry-run passed: {'yes' if dry_voltage_ok and dry_capacity_ok else 'no'}")
    lines.append("")
    lines.append("model files:")
    lines.append(f"    {OUT_VOLTAGE_MODEL.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append(f"    {OUT_CAPACITY_MODEL.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append("")
    lines.append(f"feature schema SHA256: {feature_schema_sha256}")
    lines.append(f"Voltage training-record SHA256: {training_uid_hashes['average_voltage']}")
    lines.append(f"Capacity training-record SHA256: {training_uid_hashes['capacity_grav']}")
    lines.append("")
    lines.append("package versions:")
    for name, version in versions.items():
        lines.append(f"    {name}: {version}")
    lines.append("")
    lines.append("policy statements:")
    lines.append("    No new model selection was performed.")
    lines.append("    No new hyperparameter tuning was performed.")
    lines.append("    No validation fold was created.")
    lines.append("    All eligible records were used for final refit according to the")
    lines.append("    pre-frozen target-specific deployment policy.")
    lines.append("    Phase 15 training metrics, if reported, are not generalization metrics.")
    lines.append("    No candidate ranking or screening was performed.")
    lines.append("    Candidate data were never used to fit the imputer or model.")
    lines.append("")
    lines.append(f"runtime: {elapsed:.1f} s")
    lines.append("")
    OUT_SUMMARY.write_text("\\n".join(lines), encoding="utf-8")
    log(f"Saved final refit summary -> {OUT_SUMMARY}")

    # ---- 10. console -----------------------------------------------------------------
    print("")
    print("Phase 15 final deployment refit completed.")
    print("Voltage:")
    print(f"    training regime: {DEPLOYMENT_POLICY['average_voltage']['final_training_regime']}")
    print(f"    n_train: {n_train_map['average_voltage']}")
    print(f"    model path: {OUT_VOLTAGE_MODEL}")
    print("Capacity:")
    print(f"    training regime: {DEPLOYMENT_POLICY['capacity_grav']['final_training_regime']}")
    print(f"    n_train: {n_train_map['capacity_grav']}")
    print(f"    model path: {OUT_CAPACITY_MODEL}")
    print("Candidate compatibility:")
    print(f"    n_candidates: {n_candidates}")
    print("    schema PASS")
    print(f"    voltage dry-run {'PASS' if dry_voltage_ok else 'FAIL'}")
    print(f"    capacity dry-run {'PASS' if dry_capacity_ok else 'FAIL'}")
    print(f"outputs: {DEPLOY_DIR}")
    print(f"         {RESULT_DIR}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
''',
    16: '''# -*- coding: utf-8 -*-
"""
Phase 16 - Candidate prediction uncertainty + applicability-domain / OOD
analysis for the Phase 15 final deployment models.

This phase:
    1. uses the SAVED Phase 15 final pipelines (no retraining of the final
       models) to predict all Zn candidates;
    2. builds a 5-member development ensemble per target (reconstructing the
       Phase 13 development fits: MIXED_ION_GROUP_SAFE for voltage, ZN_ONLY
       for capacity) purely as an epistemic-disagreement / model-instability
       proxy;
    3. builds a Zn-domain applicability-domain reference from the 434 known
       Zn insertion records (imputer + scaler + PCA fit ONLY on those Zn
       records; candidates are only transformed);
    4. computes PCA-5NN applicability distances and IN_DOMAIN / BORDERLINE /
       OOD flags;
    5. flags candidates that overlap with known Zn discharge materials;
    6. saves the full table for the Phase 17 screening stage.

Hard rules: no retuning, no model re-selection, no candidate ranking, no
composite score, no Top-N list, no automatic deletion of any candidate, and
candidate data NEVER participates in any preprocessor fitting.

Ensemble std is a development-ensemble disagreement proxy (epistemic proxy),
NOT a calibrated confidence interval.

Outputs:
    05_Results/Uncertainty/Phase16_Candidate_Uncertainty_OOD/
        candidate_uncertainty_ood.csv
        ensemble_member_predictions.csv
        oof_residual_reference.csv
        zn_applicability_domain_reference.csv
        zn_feature_range_reference.csv
        known_material_overlap_summary.csv
        phase16_candidate_uncertainty_ood_summary.txt
    06_Figures/Draft_Figures/Phase16_Candidate_Uncertainty_OOD/
        01..08 PNG (600 dpi) + PDF

Run from the project root:
    py 03_Code/Uncertainty/16_candidate_uncertainty_and_ood.py
"""

from __future__ import annotations

import hashlib
import json
import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

import joblib

from sklearn.pipeline import Pipeline
from sklearn.impute import SimpleImputer
from sklearn.preprocessing import StandardScaler
from sklearn.decomposition import PCA
from sklearn.neighbors import NearestNeighbors

try:
    from catboost import CatBoostRegressor
    CATBOOST_AVAILABLE = True
except ImportError:  # pragma: no cover
    CatBoostRegressor = None  # type: ignore[assignment]
    CATBOOST_AVAILABLE = False

# ---------------------------------------------------------------------------
# Paths
# ---------------------------------------------------------------------------
PROJECT_ROOT = Path(_SCIENCE_WORK_ROOT)

IN_ALL = PROJECT_ROOT / "02_Datasets" / "Features" / "all_battery_candidate_compatible_features.csv"
IN_ZN = PROJECT_ROOT / "02_Datasets" / "Features" / "zinc_battery_candidate_compatible_features.csv"
IN_CAND = PROJECT_ROOT / "02_Datasets" / "Features" / "zinc_candidates_candidate_compatible_features.csv"
IN_CORE = PROJECT_ROOT / "02_Datasets" / "Features" / "Feature_Sets" / "core_numeric_features.csv"
IN_PRIMARY = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "primary_group_holdout.csv"
IN_ZN_FOLDS = PROJECT_ROOT / "02_Datasets" / "Processed" / "Splits" / "zn_group_cv_folds.csv"
IN_ZN_ENRICHED = PROJECT_ROOT / "02_Datasets" / "Processed" / "zinc_battery_insertion_enriched.csv"
IN_BEST = PROJECT_ROOT / "05_Results" / "Metrics" / "Phase9_Tuning" / "best_hyperparameters.csv"
IN_P13_POOLED = PROJECT_ROOT / "05_Results" / "Ablation" / "Phase13_Feature_Groups" / "feature_ablation_pooled_oof_metrics.csv"
IN_P13_PREDS = PROJECT_ROOT / "05_Results" / "Predictions" / "Phase13_Feature_Groups" / "feature_ablation_oof_predictions.csv"
IN_MANIFEST_JSON = PROJECT_ROOT / "04_Models" / "Deployment" / "deployment_model_manifest.json"
IN_VOLTAGE_MODEL = PROJECT_ROOT / "04_Models" / "Deployment" / "Voltage" / "final_voltage_catboost_pipeline.joblib"
IN_CAPACITY_MODEL = PROJECT_ROOT / "04_Models" / "Deployment" / "Capacity" / "final_capacity_catboost_pipeline.joblib"

OUT_DIR = PROJECT_ROOT / "05_Results" / "Uncertainty" / "Phase16_Candidate_Uncertainty_OOD"
OUT_CAND = OUT_DIR / "candidate_uncertainty_ood.csv"
OUT_MEMBER = OUT_DIR / "ensemble_member_predictions.csv"
OUT_OOF_REF = OUT_DIR / "oof_residual_reference.csv"
OUT_AD_REF = OUT_DIR / "zn_applicability_domain_reference.csv"
OUT_RANGE_REF = OUT_DIR / "zn_feature_range_reference.csv"
OUT_OVERLAP = OUT_DIR / "known_material_overlap_summary.csv"
OUT_SUMMARY = OUT_DIR / "phase16_candidate_uncertainty_ood_summary.txt"

FIG_DIR = PROJECT_ROOT / "06_Figures" / "Draft_Figures" / "Phase16_Candidate_Uncertainty_OOD"

TARGETS = ("average_voltage", "capacity_grav")
MODEL_NAME = "CatBoost"
DEPLOYMENT_REGIME = {
    "average_voltage": "MIXED_ION_GROUP_SAFE",
    "capacity_grav": "ZN_ONLY",
}
FORBIDDEN_IN_FEATURES = {
    "average_voltage",
    "capacity_grav",
    "capacity_vol",
    "energy_grav",
    "energy_vol",
    "adj_pairs",
    "max_voltage_step",
}
N_FOLDS = 5
K_NEIGHBORS = 5
REPRO_TOLERANCE = 1e-6


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------
def log(message: str) -> None:
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S")
    print(f"[{stamp}Z] {message}", flush=True)


def sig6(value) -> float | None:
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
        return float(f"{float(value):.6g}")
    except (TypeError, ValueError):
        return None


def atomic_to_csv(df: pd.DataFrame, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    df.to_csv(tmp, index=False, encoding="utf-8-sig")
    os.replace(tmp, path)
    log(f"Saved {len(df)} rows -> {path}")


def save_figure(fig, path: Path) -> None:
    fig.tight_layout()
    fig.savefig(path.with_suffix(".png"), dpi=600)
    fig.savefig(path.with_suffix(".pdf"))
    plt.close(fig)
    log(f"  saved figure: {path.name}.png/.pdf")


def read_required(path: Path) -> pd.DataFrame:
    if not path.is_file():
        log(f"ERROR: required input file not found: {path}")
        sys.exit(1)
    return pd.read_csv(path, low_memory=False)


def sha256_of_lines(lines: list[str]) -> str:
    return hashlib.sha256("\\n".join(lines).encode("utf-8")).hexdigest()


def make_ensemble_pipeline(params: dict) -> Pipeline:
    model = CatBoostRegressor(
        loss_function="RMSE",
        random_seed=42,
        verbose=False,
        allow_writing_files=False,
        thread_count=1,  # identical to Phase 13 development fits
    )
    pipeline = Pipeline(
        [("imputer", SimpleImputer(strategy="median")), ("model", model)]
    )
    pipeline.set_params(**params)  # Phase 9 model__* keys, values unchanged
    return pipeline


# ---------------------------------------------------------------------------
# Figures
# ---------------------------------------------------------------------------
def figure_hist(series: np.ndarray, path: Path, title: str, xlabel: str) -> None:
    fig, ax = plt.subplots(figsize=(9, 5))
    ax.hist(series, bins=80, color="#4C72B0")
    ax.set_xlabel(xlabel)
    ax.set_ylabel("candidate count")
    ax.set_title(title)
    save_figure(fig, path)


def figure_two_hists(train: np.ndarray, cand: np.ndarray, path: Path,
                     title: str, xlabel: str) -> None:
    fig, ax = plt.subplots(figsize=(9, 5))
    ax.hist(train, bins=60, alpha=0.6, label="Zn reference (434)", color="#55A868")
    ax.hist(cand, bins=60, alpha=0.6, label="candidates", color="#4C72B0")
    ax.set_xlabel(xlabel)
    ax.set_ylabel("count")
    ax.set_title(title)
    ax.legend()
    save_figure(fig, path)


def figure_category_counts(cat_counts: dict, path: Path) -> None:
    fig, ax = plt.subplots(figsize=(8, 5))
    order = ["IN_DOMAIN", "BORDERLINE", "OOD"]
    values = [cat_counts.get(c, 0) for c in order]
    colors = ["#55A868", "#F0C571", "#C44E52"]
    ax.bar(order, values, color=colors)
    for i, v in enumerate(values):
        ax.text(i, v + 10, str(int(v)), ha="center", fontsize=10)
    ax.set_ylabel("candidate count")
    ax.set_title("candidate applicability-domain category counts")
    save_figure(fig, path)


def figure_scatter(x: np.ndarray, y: np.ndarray, path: Path, title: str,
                   xlabel: str, ylabel: str) -> None:
    fig, ax = plt.subplots(figsize=(9, 5.5))
    ax.scatter(x, y, s=5, alpha=0.4, color="#4C72B0")
    ax.set_xlabel(xlabel)
    ax.set_ylabel(ylabel)
    ax.set_title(title)
    save_figure(fig, path)


def figure_final_vs_mean(final: np.ndarray, mean: np.ndarray, path: Path, title: str) -> None:
    fig, ax = plt.subplots(figsize=(9, 7))
    ax.scatter(mean, final, s=6, alpha=0.4, color="#4C72B0")
    vmin = min(np.nanmin(mean), np.nanmin(final))
    vmax = max(np.nanmax(mean), np.nanmax(final))
    ax.plot([vmin, vmax], [vmin, vmax], "k--", lw=1)
    ax.set_xlabel("ensemble mean")
    ax.set_ylabel("final Phase 15 prediction")
    ax.set_title(title)
    save_figure(fig, path)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    overall_started = time.perf_counter()
    log("Phase 16 - candidate prediction uncertainty + AD/OOD analysis")

    if not CATBOOST_AVAILABLE:
        log("ERROR: catboost is not installed. Install with: py -m pip install catboost")
        return 1

    # ---- 1. inputs ---------------------------------------------------------
    all_df = read_required(IN_ALL)
    zn_df = read_required(IN_ZN)
    cand_df = read_required(IN_CAND)
    core_set = read_required(IN_CORE)
    primary = read_required(IN_PRIMARY)
    zn_folds = read_required(IN_ZN_FOLDS)
    zn_enriched = read_required(IN_ZN_ENRICHED)
    best_df = read_required(IN_BEST)
    read_required(IN_P13_POOLED)  # existence confirmation only
    p13_preds = read_required(IN_P13_PREDS)
    manifest_json = json.loads(IN_MANIFEST_JSON.read_text(encoding="utf-8"))

    # ---- 2. feature QA + Phase 15 schema hash ---------------------------------
    features = core_set["feature"].tolist()
    if len(features) != 53:
        log(f"ERROR: CORE_NUMERIC must contain exactly 53 features; found {len(features)}")
        return 1
    forbidden_found = [f for f in features if f in FORBIDDEN_IN_FEATURES]
    if forbidden_found:
        log(f"ERROR: forbidden fields in feature set: {forbidden_found}")
        return 1
    for label, df in (("all_battery", all_df), ("zinc_battery", zn_df), ("candidates", cand_df)):
        missing_cols = [f for f in features if f not in df.columns]
        if missing_cols:
            log(f"ERROR: {label} missing feature column(s): {missing_cols}")
            return 1
    feature_schema_sha256 = sha256_of_lines(features)
    manifest_hash = manifest_json.get("feature_set", {}).get("feature_schema_sha256")
    if manifest_hash != feature_schema_sha256:
        log(f"ERROR: feature schema hash mismatch: current={feature_schema_sha256}, "
            f"Phase15 manifest={manifest_hash}")
        return 1
    log(f"Phase 15 feature schema hash QA passed: {feature_schema_sha256[:16]}...")

    # ---- 3. final deployment predictions ----------------------------------------
    for path in (IN_VOLTAGE_MODEL, IN_CAPACITY_MODEL):
        if not path.is_file():
            log(f"ERROR: final deployment model not found: {path}")
            return 1
    final_v_pipeline = joblib.load(IN_VOLTAGE_MODEL)
    final_c_pipeline = joblib.load(IN_CAPACITY_MODEL)

    n_candidates = len(cand_df)
    if not bool(cand_df["material_id"].is_unique):
        log("ERROR: candidate material_id is not unique")
        return 1
    cand_X = cand_df[features]
    cand_X = cand_X.replace([np.inf, -np.inf], np.nan)

    pred_voltage_final = final_v_pipeline.predict(cand_X)
    pred_capacity_final = final_c_pipeline.predict(cand_X)
    if not (np.all(np.isfinite(pred_voltage_final)) and np.all(np.isfinite(pred_capacity_final))):
        log("ERROR: final deployment predictions contain non-finite values")
        return 1
    log(f"final predictions computed for {n_candidates} candidates (all finite, not clipped)")

    # ---- 4/5. 5-member ensembles + Phase 13 reproduction QA --------------------------
    all_df = all_df.merge(
        primary[["record_uid", "group_framework_formula"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    zn_df = zn_df.merge(
        zn_folds[["record_uid", "group_framework_formula", "cv_fold"]],
        on="record_uid", how="left", validate="one_to_one",
    )
    if int(all_df["group_framework_formula"].isna().sum()) or int(zn_df["cv_fold"].isna().sum()):
        log("ERROR: unmatched records after group/fold merge")
        return 1
    all_groups = all_df["group_framework_formula"]
    zn_groups = zn_df["group_framework_formula"]
    all_df[features] = all_df[features].replace([np.inf, -np.inf], np.nan)
    zn_df[features] = zn_df[features].replace([np.inf, -np.inf], np.nan)

    best_params: dict[str, dict] = {}
    for target in TARGETS:
        rows = best_df[(best_df["target"] == target) & (best_df["model"] == MODEL_NAME)]
        if rows.empty:
            log(f"ERROR: no Phase 9 best hyperparameters for {target} + {MODEL_NAME}")
            return 1
        best_params[target] = json.loads(rows.iloc[0]["best_params_json"])

    member_preds: dict[str, np.ndarray] = {}
    max_repro_diff: dict[str, float] = {}

    for target in TARGETS:
        regime = DEPLOYMENT_REGIME[target]
        log(f"== ensemble [{target}] regime {regime} ==")
        y_all = pd.to_numeric(all_df[target], errors="coerce")
        y_zn = pd.to_numeric(zn_df[target], errors="coerce")
        member_preds[target] = np.zeros((N_FOLDS, n_candidates), dtype=float)
        max_diff_target = 0.0

        for fold in range(N_FOLDS):
            val_mask = (zn_df["cv_fold"] == fold).to_numpy()
            val_groups = set(zn_groups[val_mask])

            if regime == "MIXED_ION_GROUP_SAFE":
                train_mask = (~all_groups.isin(val_groups)).to_numpy()
                X_train = all_df.loc[train_mask, features]
                y_train = y_all[train_mask]
            else:  # ZN_ONLY
                train_mask = (zn_df["cv_fold"] != fold).to_numpy()
                X_train = zn_df.loc[train_mask, features]
                y_train = y_zn[train_mask]

            # ---- per-fold leakage hard QA ----------------------------------------
            if regime == "MIXED_ION_GROUP_SAFE":
                train_uid = all_df.loc[train_mask, "record_uid"]
                train_groups = all_df.loc[train_mask, "group_framework_formula"]
            else:
                train_uid = zn_df.loc[train_mask, "record_uid"]
                train_groups = zn_df.loc[train_mask, "group_framework_formula"]
            val_uid = zn_df.loc[val_mask, "record_uid"]
            val_groups = zn_df.loc[val_mask, "group_framework_formula"]
            uid_overlap = len(set(train_uid) & set(val_uid))
            group_overlap = len(set(train_groups) & set(val_groups))
            if uid_overlap or group_overlap:
                log(f"ERROR: [{target}] fold {fold} leakage: uid_overlap={uid_overlap}, "
                    f"framework_overlap={group_overlap}")
                return 1
            if target == "capacity_grav":
                if not bool((zn_df.loc[train_mask, "working_ion"] == "Zn").all()):
                    log(f"ERROR: [{target}] fold {fold}: ZN_ONLY training contains non-Zn records")
                    return 1
            log(f"  [{target}] fold {fold}: uid_overlap=0, framework_overlap=0")

            pipeline = make_ensemble_pipeline(best_params[target])
            pipeline.fit(X_train, y_train)

            # candidate member predictions (all 6874)
            member_preds[target][fold] = pipeline.predict(cand_X)

            # reproduction QA against Phase 13 FULL_CORE on this fold's Zn records
            X_val = zn_df.loc[val_mask, features]
            our_pred = pipeline.predict(X_val)
            ours = pd.DataFrame(
                {
                    "record_uid": zn_df.loc[val_mask, "record_uid"].to_numpy(),
                    "y_true": y_zn[val_mask].to_numpy(dtype=float),
                    "y_pred": our_pred,
                }
            ).sort_values("record_uid").reset_index(drop=True)
            theirs = p13_preds[
                (p13_preds["target"] == target)
                & (p13_preds["deployment_regime"] == regime)
                & (p13_preds["feature_subset"] == "FULL_CORE")
                & (p13_preds["cv_fold"] == fold)
            ].sort_values("record_uid").reset_index(drop=True)
            if len(ours) != len(theirs):
                log(f"ERROR: row count mismatch vs Phase 13 for {target} fold {fold}: "
                    f"{len(ours)} vs {len(theirs)}")
                return 1
            if not np.array_equal(ours["record_uid"].to_numpy(), theirs["record_uid"].to_numpy()):
                log(f"ERROR: record_uid mismatch vs Phase 13 for {target} fold {fold}")
                return 1
            if not np.allclose(ours["y_true"].to_numpy(dtype=float),
                               theirs["y_true"].to_numpy(dtype=float), rtol=0, atol=1e-9):
                log(f"ERROR: y_true mismatch vs Phase 13 for {target} fold {fold}")
                return 1
            fold_diff = float(np.max(np.abs(
                ours["y_pred"].to_numpy(dtype=float)
                - theirs["y_pred"].to_numpy(dtype=float)
            )))
            max_diff_target = max(max_diff_target, fold_diff)
            if fold_diff >= REPRO_TOLERANCE:
                log(f"ERROR: Phase 13 reproduction failed for {target} fold {fold}: "
                    f"max diff={fold_diff:.3e} >= {REPRO_TOLERANCE}")
                return 1
            log(f"  [{target}] fold {fold}: n_train={int(train_mask.sum())}, "
                f"reproduction max diff={fold_diff:.3e}")

        max_repro_diff[target] = max_diff_target
        log(f"[{target}] ensemble reproduction QA max difference: {max_diff_target:.3e}")

    # ---- 6. ensemble statistics per candidate ---------------------------------------
    stats = {}
    for target, tag in (("average_voltage", "voltage"), ("capacity_grav", "capacity")):
        P = member_preds[target]  # (5, n_candidates)
        stats[f"{tag}_ensemble_mean"] = P.mean(axis=0)
        stats[f"{tag}_ensemble_std"] = P.std(axis=0, ddof=1)
        stats[f"{tag}_ensemble_min"] = P.min(axis=0)
        stats[f"{tag}_ensemble_max"] = P.max(axis=0)
        stats[f"{tag}_ensemble_range"] = P.max(axis=0) - P.min(axis=0)

    stats["voltage_final_minus_ensemble_mean"] = pred_voltage_final - stats["voltage_ensemble_mean"]
    stats["capacity_final_minus_ensemble_mean"] = pred_capacity_final - stats["capacity_ensemble_mean"]

    # ---- 8. OOF residual reference ------------------------------------------------------
    oof_ref_rows = []
    oof_rmse: dict[str, float] = {}
    for target, tag in (("average_voltage", "voltage"), ("capacity_grav", "capacity")):
        sub = p13_preds[
            (p13_preds["target"] == target)
            & (p13_preds["deployment_regime"] == DEPLOYMENT_REGIME[target])
            & (p13_preds["feature_subset"] == "FULL_CORE")
        ]
        residual = (sub["y_true"] - sub["y_pred"]).to_numpy(dtype=float)
        rmse = float(np.sqrt(np.mean(residual ** 2)))
        mae = float(np.mean(np.abs(residual)))
        oof_rmse[tag] = rmse
        abs_res = np.abs(residual)
        qs = np.percentile(abs_res, [50, 80, 90, 95])
        oof_ref_rows.append(
            {
                "target": target,
                "OOF_RMSE": sig6(rmse),
                "OOF_MAE": sig6(mae),
                "abs_residual_q50": sig6(qs[0]),
                "abs_residual_q80": sig6(qs[1]),
                "abs_residual_q90": sig6(qs[2]),
                "abs_residual_q95": sig6(qs[3]),
            }
        )
    oof_ref = pd.DataFrame(oof_ref_rows)

    stats["voltage_ensemble_std_over_oof_rmse"] = stats["voltage_ensemble_std"] / oof_rmse["voltage"]
    stats["capacity_ensemble_std_over_oof_rmse"] = stats["capacity_ensemble_std"] / oof_rmse["capacity"]

    # ---- 10-14. Zn-reference AD preprocessing + PCA + kNN -------------------------------
    zn_X = zn_df[features].replace([np.inf, -np.inf], np.nan)
    ad_imputer = SimpleImputer(strategy="median")
    ad_imputer.fit(zn_X)                    # fit ONLY on the 434 Zn records
    zn_imputed = ad_imputer.transform(zn_X)
    ad_scaler = StandardScaler()
    ad_scaler.fit(zn_imputed)               # fit ONLY on Zn reference
    zn_scaled = ad_scaler.transform(zn_imputed)
    ad_pca = PCA(n_components=0.95, svd_solver="full")
    ad_pca.fit(zn_scaled)                   # fit ONLY on Zn reference
    zn_pca = ad_pca.transform(zn_scaled)

    cand_imputed = ad_imputer.transform(cand_X)   # candidates only transformed
    cand_scaled = ad_scaler.transform(cand_imputed)
    cand_pca = ad_pca.transform(cand_scaled)

    pca_components = int(zn_pca.shape[1])
    pca_var = float(np.sum(ad_pca.explained_variance_ratio_))
    log(f"Zn-reference PCA: {pca_components} components, explained variance {pca_var:.4f}")

    nn = NearestNeighbors(n_neighbors=K_NEIGHBORS + 1)
    nn.fit(zn_pca)
    train_dist, _ = nn.kneighbors(zn_pca, n_neighbors=K_NEIGHBORS + 1)
    train_5nn = train_dist[:, 1:].mean(axis=1)  # drop the self (distance 0) column
    q50, q90, q95, q99 = np.percentile(train_5nn, [50, 90, 95, 99])
    train_5nn_max = float(train_5nn.max())

    cand_dist, _ = nn.kneighbors(cand_pca, n_neighbors=K_NEIGHBORS)
    cand_5nn = cand_dist.mean(axis=1)
    if not np.all(np.isfinite(cand_5nn)):
        log("ERROR: candidate AD distances contain non-finite values")
        return 1

    ad_ratio_q95 = cand_5nn / q95
    ad_category = np.select(
        [cand_5nn <= q95, cand_5nn <= q99],
        ["IN_DOMAIN", "BORDERLINE"],
        default="OOD",
    )

    # ---- feature range reference (raw Zn values, pre-imputation) ------------------------
    range_rows = []
    n_outside_minmax = np.zeros(n_candidates, dtype=int)
    n_outside_p = np.zeros(n_candidates, dtype=int)
    for feature in features:
        zn_vals = zn_df[feature].to_numpy(dtype=float)
        fmin = float(np.nanmin(zn_vals))
        fmax = float(np.nanmax(zn_vals))
        p01 = float(np.nanpercentile(zn_vals, 1))
        p99 = float(np.nanpercentile(zn_vals, 99))
        constant = bool(fmin == fmax)
        range_rows.append(
            {"feature": feature, "min": sig6(fmin), "max": sig6(fmax),
             "p01": sig6(p01), "p99": sig6(p99), "constant": constant}
        )
        cand_vals = cand_df[feature].to_numpy(dtype=float)
        valid = ~np.isnan(cand_vals)
        if constant:
            outside = valid & (cand_vals != fmin)
        else:
            outside = valid & ((cand_vals < fmin) | (cand_vals > fmax))
        n_outside_minmax += outside.astype(int)
        outside_p = valid & ((cand_vals < p01) | (cand_vals > p99))
        n_outside_p += outside_p.astype(int)

    # ---- 15. known Zn discharge material overlap ------------------------------------------
    if "id_discharge" not in zn_enriched.columns:
        log("ERROR: zinc_battery_insertion_enriched.csv has no id_discharge column")
        return 1
    known_ids = set(
        str(v).strip()
        for v in zn_enriched["id_discharge"].dropna()
        if str(v).strip()
    )
    known_formulas: set[str] = set()
    formula_col = None
    if "discharge_formula_pretty" in zn_enriched.columns:
        formula_col = "discharge_formula_pretty"
    elif "formula_discharge" in zn_enriched.columns:
        formula_col = "formula_discharge"
    if formula_col:
        known_formulas = set(
            str(v).strip()
            for v in zn_enriched[formula_col].dropna()
            if str(v).strip()
        )
    is_known_id = cand_df["material_id"].astype("string").isin(known_ids).to_numpy()
    is_known_formula = cand_df["formula_pretty"].astype("string").isin(known_formulas).to_numpy()
    log(f"known Zn discharge material ids: {len(known_ids)}; known formulas: {len(known_formulas)}")

    # ---- 17/18. main candidate table ---------------------------------------------------------
    out = pd.DataFrame(
        {
            "material_id": cand_df["material_id"].astype("string"),
            "formula_pretty": cand_df["formula_pretty"].astype("string"),
            "working_ion": cand_df["working_ion"].astype("string"),
            "pred_voltage_final": pred_voltage_final,
            "pred_capacity_final": pred_capacity_final,
            "voltage_ensemble_mean": stats["voltage_ensemble_mean"],
            "voltage_ensemble_std": stats["voltage_ensemble_std"],
            "voltage_ensemble_min": stats["voltage_ensemble_min"],
            "voltage_ensemble_max": stats["voltage_ensemble_max"],
            "voltage_ensemble_range": stats["voltage_ensemble_range"],
            "voltage_final_minus_ensemble_mean": stats["voltage_final_minus_ensemble_mean"],
            "voltage_ensemble_std_over_oof_rmse": stats["voltage_ensemble_std_over_oof_rmse"],
            "capacity_ensemble_mean": stats["capacity_ensemble_mean"],
            "capacity_ensemble_std": stats["capacity_ensemble_std"],
            "capacity_ensemble_min": stats["capacity_ensemble_min"],
            "capacity_ensemble_max": stats["capacity_ensemble_max"],
            "capacity_ensemble_range": stats["capacity_ensemble_range"],
            "capacity_final_minus_ensemble_mean": stats["capacity_final_minus_ensemble_mean"],
            "capacity_ensemble_std_over_oof_rmse": stats["capacity_ensemble_std_over_oof_rmse"],
            "zn_ad_5nn_distance": cand_5nn,
            "zn_ad_ratio_q95": ad_ratio_q95,
            "zn_ad_category": ad_category,
            "n_features_outside_zn_minmax": n_outside_minmax,
            "fraction_features_outside_zn_minmax": n_outside_minmax / len(features),
            "n_features_outside_zn_p01_p99": n_outside_p,
            "fraction_features_outside_zn_p01_p99": n_outside_p / len(features),
            "is_known_zn_discharge_material_id": is_known_id,
            "is_known_zn_discharge_formula": is_known_formula,
        }
    )
    if len(out) != n_candidates:
        log(f"ERROR: candidate table rows {len(out)} != {n_candidates}")
        return 1

    # ---- member predictions wide table -------------------------------------------------------
    member_table = pd.DataFrame({"material_id": cand_df["material_id"].astype("string")})
    for target, tag in (("average_voltage", "voltage"), ("capacity_grav", "capacity")):
        for fold in range(N_FOLDS):
            member_table[f"{tag}_member_fold{fold}"] = member_preds[target][fold]
    if len(member_table) != n_candidates:
        log(f"ERROR: member table rows {len(member_table)} != {n_candidates}")
        return 1

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    FIG_DIR.mkdir(parents=True, exist_ok=True)
    atomic_to_csv(out, OUT_CAND)
    atomic_to_csv(member_table, OUT_MEMBER)
    atomic_to_csv(oof_ref, OUT_OOF_REF)

    ad_ref = pd.DataFrame(
        {
            "metric": [
                "n_reference", "n_features", "PCA_components", "PCA_explained_variance",
                "K", "training_5nn_q50", "training_5nn_q90", "training_5nn_q95",
                "training_5nn_q99", "training_5nn_max",
            ],
            "value": [
                len(zn_df), len(features), pca_components, pca_var,
                K_NEIGHBORS, q50, q90, q95, q99, train_5nn_max,
            ],
        }
    )
    atomic_to_csv(ad_ref, OUT_AD_REF)
    atomic_to_csv(pd.DataFrame(range_rows), OUT_RANGE_REF)

    overlap_summary = pd.DataFrame(
        {
            "metric": [
                "candidate_total",
                "known_Zn_discharge_ID_overlap_count",
                "known_Zn_discharge_formula_overlap_count",
                "novel_by_material_id_count",
            ],
            "value": [
                n_candidates,
                int(is_known_id.sum()),
                int(is_known_formula.sum()),
                int((~is_known_id).sum()),
            ],
        }
    )
    atomic_to_csv(overlap_summary, OUT_OVERLAP)

    # ---- 22. QA ---------------------------------------------------------------------------------
    if not np.all(np.isfinite(member_preds["average_voltage"])) or not np.all(
        np.isfinite(member_preds["capacity_grav"])
    ):
        log("ERROR: ensemble member predictions contain non-finite values")
        return 1
    allowed_categories = {"IN_DOMAIN", "BORDERLINE", "OOD"}
    if not set(np.unique(ad_category)).issubset(allowed_categories):
        log(f"ERROR: unexpected AD category values: {set(np.unique(ad_category))}")
        return 1
    log("all QA checks passed (finite predictions, 5 members per target, "
        f"reproduction max diff {max(max_repro_diff.values()):.3e})")

    # ---- 23. figures ------------------------------------------------------------------------------
    FIGURE_NAMES = {
        "voltage": {
            "unc_dist": "01_voltage_ensemble_uncertainty_distribution",
            "unc_vs_ad": "05_voltage_uncertainty_vs_ad_distance",
            "final_vs_mean": "07_voltage_final_vs_ensemble_mean",
        },
        "capacity": {
            "unc_dist": "02_capacity_ensemble_uncertainty_distribution",
            "unc_vs_ad": "06_capacity_uncertainty_vs_ad_distance",
            "final_vs_mean": "08_capacity_final_vs_ensemble_mean",
        },
    }
    log("generating figures ...")
    for tag in ("voltage", "capacity"):
        figure_hist(
            stats[f"{tag}_ensemble_std"], FIG_DIR / FIGURE_NAMES[tag]["unc_dist"],
            f"{tag}: ensemble std distribution (epistemic disagreement proxy)",
            "ensemble std (ddof=1)",
        )
        figure_scatter(
            cand_5nn, stats[f"{tag}_ensemble_std"],
            FIG_DIR / FIGURE_NAMES[tag]["unc_vs_ad"],
            f"{tag}: ensemble uncertainty vs Zn AD distance",
            "Zn AD 5NN distance", "ensemble std",
        )
        figure_final_vs_mean(
            out[f"pred_{tag}_final"].to_numpy() if tag == "voltage" else out["pred_capacity_final"].to_numpy(),
            stats[f"{tag}_ensemble_mean"],
            FIG_DIR / FIGURE_NAMES[tag]["final_vs_mean"],
            f"{tag}: final Phase 15 prediction vs ensemble mean",
        )
    figure_two_hists(
        train_5nn, cand_5nn, FIG_DIR / "03_zn_ad_training_vs_candidate_distance",
        "Zn AD 5NN distance: Zn reference vs candidates",
        "5NN mean Euclidean distance (PCA space)",
    )
    cat_counts = {
        c: int((ad_category == c).sum()) for c in ("IN_DOMAIN", "BORDERLINE", "OOD")
    }
    figure_category_counts(cat_counts, FIG_DIR / "04_candidate_ad_category_counts")

    # ---- 24/25. summary -----------------------------------------------------------------------------
    elapsed = time.perf_counter() - overall_started
    lines: list[str] = []
    lines.append("Phase 16 - Candidate prediction uncertainty + AD/OOD summary")
    lines.append("=" * 70)
    lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")
    lines.append("")
    lines.append(f"candidate count: {n_candidates}")
    lines.append(f"final model paths:")
    lines.append(f"    voltage: {IN_VOLTAGE_MODEL.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append(f"    capacity: {IN_CAPACITY_MODEL.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append(f"features: {len(features)} CORE_NUMERIC")
    lines.append(f"Phase 15 feature schema hash QA: PASS ({feature_schema_sha256[:16]}...)")
    lines.append("5-member ensemble design: voltage = MIXED_ION_GROUP_SAFE reconstruction,")
    lines.append("    capacity = ZN_ONLY reconstruction (fixed Phase 9 params, Phase 10 folds)")
    lines.append(f"Phase 13 reproduction QA max difference: voltage="
                 f"{max_repro_diff['average_voltage']:.3e}, capacity="
                 f"{max_repro_diff['capacity_grav']:.3e} (tolerance 1e-6)")
    lines.append("")
    for tag, label in (("voltage", "Voltage"), ("capacity", "Capacity")):
        std = stats[f"{tag}_ensemble_std"]
        lines.append(
            f"{label} ensemble std: min={np.min(std):.4f}, median={np.median(std):.4f}, "
            f"p90={np.percentile(std, 90):.4f}, p95={np.percentile(std, 95):.4f}, max={np.max(std):.4f}"
        )
    lines.append("")
    lines.append("OOF residual reference (Phase 13 FULL_CORE):")
    for _, row in oof_ref.iterrows():
        lines.append(
            f"    [{row['target']}] RMSE={row['OOF_RMSE']:.4f}, MAE={row['OOF_MAE']:.4f}, "
            f"abs-res q50={row['abs_residual_q50']:.4f}, q90={row['abs_residual_q90']:.4f}, "
            f"q95={row['abs_residual_q95']:.4f}"
        )
    lines.append("")
    lines.append("Zn applicability domain:")
    lines.append(f"    434 reference records (actual: {len(zn_df)})")
    lines.append(f"    PCA components: {pca_components}")
    lines.append(f"    PCA explained variance: {pca_var:.4f}")
    lines.append(f"    5NN training distance q95: {q95:.4f}; q99: {q99:.4f}; max: {train_5nn_max:.4f}")
    lines.append(f"    candidate AD categories: IN_DOMAIN={cat_counts['IN_DOMAIN']}, "
                 f"BORDERLINE={cat_counts['BORDERLINE']}, OOD={cat_counts['OOD']}")
    lines.append("")
    lines.append("feature extrapolation counts (candidate vs Zn min/max and p01/p99):")
    lines.append(f"    median n_features_outside_zn_minmax: {np.median(n_outside_minmax):.1f}")
    lines.append(f"    max n_features_outside_zn_minmax: {np.max(n_outside_minmax)}")
    lines.append(f"    median n_features_outside_zn_p01_p99: {np.median(n_outside_p):.1f}")
    lines.append("")
    lines.append(f"known Zn discharge material overlap: "
                 f"ID overlap={int(is_known_id.sum())}, formula overlap={int(is_known_formula.sum())}, "
                 f"novel by ID={int((~is_known_id).sum())}")
    lines.append("")
    lines.append("candidate final prediction distributions (reported only, not filtered):")
    for tag, col, label in (
        ("voltage", "pred_voltage_final", "Voltage"),
        ("capacity", "pred_capacity_final", "Capacity"),
    ):
        vals = out[col].to_numpy()
        lines.append(
            f"    {label}: min={np.min(vals):.4f}, p01={np.percentile(vals, 1):.4f}, "
            f"median={np.median(vals):.4f}, p99={np.percentile(vals, 99):.4f}, max={np.max(vals):.4f}"
        )
    lines.append("")
    lines.append("output files:")
    for path in (
        OUT_CAND, OUT_MEMBER, OUT_OOF_REF, OUT_AD_REF, OUT_RANGE_REF, OUT_OVERLAP,
        FIG_DIR, OUT_SUMMARY,
    ):
        lines.append(f"    {path.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append("")
    lines.append("policy statements:")
    lines.append("    Final central predictions come from the Phase15 all-data deployment models.")
    lines.append("    The five-member ensemble is used only as a model-instability /")
    lines.append("    epistemic-disagreement proxy.")
    lines.append("    Ensemble standard deviation is not a calibrated confidence interval.")
    lines.append("    The applicability domain is defined relative to known Zn insertion")
    lines.append("    records, because the deployment population is Zn-containing candidates.")
    lines.append("    OOD status is a diagnostic flag and does not automatically remove a")
    lines.append("    candidate.")
    lines.append("    Known training-material overlap is retained and flagged, not deleted.")
    lines.append("    No final candidate ranking or screening was performed.")
    lines.append("")
    lines.append(f"runtime: {elapsed:.1f} s")
    lines.append("")
    OUT_SUMMARY.write_text("\\n".join(lines), encoding="utf-8")
    log(f"Saved candidate uncertainty/OOD summary -> {OUT_SUMMARY}")

    # ---- 27. console ----------------------------------------------------------------------------------
    print("")
    print("Phase 16 candidate uncertainty and OOD analysis completed.")
    print(f"candidate count: {n_candidates}")
    print(f"Voltage ensemble std median / p95: "
          f"{np.median(stats['voltage_ensemble_std']):.4f} / "
          f"{np.percentile(stats['voltage_ensemble_std'], 95):.4f}")
    print(f"Capacity ensemble std median / p95: "
          f"{np.median(stats['capacity_ensemble_std']):.4f} / "
          f"{np.percentile(stats['capacity_ensemble_std'], 95):.4f}")
    print(f"Zn AD PCA components: {pca_components}")
    print(f"IN_DOMAIN count: {cat_counts['IN_DOMAIN']}")
    print(f"BORDERLINE count: {cat_counts['BORDERLINE']}")
    print(f"OOD count: {cat_counts['OOD']}")
    print(f"known Zn material-ID overlap count: {int(is_known_id.sum())}")
    print(f"Phase13 reproduction max difference: {max(max_repro_diff.values()):.3e}")
    print(f"outputs: {OUT_DIR}")
    print(f"figures: {FIG_DIR}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
