def figure_bar_counts(labels: list, counts: list, path: Path, title: str,
                      ylabel: str, color: str = "#4C72B0") -> None:
    fig, ax = plt.subplots(figsize=(10, 5.5))
    if not counts:
        ax.text(0.5, 0.5, "No candidates", ha="center", va="center",
                transform=ax.transAxes, fontsize=14)
        ax.set_ylabel(ylabel)
        ax.set_title(title)
        save_figure(fig, path)
        return
    ax.bar(labels, counts, color=color)
    for i, n in enumerate(counts):
        ax.text(i, n + max(counts) * 0.01, str(int(n)), ha="center", fontsize=9)
    ax.set_ylabel(ylabel)
    ax.set_title(title)
    save_figure(fig, path)


def figure_scatter_tier(master: pd.DataFrame, path: Path, title: str) -> None:
    colors = {
        "TIER_A_FRAMEWORK_LIKE": "#55A868",
        "TIER_B_POSSIBLE_FRAMEWORK": "#F0C571",
        "TIER_C_LOW_HOST_LIKENESS": "#C44E52",
        "UNKNOWN": "#888888",
    }
    fig, ax = plt.subplots(figsize=(9, 6.5))
    for tier in HOST_TIERS:
        sub = master[master["host_likeness_tier"] == tier]
        ax.scatter(sub["pred_voltage_final"], sub["pred_capacity_final"],
                   s=5, alpha=0.4, color=colors[tier], label=tier, linewidths=0)
    ax.set_xlabel("predicted voltage (V)")
    ax.set_ylabel("predicted capacity (mAh/g)")
    ax.set_title(title)
    ax.legend(fontsize=7)
    save_figure(fig, path)


def figure_funnel(steps: list[tuple[str, int]],
                  branches: list[tuple[str, int]] | None, path: Path) -> None:
    fig, ax = plt.subplots(figsize=(9, 7.5))
    labels = [s for s, _ in steps]
    values = [n for _, n in steps]
    y = np.arange(len(steps))[::-1]
    ax.barh(y, values, color="#4C72B0")
    all_values = list(values) + [n for _, n in (branches or [])]
    base_max = max(all_values) if all_values else 1
    for yi, n in zip(y, values):
        ax.text(n + base_max * 0.01, yi, str(int(n)), va="center", fontsize=9)
    branch_ys = []
    for i, (branch_label, branch_n) in enumerate(branches or []):
        yb = -(i + 1)
        branch_ys.append(yb)
        ax.barh(yb, branch_n, color="#55A868", hatch="//", edgecolor="black", height=0.6)
        ax.text(branch_n + base_max * 0.01, yb, str(int(branch_n)), va="center", fontsize=9)
        labels.append(f"{branch_label} (parallel terminal branch)")
    ax.axhline(-0.5, color="gray", lw=0.8, ls="--")
    ax.set_yticks(list(y) + branch_ys)
    ax.set_yticklabels(labels, fontsize=8)
    ax.set_xlabel("candidate count")
    ax.set_title(
        "Phase 17 -> Phase 18 triage counts\\n"
        "(PRIORITY_A and PRIORITY_B are parallel terminal categories)"
    )
    save_figure(fig, path)


def figure_queue_top30(queue: pd.DataFrame, path: Path) -> None:
    sub = queue.head(30).reset_index(drop=True)
    fig, axes = plt.subplots(1, 3, figsize=(17, 7))
    for ax, col, name in (
        (axes[0], "pred_voltage_final", "predicted voltage (V)"),
        (axes[1], "pred_capacity_final", "predicted capacity (mAh/g)"),
        (axes[2], "pred_specific_energy_proxy_Wh_kg", "specific-energy proxy (Wh/kg)"),
    ):
        ax.barh(np.arange(len(sub))[::-1], sub[col], color="#4C72B0")
        ax.set_yticks(np.arange(len(sub))[::-1])
        ax.set_yticklabels(
            [f"{r['formula_pretty']} ({r['host_likeness_tier'].replace('TIER_','')[:1]})"
             for _, r in sub.iterrows()],
            fontsize=6,
        )
        ax.set_title(name)
    fig.suptitle("literature verification queue top 30 (no composite score)", fontsize=13)
    save_figure(fig, path)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    overall_started = time.perf_counter()
    log("Phase 18 - aqueous-ZIB feasibility triage (composition heuristics only)")

    if not PYMATGEN_AVAILABLE:
        log("ERROR: pymatgen is not installed. Install with: py -m pip install pymatgen")
        return 1

    # ---- 1. inputs ---------------------------------------------------------
    master = read_required(IN_P17_MASTER)
    shortlist = read_required(IN_P17_SHORTLIST)
    top20 = read_required(IN_P17_TOP20)
    read_required(IN_P17_PARETO)  # existence confirmation
    zn_target_ref = read_required(IN_ZN_TARGET_REF)
    read_required(IN_UNC_REF)     # existence confirmation
    cand_features = read_required(IN_CAND_FEATURES)

    # required-column QA: fail fast instead of a mid-run KeyError
    REQUIRED_MASTER_COLUMNS = [
        "material_id", "formula_pretty", "novelty_class",
        "conservative_discovery_candidate", "is_formula_representative",
        "pareto_front_conservative_discovery",
        "pred_voltage_final", "pred_capacity_final", "pred_specific_energy_proxy_Wh_kg",
        "voltage_ensemble_std", "capacity_ensemble_std",
        "voltage_ensemble_std_over_oof_rmse", "capacity_ensemble_std_over_oof_rmse",
        "zn_ad_5nn_distance", "mp_energy_above_hull", "mp_is_stable",
    ]
    missing_required = [c for c in REQUIRED_MASTER_COLUMNS if c not in master.columns]
    if missing_required:
        log(f"ERROR: Phase 17 master missing required column(s): {missing_required}")
        return 1

    # ---- 2. base QA -----------------------------------------------------------
    if not bool(master["material_id"].is_unique):
        log("ERROR: master material_id is not unique")
        return 1
    shortlist_ids = set(shortlist["material_id"])
    if not shortlist_ids.issubset(set(master["material_id"])):
        log("ERROR: some final-shortlist material_ids are missing from master")
        return 1
    if list(shortlist["material_id"])[:20] != list(top20["material_id"]):
        log("ERROR: top20 is not the first 20 of the final shortlist")
        return 1
    n_total = len(master)
    log(f"master: {n_total} candidates; shortlist subset QA passed")

    # candidate feature table alignment QA (no merge, consistency only)
    if not bool(cand_features["material_id"].is_unique):
        log("ERROR: candidate feature table material_id is not unique")
        return 1
    if set(master["material_id"]) != set(cand_features["material_id"]) or len(master) != len(cand_features):
        log("ERROR: candidate feature table ID set / row count mismatch vs Phase 17 master")
        return 1

    # ---- 3. composition parsing (never deletes rows) ------------------------------
    parsed = master["formula_pretty"].apply(parse_composition_info)
    parsed_df = pd.DataFrame(list(parsed), index=master.index)
    for column in parsed_df.columns:
        master[column] = parsed_df[column]
    n_parse_failed = int((master["formula_parse_status"] == "FAILED").sum())
    log(f"formula parsing: {n_total - n_parse_failed} OK, {n_parse_failed} FAILED (kept)")

    # hard QA: every successfully parsed formula must contain Zn
    # (the candidate pool is defined as Zn-containing materials).
    no_zn = master[
        (master["formula_parse_status"] == "OK") & (~master["contains_Zn"].astype(bool))
    ]
    if len(no_zn):
        log(f"ERROR: {len(no_zn)} successfully parsed formula(s) do not contain Zn; first 10:")
        for _, row in no_zn.head(10).iterrows():
            log(f"  {row['material_id']}  {row['formula_pretty']}")
        return 1

    # ---- 4. chemistry family (priority rules A-H) -----------------------------------
    a_all_metal = master["all_elements_are_metals"].astype(bool)
    has_nonmetal = master["n_elements"] > 0
    b_zn_only = master["zn_is_only_metal"].astype(bool)
    contains_nzn_tm = master["contains_non_zn_transition_metal"].astype(bool)
    contains_nzn_metal = master["contains_non_zn_metal"].astype(bool)
    c_O = master["contains_O"].astype(bool)
    c_S = master["contains_S"].astype(bool)
    c_Se = master["contains_Se"].astype(bool)
    c_Te = master["contains_Te"].astype(bool)
    chalc = c_S | c_Se | c_Te
    hal = (
        master["contains_F"].astype(bool)
        | master["contains_Cl"].astype(bool)
        | master["contains_Br"].astype(bool)
        | master["contains_I"].astype(bool)
    )
    family = np.select(
        [
            a_all_metal,
            b_zn_only & (~a_all_metal),
            contains_nzn_tm & c_O,
            contains_nzn_tm & (~c_O) & chalc,
            contains_nzn_tm & hal & (~c_O) & (~chalc),
            contains_nzn_metal & c_O,
            contains_nzn_metal,
        ],
        [
            "ALL_METAL_INTERMETALLIC",
            "ZN_ONLY_METAL_NONMETAL_COMPOUND",
            "NONZN_TM_OXIDE_OR_OXYCOMPOUND",
            "NONZN_TM_CHALCOGENIDE",
            "NONZN_TM_HALIDE",
            "NONZN_METAL_OXYCOMPOUND",
            "OTHER_NONZN_METAL_COMPOUND",
        ],
        default="OTHER",
    )
    master["chemistry_family"] = family

    # ---- 5. host-likeness tiers -----------------------------------------------------
    host_tier = np.select(
        [
            master["formula_parse_status"] == "FAILED",
            contains_nzn_tm & (~a_all_metal) & (c_O | chalc),
            (~a_all_metal) & contains_nzn_metal,
            a_all_metal | b_zn_only,
        ],
        ["UNKNOWN", "TIER_A_FRAMEWORK_LIKE", "TIER_B_POSSIBLE_FRAMEWORK",
         "TIER_C_LOW_HOST_LIKENESS"],
        default="TIER_C_LOW_HOST_LIKENESS",
    )
    master["host_likeness_tier"] = host_tier

    # ---- 6. high-risk manual-review flags ------------------------------------------------
    master["flag_all_metal_intermetallic"] = a_all_metal
    master["flag_zn_only_metal_compound"] = b_zn_only & (~a_all_metal)
    master["flag_halide_rich"] = hal & (~c_O) & (~chalc)
    master["flag_no_non_zn_metal"] = ~contains_nzn_metal
    master["flag_no_non_zn_transition_metal"] = ~contains_nzn_tm

    # ---- 7. reference formula status -----------------------------------------------------
    # Derived from the Phase 17 FROZEN novelty classification (never re-judged).
    required_novelty_classes = {
        "KNOWN_MATERIAL",
        "KNOWN_FORMULA_NEW_MATERIAL",
        "STRICT_NOVEL_FORMULA",
    }
    actual_novelty_classes = set(master["novelty_class"].dropna().astype(str).unique())
    unexpected_classes = actual_novelty_classes - required_novelty_classes
    if unexpected_classes:
        log(f"ERROR: unexpected novelty_class values: {sorted(unexpected_classes)}")
        return 1
    master["reference_formula_status"] = np.where(
        master["novelty_class"].isin(["KNOWN_MATERIAL", "KNOWN_FORMULA_NEW_MATERIAL"]),
        "KNOWN_IN_ZN_REFERENCE",
        "UNSEEN_IN_ZN_REFERENCE",
    )

    # ---- 8/9. empirical voltage/capacity classes ---------------------------------------------
    v_ref = zn_target_ref[zn_target_ref["target"] == "average_voltage"].iloc[0]
    c_ref = zn_target_ref[zn_target_ref["target"] == "capacity_grav"].iloc[0]
    pred_v = master["pred_voltage_final"].to_numpy(dtype=float)
    pred_c = master["pred_capacity_final"].to_numpy(dtype=float)
    empirical_voltage_class = np.select(
        [
            pred_v <= 0,
            pred_v < v_ref["q01"],
            pred_v <= v_ref["q99"],
            pred_v <= v_ref["max"],
        ],
        ["NEGATIVE", "LOW_EXTRAPOLATION", "REFERENCE_CORE", "HIGH_EXTRAPOLATION"],
        default="EXTREME_HIGH_EXTRAPOLATION",
    )
    empirical_capacity_class = np.select(
        [
            pred_c < c_ref["q01"],
            pred_c <= c_ref["q99"],
            pred_c <= c_ref["max"],
        ],
        ["BELOW_REFERENCE", "REFERENCE_CORE", "HIGH_EXTRAPOLATION"],
        default="EXTREME_HIGH_EXTRAPOLATION",
    )
    master["empirical_voltage_class"] = empirical_voltage_class
    master["empirical_capacity_class"] = empirical_capacity_class

    # ---- 10/11. pre-literature flags ----------------------------------------------------------
    tier_ab = master["host_likeness_tier"].isin(
        ["TIER_A_FRAMEWORK_LIKE", "TIER_B_POSSIBLE_FRAMEWORK"]
    )
    pre_lit = (
        master["conservative_discovery_candidate"].astype(bool)
        & master["is_formula_representative"].astype(bool)
        & tier_ab
        & (master["empirical_voltage_class"] != "EXTREME_HIGH_EXTRAPOLATION")
    )
    priority_a = (
        pre_lit
        & (master["host_likeness_tier"] == "TIER_A_FRAMEWORK_LIKE")
        & (master["mp_energy_above_hull"] <= 0.05)
        & master["empirical_voltage_class"].isin(["REFERENCE_CORE", "HIGH_EXTRAPOLATION"])
    )
    phase17_conservative = master["conservative_discovery_candidate"].astype(bool)
    review_only = phase17_conservative & (~pre_lit)
    master["pre_literature_host_candidate"] = pre_lit
    master["pre_literature_priority_tier"] = np.select(
        [priority_a, pre_lit, review_only],
        ["PRIORITY_A", "PRIORITY_B", "REVIEW_ONLY"],
        default="NOT_PHASE17_CONSERVATIVE",
    )
    # hard QA: conservative rows must never be labelled NOT_PHASE17_CONSERVATIVE
    bad_label = phase17_conservative & (
        master["pre_literature_priority_tier"] == "NOT_PHASE17_CONSERVATIVE"
    )
    if int(bad_label.sum()):
        log(f"ERROR: {int(bad_label.sum())} conservative candidate(s) mislabelled "
            "NOT_PHASE17_CONSERVATIVE")
        return 1
    # explanatory reasons for REVIEW_ONLY rows (informative, not rejection reasons)
    review_reasons = []
    for _, row in master[review_only].iterrows():
        reasons = []
        if not bool(row["is_formula_representative"]):
            reasons.append("NON_FORMULA_REPRESENTATIVE")
        if row["host_likeness_tier"] == "TIER_C_LOW_HOST_LIKENESS":
            reasons.append("TIER_C_LOW_HOST_LIKENESS")
        if row["formula_parse_status"] == "FAILED":
            reasons.append("FORMULA_PARSE_FAILED")
        if row["empirical_voltage_class"] == "EXTREME_HIGH_EXTRAPOLATION":
            reasons.append("EXTREME_VOLTAGE_EXTRAPOLATION")
        review_reasons.append(";".join(reasons))
    master["pre_literature_review_reason"] = ""
    master.loc[master.index[review_only], "pre_literature_review_reason"] = review_reasons

    # ---- 12/13. literature verification queue ------------------------------------------------------
    queue_base = master[
        master["pre_literature_host_candidate"].astype(bool)
        & master["is_formula_representative"].astype(bool)
    ].copy()
    queue_base["_prio"] = np.where(
        queue_base["pre_literature_priority_tier"] == "PRIORITY_A", 0, 1
    )
    queue_base = queue_base.sort_values(
        by=[
            "_prio",
            "pareto_front_conservative_discovery",
            "pred_specific_energy_proxy_Wh_kg",
            "mp_energy_above_hull",
            "zn_ad_5nn_distance",
            "voltage_ensemble_std_over_oof_rmse",
            "capacity_ensemble_std_over_oof_rmse",
            "material_id",
        ],
        ascending=[True, True, False, True, True, True, True, True],
        na_position="last",
    )
    queue = queue_base.head(100).copy()

    queue_cols = [
        "material_id", "formula_pretty", "non_zn_framework_formula_proxy",
        "chemistry_family", "host_likeness_tier", "pre_literature_priority_tier",
        "pred_voltage_final", "pred_capacity_final", "pred_specific_energy_proxy_Wh_kg",
        "voltage_ensemble_std", "capacity_ensemble_std", "zn_ad_5nn_distance",
        "mp_energy_above_hull", "mp_is_stable", "pareto_front_conservative_discovery",
        "empirical_voltage_class", "empirical_capacity_class", "reference_formula_status",
    ]
    queue = queue[queue_cols].copy()
    for column in QUEUE_LITERATURE_COLUMNS:
        queue[column] = "NOT_CHECKED"
    for i, qname in enumerate(("search_query_1", "search_query_2", "search_query_3",
                                "search_query_4", "search_query_5"), start=1):
        template = [
            '"{formula}" "aqueous zinc-ion battery" cathode',
            '"{formula}" "zinc-ion battery"',
            '"{formula}" Zn2+ insertion',
            '"{formula}" aqueous stability',
            '"{formula}" solubility water',
        ][i - 1]
        queue[qname] = queue["formula_pretty"].apply(
            lambda f: template.replace("{formula}", str(f))
        )
    queue["verification_questions"] = VERIFICATION_QUESTIONS

    # ---- 14. deprioritized table -------------------------------------------------------------------
    deprioritized = master[
        master["conservative_discovery_candidate"].astype(bool)
        & (
            (master["host_likeness_tier"] == "TIER_C_LOW_HOST_LIKENESS")
            | (master["empirical_voltage_class"] == "EXTREME_HIGH_EXTRAPOLATION")
        )
    ].copy()
    reasons = []
    for _, row in deprioritized.iterrows():
        row_reasons = []
        if row["flag_all_metal_intermetallic"]:
            row_reasons.append("ALL_METAL_INTERMETALLIC_HEURISTIC")
        if row["flag_zn_only_metal_compound"]:
            row_reasons.append("ZN_ONLY_METAL_COMPOUND_HEURISTIC")
        if row["empirical_voltage_class"] == "EXTREME_HIGH_EXTRAPOLATION":
            row_reasons.append("EXTREME_VOLTAGE_EXTRAPOLATION")
        reasons.append(";".join(row_reasons))
    deprioritized["deprioritization_reason"] = reasons

    # ---- 15/16. QA ---------------------------------------------------------------------------------
    if len(master) != n_total:
        log(f"ERROR: master row count changed: {len(master)} != {n_total}")
        return 1
    if not bool(master["material_id"].is_unique):
        log("ERROR: material_id not unique after Phase 18 enrichment")
        return 1
    if not set(master[master["conservative_discovery_candidate"].astype(bool)]["material_id"]).issubset(
        set(master["material_id"])
    ):
        log("ERROR: Phase 17 conservative candidates lost")
        return 1
    if not set(queue["material_id"]).issubset(set(master["material_id"])):
        log("ERROR: literature queue is not a subset of master")
        return 1
    queue_master_rows = master[master["material_id"].isin(set(queue["material_id"]))]
    if not bool(
        queue_master_rows["pre_literature_host_candidate"].astype(bool).all()
        and queue_master_rows["is_formula_representative"].astype(bool).all()
    ):
        log("ERROR: literature queue rows must be pre-literature host + formula representative")
        return 1
    if len(queue) > 100:
        log(f"ERROR: literature queue exceeds 100 rows: {len(queue)}")
        return 1
    if not bool(
        (master.loc[master["pre_literature_priority_tier"] == "PRIORITY_A",
                    "pre_literature_host_candidate"].astype(bool).all())
        and (master.loc[master["pre_literature_priority_tier"] == "PRIORITY_A",
                       "host_likeness_tier"] == "TIER_A_FRAMEWORK_LIKE").all()
        and (master.loc[master["pre_literature_priority_tier"] == "PRIORITY_A",
                       "mp_energy_above_hull"] <= 0.05).all()
    ):
        log("ERROR: PRIORITY_A QA failed")
        return 1
    log("Phase 18 QA passed (no candidate deleted, no weighted score created)")

    # ---- 17. summaries --------------------------------------------------------------------------------
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    FIG_DIR.mkdir(parents=True, exist_ok=True)

    family_summary_rows = []
    for fam, sub in master.groupby("chemistry_family", sort=False):
        family_summary_rows.append(
            {
                "chemistry_family": fam,
                "all_candidates_count": len(sub),
                "phase17_conservative_count": int(sub["conservative_discovery_candidate"].sum()),
                "pre_literature_host_count": int(sub["pre_literature_host_candidate"].sum()),
                "priority_A_count": int((sub["pre_literature_priority_tier"] == "PRIORITY_A").sum()),
                "priority_B_count": int((sub["pre_literature_priority_tier"] == "PRIORITY_B").sum()),
            }
        )
    family_summary = pd.DataFrame(family_summary_rows).sort_values(
        "all_candidates_count", ascending=False
    )

    host_summary_rows = []
    for tier in HOST_TIERS:
        sub = master[master["host_likeness_tier"] == tier]
        host_summary_rows.append(
            {
                "host_likeness_tier": tier,
                "all_candidates_count": len(sub),
                "phase17_conservative_count": int(sub["conservative_discovery_candidate"].sum()),
                "formula_representative_count": int(sub["is_formula_representative"].sum()),
                "mean_Voltage": round(float(sub["pred_voltage_final"].mean()), 6),
                "mean_Capacity": round(float(sub["pred_capacity_final"].mean()), 6),
                "median_energy_proxy": round(float(sub["pred_specific_energy_proxy_Wh_kg"].median()), 6),
            }
        )
    host_summary = pd.DataFrame(host_summary_rows)

    # ---- 18. write outputs --------------------------------------------------------------------------------
    atomic_to_csv(master, OUT_MASTER)
    atomic_to_csv(master[master["pre_literature_host_candidate"].astype(bool)], OUT_PRE_LIT)
    atomic_to_csv(master[master["pre_literature_priority_tier"] == "PRIORITY_A"], OUT_PRIORITY_A)
    atomic_to_csv(master[master["pre_literature_priority_tier"] == "PRIORITY_B"], OUT_PRIORITY_B)
    atomic_to_csv(deprioritized, OUT_DEPRIORITIZED)
    atomic_to_csv(queue, OUT_QUEUE)
    atomic_to_csv(family_summary, OUT_FAMILY_SUMMARY)
    atomic_to_csv(host_summary, OUT_HOST_SUMMARY)

    # ---- 19. figures -----------------------------------------------------------------------------------------
    log("generating figures ...")
    cons_rep = master[
        master["conservative_discovery_candidate"].astype(bool)
        & master["is_formula_representative"].astype(bool)
    ]
    tier_counts = [int((cons_rep["host_likeness_tier"] == t).sum()) for t in HOST_TIERS]
    figure_bar_counts(
        list(HOST_TIERS), tier_counts, FIG_DIR / "01_phase17_shortlist_by_host_likeness",
        "Phase 17 conservative formula-representatives by host-likeness tier",
        "candidate count",
    )
    fam_counts = (
        master["chemistry_family"].value_counts().sort_values(ascending=False)
    )
    figure_bar_counts(
        list(fam_counts.index), [int(v) for v in fam_counts.values],
        FIG_DIR / "02_chemistry_family_counts",
        "all candidates by chemistry family (composition heuristic)",
        "candidate count",
    )
    figure_scatter_tier(
        master, FIG_DIR / "03_voltage_capacity_host_likeness",
        "predicted voltage vs capacity colored by host-likeness tier",
    )
    fig, ax = plt.subplots(figsize=(9, 5.5))
    box_data = [
        master[master["host_likeness_tier"] == t]["pred_specific_energy_proxy_Wh_kg"].dropna().to_numpy()
        for t in HOST_TIERS
    ]
    ax.boxplot(box_data, tick_labels=list(HOST_TIERS))
    ax.set_ylabel("specific-energy proxy (Wh/kg)")
    ax.set_title("specific-energy proxy by host-likeness tier")
    save_figure(fig, FIG_DIR / "04_energy_proxy_by_host_likeness")
    priority_a = master[master["pre_literature_priority_tier"] == "PRIORITY_A"]
    fig, ax = plt.subplots(figsize=(9, 6.5))
    ax.scatter(priority_a["pred_voltage_final"], priority_a["pred_capacity_final"],
               s=20, color="#C44E52", alpha=0.8)
    ax.set_xlabel("predicted voltage (V)")
    ax.set_ylabel("predicted capacity (mAh/g)")
    ax.set_title("PRIORITY_A pre-literature candidates")
    save_figure(fig, FIG_DIR / "05_priority_A_voltage_capacity")

    funnel_steps = [
        ("Phase17 conservative discovery", int(master["conservative_discovery_candidate"].sum())),
        ("formula representatives", int((master["conservative_discovery_candidate"] & master["is_formula_representative"]).sum())),
        ("host tier A/B", int((cons_rep["host_likeness_tier"].isin(["TIER_A_FRAMEWORK_LIKE", "TIER_B_POSSIBLE_FRAMEWORK"])).sum())),
        ("pre-literature host candidates (no extreme-high V)", int(pre_lit.sum())),
    ]
    funnel_branches = [
        ("PRIORITY_A", int((master["pre_literature_priority_tier"] == "PRIORITY_A").sum())),
        ("PRIORITY_B", int((master["pre_literature_priority_tier"] == "PRIORITY_B").sum())),
    ]
    figure_funnel(funnel_steps, funnel_branches, FIG_DIR / "06_phase17_to_phase18_funnel")
    pa_fam = priority_a["chemistry_family"].value_counts()
    figure_bar_counts(
        list(pa_fam.index), [int(v) for v in pa_fam.values],
        FIG_DIR / "07_priority_A_chemistry_family",
        "PRIORITY_A candidates by chemistry family",
        "candidate count",
    )
    figure_queue_top30(queue, FIG_DIR / "08_literature_verification_queue_top30")

    # ---- 20. summary -----------------------------------------------------------------------------------------------
    elapsed = time.perf_counter() - overall_started
    n_conservative = int(master["conservative_discovery_candidate"].sum())
    n_cons_rep = int((master["conservative_discovery_candidate"] & master["is_formula_representative"]).sum())
    n_pre_lit = int(pre_lit.sum())
    n_prio_a = int((master["pre_literature_priority_tier"] == "PRIORITY_A").sum())
    n_prio_b = int((master["pre_literature_priority_tier"] == "PRIORITY_B").sum())
    n_review = int((master["pre_literature_priority_tier"] == "REVIEW_ONLY").sum())

    lines: list[str] = []
    lines.append("Phase 18 - Aqueous-ZIB feasibility triage summary")
    lines.append("=" * 70)
    lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")
    lines.append("")
    lines.append(f"total candidates: {n_total}")
    lines.append(f"Phase17 conservative count: {n_conservative}")
    lines.append(f"Phase17 formula-representative conservative count: {n_cons_rep}")
    lines.append(f"formula parse failures (kept): {n_parse_failed}")
    lines.append("host tiers (all candidates):")
    for tier in HOST_TIERS:
        lines.append(f"    {tier}: {int((master['host_likeness_tier'] == tier).sum())}")
    lines.append("chemistry family counts (all candidates):")
    for _, row in family_summary.iterrows():
        lines.append(f"    {row['chemistry_family']}: {int(row['all_candidates_count'])}")
    lines.append(f"all-metal intermetallic flag count: {int(master['flag_all_metal_intermetallic'].sum())}")
    lines.append(f"Zn-only-metal-compound flag count: {int(master['flag_zn_only_metal_compound'].sum())}")
    lines.append(f"pre_literature_host_candidate count: {n_pre_lit}")
    lines.append(f"PRIORITY_A count: {n_prio_a}")
    lines.append(f"PRIORITY_B count: {n_prio_b}")
    lines.append(f"REVIEW_ONLY count: {n_review}")
    lines.append(f"literature verification queue count: {len(queue)}")
    lines.append("")
    lines.append("literature verification queue Top30:")
    lines.append("    material_id | formula | family | host tier | V | C | energy | e_hull | Pareto")
    for _, row in queue.head(30).iterrows():
        lines.append(
            f"    {row['material_id']} | {row['formula_pretty']} | {row['chemistry_family']} | "
            f"{row['host_likeness_tier']} | {row['pred_voltage_final']:.3f} | "
            f"{row['pred_capacity_final']:.2f} | {row['pred_specific_energy_proxy_Wh_kg']:.2f} | "
            f"{row['mp_energy_above_hull']:.4f} | {int(row['pareto_front_conservative_discovery']) if pd.notna(row['pareto_front_conservative_discovery']) else '-'}"
        )
    lines.append("")
    lines.append("output files:")
    for path in (
        OUT_MASTER, OUT_PRE_LIT, OUT_PRIORITY_A, OUT_PRIORITY_B, OUT_DEPRIORITIZED,
        OUT_QUEUE, OUT_FAMILY_SUMMARY, OUT_HOST_SUMMARY, FIG_DIR, OUT_SUMMARY,
    ):
        lines.append(f"    {path.relative_to(PROJECT_ROOT).as_posix()}")
    lines.append("")
    lines.append("policy statements:")
    lines.append("    Phase18 does not establish aqueous stability.")
    lines.append("    Phase18 does not establish reversible Zn2+ insertion.")
    lines.append("    Phase18 does not establish literature novelty.")
    lines.append("    Host-likeness tiers are composition-based heuristics used only to")
    lines.append("    prioritize manual literature verification.")
    lines.append("    The remove-Zn formula is only a composition proxy, not a computed")
    lines.append("    charged phase.")
    lines.append("    Phase17 STRICT_NOVEL_FORMULA means unseen in the current Zn-insertion")
    lines.append("    reference set, not globally novel.")
    lines.append("    No model was retrained.")
    lines.append("    No Phase15/16/17 predictions, uncertainties, AD categories or Pareto")
    lines.append("    fronts were changed.")
    lines.append("")
    lines.append(f"runtime: {elapsed:.1f} s")
    lines.append("")
    OUT_SUMMARY.write_text("\\n".join(lines), encoding="utf-8")
    log(f"Saved feasibility summary -> {OUT_SUMMARY}")

    # ---- 21. console ----------------------------------------------------------------------------------------------------
    print("")
    print("Phase 18 aqueous-ZIB feasibility triage completed.")
    print(f"Phase17 conservative count: {n_conservative}")
    print(f"Tier A count: {int((master['host_likeness_tier'] == 'TIER_A_FRAMEWORK_LIKE').sum())}")
    print(f"Tier B count: {int((master['host_likeness_tier'] == 'TIER_B_POSSIBLE_FRAMEWORK').sum())}")
    print(f"Tier C count: {int((master['host_likeness_tier'] == 'TIER_C_LOW_HOST_LIKENESS').sum())}")
    print(f"pre-literature host candidate count: {n_pre_lit}")
    print(f"Priority A count: {n_prio_a}")
    print(f"Priority B count: {n_prio_b}")
    print(f"literature verification queue count: {len(queue)}")
    print("queue Top10:")
    for _, row in queue.head(10).iterrows():
        print(f"  {row['material_id']}  {row['formula_pretty']}  "
              f"{row['host_likeness_tier']}  V={row['pred_voltage_final']:.3f}  "
              f"C={row['pred_capacity_final']:.2f}  "
              f"E={row['pred_specific_energy_proxy_Wh_kg']:.2f}  "
              f"e_hull={row['mp_energy_above_hull']:.4f}")
    print(f"outputs: {OUT_DIR}")
    print(f"figures: {FIG_DIR}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
''',
    19: '''# -*- coding: utf-8 -*-
"""
Phase 19A - Literature verification preparation: evidence schema +
auditable research batches.

This phase prepares (does NOT perform) the literature verification of the
Phase 18 queue. It:

    1. freezes the verification set (Phase 18 queue order, max 100 rows),
    2. creates a candidate-level evidence schema with strict status
       vocabularies,
    3. creates a source-level (one-to-many) evidence table template,
    4. splits the frozen set into 5 auditable batches of 20 candidates,
    5. writes the Phase 19B evidence protocol (hierarchy, source
       verification rules, search completeness rules).

Hard rules: no web search, no API calls, no guessed DOIs/titles, and NO
literature conclusions are generated. Every literature field starts as
NOT_CHECKED / NOT_STARTED / NA / empty. Negative findings can only be
interpreted as "no exact evidence identified under the standardized
protocol up to the search cutoff date (2026-09-17)" - never as
"globally novel".

Outputs:
    05_Results/Literature_Verification/Phase19/
        literature_candidate_verification_template.csv
        literature_evidence_sources_template.csv
        literature_search_log_template.csv
        batch_01_candidates.csv .. batch_05_candidates.csv
        phase19_evidence_protocol.txt
        phase19_preparation_summary.txt

Run from the project root:
    py 03_Code/Screening/19_prepare_literature_verification.py
"""

from __future__ import annotations

import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

try:
    from pymatgen.core import Composition
    PYMATGEN_AVAILABLE = True
except ImportError:  # pragma: no cover
    Composition = None  # type: ignore[assignment]
    PYMATGEN_AVAILABLE = False

# ---------------------------------------------------------------------------
# Paths
# ---------------------------------------------------------------------------
PROJECT_ROOT = Path(_SCIENCE_WORK_ROOT)

IN_QUEUE = PROJECT_ROOT / "05_Results" / "Candidate_Screening" / "Phase18_Aqueous_Feasibility" / "literature_verification_queue.csv"
