# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------
def log(message: str) -> None:
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S")
    print(f"[{stamp}Z] {message}", flush=True)


def atomic_to_csv(df: pd.DataFrame, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    df.to_csv(tmp, index=False, encoding="utf-8-sig")
    os.replace(tmp, path)
    log(f"Saved {len(df)} rows -> {path}")


def read_required(path: Path) -> pd.DataFrame:
    if not path.is_file():
        log(f"ERROR: required input file not found: {path}")
        sys.exit(1)
    return pd.read_csv(path, low_memory=False)


def formula_variants(formula) -> tuple[str, str, str]:
    original = str(formula)
    reduced, alphabetical = original, original
    if PYMATGEN_AVAILABLE and Composition is not None:
        try:
            comp = Composition(original)
            reduced = comp.reduced_formula
            alphabetical = comp.alphabetical_formula
        except Exception:  # noqa: BLE001
            pass
    return original, reduced, alphabetical


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    overall_started = time.perf_counter()
    log("Phase 19A - literature verification preparation (no search, no conclusions)")

    # ---- 1. inputs ---------------------------------------------------------
    queue = read_required(IN_QUEUE)
    master = read_required(IN_MASTER)
    read_required(IN_PRIORITY_A)   # existence confirmation
    if not IN_P18_SUMMARY.is_file():
        log(f"ERROR: required input file not found: {IN_P18_SUMMARY}")
        return 1

    # ---- 2. freeze the verification set ----------------------------------------
    n_candidates = len(queue)
    if n_candidates == 0 or n_candidates > 100:
        log(f"ERROR: verification set size must be 1..100; found {n_candidates}")
        return 1
    if not bool(queue["material_id"].is_unique):
        log("ERROR: queue material_id is not unique")
        return 1
    if not set(queue["material_id"]).issubset(set(master["material_id"])):
        log("ERROR: some queue material_ids are missing from the Phase 18 master")
        return 1
    master_by_id = master.set_index("material_id")
    for mid in queue["material_id"]:
        row = master_by_id.loc[mid]
        if not (bool(row["pre_literature_host_candidate"]) and bool(row["is_formula_representative"])):
            log(f"ERROR: {mid} in queue is not pre-literature host + formula representative")
            return 1
    log(f"frozen verification set: {n_candidates} candidates (order kept from Phase 18 queue)")

    # ---- 3. build candidate template --------------------------------------------
    keep_columns = [
        "material_id", "formula_pretty", "non_zn_framework_formula_proxy",
        "chemistry_family", "host_likeness_tier", "pre_literature_priority_tier",
        "pred_voltage_final", "pred_capacity_final", "pred_specific_energy_proxy_Wh_kg",
        "voltage_ensemble_std", "capacity_ensemble_std",
        "zn_ad_5nn_distance", "mp_energy_above_hull", "mp_is_stable",
        "pareto_front_conservative_discovery",
        "empirical_voltage_class", "empirical_capacity_class",
        "reference_formula_status",
    ]
    template = queue[keep_columns].copy()
    template.insert(0, "verification_rank", np.arange(1, n_candidates + 1))
    # exact order check: template rows must equal queue rows
    if list(template["material_id"]) != list(queue["material_id"]):
        log("ERROR: template order diverges from the Phase 18 queue order")
        return 1

    # evidence fields (all initialized; no conclusions pre-filled)
    for column, default_value in CANDIDATE_EVIDENCE_DEFAULTS.items():
        template[column] = default_value

    # formula search aliases (never change candidate identity)
    variants = template["formula_pretty"].apply(formula_variants)
    template["formula_original"] = [v[0] for v in variants]
    template["formula_reduced"] = [v[1] for v in variants]
    template["formula_alphabetical"] = [v[2] for v in variants]

    # 12 standard search queries (strings only; no search executed)
    for i, query_template in enumerate(QUERY_TEMPLATES, start=1):
        column = f"search_query_{i}"
        rows = []
        for _, row in template.iterrows():
            proxy = str(row["non_zn_framework_formula_proxy"] or row["formula_pretty"])
            rows.append(
                query_template.replace("{formula}", str(row["formula_pretty"]))
                .replace("{proxy}", proxy)
            )
        template[column] = rows
    template["verification_questions"] = VERIFICATION_QUESTIONS

    # ---- 4. QA on the candidate template -----------------------------------------
    initial_ok_statuses = {"NOT_CHECKED", "NOT_STARTED", "NA", ""}
    for column, default_value in CANDIDATE_EVIDENCE_DEFAULTS.items():
        values = set(template[column].astype(str).unique())
        if not values.issubset(initial_ok_statuses):
            log(f"ERROR: evidence field {column} contains non-initial values: {values}")
            return 1
    log("candidate template QA passed (all evidence fields initialized, nothing pre-filled)")

    # ---- 5. source table template (header only) -------------------------------------
    source_template = pd.DataFrame(columns=SOURCE_TEMPLATE_COLUMNS)

    # ---- 6. search log template (pre-generated query rows, fields empty) --------------
    log_rows = []
    for _, row in template.iterrows():
        for i in range(1, 13):
            query_name = f"query_{i}"
            log_rows.append(
                {
                    "verification_rank": int(row["verification_rank"]),
                    "material_id": row["material_id"],
                    "formula_pretty": row["formula_pretty"],
                    "query_name": query_name,
                    "is_core_query": query_name in CORE_QUERY_NAMES,
                    "search_date": "",
                    "search_engine_or_database": "",
                    "query": row[f"search_query_{i}"],
                    "results_screened_count": "",
                    "potential_sources_found": "",
                    "sources_opened": "",
                    "notes": "",
                }
            )
    search_log = pd.DataFrame(log_rows, columns=SEARCH_LOG_COLUMNS)

    # search-log auditability QA
    if len(search_log) != n_candidates * 12:
        log(f"ERROR: search log rows {len(search_log)} != {n_candidates * 12}")
        return 1
    for _, row in template.iterrows():
        sub = search_log[search_log["material_id"] == row["material_id"]]
        names = set(sub["query_name"])
        if names != {f"query_{i}" for i in range(1, 13)}:
            log(f"ERROR: query_name set wrong for {row['material_id']}: {sorted(names)}")
            return 1
        if int(sub["is_core_query"].astype(bool).sum()) != 6:
            log(f"ERROR: core query count != 6 for {row['material_id']}")
            return 1
    log("search-log QA passed (12 queries per candidate, exactly 6 core queries)")

    # ---- 7. batches (original order, 20 per batch) -------------------------------------
    batch_columns = [
        "verification_rank", "material_id", "formula_pretty",
        "pre_literature_priority_tier",
        "pred_voltage_final", "pred_capacity_final", "pred_specific_energy_proxy_Wh_kg",
        "voltage_ensemble_std", "capacity_ensemble_std",
        "chemistry_family", "host_likeness_tier", "non_zn_framework_formula_proxy",
        "zn_ad_5nn_distance", "mp_energy_above_hull", "mp_is_stable",
    ] + [f"search_query_{i}" for i in range(1, 13)] + ["verification_questions"]

    batches = []
    for start in range(0, n_candidates, BATCH_SIZE):
        batches.append(template.iloc[start:start + BATCH_SIZE][batch_columns].reset_index(drop=True))

    # batch recovery QA: concatenation restores the template exactly (ids + order)
    recovered_ids = [mid for batch in batches for mid in batch["material_id"]]
    if recovered_ids != list(template["material_id"]):
        log("ERROR: batch concatenation does not recover the verification set")
        return 1
    if len(set(recovered_ids)) != len(recovered_ids):
        log("ERROR: duplicate material_ids across batches")
        return 1
    log(f"batches: {len(batches)}; batch sizes: {[len(b) for b in batches]}")

    # ---- 8. write outputs ------------------------------------------------------------------
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    atomic_to_csv(template, OUT_CANDIDATE_TEMPLATE)
    atomic_to_csv(source_template, OUT_SOURCE_TEMPLATE)
    atomic_to_csv(search_log, OUT_SEARCH_LOG)
    for i, batch in enumerate(batches, start=1):
        atomic_to_csv(batch, OUT_DIR / f"batch_{i:02d}_candidates.csv")

    # ---- 9. evidence protocol -----------------------------------------------------------------
    protocol_lines = []
    protocol_lines.append("Phase 19 - Literature verification evidence protocol")
    protocol_lines.append("=" * 70)
    protocol_lines.append(f"search cutoff date: {SEARCH_CUTOFF_DATE}")
    protocol_lines.append("")
    protocol_lines.append("1. Evidence hierarchy (candidate-level):")
    protocol_lines.append("    LEVEL_1: Exact material/phase + direct aqueous-ZIB experimental evidence")
    protocol_lines.append("    LEVEL_2: Exact formula + aqueous-ZIB evidence, phase identity uncertain")
    protocol_lines.append("    LEVEL_3: Exact material/formula reported outside AZIB")
    protocol_lines.append("    LEVEL_4: Related chemistry/material only")
    protocol_lines.append("    LEVEL_5: No exact evidence found under standardized search")
    protocol_lines.append("    NOTE: LEVEL_5 never means 'novel'. It only means no exact-formula")
    protocol_lines.append("    evidence was identified under the current search protocol by")
    protocol_lines.append(f"    {SEARCH_CUTOFF_DATE}.")
    protocol_lines.append("")
    protocol_lines.append("2. Recommended Phase 19B search order (Phase 19A does NOT search):")
    protocol_lines.append("    1. Crossref / DOI metadata")
    protocol_lines.append("    2. Publisher journal page")
    protocol_lines.append("    3. Google Scholar / general scholarly search")
    protocol_lines.append("    4. Web of Science / Scopus (if accessible)")
    protocol_lines.append("    5. Semantic Scholar")
    protocol_lines.append("    6. Materials Project / ICSD / COD structural databases")
    protocol_lines.append("       (structural existence only, NOT AZIB electrochemistry evidence)")
    protocol_lines.append("    7. Review articles only to locate primary references; performance")
    protocol_lines.append("       data from reviews must be traced back to the primary paper.")
    protocol_lines.append("")
    protocol_lines.append("3. Source verification rules (source_verified=True requires):")
    protocol_lines.append("    - title, source location and year are confirmed,")
    protocol_lines.append("    - AND at least one verifiable identifier exists")
    protocol_lines.append("      (DOI matching the title, publisher page, or trusted database record).")
    protocol_lines.append("    - Search-engine snippets alone NEVER qualify.")
    protocol_lines.append("    - If the DOI cannot be matched to the title with confidence, leave it empty.")
    protocol_lines.append("    - Never guess a DOI.")
    protocol_lines.append("")
    protocol_lines.append("4. Negative-finding rules:")
    protocol_lines.append("    - NO_EXACT_AZIB_REPORT_FOUND / NO_EXACT_FORMULA_EVIDENCE_FOUND /")
    protocol_lines.append("      NO_EVIDENCE_FOUND may only be assigned after at least the six core")
    protocol_lines.append("      queries (query_1, query_2, query_3, query_6, query_7, query_9)")
    protocol_lines.append("      have been executed and logged.")
    protocol_lines.append("    - These statuses mean 'no exact evidence identified under the")
    protocol_lines.append("      standardized protocol', never 'globally novel' or 'never reported'.")
    protocol_lines.append("")
    protocol_lines.append("5. Formula vs phase identity:")
    protocol_lines.append("    - exact_formula_match does NOT imply exact_phase_match.")
    protocol_lines.append("    - A formula-level mention is FORMULA_ONLY_AMBIGUOUS unless the")
    protocol_lines.append("      reported phase/structure (e.g. space group) matches the candidate.")
    protocol_lines.append("    - Search aliases (formula_reduced / formula_alphabetical) are query")
    protocol_lines.append("      variants only; an alias hit is not an exact-phase match.")
    protocol_lines.append("")
    protocol_lines.append("6. Phase 18 remove-Zn proxy:")
    protocol_lines.append("    - non_zn_framework_formula_proxy is a composition-level host proxy.")
    protocol_lines.append("    - It is NOT charged-host evidence. charged_host_status requires a")
    protocol_lines.append("      literature-reported de-zincated host.")
    protocol_lines.append("")
    protocol_lines.append("7. Confidence rules:")
    protocol_lines.append("    - evidence_confidence is based on evidence quality and directness,")
    protocol_lines.append("      never on journal impact factor.")
    protocol_lines.append("    - HIGH requires at least one primary peer-reviewed source directly")
    protocol_lines.append("      matching candidate/formula/phase with clear experimental data.")
    protocol_lines.append("")
    protocol_lines.append("8. Allowed candidate-level status vocabularies (frozen for Phase 19B):")
    for field, allowed_values in EVIDENCE_STATUS_VOCABULARIES.items():
        protocol_lines.append(f"    {field}:")
        for value in allowed_values:
            protocol_lines.append(f"        {value}")
    protocol_lines.append("")
    protocol_lines.append("9. Source-level allowed vocabularies:")
    protocol_lines.append("    source_type: PRIMARY_ARTICLE, REVIEW, DATABASE, THESIS, CONFERENCE,")
    protocol_lines.append("                 PREPRINT, OTHER")
    protocol_lines.append("    evidence_category: MATERIAL_IDENTITY, AZIB_CATHODE, ZN_INSERTION,")
    protocol_lines.append("                       PROTON_COINsertion, REACTION_MECHANISM, CHARGED_HOST,")
    protocol_lines.append("                       AQUEOUS_STABILITY, DISSOLUTION, ELECTROCHEMISTRY, OTHER")
    protocol_lines.append("    evidence_direction: SUPPORTS, CONTRADICTS, CONTEXT_ONLY, UNCLEAR")
    protocol_lines.append("    source_verified: False / True")
    protocol_lines.append("")
    protocol_lines.append("10. Search-completeness rule for verification_status:")
    protocol_lines.append("    - NOT_STARTED: searching may not have happened yet.")
    protocol_lines.append("    - Any other status (IN_PROGRESS / VERIFIED / AMBIGUOUS /")
    protocol_lines.append("      INSUFFICIENT_EVIDENCE) requires the six core queries")
    protocol_lines.append("      (query_1, query_2, query_3, query_6, query_7, query_9) to have been")
    protocol_lines.append("      executed and recorded in the search log.")
    protocol_lines.append("    - Phase 19A executes no searches, so every candidate remains")
    protocol_lines.append("      verification_status = NOT_STARTED.")
    protocol_lines.append("")
    OUT_PROTOCOL.write_text("\\n".join(protocol_lines), encoding="utf-8")
    log(f"Saved evidence protocol -> {OUT_PROTOCOL}")

    # ---- 10. preparation summary ----------------------------------------------------------------
    elapsed = time.perf_counter() - overall_started
    summary_lines = []
    summary_lines.append("Phase 19A - Literature verification preparation summary")
    summary_lines.append("=" * 70)
    summary_lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")
    summary_lines.append("")
    summary_lines.append(f"candidate verification count: {n_candidates}")
    summary_lines.append(f"batch count: {len(batches)}")
    summary_lines.append(f"batch sizes: {[len(b) for b in batches]}")
    summary_lines.append(f"search cutoff date: {SEARCH_CUTOFF_DATE}")
    summary_lines.append("candidate order frozen from Phase18 queue: yes")
    summary_lines.append("")
    summary_lines.append("state of the prepared artifacts:")
    summary_lines.append("    - candidate template: all evidence fields = NOT_CHECKED / NOT_STARTED / NA / empty")
    summary_lines.append("    - source table: header only (0 rows)")
    summary_lines.append("    - search log: 12 query rows per candidate pre-generated, all fields empty")
    summary_lines.append("    - no literature conclusions generated")
    summary_lines.append("    - no candidate removed")
    summary_lines.append("    - no ML value changed")
    summary_lines.append("    - no Phase15/16/17/18 result changed")
    summary_lines.append("")
    summary_lines.append("Phase19A prepares an auditable literature-verification workflow.")
    summary_lines.append("It does not establish literature novelty, aqueous stability,")
    summary_lines.append("or reversible Zn-ion storage.")
    summary_lines.append("")
    OUT_SUMMARY.write_text("\\n".join(summary_lines), encoding="utf-8")
    log(f"Saved preparation summary -> {OUT_SUMMARY}")

    # ---- 11. console -------------------------------------------------------------------------------
    print("")
    print("Phase 19A literature-verification preparation completed.")
    print(f"verification candidates: {n_candidates}")
    print(f"batches: {len(batches)}")
    print(f"batch sizes: {[len(b) for b in batches]}")
    print(f"search cutoff: {SEARCH_CUTOFF_DATE}")
    print(f"outputs: {OUT_DIR}")
    print(f"elapsed: {elapsed:.1f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
