# ===== INLINED evidence_sections.py; no runtime module dependency =====
"""Inline-ready AZIB structure, archived evidence, tables, and narrow DOCX repairs.

No helper script is imported or launched. The frozen Phase21B numerical code is
embedded below and executed in an isolated namespace; historical human evidence
is explicitly labelled as archived evidence. Original project files are read only.
"""


def _evidence_read_csv(path):
    import csv
    from pathlib import Path
    with Path(path).open(encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def _evidence_write_csv(path, rows, columns=None):
    import csv
    from pathlib import Path
    path = Path(path)
    if path.exists():
        raise FileExistsError(f"Refusing to replace existing generated table: {path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    columns = columns or (list(rows[0]) if rows else [])
    with path.open("x", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=columns)
        writer.writeheader()
        writer.writerows(rows)


def _evidence_write_json(path, value):
    import json
    from pathlib import Path
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("x", encoding="utf-8") as handle:
        json.dump(value, handle, ensure_ascii=False, indent=2)


def _evidence_bool(value):
    if str(value).strip().lower() in {"true", "1", "yes"}:
        return True
    if str(value).strip().lower() in {"false", "0", "no"}:
        return False
    raise ValueError(f"Invalid Boolean evidence field: {value!r}")


def run_structure_stage(work_root, log_path, threads=1):
    """Recompute all 13 frozen structures offline, without old figures or SI.

    Required inputs are DB-restored original relative paths for the Phase21
    manifest, 13 JSONs, 13 CIFs, and Phase22 experimental-coordinate evidence.
    Numerical output is always a new directory. Frozen source provenance checks
    remain strict: a missing/mismatched file is BLOCKED, never UNRESOLVED.
    """
    import contextlib
    import hashlib
    import os
    import time
    from pathlib import Path

    root = Path(work_root).resolve()
    output = root / "05_Results/Structure_Validation/Phase21_Dezincation_Feasibility"
    if output.exists() and any(output.iterdir()):
        raise FileExistsError(f"Refusing nonempty structure output: {output}")
    if int(threads) < 1:
        raise ValueError("threads must be >= 1")
    log_path = Path(log_path).resolve()
    if log_path.exists():
        raise FileExistsError(f"Refusing existing structure log: {log_path}")
    log_path.parent.mkdir(parents=True, exist_ok=True)
    old_environment = {key: os.environ.get(key) for key in
                       ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS")}
    for key in old_environment:
        os.environ[key] = str(int(threads))
    started = time.perf_counter()
    namespace = {"__name__": "_azib_inline_structure21b",
                 "__file__": str(root / "03_Code/Structure_Analysis/inline_structure21b.py")}
    try:
        with log_path.open("x", encoding="utf-8") as log_handle:
            with contextlib.redirect_stdout(log_handle), contextlib.redirect_stderr(log_handle):
                # This source is part of the single delivered program, not read
                # from an external .py at normal runtime.
                exec(compile(STRUCTURE21B_INLINE_SOURCE,
                             "<embedded-frozen-phase21b-numerical-logic>", "exec"), namespace)
                if not namespace["DEPENDENCIES_AVAILABLE"]:
                    return {"stage": "structure21b", "status": "BLOCKED",
                            "reason": "Missing pymatgen/networkx/numpy/pandas",
                            "log": str(log_path)}
                exit_code = int(namespace["main"]())
                if exit_code != 0:
                    return {"stage": "structure21b", "status": "BLOCKED",
                            "exit_code": exit_code, "log": str(log_path),
                            "failure_file": str(output / "phase21b_failures.csv")}
                mapping = recompute_experimental_site_mapping(root)
        assessment = _evidence_read_csv(output / "phase21b_final_13_assessment.csv")
        shortlist = _evidence_read_csv(output / "phase21b_final_3to5_candidates.csv")
        if len(assessment) != 13 or assessment[7]["material_id"] != "mp-aaacpfiq":
            raise ValueError("Structure identity/order lost; hodgkinsonite must remain row 8")
        result = {
            "stage": "structure21b", "status": "COMPLETED",
            "calculation": "NEW_UNRELAXED_TOPOLOGY_AND_COMPOSITION_CHARGE_PROXY",
            "source_script_sha256": STRUCTURE21B_SOURCE_SHA256,
            "embedded_numerical_source_sha256": hashlib.sha256(
                STRUCTURE21B_INLINE_SOURCE.encode("utf-8")).hexdigest(),
            "n_structures": len(assessment), "n_retained": len(shortlist),
            "retained_ids": [row["material_id"] for row in shortlist],
            "experimental_coordinate_source": "ARCHIVED_HUMAN_EXTRACTED_PHASE22_EVIDENCE",
            "experimental_site_mapping": mapping,
            "recorded_site_mapping_validation": "PASS" if all(row["status"] == "PASS" for row in mapping) else "DIFFERENT",
            "elapsed_seconds": time.perf_counter() - started,
            "output_directory": str(output), "log": str(log_path),
            "no_dft_or_relaxation_or_electrochemical_validation": True,
            "historical_claim_status": "HYPOTHESIS_ONLY",
        }
        _evidence_write_json(output / "structure_stage_provenance.json", result)
        return result
    finally:
        for key, value in old_environment.items():
            if value is None:
                os.environ.pop(key, None)
            else:
                os.environ[key] = value


def recompute_experimental_site_mapping(work_root):
    """Numerically verify recorded setting transform against frozen MP sites.

    The experimental coordinates and setting transform are archived human
    evidence, not independently regenerated literature or a new experiment.
    """
    import json
    from pathlib import Path
    from pymatgen.core import Structure

    root = Path(work_root)
    source_path = root / "05_Results/Structure_Validation/Phase22_Final_Freeze/phase22_final_evidence_table.csv"
    evidence = {row["claim_id"]: row for row in _evidence_read_csv(source_path)}
    structure = Structure.from_dict(json.loads(
        (root / "02_Datasets/Structures/Phase21/JSON/mp-aaacpfiq.json").read_text(encoding="utf-8")))
    inventory = _evidence_read_csv(root / "05_Results/Structure_Validation/Phase21_Dezincation_Feasibility/phase21b_zn_site_inventory.csv")
    zinc_sites = [index for index, site in enumerate(structure)
                  if any(element.symbol == "Zn" for element in site.species)]
    result = []
    for claim_id, experimental_label in (("P22-C06", "experimental_Zn(1)"),
                                         ("P22-C07", "experimental_Zn(2)")):
        claim = evidence[claim_id]
        data = json.loads(claim["numerical_evidence_json"])
        x, y, z = data[experimental_label]
        transformed = [y % 1, x % 1, (-z) % 1]
        distances = [(float(structure.lattice.get_all_distances(
            [transformed], [structure[index].frac_coords])[0, 0]), index)
                     for index in zinc_sites]
        residual, best_index = min(distances)
        expected_index = int(data["matched_MP_site_index"])
        recorded_residual = float(data["cartesian_residual_A"])
        # Original evidence reports 9 decimal places. This threshold validates
        # that recorded precision and never changes the new numerical result.
        orbit_rows = [row for row in inventory if row["material_id"] == "mp-aaacpfiq"
                      and row["zn_orbit_id"] == data["Phase21B_orbit"]]
        new_orbit_sites = json.loads(orbit_rows[0]["equivalent_site_indices"]) if len(orbit_rows) == 1 else None
        matches = (best_index == expected_index and abs(residual - recorded_residual) <= 5.1e-9
                   and new_orbit_sites == data["orbit_sites"])
        record = {"claim_id": claim_id, "experimental_label": experimental_label,
                  "archived_experimental_coordinate": [x, y, z],
                  "setting_transform": "(y_exp, x_exp, -z_exp) mod 1",
                  "transformed_coordinate": transformed,
                  "recomputed_matched_MP_site_index": best_index,
                  "archived_matched_MP_site_index": expected_index,
                  "recomputed_residual_A": residual,
                  "archived_residual_A": recorded_residual,
                  "recorded_orbit": data["Phase21B_orbit"],
                  "recorded_orbit_sites": data["orbit_sites"],
                  "recomputed_orbit_sites": new_orbit_sites,
                  "source_doi_or_path": claim["source_doi_or_path"],
                  "evidence_kind": "ARCHIVED_EXPERIMENTAL_COORDINATE_EVIDENCE",
                  "status": "PASS" if matches else "DIFFERENT"}
        result.append(record)
    _evidence_write_json(root / "05_Results/Structure_Validation/Phase21_Dezincation_Feasibility/experimental_site_mapping_recomputed.json", result)
    return result


def rebuild_phase20_from_archived_annotations(archive_root, outroot):
    """Apply recorded sequential gates to archived human judgements.

    Literature interpretation and four explicit hard-risk judgements remain
    ARCHIVE_ONLY. No network search, novelty inference, or new human decision is
    performed. The returned 13 are the archived pool, not a newly validated
    full-run 100-to-13 funnel.
    """
    from collections import Counter
    from pathlib import Path
    root = Path(archive_root)
    base = root / "05_Results/Candidate_Screening/Phase20_Final_Evidence_Backed_Screening"
    rows = _evidence_read_csv(base / "phase20_all_100_integrated.csv")
    if len(rows) != 100 or len({row["material_id"] for row in rows}) != 100:
        raise ValueError("Archived Phase20 annotation pool is not 100 unique candidates")
    output_rows = []
    priority = 0
    for source in sorted(rows, key=lambda row: int(row["verification_rank"])):
        row = dict(source)
        direct = row["azib_cathode_status"] in {"DIRECT_EXACT_MATERIAL", "DIRECT_FORMULA_LEVEL_ONLY"}
        # Four material-specific judgements were made by human literature review.
        # Risk facts are read from the DB archived annotation, not synthesized.
        hard_risk = any(flag in row.get("phase20_risk_flags", "") for flag in
                        ("VERY_LOW_REPORTED_CONDUCTIVITY", "SYNTHESIS_FAILURE_REPORTED",
                         "PRECIPITATION_SIDE_REACTION_REPORTED",
                         "HYPOTHETICAL_SPECIES_NOT_EXPERIMENTALLY_REALIZED"))
        if direct:
            category = "BENCHMARK_ALREADY_REPORTED_AZIB"
        elif hard_risk:
            category = "HIGH_RISK_DEPRIORITIZED"
        elif (row["material_identity_status"] == "EXACT_MATERIAL_CONFIRMED"
              and row["evidence_confidence"] == "HIGH"
              and row["dissolution_evidence"] == "NO_DIRECT_EVIDENCE_FOUND"):
            category = "FINAL_EXPERIMENTAL_PRIORITY"
        elif row["material_identity_status"] == "EXACT_MATERIAL_CONFIRMED":
            category = "EXACT_MATERIAL_SECONDARY"
        elif row["material_identity_status"] in {"FORMULA_ONLY_AMBIGUOUS", "EXACT_FORMULA_MULTIPLE_PHASES"}:
            category = "PHASE_UNRESOLVED_SECONDARY"
        elif row["literature_status"] == "FORMULA_REPORTED_OTHER_CONTEXT":
            category = "FORMULA_CONTEXT_SECONDARY"
        else:
            category = "LITERATURE_GAP_UNVERIFIED"
        if category == "FINAL_EXPERIMENTAL_PRIORITY":
            priority += 1
        row.update({"gate_recomputed_category": category,
                    "gate_recomputed_priority": priority if category == "FINAL_EXPERIMENTAL_PRIORITY" else "",
                    "archive_category_matches": category == source["phase20_category"],
                    "human_evidence_status": "ARCHIVE_ONLY",
                    "decision_calculation": "SEQUENTIAL_GATE_ON_ARCHIVED_HUMAN_ANNOTATIONS"})
        output_rows.append(row)
    finalists = [row for row in output_rows if row["gate_recomputed_category"] == "FINAL_EXPERIMENTAL_PRIORITY"]
    original = _evidence_read_csv(base / "phase20_final_experimental_priority.csv")
    if [row["material_id"] for row in finalists] != [row["material_id"] for row in original]:
        raise ValueError("Recorded Phase20 gates produce a different identity/order from archived final13")
    out = Path(outroot) / "Evidence_Reconstruction"
    _evidence_write_csv(out / "phase20_gate_reconstruction.csv", output_rows)
    _evidence_write_csv(out / "phase20_finalists_archived_human_pool.csv", finalists)
    result = {"status": "ARCHIVE_ONLY", "gate_recomputation": "PASS",
              "n_annotated_candidates": len(rows), "n_finalists": len(finalists),
              "category_counts": dict(Counter(row["gate_recomputed_category"] for row in output_rows)),
              "new_full_run_100_to_13_verified": False,
              "historical_literature_search_independently_reexecuted": False,
              "source": str(base / "phase20_all_100_integrated.csv")}
    _evidence_write_json(out / "phase20_gate_provenance.json", result)
    return result


def generate_paper_tables(science_root, archive_root, outroot, mode):
    """Rebuild Table1-3 from scientific records and bounded human evidence.

    In full mode only the human-reviewed 13-material identity pool and literature
    conclusions are archived. Their numerical properties are joined to NEW
    Phase16 deployment predictions and NEW Phase21B computations. No success
    claim is made for reproducing a new full-run literature 100-to-13 decision.
    """
    import json
    from pathlib import Path
    if mode not in {"reproduce", "full"}:
        raise ValueError("mode must be reproduce or full")
    science, archive, output = map(Path, (science_root, archive_root, outroot))
    if mode == "full" and science.resolve() == archive.resolve():
        raise ValueError("Full-mode table construction requires an isolated new scientific root")
    kind = "ARCHIVED_MODEL_RESULT" if mode == "reproduce" else "NEW_MODEL_RESULT"
    sources = []
    def read(relative, root=science):
        path = root / relative
        source_kind = kind
        if "Phase20_Final_Evidence" in relative or "Phase22_Final_Freeze" in relative:
            source_kind = "ARCHIVED_HUMAN_EVIDENCE"
        elif "Phase21_Dezincation" in relative:
            source_kind = "ARCHIVED_STRUCTURE_PROXY" if mode == "reproduce" else "NEW_STRUCTURE_PROXY"
        elif relative.startswith("02_Datasets/Processed/Splits/"):
            source_kind = "FROZEN_VALIDATION_PARTITION"
        elif relative.startswith("02_Datasets/Features/"):
            source_kind = "ARCHIVED_DATABASE_AND_COMPOSITION_FEATURES" if mode == "reproduce" else "NEW_FEATURES_FROM_FROZEN_DATABASE_RECORDS"
        sources.append({"path": str(path), "relative_path": relative,
                        "kind": source_kind})
        return _evidence_read_csv(path)
    def select(rows, **conditions):
        matches = [row for row in rows if all(row.get(key) == value for key, value in conditions.items())]
        if len(matches) != 1:
            raise ValueError(f"Expected one scientific row for {conditions}; found {len(matches)}")
        return matches[0]
    def f(value, digits):
        return f"{float(value):.{digits}f}"
    all_features = read("02_Datasets/Features/all_battery_candidate_compatible_features.csv")
    candidate_features = read("02_Datasets/Features/zinc_candidates_candidate_compatible_features.csv")
    feature_rows = read("02_Datasets/Features/Feature_Sets/core_numeric_features.csv")
    primary = read("02_Datasets/Processed/Splits/primary_group_holdout.csv")
    strict = read("02_Datasets/Processed/Splits/strict_zn_transfer_holdout.csv")
    zn_folds = read("02_Datasets/Processed/Splits/zn_group_cv_folds.csv")
    train = [row for row in primary if row["split"] == "train"]
    test = [row for row in primary if row["split"] == "test"]
    overlap = len({row["group_framework_formula"] for row in train} &
                  {row["group_framework_formula"] for row in test})
    strict_train = [row for row in strict if row["transfer_split"] == "strict_nonzn_train"]
    strict_test = [row for row in strict if row["transfer_split"] == "zn_test"]
    strict_overlap = len({row["group_framework_formula"] for row in strict_train} &
                         {row["group_framework_formula"] for row in strict_test})
    tuned = read("05_Results/Metrics/Phase9_Tuning/tuned_primary_group_test_metrics.csv")
    tuned_cv = read("05_Results/Metrics/Phase9_Tuning/tuned_cv_model_ranking.csv")
    tuned_strict = read("05_Results/Metrics/Phase9_Tuning/tuned_strict_zn_transfer_metrics.csv")
    zn_oof = read("05_Results/Metrics/Phase10_Zn_Domain/zn_group_pooled_oof_metrics.csv")
    mixed_oof = read("05_Results/Metrics/Phase11_Training_Regime/training_regime_pooled_oof_metrics.csv")
    v = select(tuned, target="average_voltage", model="CatBoost")
    c = select(tuned, target="capacity_grav", model="CatBoost")
    vt = select(tuned_strict, target="average_voltage", model="CatBoost")
    ct = select(tuned_strict, target="capacity_grav", model="CatBoost")
    vz = select(zn_oof, target="average_voltage", model="CatBoost")
    cz = select(zn_oof, target="capacity_grav", model="CatBoost")
    vm = select(mixed_oof, target="average_voltage", regime="MIXED_ION_GROUP_SAFE")
    nzn = sum(row["working_ion"] == "Zn" for row in all_features)
    n_features = len(feature_rows)
    if n_features != 53:
        raise ValueError(f"Expected 53 feature definitions; found {n_features}")
    table1 = [
        ["Population / evaluation", "Records / features", "Voltage", "Capacity"],
        ["Modeling population", f"{len(all_features):,} / {n_features}", f"{nzn} Zn records", "Same Zn subset"],
        ["Primary group holdout", f"{len(train):,} / {len(test):,}; overlap {overlap}",
         f"R2 {f(v['R2'],4)}; RMSE {f(v['RMSE'],4)} V; MAE {f(v['MAE'],4)} V",
         f"R2 {f(c['R2'],4)}; RMSE {f(c['RMSE'],4)} mAh g-1; MAE {f(c['MAE'],4)} mAh g-1"],
        ["Selection group CV", "Five folds" if len({row['cv_fold'] for row in train}) == 5 else f"{len({row['cv_fold'] for row in train})} folds",
         f"RMSE {f(select(tuned_cv,target='average_voltage',model='CatBoost')['best_cv_RMSE'],4)} V",
         f"RMSE {f(select(tuned_cv,target='capacity_grav',model='CatBoost')['best_cv_RMSE'],4)} mAh g-1"],
        ["Strict non-Zn → Zn", f"{len(strict_train):,} / {len(strict_test):,}; overlap {strict_overlap}",
         f"R2 {f(vt['R2'],2)}".replace("-", "−"), f"R2 {f(ct['R2'],2)}"],
        ["Zn-only CatBoost OOF", f"{len(zn_folds)} / {len({row['group_framework_formula'] for row in zn_folds})} framework groups",
         f"R2 {f(vz['pooled_oof_R2'],4)}; RMSE {f(vz['pooled_oof_RMSE'],4)} V",
         f"R2 {f(cz['pooled_oof_R2'],4)}; RMSE {f(cz['pooled_oof_RMSE'],4)} mAh g-1"],
        ["Mixed-ion group-safe OOF", f"{int(float(vm['n_oof']))} Zn validation records",
         f"R2 {f(vm['pooled_oof_R2'],4)}; RMSE {f(vm['pooled_oof_RMSE'],4)} V", "Zn-only regime selected"],
        ["Screening library", f"{len(candidate_features):,} candidates", "Prediction population", "Not evaluation data"]]
    finalists = read("05_Results/Candidate_Screening/Phase20_Final_Evidence_Backed_Screening/phase20_final_experimental_priority.csv", archive)
    finalists = sorted(finalists, key=lambda row: int(row["phase20_priority_order"]))
    assessment = read("05_Results/Structure_Validation/Phase21_Dezincation_Feasibility/phase21b_final_13_assessment.csv")
    assessment_by_id = {row["material_id"]: row for row in assessment}
    if len(finalists) != 13 or finalists[7]["material_id"] != "mp-aaacpfiq":
        raise ValueError("Archived human final13 pool/order has changed")
    predictions = None
    if mode == "full":
        predictions = {row["material_id"]: row for row in read("05_Results/Uncertainty/Phase16_Candidate_Uncertainty_OOD/candidate_uncertainty_ood.csv")}
    table2 = [["No", "Material ID", "Formula", "Predicted voltage (V)",
               "Predicted capacity (mAh g-1)", "MP hull energy (eV atom-1)",
               "Screening outcome / phase reference"]]
    phase_refs = ["[36]", "[37]", "[38]", "[39]", "[40]", "[41]", "[42]", "[31,32]", "[43]", "[44]", "[45]", "[46]", "[47]"]
    for index, row in enumerate(finalists, 1):
        scientific = predictions[row["material_id"]] if predictions is not None else row
        structure = assessment_by_id[row["material_id"]]
        retained = _evidence_bool(structure["phase21b_eligible_for_final_shortlist"])
        outcome = "Partial de-zincation plausible" if retained and structure['phase21b_classification'] == "PLAUSIBLE_WITH_PARTIAL_DEZINCATION" else (
            "Structurally plausible" if retained and structure['phase21b_classification'] == "STRUCTURALLY_PLAUSIBLE" else "Not retained")
        formula = "Zn2Mn(SiO4)(OH)2" if row["material_id"] == "mp-aaacpfiq" else row["formula_pretty"]
        table2.append([str(index), row["material_id"], formula,
                       f(scientific["pred_voltage_final"], 3), f(scientific["pred_capacity_final"], 1),
                       f(row["mp_energy_above_hull"], 4), outcome + phase_refs[index - 1]])
    states = read("05_Results/Structure_Validation/Phase21_Dezincation_Feasibility/phase21b_dezincation_states.csv")
    oxi = read("05_Results/Structure_Validation/Phase21_Dezincation_Feasibility/phase21b_oxidation_state_analysis.csv")
    inventory = read("05_Results/Structure_Validation/Phase21_Dezincation_Feasibility/phase21b_zn_site_inventory.csv")
    phase22 = read("05_Results/Structure_Validation/Phase22_Final_Freeze/phase22_final_evidence_table.csv", archive)
    hodg = [row for row in states if row["material_id"] == "mp-aaacpfiq"]
    zn1 = select(hodg, state_id="SYM_ORBIT_Zn1")
    zn2 = select(hodg, state_id="SYM_ORBIT_Zn2")
    full = select(hodg, state_id="FULL_ZN_REMOVAL")
    charge = select(oxi, material_id="mp-aaacpfiq")
    def retention(row):
        value = float(row["component_retention_fraction"])
        return f"{value:.1f}" if value in {0.0, 1.0} else f"{value:.3f}"
    def gate(row):
        return "PASS" if _evidence_bool(row["topology_pass"]) else "FAIL"
    headroom_min = float(charge["common_headroom_min_e_per_cell"])
    headroom_max = float(charge["common_headroom_max_e_per_cell"])
    headroom_text = f"{headroom_min:g}" if headroom_min == headroom_max else f"{headroom_min:g}–{headroom_max:g}"
    hodg_orbits = [row for row in inventory if row["material_id"] == "mp-aaacpfiq"]
    orbit_count = len(hodg_orbits)
    if orbit_count != 2:
        raise ValueError("Current Table3 identity summary expects exactly two symmetry-distinct Zn orbits")
    if {row["wyckoff_symbol"] for row in hodg_orbits} != {"4e"}:
        raise ValueError("New Zn orbit inventory does not support Table3's two 4e identity description")
    table3 = [
        ["Evidence", "Observation", "Boundary"],
        ["Identity / sites", "Zn2Mn(SiO4)(OH)2; two 4e Zn orbits; experimental correspondence", "Site identity does not demonstrate Zn mobility."],
        ["Partial-removal topology", f"Zn1: {retention(zn1)}, {gate(zn1)}; Zn2: {retention(zn2)}, {gate(zn2)}", "Unrelaxed pristine connectivity only."],
        ["Charge headroom", f"Half removal: {float(zn2['required_electron_removal_per_cell']):g} e-; full: {float(full['required_electron_removal_per_cell']):g} e-; available: {headroom_text} e- per cell", "Composition-level sanity, without extraction energetics."],
        ["Full-removal topology", f"Retention {retention(full)}, {gate(full)} despite charge {'PASS' if full['charge_balance_status'] in {'ROBUST_COMMON_CATION_HEADROOM','POSSIBLE_COMMON_CATION_HEADROOM'} else 'FAIL'}", "Full removal unsupported as retained connectivity."],
        ["Literature scope", "No direct aqueous-ZIB cathode report was identified.", "No claim of global novelty."],
        ["Conclusion", "Site-dependent partial de-zincation remains structurally plausible.", "Electrochemical reversibility, aqueous stability, vacancy energetics and migration kinetics remain unverified."]]
    # An unexpected new topology result must not receive the old hypothesis.
    if not (_evidence_bool(zn2["topology_pass"]) and not _evidence_bool(zn1["topology_pass"])
            and not _evidence_bool(full["topology_pass"])
            and zn2["charge_balance_status"] in {"ROBUST_COMMON_CATION_HEADROOM", "POSSIBLE_COMMON_CATION_HEADROOM"}
            and _evidence_bool(assessment_by_id["mp-aaacpfiq"]["phase21b_eligible_for_final_shortlist"])):
        table3[-1][1] = "New structural proxy differs; site-dependent interpretation requires review."
        table3[4][2] = "New unrelaxed proxy result; historical interpretation requires review."
    tables = [{"table": number, "rows": rows} for number, rows in enumerate((table1, table2, table3), 1)]
    table_dir = output / "Tables"
    for table in tables:
        headers, *data = table["rows"]
        _evidence_write_csv(table_dir / f"Table_{table['table']:02d}.csv", [dict(zip(headers, row)) for row in data], headers)
    metadata = {"mode": mode, "tables": tables, "sources": sources,
                "table1": {"numerical_source": kind, "primary_model": "TUNED_CATBOOST_PHASE9", "snapshot_used_as_numeric_source": False},
                "table2": {"identity_pool": "ARCHIVE_ONLY_HUMAN_REVIEWED_13", "numerical_properties": kind,
                           "hull_energy": "ARCHIVED_DATABASE_PROPERTY", "phase_references": "ARCHIVED_LITERATURE_VERIFICATION",
                           "structural_outcome": "ARCHIVED_STRUCTURE_PROXY" if mode == "reproduce" else "NEW_STRUCTURE_PROXY",
                           "historical_100_to_13_gate_revalidated_by_new_prediction": False},
                "table3": {"structural_numbers": "ARCHIVED_STRUCTURE_PROXY" if mode == "reproduce" else "NEW_STRUCTURE_PROXY",
                           "experimental_identity_and_roles": "ARCHIVE_ONLY_HUMAN_CRYSTALLOGRAPHIC_EVIDENCE",
                           "literature_negative_finding": "ARCHIVE_ONLY_PROTOCOL_AND_CUTOFF_BOUNDED",
                           "claim_ceiling": "HYPOTHESIS_ONLY"}}
    snapshot = archive / "03_Code/config/paper_table_contents.json"
    if mode == "reproduce" and snapshot.is_file():
        prior = json.loads(snapshot.read_text(encoding="utf-8"))
        differences = []
        for before, after in zip(prior["tables"], tables):
            if before["rows"] != after["rows"]:
                differences.append({"table": after["table"], "archived": before["rows"], "rebuilt": after["rows"]})
        metadata["display_precision_validation"] = {"status": "PASS" if not differences else "DIFFERENT", "differences": differences}
    _evidence_write_json(table_dir / "paper_tables_rebuilt.json", metadata)
    return metadata


def _evidence_docx_fields(paragraph, namespaces):
    """Read complex Word fields without flattening them or altering runs."""
    stack, complete = [], []
    w = namespaces["w"]
    for node in paragraph.iter():
        if node.tag == "{" + w + "}fldChar":
            kind = node.get("{" + w + "}fldCharType")
            if kind == "begin":
                stack.append({"begin": node, "instruction_nodes": [], "result_nodes": [], "separated": False})
            elif kind == "separate" and stack:
                stack[-1]["separated"] = True
            elif kind == "end" and stack:
                field = stack.pop()
                field["end"] = node
                field["instruction"] = "".join(item.text or "" for item in field["instruction_nodes"])
                field["result"] = "".join(item.text or "" for item in field["result_nodes"])
                complete.append(field)
        elif node.tag == "{" + w + "}instrText" and stack and not stack[-1]["separated"]:
            stack[-1]["instruction_nodes"].append(node)
        elif node.tag == "{" + w + "}t" and stack:
            for field in stack:
                if field["separated"]:
                    field["result_nodes"].append(node)
    if stack:
        raise ValueError("Unbalanced Word field in inspected paragraph")
    return complete


def repair_manuscript_cross_references(source_docx, output_docx, expected_source_sha256=None):
    """Repair only the two misdirected Table2 REF fields in a new DOCX copy.

    All image bytes, other package parts, bookmarks, SEQ instructions, scientific
    text and formatting survive. Correct existing cached text is left untouched.
    Rendering and Word field update remain an explicit caller-owned QA step.
    """
    import hashlib
    import re
    from pathlib import Path
    from zipfile import ZipFile
    from lxml import etree

    source, output = Path(source_docx).resolve(), Path(output_docx).resolve()
    if source == output or output.exists():
        raise FileExistsError("DOCX repair requires a distinct, nonexistent output copy")
    digest = hashlib.sha256(source.read_bytes()).hexdigest()
    if expected_source_sha256 and digest != expected_source_sha256:
        raise ValueError("Source DOCX changed since the caller's audit")
    ns = {"w": "http://schemas.openxmlformats.org/wordprocessingml/2006/main"}
    with ZipFile(source) as archive:
        root = etree.fromstring(archive.read("word/document.xml"))
        body = root.find("w:body", ns)
        paragraphs = body.findall("w:p", ns)
        table2 = [p for p in paragraphs if any(re.match(r"\s*SEQ\s+Table\b", f["instruction"])
                  and f["result"].strip() == "2" for f in _evidence_docx_fields(p, ns))]
        if len(table2) != 1:
            raise ValueError("Cannot uniquely identify Table2's actual SEQ caption")
        target_bookmarks = table2[0].xpath("./w:bookmarkStart/@w:name", namespaces=ns)
        if "_Ref242653996" not in target_bookmarks:
            raise ValueError("Audited Table2 caption bookmark is absent; do not guess another target")
        repairs, contexts = [], []
        for index, p in enumerate(paragraphs):
            text = "".join(p.xpath(".//w:t/text()", namespaces=ns))
            fields = _evidence_docx_fields(p, ns)
            is_caption10 = any(re.match(r"\s*SEQ\s+Fig\.\s", f["instruction"])
                               and f["result"].strip() == "10" for f in fields)
            is_row8 = "mp-aaacpfiq; row 8 of " in text
            is_body10 = text.startswith("Fig. 10 visualizes")
            if not (is_caption10 or is_row8 or is_body10):
                continue
            contexts.append({"paragraph_index": index, "caption10": is_caption10, "row8": is_row8, "body10": is_body10})
            for field in fields:
                if re.search(r"\bREF\s+_Ref242480998\b", field["instruction"]):
                    if not (is_caption10 or is_row8):
                        raise ValueError("Unexpected corrupted-body context needs a separate explicit audit")
                    old = field["instruction"]
                    found = 0
                    for node in field["instruction_nodes"]:
                        if "_Ref242480998" in (node.text or ""):
                            node.text = node.text.replace("_Ref242480998", "_Ref242653996")
                            found += 1
                    if found != 1:
                        raise ValueError("REF target crosses XML runs or occurs ambiguously")
                    cache_changed = field["result"] != "Table 2"
                    if cache_changed:
                        if not field["result_nodes"]:
                            raise ValueError("Missing REF result nodes; cannot safely restore cache")
                        field["result_nodes"][0].text = "Table 2"
                        for node in field["result_nodes"][1:]:
                            node.text = ""
                    field["begin"].set("{" + ns["w"] + "}dirty", "true")
                    repairs.append({"paragraph_index": index, "context": "Fig10_caption" if is_caption10 else "Section3.6_row8",
                                    "old_instruction": old, "new_target": "_Ref242653996", "cache_changed": cache_changed})
        if len(repairs) not in {0, 2}:
            raise ValueError(f"Expected both audited damaged fields or already repaired copy; found {len(repairs)}")
        if len(contexts) != 3:
            raise ValueError("The three audited caption/body/row8 contexts are not uniquely present")
        document_xml = etree.tostring(root, encoding="UTF-8", xml_declaration=True, standalone=True)
        output.parent.mkdir(parents=True, exist_ok=True)
        with output.open("xb") as raw:
            with ZipFile(raw, "w") as destination:
                for info in archive.infolist():
                    destination.writestr(info, document_xml if info.filename == "word/document.xml" else archive.read(info.filename))
    return {"source_sha256": digest, "output_sha256": hashlib.sha256(output.read_bytes()).hexdigest(),
            "repairs": repairs, "formal_original_docx_modified": False,
            "render_visual_qa": "PENDING_CALLER_WORD_FIELD_UPDATE_AND_PAGE_INSPECTION"}


