STRUCTURE21B_INLINE_SOURCE = '# -*- coding: utf-8 -*-\n"""\nPhase 21B - Structure-level de-zincation feasibility analysis (offline).\n\nPhase 21A froze 13 exact Materials Project structures (JSON + CIF + manifest).\nPhase 21B analyzes ONLY those frozen files, completely offline:\n\n    1. re-verifies the Phase 21A hashes (files must be unmodified),\n    2. identifies inequivalent Zn crystallographic sites (orbits),\n    3. describes Zn local coordination (CrystalNN primary),\n    4. builds a 3x3x3 PERIODIC TORUS bond graph from the pristine CrystalNN\n       StructureGraph (jimage translations preserved and wrapped mod 3;\n       graph representation only - never a supercell, never saved as a new\n       structure), deletes Zn nodes WITHOUT creating any new bonds, and\n       scores each state with the PRISTINE-RELATIVE\n       component_retention_fraction (pure topology retention analysis),\n    5. generates deterministic unrelaxed de-zincation proxy states\n       (symmetry-orbit removals, 25/50/75% fractional vacancies selected by\n       the deterministic farthest-point/maximin rule via\n       deterministic_farthest_selection, full removal) - never supercells,\n       never relaxations,\n    6. performs a composition-level oxidation-state / charge-balance sanity\n       check (fixed Zn/O/H/Li/Na/Sr/P/Si/As states are passed into the\n       pymatgen solver via oxi_states_override as dict[str, list[float]];\n       charge headroom is computed per oxidation solution and per\n       crystallographic CELL, never per reduced formula unit, never\n       averaged),\n    7. classifies each candidate as STRUCTURALLY_PLAUSIBLE /\n       PLAUSIBLE_WITH_PARTIAL_DEZINCATION / HIGH_RECONSTRUCTION_RISK /\n       UNRESOLVED using frozen sequential rules (no weighted score),\n    8. selects a 3-5 structural shortlist with the Phase 20 priority order\n       as the only tie-breaker.\n\n    Frozen-input/provenance failures (any SHA-256 mismatch, missing\n    JSON/CIF, manifest identity/order mismatch, JSON parse failure,\n    num_sites mismatch, missing Zn, drift flag, QA flag) are CRITICAL:\n    recorded to phase21b_failures.csv and the run aborts with exit code 1.\n    UNRESOLVED is reserved for post-provenance SCIENTIFIC analysis\n    uncertainty (disorder, mixed/partial Zn occupancy, symmetry failure,\n    CrystalNN fallback, zero oxidation-state solutions).\n\nHard boundaries: no MP API, no network, no DFT, no relaxation, no energy\ncalculation, no NEB/AIMD/phonons, no re-ranking, no weighted scores, and\nPhase 15-21A outputs are never modified. All de-zincated structures are\nUNRELAXED TOPOLOGY / CHARGE-BALANCE PROXIES, never called stable charged\nphases.\n\nOutputs:\n    05_Results/Structure_Validation/Phase21_Dezincation_Feasibility/\n        phase21b_zn_site_inventory.csv\n        phase21b_candidate_topology.csv\n        phase21b_dezincation_states.csv\n        phase21b_oxidation_state_analysis.csv\n        phase21b_final_13_assessment.csv\n        phase21b_final_3to5_candidates.csv\n        phase21b_deprioritized_candidates.csv\n        phase21b_qa_report.csv\n        phase21b_failures.csv (only on critical failure)\n        phase21b_methodology.txt\n        phase21b_summary.txt\n    06_Figures/Phase21/\n        Figure21B_01_final_classification.png/pdf\n        Figure21B_02_nonZn_framework_connectivity.png/pdf\n        Figure21B_03_Zn_site_role_summary.png/pdf\n        Figure21B_04_charge_headroom.png/pdf\n\nRun from the project root:\n    py 03_Code/Structure_Analysis/21b_dezincation_structure_analysis.py\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport importlib.metadata\nimport json\nimport os\nimport sys\nimport time\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\n\n\ntry:\n    from pymatgen.core import Structure, Composition, Element\n    from pymatgen.symmetry.analyzer import SpacegroupAnalyzer\n    from pymatgen.analysis.local_env import CrystalNN, MinimumDistanceNN\n    from pymatgen.analysis.graphs import StructureGraph\n    import networkx as nx\n    DEPENDENCIES_AVAILABLE = True\nexcept ImportError:  # pragma: no cover\n    Structure = None  # type: ignore[assignment]\n    Composition = None  # type: ignore[assignment]\n    Element = None  # type: ignore[assignment]\n    SpacegroupAnalyzer = None  # type: ignore[assignment]\n    CrystalNN = None  # type: ignore[assignment]\n    MinimumDistanceNN = None  # type: ignore[assignment]\n    StructureGraph = None  # type: ignore[assignment]\n    nx = None  # type: ignore[assignment]\n    DEPENDENCIES_AVAILABLE = False\n\n# ---------------------------------------------------------------------------\n# Paths\n# ---------------------------------------------------------------------------\nPROJECT_ROOT = Path(__file__).resolve().parents[2]\n\nIN_MANIFEST = PROJECT_ROOT / "02_Datasets" / "Structures" / "Phase21" / "phase21_structure_manifest.csv"\nPHASE21_DIR = PROJECT_ROOT / "02_Datasets" / "Structures" / "Phase21"\nJSON_DIR = PHASE21_DIR / "JSON"\nCIF_DIR = PHASE21_DIR / "CIF"\n\nOUT_DIR = PROJECT_ROOT / "05_Results" / "Structure_Validation" / "Phase21_Dezincation_Feasibility"\nOUT_ZN_INVENTORY = OUT_DIR / "phase21b_zn_site_inventory.csv"\nOUT_TOPOLOGY = OUT_DIR / "phase21b_candidate_topology.csv"\nOUT_STATES = OUT_DIR / "phase21b_dezincation_states.csv"\nOUT_OXI = OUT_DIR / "phase21b_oxidation_state_analysis.csv"\nOUT_ASSESSMENT = OUT_DIR / "phase21b_final_13_assessment.csv"\nOUT_SHORTLIST = OUT_DIR / "phase21b_final_3to5_candidates.csv"\nOUT_DEPRIORITIZED = OUT_DIR / "phase21b_deprioritized_candidates.csv"\nOUT_QA = OUT_DIR / "phase21b_qa_report.csv"\nOUT_FAILURES = OUT_DIR / "phase21b_failures.csv"\nOUT_METHODOLOGY = OUT_DIR / "phase21b_methodology.txt"\nOUT_SUMMARY = OUT_DIR / "phase21b_summary.txt"\n\nFIG_DIR = PROJECT_ROOT / "06_Figures" / "Phase21"\n\n# Frozen Phase 20 finalist order (priority, verification_rank, material_id, formula).\nEXPECTED_FINALISTS = [\n    (1, 43, "mp-aaacqxjn", "Li2Zn2(MoO4)3"),\n    (2, 47, "mp-aaabfxob", "NaZnFe2(PO4)3"),\n    (3, 55, "mp-aaaabrbk", "Ti3Zn2O8"),\n    (4, 64, "mp-aaaaazyv", "V2Zn3O8"),\n    (5, 66, "mp-aaaabbml", "Nb2Zn3O8"),\n    (6, 70, "mp-aaabfran", "SrV2ZnO7"),\n    (7, 71, "mp-aaacltye", "ZnFe2(P2O7)2"),\n    (8, 78, "mp-aaacpfiq", "MnZn2Si(HO3)2"),\n    (9, 84, "mp-aaaabahh", "Ta2ZnO6"),\n    (10, 91, "mp-aaaabpxr", "V2Zn4O9"),\n    (11, 92, "mp-aaabdbiu", "ZnCuAsHO5"),\n    (12, 97, "mp-aaacpyhb", "ZnAgPO4"),\n    (13, 98, "mp-aaaabrpd", "Zn3Mo2O9"),\n]\n\nREQUIRED_MANIFEST_COLUMNS = [\n    "phase20_priority_order", "verification_rank", "material_id", "formula_phase20",\n    "structure_num_sites", "spacegroup_symbol_api", "spacegroup_number_api",\n    "cif_filename", "json_filename",\n    "structure_json_sha256", "cif_file_sha256", "json_file_sha256",\n    "json_roundtrip_pass", "cif_roundtrip_pass",\n    "historical_structure_drift_flag", "overall_structure_QA_pass",\n]\n\nFAILURE_COLUMNS = ["material_id", "failure_stage", "failure_message"]\n\n# Frozen symmetry parameters (never tuned per candidate).\nSYMPREC = 1e-3\nANGLE_TOLERANCE = 5\n\n# Frozen topology heuristic thresholds (never re-fitted). The 0.95/0.80 gates\n# are applied to the PRISTINE-RELATIVE component_retention_fraction (fraction\n# of pristine connectivity retained), NOT to the absolute largest component\n# fraction - so intrinsically 1D/2D or multi-component periodic crystals are\n# not penalized for their pristine component structure.\nTOPO_RETENTION_MIN = 0.95\nTOPO_ISOLATED_MAX = 0.05\nGUEST_ORBIT_RETENTION_MIN = 0.95\nGUEST_ORBIT_ISOLATED_MAX = 0.05\nFRAMEWORK_ARTICULATION_MIN = 0.50\nFRAMEWORK_ORBIT_RETENTION_MAX = 0.80\nFRAMEWORK_ORBIT_ISOLATED_MIN = 0.20\nPARTIAL_STATE_MAX_FRACTION = 0.50\n\n# Periodic torus graph replication (GRAPH REPRESENTATION ONLY - never a\n# supercell, never saved as a structure).\nPERIODIC_GRAPH_REPLICATION = 3\n\n# Fixed oxidation-state assumptions (recorded in methodology/summary).\nFIXED_OXI_OVERRIDES = {\n    "Zn": 2, "O": -2, "H": 1,\n    "Li": 1, "Na": 1, "Sr": 2,\n    "P": 5, "Si": 4, "As": 5,\n}\n\nCLASSIFICATIONS = (\n    "STRUCTURALLY_PLAUSIBLE",\n    "PLAUSIBLE_WITH_PARTIAL_DEZINCATION",\n    "HIGH_RECONSTRUCTION_RISK",\n    "UNRESOLVED",\n)\n\nGOOD_CHARGE_STATUSES = {\n    "ROBUST_COMMON_CATION_HEADROOM",\n    "POSSIBLE_COMMON_CATION_HEADROOM",\n}\n\n\n# ---------------------------------------------------------------------------\n# Small helpers\n# ---------------------------------------------------------------------------\ndef log(message: str) -> None:\n    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S")\n    print(f"[{stamp}Z] {message}", flush=True)\n\n\ndef atomic_to_csv(df: pd.DataFrame, path: Path) -> None:\n    tmp = path.with_suffix(path.suffix + ".tmp")\n    df.to_csv(tmp, index=False, encoding="utf-8-sig")\n    os.replace(tmp, path)\n    log(f"Saved {len(df)} rows -> {path}")\n\n\n\n\ndef read_required(path: Path) -> pd.DataFrame:\n    if not path.is_file():\n        log(f"ERROR: required input file not found: {path}")\n        sys.exit(1)\n    return pd.read_csv(path, low_memory=False)\n\n\ndef manifest_bool(value) -> bool:\n    """Strict interpretation of a manifest boolean column ("True"/"False"\n    strings after CSV round-trip). Raises ValueError on anything else so a\n    malformed provenance flag can never silently pass."""\n    if isinstance(value, (bool, np.bool_)):\n        return bool(value)\n    if pd.isna(value):\n        raise ValueError("manifest boolean is NaN")\n    s = str(value).strip().lower()\n    if s in {"true", "1", "yes"}:\n        return True\n    if s in {"false", "0", "no"}:\n        return False\n    raise ValueError(f"cannot interpret manifest boolean: {value!r}")\n\n\ndef write_failures_and_abort(failures: list[dict], message: str) -> int:\n    """CRITICAL INPUT/PROVENANCE FAILURE handler: record every failure to\n    phase21b_failures.csv, then abort with exit code 1. Provenance failures\n    are frozen-input integrity failures and are NEVER downgraded to\n    UNRESOLVED or followed by classification/shortlist outputs."""\n    try:\n        OUT_DIR.mkdir(parents=True, exist_ok=True)\n        atomic_to_csv(pd.DataFrame(failures, columns=FAILURE_COLUMNS), OUT_FAILURES)\n    except Exception as exc:  # noqa: BLE001\n        log(f"ERROR: could not write failure record {OUT_FAILURES}: "\n            f"{type(exc).__name__}: {exc}")\n    log(f"CRITICAL INPUT/PROVENANCE FAILURE: {message} "\n        f"({len(failures)} failure record(s))")\n    log("Phase 21B ABORTED - no classification, no shortlist, no completed status.")\n    return 1\n\n\ndef package_version(name: str) -> str:\n    try:\n        return importlib.metadata.version(name)\n    except importlib.metadata.PackageNotFoundError:\n        return "not installed"\n\n\ndef sha256_of_bytes(data: bytes) -> str:\n    return hashlib.sha256(data).hexdigest()\n\n\ndef canonical_structure_json(structure) -> str:\n    return json.dumps(\n        structure.as_dict(), sort_keys=True, separators=(",", ":"), ensure_ascii=False\n    )\n\n\ndef min_image_distance(lattice, coord_a, coord_b) -> float:\n    try:\n        return float(lattice.get_all_distances([coord_a], [coord_b])[0, 0])\n    except Exception:  # noqa: BLE001\n        return float(np.linalg.norm(lattice.get_cartesian_coords(coord_a)\n                                    - lattice.get_cartesian_coords(coord_b)))\n\n\n# Hard-QA audit counter: every 25/50/75% fractional vacancy state must be\n# selected by deterministic_farthest_selection. main() checks that the number\n# of helper calls equals the number of generated fractional states.\nFARTHEST_SELECTION_CALLS = {"count": 0}\n\n\ndef deterministic_farthest_selection(coords: list, lattice, n_select: int,\n                                     site_indices: list | None = None) -> list[int]:\n    """Deterministic maximin (farthest-point) vacancy selection.\n\n    Frozen rules:\n      * candidates are the entries of `coords`, identified by `site_indices`\n        (defaults to positional order);\n      * the first vacancy is the candidate with the SMALLEST site index;\n      * every later vacancy is the candidate whose periodic minimum-image\n        distance to the nearest already-selected vacancy is largest;\n      * distance ties are broken by the smaller site index.\n    Purely deterministic - no randomness. Returns the selected entries as a\n    sorted list of indices into `coords`.\n    """\n    FARTHEST_SELECTION_CALLS["count"] += 1\n    if site_indices is None:\n        site_indices = list(range(len(coords)))\n    if not coords or int(n_select) <= 0:\n        return []\n    n_select = min(int(n_select), len(coords))\n    start = min(range(len(coords)), key=lambda i: (site_indices[i], i))\n    selected: list[int] = [start]\n    while len(selected) < n_select:\n        best_index = None\n        best_score = -1.0\n        for i in range(len(coords)):\n            if i in selected:\n                continue\n            d_min = min(min_image_distance(lattice, coords[i], coords[j]) for j in selected)\n            if best_index is None or d_min > best_score + 1e-12 or (\n                abs(d_min - best_score) <= 1e-12\n                and site_indices[i] < site_indices[best_index]\n            ):\n                best_index = i\n                best_score = d_min\n        selected.append(best_index)\n    return sorted(selected)\n\n\ndef generate_fractional_vacancy_sites(structure, zn_site_indices: list[int],\n                                      target_fraction: float) -> tuple:\n    """Deterministic fractional Zn-vacancy proxy for ONE target fraction.\n\n    * candidates = the current structure\'s Zn site indices ONLY;\n    * target_count = nearest representable integer count of removed Zn in\n      this cell (round half up, clamped to 1..total-1);\n    * selection is delegated to deterministic_farthest_selection (maximin,\n      periodic minimum-image distances, first vacancy = smallest Zn site\n      index) - never a fractional-coordinate sort, never a supercell.\n    Returns (removed_site_indices, target_count); (None, 0) when no proper\n    partial state is representable in this cell (e.g. a single Zn site).\n    """\n    total = len(zn_site_indices)\n    if total < 2:\n        return None, 0\n    n_target = int(target_fraction * total + 0.5)  # round half up (nearest)\n    n_target = max(1, min(n_target, total - 1))\n    coords = [structure[i].frac_coords for i in zn_site_indices]\n    chosen = deterministic_farthest_selection(\n        coords, structure.lattice, n_target,\n        site_indices=list(zn_site_indices),\n    )\n    removed = [zn_site_indices[i] for i in chosen]\n    return removed, n_target\n\n\ndef remaining_formula_after_removal(structure, removed_indices: list[int]) -> str:\n    kept = [site for i, site in enumerate(structure) if i not in set(removed_indices)]\n    if not kept:\n        return ""\n    try:\n        return Composition(\n            {str(el): 0.0 for el in set().union(*[site.species for site in kept])}\n            | {\n                str(el): sum(site.species[el] for site in kept)\n                for el in set().union(*[site.species for site in kept])\n            }\n        ).reduced_formula\n    except Exception:  # noqa: BLE001\n        return ""\n\n\ndef periodic_edges_from_structure_graph(sg) -> list[tuple]:\n    """Extract periodic edges (u, v, shift) from a pymatgen StructureGraph.\n\n    shift = to_jimage - from_jimage; a missing jimage is treated as (0,0,0).\n    The periodic translation is KEPT - it is the whole point of the torus\n    graph, so it must not be discarded when building topology graphs.\n    """\n    edges: list[tuple] = []\n    for u, v, data in sg.graph.edges(data=True):\n        from_j = data.get("from_jimage")\n        to_j = data.get("to_jimage")\n        if from_j is None:\n            from_j = (0, 0, 0)\n        if to_j is None:\n            to_j = (0, 0, 0)\n        shift = (int(to_j[0]) - int(from_j[0]),\n                 int(to_j[1]) - int(from_j[1]),\n                 int(to_j[2]) - int(from_j[2]))\n        edges.append((int(u), int(v), shift))\n    return edges\n\n\ndef build_periodic_torus_graph(num_sites: int, periodic_edges: list[tuple],\n                               replication: int = PERIODIC_GRAPH_REPLICATION) -> nx.Graph:\n    """3x3x3 periodic torus graph (GRAPH REPRESENTATION ONLY).\n\n    Nodes are (site_index, ia, ib, ic) - one node per (site, torus cell), so\n    the total node count is num_sites * replication**3. Every periodic edge\n    (u, v, shift) is replicated into every torus cell R as\n        (u, R) - (v, (R + shift) mod replication),\n    so periodic boundaries wrap around and there is no finite-supercell\n    surface artifact. This graph is never saved as a structure and is never\n    used to generate a candidate/supercell structure.\n    """\n    graph = nx.Graph()\n    for i in range(num_sites):\n        for ia in range(replication):\n            for ib in range(replication):\n                for ic in range(replication):\n                    graph.add_node((i, ia, ib, ic))\n    for u, v, shift in periodic_edges:\n        sa, sb, sc = (int(x) for x in shift)\n        for ia in range(replication):\n            for ib in range(replication):\n                for ic in range(replication):\n                    va = (ia + sa) % replication\n                    vb = (ib + sb) % replication\n                    vc = (ic + sc) % replication\n                    graph.add_edge((u, ia, ib, ic), (v, va, vb, vc))\n    return graph\n\n\ndef remove_site_index_images(graph, site_indices) -> nx.Graph:\n    """Return a copy of the torus graph with ALL periodic images of the given\n    original site indices deleted (e.g. removing Zn site 3 removes the 27\n    nodes (3, ia, ib, ic))."""\n    removed = graph.copy()\n    removed_set = set(int(i) for i in site_indices)\n    removed.remove_nodes_from([n for n in removed.nodes if n[0] in removed_set])\n    return removed\n\n\ndef component_retention_fraction(pristine_graph, current_graph) -> float:\n    """Pristine-relative connectivity retention metric.\n\n    For every PRISTINE connected component C:\n        remaining_C = C intersect current_graph.nodes (skipped when empty);\n        largest_descendant_C = size of the largest connected component of\n        current_graph.subgraph(remaining_C).\n    component_retention_fraction = sum(largest_descendant_C)\n                                   / sum(len(remaining_C)).\n\n    1.0  -> every pristine component fully retains its internal connectivity\n            (a pristine 1D/2D/multi-component crystal scores 1.0 when the\n            removal breaks nothing);\n    <1.0 -> at least one pristine component was fragmented by the removal.\n    Always in [0, 1]; returns 1.0 (vacuous) when no pristine nodes remain.\n    """\n    numerator = 0\n    denominator = 0\n    current_nodes = set(current_graph.nodes)\n    for comp in nx.connected_components(pristine_graph):\n        remaining = [n for n in comp if n in current_nodes]\n        if not remaining:\n            continue\n        sub = current_graph.subgraph(remaining)\n        largest = max((len(c) for c in nx.connected_components(sub)), default=0)\n        numerator += largest\n        denominator += len(remaining)\n    if denominator == 0:\n        return 1.0\n    return float(numerator) / float(denominator)\n\n\ndef graph_from_structure(structure) -> tuple:\n    """Return (periodic torus graph, method, periodic_edge_count).\n\n    Primary strategy: CrystalNN. If CrystalNN raises OR returns a degenerate\n    graph (zero periodic edges, i.e. no valid bond topology), MinimumDistanceNN\n    is tried as a DESCRIPTIVE fallback; candidates whose core graph needs the\n    fallback are capped at UNRESOLVED by the classification logic and can\n    never reach STRUCTURALLY_PLAUSIBLE. The returned graph is the 3x3x3\n    periodic torus graph built with the jimage translations preserved.\n    """\n    periodic_edges: list[tuple] = []\n    method = "CRYSTALNN"\n    strategies = (\n        (CrystalNN(), "CRYSTALNN"),\n        (MinimumDistanceNN(), "MINIMUM_DISTANCE_FALLBACK"),\n    )\n    for strategy, strategy_name in strategies:\n        try:\n            sg = StructureGraph.from_local_env_strategy(structure, strategy)\n            periodic_edges = periodic_edges_from_structure_graph(sg)\n        except Exception:  # noqa: BLE001\n            periodic_edges = []\n        if periodic_edges:\n            method = strategy_name\n            break\n    if not periodic_edges:\n        method = "FAILED"\n    graph = build_periodic_torus_graph(len(structure), periodic_edges)\n    return graph, method, len(periodic_edges)\n\n\ndef graph_components_stats(graph, nonzn_site_indices, pristine_graph=None) -> dict:\n    """Component statistics over the nodes ACTUALLY REMAINING in `graph`\n    (i.e. after the relevant site images have been removed).\n\n    absolute_largest_component_fraction = largest remaining component /\n    remaining nodes (DESCRIPTIVE only - it penalizes intrinsically 1D/2D or\n    multi-component periodic crystals, so classification does NOT use it).\n    component_retention_fraction = pristine-relative connectivity retention\n    (the metric the frozen 0.95 gate actually uses; see\n    component_retention_fraction). isolated_nonZn_fraction = isolated\n    remaining non-Zn / remaining non-Zn nodes (non-Zn only). All fractions\n    are always in [0, 1]. For FULL_ZN_REMOVAL the remaining nodes are\n    exactly the remaining non-Zn nodes.\n    """\n    remaining_nodes = list(graph.nodes)\n    nonzn = set(int(i) for i in nonzn_site_indices)\n    remaining_nonzn_nodes = [n for n in remaining_nodes if n[0] in nonzn]\n    components = list(nx.connected_components(graph))\n    component_sizes = sorted([len(c) for c in components], reverse=True)\n    largest = component_sizes[0] if component_sizes else 0\n    isolated = [n for n in remaining_nonzn_nodes if graph.degree(n) == 0]\n    n_remaining = len(remaining_nodes)\n    stats = {\n        "node_count": n_remaining,\n        "component_count": len(components),\n        "largest_component_size": largest,\n        "absolute_largest_component_fraction": (\n            (largest / n_remaining) if n_remaining else 0.0\n        ),\n        "isolated_nonZn_count": len(isolated),\n        "isolated_nonZn_fraction": (\n            (len(isolated) / len(remaining_nonzn_nodes)) if remaining_nonzn_nodes else 0.0\n        ),\n    }\n    if pristine_graph is not None:\n        stats["component_retention_fraction"] = component_retention_fraction(\n            pristine_graph, graph\n        )\n    else:\n        stats["component_retention_fraction"] = None\n    return stats\n\n\ndef charge_status_for_removed(removed_zn_in_cell: int, headroom_min_e_per_cell,\n                              headroom_max_e_per_cell, n_oxi_solutions: int) -> str:\n    """Compare the per-CELL electron requirement of removing Zn (2 electrons\n    per removed Zn site in the crystallographic cell) against the per-cell\n    oxidation headroom bounds. All quantities are electrons per cell."""\n    if (n_oxi_solutions == 0 or headroom_min_e_per_cell is None\n            or headroom_max_e_per_cell is None):\n        return "UNRESOLVED_CHARGE"\n    required = 2 * removed_zn_in_cell\n    if required <= headroom_min_e_per_cell:\n        return "ROBUST_COMMON_CATION_HEADROOM"\n    if required <= headroom_max_e_per_cell:\n        return "POSSIBLE_COMMON_CATION_HEADROOM"\n    return "INSUFFICIENT_COMMON_CATION_HEADROOM"\n\n\ndef compute_headroom_per_solution(oxi_solutions: list, redox_elements: list,\n                                  n_atoms_by_symbol_per_cell: dict) -> tuple:\n    """Per-solution oxidation headroom in ELECTRONS PER CRYSTALLOGRAPHIC CELL.\n\n    For EACH plausible pristine oxidation-state solution and EACH redox-active\n    element (frozen definition: non-Zn transition metals only): contribution =\n    n_atoms_per_cell * (max_allowed_state - guessed_state), counted only when\n    positive. The guessed oxidation state comes from the reduced-composition\n    solution, but n_atoms MUST be the full-cell element count so the result\n    is electrons per cell (same unit as 2 * removed_Zn_sites_in_cell).\n    Allowed states are Element.common_oxidation_states; Element.oxidation_states\n    is used only when the common list is empty (rare_oxidation_fallback_used =\n    True). Solutions are never averaged and elements are never mixed across\n    solutions. Returns (headroom_per_solution_e_per_cell, min_e_per_cell,\n    max_e_per_cell, rare_fallback_used).\n    """\n    headrooms: list[float] = []\n    rare_fallback_used = False\n    for solution in oxi_solutions:\n        by_symbol = {str(k): v for k, v in solution.items()}\n        total_headroom = 0.0\n        for el in redox_elements:\n            guess = by_symbol.get(el.symbol)\n            if guess is None:\n                continue\n            common = el.common_oxidation_states\n            if common:\n                allowed = common\n            else:\n                allowed = el.oxidation_states\n                rare_fallback_used = True\n            higher = [s for s in allowed if s > guess]\n            if higher:\n                n_atoms = float(n_atoms_by_symbol_per_cell.get(el.symbol, 0.0))\n                total_headroom += n_atoms * (max(higher) - guess)\n        headrooms.append(total_headroom)\n    if not headrooms:\n        return [], None, None, rare_fallback_used\n    return headrooms, float(min(headrooms)), float(max(headrooms)), rare_fallback_used\n\n\ndef build_oxi_overrides(present_symbols) -> dict:\n    """Fixed oxidation states in the exact format required by pymatgen\n    Composition.oxi_state_guesses: dict[str, list[float]] (e.g.\n    {"V": [2, 3, 4, 5]}). Fixed states are passed as single-element lists and\n    restricted to the elements present in the composition."""\n    return {\n        sym: [float(FIXED_OXI_OVERRIDES[sym])]\n        for sym in FIXED_OXI_OVERRIDES\n        if sym in present_symbols\n    }\n\n\ndef map_zn_orbits(symmetrized, zn_site_indices: list[int]) -> list[dict]:\n    """Group Zn sites into crystallographic orbits by the equivalent-indices\n    GROUP INDEX (never by site index). The Wyckoff symbol is read at the\n    GROUP index of the equivalent-indices list. Returns orbit dicts with\n    equivalent_group_index, equivalent_group_size, equivalent_site_indices,\n    multiplicity, wyckoff_symbol and zn_orbit_id."""\n    equiv = symmetrized.equivalent_indices\n    w_symbols = getattr(symmetrized, "wyckoff_symbols", None)\n    zn_set = set(int(i) for i in zn_site_indices)\n    orbit_map: dict[int, list[int]] = {}\n    for group_idx, group in enumerate(equiv):\n        zn_in_group = sorted(idx for idx in group if idx in zn_set)\n        if zn_in_group:\n            orbit_map[group_idx] = zn_in_group\n    orbits: list[dict] = []\n    for group_idx in sorted(orbit_map):\n        group_sites = orbit_map[group_idx]\n        if w_symbols is not None and len(w_symbols) == len(equiv):\n            # pymatgen >= 2024 (incl. 2026.5.4): wyckoff_symbols is per GROUP\n            w_symbol = str(w_symbols[group_idx])\n        elif w_symbols is not None:\n            # defensive per-site list fallback (value identical across group)\n            w_symbol = str(w_symbols[min(group_sites)])\n        else:\n            w_symbol = ""\n        orbits.append(\n            {\n                "zn_orbit_id": f"Zn{len(orbits) + 1}",\n                "equivalent_group_index": group_idx,\n                "equivalent_group_size": len(equiv[group_idx]),\n                "equivalent_site_indices": sorted(group_sites),\n                "multiplicity": len(group_sites),\n                "wyckoff_symbol": w_symbol,\n            }\n        )\n    return orbits\n\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\ndef main() -> int:\n    overall_started = time.perf_counter()\n    log("Phase 21B - structure-level de-zincation feasibility analysis (offline)")\n\n    if not DEPENDENCIES_AVAILABLE:\n        log("ERROR: required packages missing. Install: pip install pymatgen networkx "\n            "numpy pandas")\n        return 1\n\n    # ---- 1. frozen Phase 21A inputs ---------------------------------------------\n    # Every failure below is a CRITICAL INPUT/PROVENANCE FAILURE: recorded to\n    # phase21b_failures.csv and followed by return 1 (hard abort). None of\n    # these ever becomes UNRESOLVED or proceeds to classification.\n    provenance_failures: list[dict] = []\n\n    def record_provenance_failure(material_id: str, stage: str, message: str) -> None:\n        provenance_failures.append(\n            {"material_id": material_id, "failure_stage": stage,\n             "failure_message": message}\n        )\n\n    if not IN_MANIFEST.is_file():\n        return write_failures_and_abort(\n            [{"material_id": "manifest", "failure_stage": "manifest_file",\n              "failure_message": f"required input not found: {IN_MANIFEST}"}],\n            "manifest file missing",\n        )\n    try:\n        manifest = pd.read_csv(IN_MANIFEST, low_memory=False)\n    except Exception as exc:  # noqa: BLE001\n        return write_failures_and_abort(\n            [{"material_id": "manifest", "failure_stage": "manifest_read",\n              "failure_message": f"{type(exc).__name__}: {exc}"}],\n            "manifest unreadable",\n        )\n    if len(manifest) != 13:\n        record_provenance_failure(\n            "manifest", "manifest_rows",\n            f"manifest must have exactly 13 rows; found {len(manifest)}")\n        return write_failures_and_abort(provenance_failures, "manifest row count mismatch")\n    if not bool(manifest["material_id"].is_unique):\n        record_provenance_failure(\n            "manifest", "manifest_identity", "manifest material_id is not unique")\n        return write_failures_and_abort(provenance_failures, "manifest material_id not unique")\n    missing_cols = [c for c in REQUIRED_MANIFEST_COLUMNS if c not in manifest.columns]\n    if missing_cols:\n        record_provenance_failure(\n            "manifest", "manifest_columns",\n            f"manifest missing required column(s): {missing_cols}")\n        return write_failures_and_abort(provenance_failures, "manifest columns missing")\n    actual_priorities = manifest["phase20_priority_order"].astype(int).tolist()\n    if actual_priorities != list(range(1, 14)):\n        record_provenance_failure(\n            "manifest", "manifest_priority_order",\n            f"manifest priority order must be exactly 1..13; got {actual_priorities}")\n        return write_failures_and_abort(provenance_failures, "manifest priority order mismatch")\n    for i, (priority, vrank, material_id, formula) in enumerate(EXPECTED_FINALISTS):\n        row = manifest.iloc[i]\n        if (\n            int(row["phase20_priority_order"]) != priority\n            or int(row["verification_rank"]) != vrank\n            or row["material_id"] != material_id\n            or row["formula_phase20"] != formula\n        ):\n            record_provenance_failure(\n                material_id, "manifest_identity",\n                f"manifest row {i + 1} mismatch vs frozen Phase 20 order "\n                f"(expected priority={priority}, verification_rank={vrank}, "\n                f"material_id={material_id}, formula={formula})")\n    if provenance_failures:\n        return write_failures_and_abort(provenance_failures, "manifest identity/order mismatch")\n    log("manifest freeze QA passed (13 rows, exact frozen order)")\n\n    # ---- 2. per-candidate frozen-file re-verification -------------------------------\n    # Any failure below is a CRITICAL INPUT/PROVENANCE FAILURE (hard abort at the\n    # end of this section) - the affected candidate is never analyzed and never\n    # marked UNRESOLVED.\n    candidates: list[dict] = []\n    for i, (priority, vrank, material_id, formula) in enumerate(EXPECTED_FINALISTS):\n        row = manifest.iloc[i]\n        rec = {\n            "phase20_priority_order": priority,\n            "verification_rank": vrank,\n            "material_id": material_id,\n            "formula_pretty": formula,\n            "manifest_row": row,\n            "json_path": JSON_DIR / row["json_filename"],\n            "cif_path": CIF_DIR / row["cif_filename"],\n        }\n        ok = True\n        if not rec["json_path"].is_file():\n            record_provenance_failure(material_id, "json_file",\n                                      f"missing {rec[\'json_path\'].name}")\n            ok = False\n        if not rec["cif_path"].is_file():\n            record_provenance_failure(material_id, "cif_file",\n                                      f"missing {rec[\'cif_path\'].name}")\n            ok = False\n        try:\n            qa_pass = manifest_bool(row["overall_structure_QA_pass"])\n            if not qa_pass:\n                record_provenance_failure(material_id, "manifest_qa",\n                                          "overall_structure_QA_pass is not True")\n                ok = False\n        except ValueError as exc:\n            record_provenance_failure(material_id, "manifest_qa",\n                                      f"unparseable overall_structure_QA_pass: {exc}")\n            ok = False\n        try:\n            drift_flag = manifest_bool(row["historical_structure_drift_flag"])\n            if drift_flag:\n                record_provenance_failure(material_id, "manifest_drift",\n                                          "historical_structure_drift_flag is True")\n                ok = False\n        except ValueError as exc:\n            record_provenance_failure(material_id, "manifest_drift",\n                                      f"unparseable historical_structure_drift_flag: {exc}")\n            ok = False\n        if not ok:\n            continue\n\n        json_bytes = rec["json_path"].read_bytes()\n        cif_bytes = rec["cif_path"].read_bytes()\n        if sha256_of_bytes(json_bytes) != row["json_file_sha256"]:\n            record_provenance_failure(material_id, "json_hash",\n                                      "json_file_sha256 mismatch")\n            ok = False\n        if sha256_of_bytes(cif_bytes) != row["cif_file_sha256"]:\n            record_provenance_failure(material_id, "cif_hash",\n                                      "cif_file_sha256 mismatch")\n            ok = False\n        try:\n            structure = Structure.from_dict(json.loads(json_bytes.decode("utf-8")))\n        except Exception as exc:  # noqa: BLE001\n            record_provenance_failure(material_id, "json_parse",\n                                      f"{type(exc).__name__}: {exc}")\n            ok = False\n        if not ok:\n            continue\n        if sha256_of_bytes(canonical_structure_json(structure).encode("utf-8")) != row["structure_json_sha256"]:\n            record_provenance_failure(material_id, "structure_hash",\n                                      "structure_json_sha256 mismatch")\n            ok = False\n        if int(structure.num_sites) != int(row["structure_num_sites"]):\n            record_provenance_failure(\n                material_id, "nsites",\n                f"num_sites {structure.num_sites} != manifest {row[\'structure_num_sites\']}")\n            ok = False\n        contains_zn = any(\n            el.symbol == "Zn" for site in structure for el in site.species\n        )\n        if not contains_zn:\n            record_provenance_failure(material_id, "zn_check",\n                                      "structure does not contain Zn")\n            ok = False\n        if ok:\n            rec["structure"] = structure\n            candidates.append(rec)\n        else:\n            log(f"  {material_id}: frozen-file verification FAILED")\n\n    if provenance_failures:\n        return write_failures_and_abort(\n            provenance_failures,\n            "frozen Phase21A input/provenance re-verification failed",\n        )\n    log(f"frozen-file re-verification passed: {len(candidates)}/13 candidates (hashes + identity)")\n\n    OUT_DIR.mkdir(parents=True, exist_ok=True)\n\n    # ---- 3. analysis structures -----------------------------------------------------\n    inventory_rows: list[dict] = []\n    topology_rows: list[dict] = []\n    state_rows: list[dict] = []\n    oxi_rows: list[dict] = []\n    assessment_rows: list[dict] = []\n    qa_rows: list[dict] = []\n\n    for rec in candidates:\n        material_id = rec["material_id"]\n        formula = rec["formula_pretty"]\n        priority = rec["phase20_priority_order"]\n        structure = rec["structure"]\n        log(f"analyzing [{priority}/13] {material_id} ({formula}) ...")\n\n        qa: dict = {k: True for k in (\n            "input_hash_pass", "manifest_identity_pass", "structure_nsites_pass",\n            "contains_Zn_pass", "symmetry_analysis_pass", "ordered_structure_pass",\n            "Zn_site_inventory_pass", "CrystalNN_graph_pass",\n            "partial_state_generation_pass", "oxidation_state_analysis_pass",\n            "fractional_selection_uses_farthest_helper_pass",\n            "classification_complete", "overall_phase21b_QA_pass",\n        )}\n        risk_flags: list[str] = []\n        unresolved_reason: list[str] = []\n\n        # ---- symmetry (frozen parameters) -----------------------------------------\n        symmetry_warning = False\n        try:\n            spg = SpacegroupAnalyzer(structure, symprec=SYMPREC, angle_tolerance=ANGLE_TOLERANCE)\n            detected_sg_number = int(spg.get_space_group_number())\n            detected_sg_symbol = spg.get_space_group_symbol()\n            symmetrized = spg.get_symmetrized_structure()\n        except Exception as exc:  # noqa: BLE001\n            qa["symmetry_analysis_pass"] = False\n            risk_flags.append("SYMMETRY_ANALYSIS_FAILED")\n            unresolved_reason.append(f"symmetry analysis failed: {type(exc).__name__}")\n            symmetrized = None\n            detected_sg_number = None\n            detected_sg_symbol = None\n            symmetry_warning = True\n        manifest_sg_number = rec["manifest_row"]["spacegroup_number_api"]\n        manifest_sg_number_val = (\n            int(float(manifest_sg_number)) if pd.notna(manifest_sg_number) else None\n        )\n        if (\n            detected_sg_number is not None\n            and manifest_sg_number_val is not None\n            and detected_sg_number != manifest_sg_number_val\n        ):\n            symmetry_warning = True\n            risk_flags.append("PHASE21B_SYMMETRY_WARNING")\n            unresolved_reason.append(\n                f"detected SG {detected_sg_number} != manifest SG {manifest_sg_number_val}"\n            )\n\n        # ---- ordering / mixed occupancy -------------------------------------------\n        ordered = bool(structure.is_ordered)\n        if not ordered:\n            qa["ordered_structure_pass"] = False\n            risk_flags.append("DISORDERED_STRUCTURE")\n            unresolved_reason.append("structure is disordered")\n\n        # ---- Zn site inventory ------------------------------------------------------\n        zn_site_indices = [\n            i for i, site in enumerate(structure)\n            if any(el.symbol == "Zn" for el in site.species)\n        ]\n        total_zn_sites = len(zn_site_indices)\n        if total_zn_sites == 0:\n            qa["Zn_site_inventory_pass"] = False\n            qa["contains_Zn_pass"] = False\n            unresolved_reason.append("no Zn sites found")\n        mixed_zn = False\n        for i in zn_site_indices:\n            site = structure[i]\n            if len(site.species) != 1 or site.species.num_atoms < 0.999999:\n                mixed_zn = True\n        if mixed_zn:\n            qa["Zn_site_inventory_pass"] = False\n            risk_flags.append("MIXED_OR_PARTIAL_ZN_OCCUPANCY")\n            unresolved_reason.append("mixed or partial Zn occupancy")\n\n        # ---- inequivalent Zn orbits (equivalent-indices GROUP mapping) -------------------\n        orbits: list[dict] = []\n        if symmetrized is not None and total_zn_sites > 0:\n            try:\n                raw_orbits = map_zn_orbits(symmetrized, zn_site_indices)\n                orbit_union = (\n                    set().union(*(set(o["equivalent_site_indices"]) for o in raw_orbits))\n                    if raw_orbits else set()\n                )\n                if orbit_union != set(zn_site_indices):\n                    qa["Zn_site_inventory_pass"] = False\n                    risk_flags.append("ZN_ORBIT_MAPPING_INCOMPLETE")\n                    unresolved_reason.append(\n                        "Zn orbit mapping incomplete: union of orbit indices != all Zn sites")\n                for orbit in raw_orbits:\n                    if orbit["multiplicity"] != orbit["equivalent_group_size"]:\n                        qa["Zn_site_inventory_pass"] = False\n                        risk_flags.append("ZN_ORBIT_PARTIAL_WYCKOFF_GROUP")\n                        unresolved_reason.append(\n                            f"orbit {orbit[\'zn_orbit_id\']} covers only "\n                            f"{orbit[\'multiplicity\']} of "\n                            f"{orbit[\'equivalent_group_size\']} equivalent sites")\n                    rep = min(orbit["equivalent_site_indices"])\n                    rep_site = structure[rep]\n                    orbit.update(\n                        {\n                            "representative_site_index": rep,\n                            "Zn_occupancy": float(rep_site.species.num_atoms),\n                            "fraction_of_total_Zn": orbit["multiplicity"] / total_zn_sites,\n                            "representative_frac_coords": list(rep_site.frac_coords),\n                        }\n                    )\n                    orbits.append(orbit)\n            except Exception as exc:  # noqa: BLE001\n                qa["Zn_site_inventory_pass"] = False\n                risk_flags.append("ZN_ORBIT_MAPPING_FAILED")\n                unresolved_reason.append(f"orbit mapping failed: {type(exc).__name__}")\n        n_inequivalent_zn = len(orbits)\n\n        # ---- coordination + bond graph (3x3x3 periodic torus) ------------------------------\n        try:\n            graph, graph_method, periodic_edge_count = graph_from_structure(structure)\n            crystalnn_ok = graph_method == "CRYSTALNN"\n        except Exception as exc:  # noqa: BLE001\n            qa["CrystalNN_graph_pass"] = False\n            risk_flags.append("GRAPH_CONSTRUCTION_FAILED")\n            unresolved_reason.append(f"bond graph construction failed: {type(exc).__name__}")\n            graph = nx.Graph()\n            graph_method = "FAILED"\n            periodic_edge_count = 0\n            crystalnn_ok = False\n        if not crystalnn_ok:\n            qa["CrystalNN_graph_pass"] = False\n            risk_flags.append("CRYSTALNN_FALLBACK_USED")\n            unresolved_reason.append(\n                "core bond graph used MinimumDistanceNN fallback or CrystalNN "\n                "returned a degenerate graph (no valid bond topology)")\n        if graph_method == "MINIMUM_DISTANCE_FALLBACK":\n            unresolved_reason.append(\n                "CrystalNN periodic graph degenerate -> MinimumDistanceNN fallback; "\n                "fallback can never reach STRUCTURALLY_PLAUSIBLE")\n\n        # coordination per orbit representative\n        nn_strategy = None\n        try:\n            nn_strategy = CrystalNN() if crystalnn_ok else MinimumDistanceNN()\n        except Exception:  # noqa: BLE001\n            nn_strategy = None\n        coordination_method = "CRYSTALNN" if crystalnn_ok else "MINIMUM_DISTANCE_FALLBACK"\n\n        for orbit in orbits:\n            rep = orbit["representative_site_index"]\n            weighted_cn = 0.0\n            neighbor_counts: dict[str, int] = {}\n            distances: list[float] = []\n            coordination_warning_count = 0\n            try:\n                nn_info = nn_strategy.get_nn_info(structure, n=rep)\n                for entry in nn_info:\n                    weighted_cn += float(entry.get("weight", 1.0))\n                    # Never fake a missing neighbor as the representative site\n                    # itself (that would invent 0-distance self neighbors).\n                    neighbor_site = entry.get("site")\n                    if neighbor_site is None:\n                        coordination_warning_count += 1\n                        continue\n                    for el in neighbor_site.species:\n                        neighbor_counts[el.symbol] = neighbor_counts.get(el.symbol, 0) + 1\n                    # Distance resolution (never fabricate a self-neighbor):\n                    # 1) primary: cartesian norm from the actual periodic\n                    #    neighbor PeriodicSite position (image already applied);\n                    # 2) base site_index + periodic image via\n                    #    get_distance(rep, base_index, jimage=image);\n                    # 3) last resort: plain get_distance(rep, base_index);\n                    # otherwise skip this neighbor and count a warning.\n                    distance = None\n                    try:\n                        distance = float(\n                            np.linalg.norm(neighbor_site.coords - structure[rep].coords)\n                        )\n                    except Exception:  # noqa: BLE001\n                        distance = None\n                    if distance is None:\n                        base_index = entry.get("site_index", entry.get("index"))\n                        if base_index is None:\n                            coordination_warning_count += 1\n                        else:\n                            image = entry.get("image")\n                            if image is not None:\n                                try:\n                                    distance = float(\n                                        structure.get_distance(\n                                            rep, int(base_index), jimage=image\n                                        )\n                                    )\n                                except Exception:  # noqa: BLE001\n                                    distance = None\n                            if distance is None:\n                                try:\n                                    distance = float(\n                                        structure.get_distance(rep, int(base_index))\n                                    )\n                                except Exception:  # noqa: BLE001\n                                    coordination_warning_count += 1\n                                    distance = None\n                    if distance is not None:\n                        distances.append(distance)\n            except Exception:  # noqa: BLE001\n                pass\n            orbit.update(\n                {\n                    "weighted_CN": weighted_cn,\n                    "neighbor_count": sum(neighbor_counts.values()),\n                    "neighbor_element_counts": json.dumps(neighbor_counts, sort_keys=True),\n                    "mean_distance": float(np.mean(distances)) if distances else None,\n                    "min_distance": float(np.min(distances)) if distances else None,\n                    "max_distance": float(np.max(distances)) if distances else None,\n                    "coordination_warning_count": coordination_warning_count,\n                }\n            )\n\n        # ---- pristine-graph Zn removal statistics (torus images) -----------------------------\n        nonzn_site_indices = [\n            i for i in range(len(structure)) if i not in set(zn_site_indices)\n        ]\n        # Articulation points are torus nodes (site, ia, ib, ic). Because the\n        # torus graph is translation-invariant, all 27 images of a site share\n        # the same articulation status, so the per-SITE semantics of the frozen\n        # FRAMEWORK_ARTICULATION_MIN heuristic is preserved.\n        articulation_site_indices = (\n            {n[0] for n in nx.articulation_points(graph)}\n            if graph.number_of_nodes() else set()\n        )\n\n        full_removed_graph = remove_site_index_images(graph, zn_site_indices)\n        nonzn_stats = graph_components_stats(\n            full_removed_graph, nonzn_site_indices, pristine_graph=graph\n        )\n\n        zn_articulation_count = len(articulation_site_indices & set(zn_site_indices))\n        zn_articulation_fraction = (\n            zn_articulation_count / total_zn_sites if total_zn_sites else 0.0\n        )\n\n        # ---- per-orbit removal + role heuristic ---------------------------------------------\n        n_guest = 0\n        n_framework = 0\n        n_ambiguous = 0\n        for orbit in orbits:\n            orbit_indices = orbit["equivalent_site_indices"]\n            removed_graph = remove_site_index_images(graph, orbit_indices)\n            stats = graph_components_stats(\n                removed_graph, nonzn_site_indices, pristine_graph=graph\n            )\n            articulation_count = len(articulation_site_indices & set(orbit_indices))\n            articulation_fraction = (\n                articulation_count / len(orbit_indices) if orbit_indices else 0.0\n            )\n            retention_frac = stats["component_retention_fraction"]\n            isolated_frac = stats["isolated_nonZn_fraction"]\n            if (\n                articulation_fraction < 1e-12\n                and retention_frac >= GUEST_ORBIT_RETENTION_MIN\n                and isolated_frac <= GUEST_ORBIT_ISOLATED_MAX\n            ):\n                role = "GUEST_LIKE_HINT"\n                n_guest += 1\n                reason = "no articulation; pristine connectivity retained after orbit removal"\n            elif (\n                articulation_fraction >= FRAMEWORK_ARTICULATION_MIN\n                or retention_frac < FRAMEWORK_ORBIT_RETENTION_MAX\n                or isolated_frac > FRAMEWORK_ORBIT_ISOLATED_MIN\n            ):\n                role = "FRAMEWORK_LIKE_HINT"\n                n_framework += 1\n                reason = "Zn bridges framework connectivity (articulation/pristine-component fragmentation/isolated non-Zn)"\n            else:\n                role = "MIXED_OR_AMBIGUOUS_HINT"\n                n_ambiguous += 1\n                reason = "mixed topology evidence"\n            orbit.update(\n                {\n                    "zn_articulation_count": articulation_count,\n                    "zn_articulation_fraction": articulation_fraction,\n                    "orbit_removal_component_count": stats["component_count"],\n                    "orbit_removal_largest_component_fraction": stats["absolute_largest_component_fraction"],\n                    "orbit_removal_component_retention_fraction": retention_frac,\n                    "site_role_hint": role,\n                    "site_role_reason": reason,\n                }\n            )\n            # inventory row\n            inventory_rows.append(\n                {\n                    "phase20_priority_order": priority,\n                    "verification_rank": rec["verification_rank"],\n                    "material_id": material_id,\n                    "formula_pretty": formula,\n                    "spacegroup_number": detected_sg_number,\n                    "total_Zn_sites": total_zn_sites,\n                    "n_inequivalent_Zn_sites": n_inequivalent_zn,\n                    "zn_orbit_id": orbit["zn_orbit_id"],\n                    "representative_site_index": orbit["representative_site_index"],\n                    "equivalent_group_index": orbit["equivalent_group_index"],\n                    "equivalent_group_size": orbit["equivalent_group_size"],\n                    "equivalent_site_indices": json.dumps(orbit["equivalent_site_indices"]),\n                    "multiplicity": orbit["multiplicity"],\n                    "wyckoff_symbol": orbit["wyckoff_symbol"],\n                    "fraction_of_total_Zn": orbit["fraction_of_total_Zn"],\n                    "Zn_occupancy": orbit["Zn_occupancy"],\n                    "coordination_method": coordination_method,\n                    "weighted_CN": orbit["weighted_CN"],\n                    "neighbor_count": orbit["neighbor_count"],\n                    "neighbor_element_counts": orbit["neighbor_element_counts"],\n                    "mean_Zn_neighbor_distance_A": orbit["mean_distance"],\n                    "min_Zn_neighbor_distance_A": orbit["min_distance"],\n                    "max_Zn_neighbor_distance_A": orbit["max_distance"],\n                    "coordination_warning_count": orbit["coordination_warning_count"],\n                    "zn_articulation_fraction": orbit["zn_articulation_fraction"],\n                    "orbit_removal_component_count": orbit["orbit_removal_component_count"],\n                    "orbit_removal_largest_component_fraction": orbit["orbit_removal_largest_component_fraction"],\n                    "orbit_removal_component_retention_fraction": orbit["orbit_removal_component_retention_fraction"],\n                    "site_role_hint": orbit["site_role_hint"],\n                    "site_role_reason": orbit["site_role_reason"],\n                }\n            )\n\n        # ---- oxidation-state sanity check -------------------------------------------------\n        # The frozen fixed oxidation states are ACTUALLY constrained inside the\n        # pymatgen solver via oxi_states_override in the format\n        # dict[str, list[float]] (fixed states as single-element lists,\n        # restricted to elements present in this composition) - NOT assumed\n        # after the fact in text. Guessing runs on the REDUCED composition.\n        composition_reduced = structure.composition.reduced_composition\n        cell_composition = structure.composition\n        present_symbols = {el.symbol for el in composition_reduced.elements}\n        # Frozen scientific definition: redox-active reservoir = non-Zn\n        # transition metals ONLY (main-group elements are never auto-added).\n        redox_elements = [\n            el for el in composition_reduced.elements\n            if el.symbol != "Zn" and bool(getattr(el, "is_transition_metal", False))\n        ]\n        overrides_applied = build_oxi_overrides(present_symbols)\n        oxi_solutions = []\n        try:\n            oxi_solutions = composition_reduced.oxi_state_guesses(\n                oxi_states_override=overrides_applied,\n                target_charge=0,\n                all_oxi_states=False,\n            )\n        except Exception as exc:  # noqa: BLE001\n            risk_flags.append("OXI_GUESS_FAILED")\n            unresolved_reason.append(f"oxidation-state guess failed: {type(exc).__name__}")\n        n_oxi_solutions = len(oxi_solutions)\n\n        headroom_per_solution_e_per_cell: list[float] = []\n        headroom_min_e_per_cell = None\n        headroom_max_e_per_cell = None\n        rare_fallback_used = False\n        cell_n_atoms_by_symbol: dict[str, float] = {}\n        if n_oxi_solutions > 0 and redox_elements:\n            # headroom n_atoms come from the FULL crystallographic cell so the\n            # result is electrons PER CELL - the same unit as 2 * removed Zn\n            # sites in the cell. (Guessed oxidation states stay per reduced\n            # formula unit; only the atom counts are cell-scaled.)\n            cell_n_atoms_by_symbol = {\n                el.symbol: float(cell_composition[el])\n                for el in cell_composition.elements\n            }\n            (headroom_per_solution_e_per_cell, headroom_min_e_per_cell,\n             headroom_max_e_per_cell, rare_fallback_used) = compute_headroom_per_solution(\n                oxi_solutions, redox_elements, cell_n_atoms_by_symbol\n            )\n        if n_oxi_solutions == 0:\n            qa["oxidation_state_analysis_pass"] = False\n            risk_flags.append("NO_OXIDATION_SOLUTION")\n            unresolved_reason.append("no composition oxidation-state solution found")\n\n        # ---- de-zincation proxy states ------------------------------------------------------\n        states: list[dict] = []\n\n        def make_state(state_id, state_type, removed_indices, removed_orbits, target_fraction):\n            removed_indices = sorted(set(int(i) for i in removed_indices))\n            # Delete ALL 27 periodic images of each removed Zn site index.\n            removed_graph = remove_site_index_images(graph, removed_indices)\n            stats = graph_components_stats(\n                removed_graph, nonzn_site_indices, pristine_graph=graph\n            )\n            # topology gate uses the PRISTINE-RELATIVE retention metric\n            # (0.95 frozen threshold), not the absolute largest component.\n            topology_pass = bool(\n                stats["component_retention_fraction"] >= TOPO_RETENTION_MIN\n                and stats["isolated_nonZn_fraction"] <= TOPO_ISOLATED_MAX\n            )\n            # Electrons per CELL (2 per removed Zn site in the cell) - same\n            # unit as the per-cell oxidation headroom.\n            required_electrons_per_cell = 2 * len(removed_indices)\n            charge_status = charge_status_for_removed(\n                len(removed_indices),\n                headroom_min_e_per_cell, headroom_max_e_per_cell, n_oxi_solutions,\n            )\n            states.append(\n                {\n                    "material_id": material_id,\n                    "state_id": state_id,\n                    "state_type": state_type,\n                    "removed_Zn_site_indices": json.dumps(removed_indices),\n                    "removed_Zn_orbits": removed_orbits,\n                    "total_Zn_before": total_zn_sites,\n                    "Zn_removed": len(removed_indices),\n                    "Zn_remaining": total_zn_sites - len(removed_indices),\n                    "target_removed_fraction": target_fraction,\n                    "actual_removed_fraction": (\n                        len(removed_indices) / total_zn_sites if total_zn_sites else 0.0\n                    ),\n                    "remaining_formula_unrelaxed": remaining_formula_after_removal(structure, removed_indices),\n                    "remaining_node_count": stats["node_count"],\n                    "component_count": stats["component_count"],\n                    # descriptive absolute metric (NOT the classification gate)\n                    "absolute_largest_component_fraction": stats["absolute_largest_component_fraction"],\n                    # legacy alias of the ABSOLUTE metric - kept only for\n                    # backward compatibility; it is NOT a retention metric\n                    "largest_component_fraction": stats["absolute_largest_component_fraction"],\n                    # pristine-relative metric used by topology_pass\n                    "component_retention_fraction": stats["component_retention_fraction"],\n                    "isolated_nonZn_count": stats["isolated_nonZn_count"],\n                    "isolated_nonZn_fraction": stats["isolated_nonZn_fraction"],\n                    "topology_pass": topology_pass,\n                    "required_electron_removal_per_cell": required_electrons_per_cell,\n                    "oxidation_headroom_min_e_per_cell": headroom_min_e_per_cell,\n                    "oxidation_headroom_max_e_per_cell": headroom_max_e_per_cell,\n                    "charge_balance_status": charge_status,\n                }\n            )\n\n        # A. symmetry-orbit removal combinations\n        orbit_sets = [tuple(sorted(o["equivalent_site_indices"])) for o in orbits]\n        n_orbits = len(orbit_sets)\n        if n_orbits <= 4:\n            combos = []\n            for r in range(1, n_orbits):\n                for combo in _combinations(range(n_orbits), r):\n                    combos.append(combo)\n        else:\n            combos = [(i,) for i in range(n_orbits)] + [\n                (i, j) for i in range(n_orbits) for j in range(i + 1, n_orbits)\n            ]\n        seen_state_sets: set[frozenset] = set()\n        for combo in combos:\n            removed = [idx for k in combo for idx in orbit_sets[k]]\n            key = frozenset(removed)\n            if key in seen_state_sets:\n                continue\n            seen_state_sets.add(key)\n            orbit_ids = ",".join(orbits[k]["zn_orbit_id"] for k in combo)\n            make_state(\n                f"SYM_ORBIT_{orbit_ids}",\n                "SYMMETRY_ORBIT_REMOVAL",\n                removed,\n                orbit_ids,\n                len(removed) / total_zn_sites if total_zn_sites else 0.0,\n            )\n\n        # B. deterministic fractional vacancy proxies (25/50/75%)\n        #    All three target fractions are generated and saved whenever they\n        #    are representable in this cell, and every one of them is selected\n        #    by deterministic_farthest_selection (maximin, periodic\n        #    minimum-image, first vacancy = smallest Zn site index). The 75%\n        #    state is excluded from the Step-2 partial gate only because its\n        #    actual_removed_fraction exceeds the 0.50 cap - it is still saved.\n        farthest_calls_before = FARTHEST_SELECTION_CALLS["count"]\n        for target_fraction in (0.25, 0.50, 0.75):\n            removed, _ = generate_fractional_vacancy_sites(\n                structure, zn_site_indices, target_fraction\n            )\n            if removed is None:\n                log(f"    {target_fraction:.2f} fractional proxy not representable "\n                    f"in this cell ({total_zn_sites} Zn site(s)); state skipped")\n                continue\n            make_state(\n                f"FRAC_{int(target_fraction * 100)}",\n                "FRACTIONAL_VACANCY_PROXY",\n                removed,\n                "",\n                target_fraction,\n            )\n        farthest_calls_delta = (\n            FARTHEST_SELECTION_CALLS["count"] - farthest_calls_before\n        )\n        n_fractional_states = sum(\n            1 for s in states if s["state_type"] == "FRACTIONAL_VACANCY_PROXY"\n        )\n        qa["fractional_selection_uses_farthest_helper_pass"] = bool(\n            farthest_calls_delta == n_fractional_states\n        )\n\n        # C. full removal\n        key = frozenset(zn_site_indices)\n        if key not in seen_state_sets:\n            seen_state_sets.add(key)\n        make_state(\n            "FULL_ZN_REMOVAL",\n            "FULL_ZN_REMOVAL",\n            zn_site_indices,\n            "",\n            1.0,\n        )\n\n        if not states:\n            qa["partial_state_generation_pass"] = False\n            risk_flags.append("NO_PROXY_STATES_GENERATED")\n            unresolved_reason.append("no de-zincation proxy states could be generated")\n\n        for state in states:\n            state.update(\n                {\n                    "phase20_priority_order": priority,\n                    "verification_rank": rec["verification_rank"],\n                    "formula_pretty": formula,\n                    "state_structural_sanity": "UNRELAXED_TOPOLOGY_PROXY",\n                    "notes": (\n                        "SYMMETRY_BROKEN_FRACTION_PROXY"\n                        if state["state_type"] == "FRACTIONAL_VACANCY_PROXY"\n                        else (\n                            "FULL_ZN_REMOVAL is NOT assumed to be experimentally accessible"\n                            if state["state_type"] == "FULL_ZN_REMOVAL"\n                            else ""\n                        )\n                    ),\n                }\n            )\n            state_rows.append(state)\n\n        full_state = next(\n            (s for s in states if s["state_type"] == "FULL_ZN_REMOVAL"), None\n        )\n        partial_states = [\n            s for s in states\n            if s["state_type"] != "FULL_ZN_REMOVAL"\n            and s["actual_removed_fraction"] <= PARTIAL_STATE_MAX_FRACTION\n        ]\n        good_partials = [\n            s for s in partial_states\n            if s["topology_pass"] and s["charge_balance_status"] in GOOD_CHARGE_STATUSES\n        ]\n        if good_partials:\n            good_partials.sort(\n                key=lambda s: (\n                    0 if s["charge_balance_status"] == "ROBUST_COMMON_CATION_HEADROOM" else 1,\n                    -s["actual_removed_fraction"],\n                )\n            )\n            best_partial = good_partials[0]\n        elif partial_states:\n            partial_states_sorted = sorted(\n                partial_states, key=lambda s: -s["actual_removed_fraction"]\n            )\n            best_partial = partial_states_sorted[0]\n        else:\n            best_partial = None\n\n        # ---- classification (frozen sequential rules, no weighted score) ----------------------\n        classification = None\n        primary_structural_reason = ""\n        primary_charge_reason = ""\n        if unresolved_reason:\n            classification = "UNRESOLVED"\n            primary_structural_reason = "; ".join(unresolved_reason[:3])\n        elif not good_partials:\n            classification = "HIGH_RECONSTRUCTION_RISK"\n            primary_structural_reason = "no <=50% partial proxy state retains pristine topology with charge headroom"\n        else:\n            full_ok = bool(\n                full_state\n                and full_state["topology_pass"]\n                and full_state["charge_balance_status"] in GOOD_CHARGE_STATUSES\n            )\n            guest_exists = n_guest > 0\n            framework_dominates = n_framework > 0\n            if full_ok and guest_exists and not framework_dominates:\n                classification = "STRUCTURALLY_PLAUSIBLE"\n                primary_structural_reason = "full de-zincation topology retained and guest-like Zn orbits"\n            else:\n                classification = "PLAUSIBLE_WITH_PARTIAL_DEZINCATION"\n                primary_structural_reason = "partial (<=50%) de-zincation topology retained"\n        if best_partial is not None:\n            primary_charge_reason = (\n                f"best partial {best_partial[\'state_id\']}: "\n                f"{best_partial[\'charge_balance_status\']}"\n            )\n        if classification is None:\n            classification = "HIGH_RECONSTRUCTION_RISK"\n        qa["classification_complete"] = True\n        for key in qa:\n            if not qa[key]:\n                qa["overall_phase21b_QA_pass"] = False\n        risk_flags = list(dict.fromkeys(risk_flags))\n\n        # ---- candidate topology row -----------------------------------------------------------\n        if graph.number_of_nodes() == 0:\n            framework_interpretation = "NO_GRAPH"\n        elif zn_articulation_fraction >= FRAMEWORK_ARTICULATION_MIN:\n            framework_interpretation = "ZN_BRIDGES_FRAMEWORK"\n        elif nonzn_stats["component_retention_fraction"] >= TOPO_RETENTION_MIN:\n            framework_interpretation = "NONZN_FRAMEWORK_RETAINED"\n        else:\n            framework_interpretation = "FRAMEWORK_FRAGMENTS_ON_ZN_REMOVAL"\n        topology_rows.append(\n            {\n                "material_id": material_id,\n                "formula": formula,\n                "graph_method": graph_method,\n                "periodic_graph_replication": PERIODIC_GRAPH_REPLICATION,\n                "periodic_graph_node_count": graph.number_of_nodes(),\n                "periodic_graph_edge_count": graph.number_of_edges(),\n                "pristine_node_count": graph.number_of_nodes(),\n                "pristine_edge_count": graph.number_of_edges(),\n                "pristine_component_count": len(list(nx.connected_components(graph))),\n                "post_full_removal_component_count": nonzn_stats["component_count"],\n                "total_Zn_nodes": total_zn_sites,\n                "nonZn_node_count": len(nonzn_site_indices),\n                "nonZn_component_count": nonzn_stats["component_count"],\n                "nonZn_largest_component_size": nonzn_stats["largest_component_size"],\n                # descriptive absolute metric (NOT the classification gate)\n                "nonZn_absolute_largest_component_fraction": nonzn_stats["absolute_largest_component_fraction"],\n                # pristine-relative metric used by the classification gate\n                "nonZn_component_retention_fraction": nonzn_stats["component_retention_fraction"],\n                "nonZn_isolated_node_count": nonzn_stats["isolated_nonZn_count"],\n                "nonZn_isolated_node_fraction": nonzn_stats["isolated_nonZn_fraction"],\n                "Zn_articulation_count": zn_articulation_count,\n                "Zn_articulation_fraction": zn_articulation_fraction,\n                "framework_connectivity_interpretation": framework_interpretation,\n            }\n        )\n\n        # ---- oxidation row ---------------------------------------------------------------------\n        full_required_e_per_cell = 2 * total_zn_sites\n        full_charge_status = charge_status_for_removed(\n            total_zn_sites, headroom_min_e_per_cell, headroom_max_e_per_cell,\n            n_oxi_solutions,\n        )\n        oxi_rows.append(\n            {\n                "material_id": material_id,\n                "formula_pretty": formula,\n                "fixed_oxidation_state_assumptions": json.dumps(FIXED_OXI_OVERRIDES, sort_keys=True),\n                "oxi_states_override_passed_to_guess": json.dumps(\n                    overrides_applied, sort_keys=True\n                ),\n                "redox_active_elements": ",".join(sorted(el.symbol for el in redox_elements)),\n                "number_of_oxidation_solutions": n_oxi_solutions,\n                "oxidation_solutions_json": json.dumps(\n                    [\n                        {str(k): v for k, v in sol.items()}\n                        for sol in oxi_solutions[:20]\n                    ]\n                ),\n                "cell_n_atoms_by_symbol_used_for_headroom": json.dumps(\n                    cell_n_atoms_by_symbol, sort_keys=True\n                ),\n                "headroom_per_solution_e_per_cell": json.dumps(headroom_per_solution_e_per_cell),\n                "rare_oxidation_fallback_used": bool(rare_fallback_used),\n                "full_dezincation_required_electrons_per_cell": full_required_e_per_cell,\n                "common_headroom_min_e_per_cell": headroom_min_e_per_cell,\n                "common_headroom_max_e_per_cell": headroom_max_e_per_cell,\n                "full_dezincation_charge_status": full_charge_status,\n                "oxidation_state_notes": (\n                    "RARE_OXIDATION_STATE_FALLBACK used for headroom"\n                    if rare_fallback_used\n                    else ""\n                ),\n            }\n        )\n\n        # ---- assessment row ----------------------------------------------------------------------\n        eligible_flag = classification in {\n            "STRUCTURALLY_PLAUSIBLE",\n            "PLAUSIBLE_WITH_PARTIAL_DEZINCATION",\n        }\n        assessment_rows.append(\n            {\n                "phase20_priority_order": priority,\n                "verification_rank": rec["verification_rank"],\n                "material_id": material_id,\n                "formula_pretty": formula,\n                "n_Zn_sites": total_zn_sites,\n                "n_inequivalent_Zn_orbits": n_inequivalent_zn,\n                "Zn_role_summary": f"guest={n_guest},framework={n_framework},ambiguous={n_ambiguous}",\n                "n_guest_like_orbits": n_guest,\n                "n_framework_like_orbits": n_framework,\n                "n_ambiguous_orbits": n_ambiguous,\n                "full_nonZn_component_retention_fraction": nonzn_stats["component_retention_fraction"],\n                "full_nonZn_component_count": nonzn_stats["component_count"],\n                "best_partial_removed_fraction": (\n                    best_partial["actual_removed_fraction"] if best_partial else None\n                ),\n                "best_partial_topology_pass": (\n                    bool(best_partial["topology_pass"]) if best_partial else None\n                ),\n                "best_partial_charge_status": (\n                    best_partial["charge_balance_status"] if best_partial else None\n                ),\n                "full_dezincation_topology_pass": (\n                    bool(full_state["topology_pass"]) if full_state else None\n                ),\n                "full_dezincation_charge_status": full_charge_status,\n                "oxidation_state_resolved": bool(n_oxi_solutions > 0),\n                "phase21b_classification": classification,\n                "primary_structural_reason": primary_structural_reason,\n                "primary_charge_reason": primary_charge_reason,\n                "main_risk_flags": ";".join(risk_flags) if risk_flags else "",\n                "phase21b_eligible_for_final_shortlist": eligible_flag,\n            }\n        )\n\n        qa.update(\n            {\n                "phase20_priority_order": priority,\n                "material_id": material_id,\n            }\n        )\n        qa_rows.append(qa)\n        log(f"  {material_id}: orbits={n_inequivalent_zn} "\n            f"(guest={n_guest},framework={n_framework},ambiguous={n_ambiguous}), "\n            f"nonZn retention={nonzn_stats[\'component_retention_fraction\']:.3f}, "\n            f"class={classification}")\n\n    # ---- hard QA: fractional selection implementation integrity ----------------------\n    # Every generated fractional vacancy state MUST have been selected by\n    # deterministic_farthest_selection (checked per candidate above). A failure\n    # here is an implementation integrity failure, not scientific uncertainty:\n    # record it and abort before any classification/shortlist output.\n    for qa_row in qa_rows:\n        if not bool(qa_row.get("fractional_selection_uses_farthest_helper_pass", False)):\n            return write_failures_and_abort(\n                [{\n                    "material_id": str(qa_row.get("material_id", "")),\n                    "failure_stage": "fractional_selection_implementation",\n                    "failure_message": (\n                        "fractional vacancy states generated without calling "\n                        "deterministic_farthest_selection"\n                    ),\n                }],\n                "fractional vacancy selection hard QA failed",\n            )\n\n    # ---- hard QA: topology fractions must lie in [0, 1] ------------------------------\n    # All three topology fractions are in [0, 1] by construction; any violation\n    # is an implementation failure.\n    fraction_qa_failures: list[dict] = []\n    for state in state_rows:\n        checks = [\n            ("absolute_largest_component_fraction",\n             state["absolute_largest_component_fraction"]),\n            ("component_retention_fraction", state["component_retention_fraction"]),\n            ("isolated_nonZn_fraction", state["isolated_nonZn_fraction"]),\n        ]\n        bad = []\n        for name, value in checks:\n            if not isinstance(value, (int, float)) or not (0.0 <= value <= 1.0):\n                bad.append(f"{name}={value}")\n        if bad:\n            fraction_qa_failures.append(\n                {\n                    "material_id": str(state.get("material_id", "")),\n                    "failure_stage": "topology_fraction_bounds",\n                    "failure_message": (\n                        f"state {state.get(\'state_id\', \'\')}: " + ", ".join(bad)\n                    ),\n                }\n            )\n    if fraction_qa_failures:\n        return write_failures_and_abort(\n            fraction_qa_failures,\n            "topology fraction bounds hard QA failed",\n        )\n\n    # ---- 4. final 3-5 shortlist (frozen tie-break = Phase 20 order only) ----------------------\n    assessment = pd.DataFrame(assessment_rows)\n    order_class = {\n        "STRUCTURALLY_PLAUSIBLE": 0,\n        "PLAUSIBLE_WITH_PARTIAL_DEZINCATION": 1,\n        "HIGH_RECONSTRUCTION_RISK": 2,\n        "UNRESOLVED": 3,\n    }\n    eligible = assessment[assessment["phase21b_eligible_for_final_shortlist"]].copy()\n    eligible["_class_order"] = eligible["phase21b_classification"].map(order_class)\n    eligible = eligible.sort_values(["_class_order", "phase20_priority_order"])\n    shortlist = eligible.head(5).reset_index(drop=True)\n    alternates = eligible.iloc[5:] if len(eligible) > 5 else eligible.iloc[0:0]\n\n    shortlist_rows = []\n    for i, (_, row) in enumerate(shortlist.iterrows(), start=1):\n        shortlist_rows.append(\n            {\n                "phase21b_structural_priority_order": i,\n                "phase20_priority_order": int(row["phase20_priority_order"]),\n                "verification_rank": int(row["verification_rank"]),\n                "material_id": row["material_id"],\n                "formula_pretty": row["formula_pretty"],\n                "phase21b_classification": row["phase21b_classification"],\n                "Zn_role_summary": row["Zn_role_summary"],\n                "best_partial_removed_fraction": row["best_partial_removed_fraction"],\n                "best_partial_charge_status": row["best_partial_charge_status"],\n                "full_dezincation_charge_status": row["full_dezincation_charge_status"],\n                "full_nonZn_component_retention_fraction": row["full_nonZn_component_retention_fraction"],\n                "primary_keep_reason": row["primary_structural_reason"],\n                "main_remaining_uncertainty": (\n                    "unrelaxed topology proxy; requires relaxation/DFT and experiment for confirmation"\n                ),\n                "recommended_next_validation": (\n                    "manual review of frozen structure + literature evidence; no ranking implied"\n                ),\n            }\n        )\n\n    deprioritized_rows = []\n    for _, row in assessment.iterrows():\n        classification = row["phase21b_classification"]\n        if classification in {"HIGH_RECONSTRUCTION_RISK", "UNRESOLVED"}:\n            deprioritized_rows.append(\n                {\n                    "material_id": row["material_id"],\n                    "formula": row["formula_pretty"],\n                    "classification": classification,\n                    "deprioritization_reason": row["primary_structural_reason"],\n                    "what_evidence_would_be_needed_to_reconsider": (\n                        "experimental evidence of reversible Zn extraction, or relaxed "\n                        "structure showing framework retention"\n                    ),\n                }\n            )\n    for _, row in alternates.iterrows():\n        deprioritized_rows.append(\n            {\n                "material_id": row["material_id"],\n                "formula": row["formula_pretty"],\n                "classification": row["phase21b_classification"],\n                "deprioritization_reason": "STRUCTURAL_ALTERNATE (outside the frozen top-5 cap)",\n                "what_evidence_would_be_needed_to_reconsider": (\n                    "re-review if higher-priority candidates fail later validation"\n                ),\n            }\n        )\n\n    # ---- 5. write outputs -----------------------------------------------------------------------\n    atomic_to_csv(pd.DataFrame(inventory_rows), OUT_ZN_INVENTORY)\n    atomic_to_csv(pd.DataFrame(topology_rows), OUT_TOPOLOGY)\n    atomic_to_csv(pd.DataFrame(state_rows), OUT_STATES)\n    atomic_to_csv(pd.DataFrame(oxi_rows), OUT_OXI)\n    atomic_to_csv(assessment, OUT_ASSESSMENT)\n    atomic_to_csv(pd.DataFrame(shortlist_rows), OUT_SHORTLIST)\n    atomic_to_csv(pd.DataFrame(deprioritized_rows), OUT_DEPRIORITIZED)\n    atomic_to_csv(pd.DataFrame(qa_rows), OUT_QA)\n\n    # ---- 6. figures ------------------------------------------------------------------------------\n\n\n\n\n    # ---- 7. methodology -----------------------------------------------------------------------------\n    versions = {\n        "python": sys.version.split()[0],\n        "pymatgen": package_version("pymatgen"),\n        "numpy": package_version("numpy"),\n        "pandas": package_version("pandas"),\n        "networkx": package_version("networkx"),\n    }\n    methodology_lines = []\n    methodology_lines.append("Phase 21B - De-zincation structure analysis methodology")\n    methodology_lines.append("=" * 70)\n    methodology_lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")\n    methodology_lines.append("")\n    methodology_lines.append("software versions (graph/CrystalNN results are version-sensitive):")\n    for name, version in versions.items():\n        methodology_lines.append(f"    {name}: {version}")\n    methodology_lines.append("")\n    methodology_lines.append("principles:")\n    methodology_lines.append("    1. All Phase21B analysis is offline.")\n    methodology_lines.append("    2. Structures are exactly the frozen Phase21A structures.")\n    methodology_lines.append("    3. No Materials Project API was called.")\n    methodology_lines.append("    4. No DFT or structural relaxation was performed.")\n    methodology_lines.append("    5. Bond topology is derived from the pristine CrystalNN graph.")\n    methodology_lines.append("    6. Removing Zn deletes nodes and associated pristine bonds only.")\n    methodology_lines.append("    7. No new bonds are introduced after Zn removal.")\n    methodology_lines.append("    Therefore the analysis measures retention of the original framework")\n    methodology_lines.append("    topology rather than hypothetical bond reconstruction in an unrelaxed")\n    methodology_lines.append("    vacancy structure.")\n    methodology_lines.append("    8. Vacancy structures are topology proxies only.")\n    methodology_lines.append("    9. Oxidation-state analysis is a composition-level chemical sanity check.")\n    methodology_lines.append("    10. Zn is assumed to leave as Zn2+, requiring removal of 2 e- per Zn.")\n    methodology_lines.append("    11. Common oxidation-state headroom is a heuristic,")\n    methodology_lines.append("        not a calculated redox energy.")\n    methodology_lines.append("    12. Anion redox / conversion / reconstruction are not explicitly modeled.")\n    methodology_lines.append("    13. ML capacity is not converted into Zn-removal stoichiometry.")\n    methodology_lines.append("    14. No weighted score is used.")\n    methodology_lines.append("    15. Phase20 order is used only as a tie-breaker after Phase21B structural gates.")\n    methodology_lines.append("    16. Frozen-input/provenance failures are CRITICAL: any SHA-256")\n    methodology_lines.append("        mismatch, missing JSON/CIF, manifest identity/order mismatch,")\n    methodology_lines.append("        JSON parse failure, num_sites mismatch, missing Zn, drift flag")\n    methodology_lines.append("        or overall QA flag failure is recorded to phase21b_failures.csv")\n    methodology_lines.append("        and the run aborts with exit code 1. These are never")\n    methodology_lines.append("        downgraded to UNRESOLVED.")\n    methodology_lines.append("    17. UNRESOLVED is reserved for post-provenance scientific")\n    methodology_lines.append("        analysis uncertainty only (disorder, mixed/partial Zn")\n    methodology_lines.append("        occupancy, symmetry failure after valid input, CrystalNN")\n    methodology_lines.append("        fallback, zero reliable oxidation-state solutions).")\n    methodology_lines.append("    18. Bond topology uses a 3x3x3 PERIODIC TORUS GRAPH built from the")\n    methodology_lines.append("        pristine CrystalNN StructureGraph with every jimage translation")\n    methodology_lines.append("        preserved (shift = to_jimage - from_jimage, wrapped modulo 3).")\n    methodology_lines.append("        It is a GRAPH REPRESENTATION ONLY - never a supercell, never a")\n    methodology_lines.append("        new candidate structure, never saved as a Phase21A structure.")\n    methodology_lines.append("    19. Removing a Zn site deletes ALL 27 of its periodic images;")\n    methodology_lines.append("        articulation status is evaluated per original site (torus graph")\n    methodology_lines.append("        is translation-invariant, so all 27 images share the status).")\n    methodology_lines.append("    20. All headroom and Zn-removal electron requirements are in")\n    methodology_lines.append("        ELECTRONS PER CRYSTALLOGRAPHIC CELL: headroom atom counts come")\n    methodology_lines.append("        from the full Phase21A cell composition, while the guessed")\n    methodology_lines.append("        oxidation states come from the reduced-composition solution.")\n    methodology_lines.append("    21. Redox-active headroom reservoirs are non-Zn TRANSITION METALS")\n    methodology_lines.append("        only (frozen definition); main-group elements are never")\n    methodology_lines.append("        auto-added as redox reservoirs.")\n    methodology_lines.append("    22. Zn orbits are mapped by equivalent-indices GROUP index (never")\n    methodology_lines.append("        by site index); incomplete orbit coverage or partially-covered")\n    methodology_lines.append("        Wyckoff groups are post-provenance scientific UNRESOLVED.")\n    methodology_lines.append("    23. CrystalNN fallback also triggers when CrystalNN succeeds but")\n    methodology_lines.append("        returns a degenerate graph (zero periodic edges); fallback")\n    methodology_lines.append("        graphs can never reach STRUCTURALLY_PLAUSIBLE.")\n    methodology_lines.append("    24. The topology gate uses the PRISTINE-RELATIVE metric")\n    methodology_lines.append("        component_retention_fraction: for each pristine connected")\n    methodology_lines.append("        component C, remaining_C = C minus removed nodes, and the")\n    methodology_lines.append("        fraction = sum(largest descendant of remaining_C) /")\n    methodology_lines.append("        sum(len(remaining_C)). Intrinsically 1D/2D or")\n    methodology_lines.append("        multi-component pristine crystals are NOT penalized; the")\n    methodology_lines.append("        absolute largest component fraction is descriptive only.")\n    methodology_lines.append("")\n    methodology_lines.append("frozen parameters:")\n    methodology_lines.append(f"    symprec={SYMPREC}, angle_tolerance={ANGLE_TOLERANCE}")\n    methodology_lines.append(f"    periodic_graph_replication = {PERIODIC_GRAPH_REPLICATION} "\n                             f"(3x3x3 torus, graph representation only)")\n    methodology_lines.append(f"    topology_pass: component_retention_fraction >= {TOPO_RETENTION_MIN} "\n                             f"and isolated_nonZn_fraction <= {TOPO_ISOLATED_MAX}")\n    methodology_lines.append("    topology fractions: component_retention_fraction (pristine-")\n    methodology_lines.append("        relative connectivity retention; THE classification metric)")\n    methodology_lines.append("        and absolute_largest_component_fraction (largest remaining")\n    methodology_lines.append("        component / remaining nodes; DESCRIPTIVE only - it would")\n    methodology_lines.append("        penalize pristine 1D/2D or multi-component crystals).")\n    methodology_lines.append("        isolated_nonZn_fraction = isolated remaining non-Zn /")\n    methodology_lines.append("        remaining non-Zn nodes. All fractions always in [0,1].")\n    methodology_lines.append(f"    GUEST_LIKE_HINT: no articulation, orbit-removal retention >= "\n                             f"{GUEST_ORBIT_RETENTION_MIN}, isolated <= {GUEST_ORBIT_ISOLATED_MAX}")\n    methodology_lines.append(f"    FRAMEWORK_LIKE_HINT: articulation >= {FRAMEWORK_ARTICULATION_MIN} "\n                             f"or orbit-removal retention < {FRAMEWORK_ORBIT_RETENTION_MAX} "\n                             f"or isolated > {FRAMEWORK_ORBIT_ISOLATED_MIN}")\n    methodology_lines.append(f"    partial-state cap (Step-2 gate): actual_removed_fraction <= {PARTIAL_STATE_MAX_FRACTION}")\n    methodology_lines.append("    fractional vacancies: 25/50/75% targets are ALL generated and saved")\n    methodology_lines.append("        when representable; target_count = nearest achievable integer")\n    methodology_lines.append("        Zn count (round half up, clamped to 1..total-1); the 75% state")\n    methodology_lines.append("        is excluded from the Step-2 partial gate only via the 0.50 cap.")\n    methodology_lines.append("    fractional vacancy selection: deterministic farthest-point /")\n    methodology_lines.append("        maximin rule via deterministic_farthest_selection - first")\n    methodology_lines.append("        vacancy = smallest Zn site index, each next vacancy maximizes")\n    methodology_lines.append("        its periodic minimum-image distance to the nearest selected")\n    methodology_lines.append("        vacancy (ties -> smaller site index); no supercells, no")\n    methodology_lines.append("        randomness; SYMMETRY_BROKEN_FRACTION_PROXY is an unrelaxed")\n    methodology_lines.append("        topology proxy only.")\n    methodology_lines.append(f"    fixed oxidation-state assumptions: {json.dumps(FIXED_OXI_OVERRIDES, sort_keys=True)}")\n    methodology_lines.append("    fixed oxidation states are passed INTO the pymatgen solver via")\n    methodology_lines.append("        oxi_states_override as dict[str, list[float]] (fixed states as")\n    methodology_lines.append("        single-element lists, e.g. {\'V\': [2, 3, 4, 5]}), with")\n    methodology_lines.append("        target_charge=0 and all_oxi_states=False, restricted to the")\n    methodology_lines.append("        elements present in each composition.")\n    methodology_lines.append("    charge headroom is computed PER oxidation solution and PER element")\n    methodology_lines.append("        (non-Zn transition metals only), in ELECTRONS PER CELL:")\n    methodology_lines.append("        cell_n_atoms * (max_allowed_state - guessed_state), positive")\n    methodology_lines.append("        contributions only; common_headroom_min/max_e_per_cell =")\n    methodology_lines.append("        min/max over solutions. Solutions are never averaged and")\n    methodology_lines.append("        elements are never mixed across solutions.")\n    methodology_lines.append("        Element.oxidation_states is used only when")\n    methodology_lines.append("        Element.common_oxidation_states is empty")\n    methodology_lines.append("        (rare_oxidation_fallback_used = True).")\n    methodology_lines.append("")\n    methodology_lines.append("post-provenance scientific uncertainty (UNRESOLVED, descriptive results only):")\n    methodology_lines.append("    disorder, mixed/partial Zn occupancy, symmetry analysis failure,")\n    methodology_lines.append("    CrystalNN graph fallback or degenerate zero-edge CrystalNN graph,")\n    methodology_lines.append("    incomplete/partial-Wyckoff Zn orbit mapping, zero oxidation-state")\n    methodology_lines.append("    solutions. (Applies ONLY after all frozen-input provenance checks")\n    methodology_lines.append("    pass.)")\n    methodology_lines.append("")\n    OUT_METHODOLOGY.write_text("\\n".join(methodology_lines), encoding="utf-8")\n    log(f"Saved methodology -> {OUT_METHODOLOGY}")\n\n    # ---- 8. summary -----------------------------------------------------------------------------------\n    n_sp = int((assessment["phase21b_classification"] == "STRUCTURALLY_PLAUSIBLE").sum())\n    n_ppd = int((assessment["phase21b_classification"] == "PLAUSIBLE_WITH_PARTIAL_DEZINCATION").sum())\n    n_hrr = int((assessment["phase21b_classification"] == "HIGH_RECONSTRUCTION_RISK").sum())\n    n_un = int((assessment["phase21b_classification"] == "UNRESOLVED").sum())\n\n    summary_lines = []\n    summary_lines.append("Phase 21B - De-zincation structure analysis summary")\n    summary_lines.append("=" * 70)\n    summary_lines.append(f"generated (UTC): {datetime.now(timezone.utc).isoformat()}")\n    summary_lines.append("")\n    summary_lines.append("purpose: offline structure-level de-zincation feasibility analysis of")\n    summary_lines.append("the 13 frozen Phase 21A structures (topology + charge-balance proxies).")\n    summary_lines.append("")\n    summary_lines.append("input integrity: all 13 frozen Phase21A files must pass SHA-256")\n    summary_lines.append("re-verification before analysis; any provenance failure aborts the")\n    summary_lines.append("run (phase21b_failures.csv) instead of producing classifications.")\n    summary_lines.append("")\n    summary_lines.append("software versions:")\n    for name, version in versions.items():\n        summary_lines.append(f"    {name}: {version}")\n    summary_lines.append("")\n    summary_lines.append("per-candidate detail:")\n    for _, row in assessment.iterrows():\n        summary_lines.append(\n            f"  [{int(row[\'phase20_priority_order\'])}] {row[\'material_id\']} {row[\'formula_pretty\']}: "\n            f"Zn_sites={int(row[\'n_Zn_sites\'])}, orbits={int(row[\'n_inequivalent_Zn_orbits\'])}, "\n            f"{row[\'Zn_role_summary\']}, nonZn_retention_full={row[\'full_nonZn_component_retention_fraction\']:.3f}, "\n            f"best_partial={row[\'best_partial_removed_fraction\']} "\n            f"(topo={row[\'best_partial_topology_pass\']}, charge={row[\'best_partial_charge_status\']}), "\n            f"full_charge={row[\'full_dezincation_charge_status\']} -> "\n            f"{row[\'phase21b_classification\']} | {row[\'primary_structural_reason\']}"\n        )\n    summary_lines.append("")\n    summary_lines.append(f"STRUCTURALLY_PLAUSIBLE: {n_sp}")\n    summary_lines.append(f"PLAUSIBLE_WITH_PARTIAL_DEZINCATION: {n_ppd}")\n    summary_lines.append(f"HIGH_RECONSTRUCTION_RISK: {n_hrr}")\n    summary_lines.append(f"UNRESOLVED: {n_un}")\n    summary_lines.append(f"final 3-5 shortlist size: {len(shortlist_rows)}")\n    for row in shortlist_rows:\n        summary_lines.append(\n            f"    {row[\'phase21b_structural_priority_order\']}. {row[\'material_id\']} "\n            f"{row[\'formula_pretty\']} ({row[\'phase21b_classification\']})"\n        )\n    summary_lines.append("")\n    summary_lines.append("deprioritized candidates:")\n    for row in deprioritized_rows:\n        summary_lines.append(\n            f"    {row[\'material_id\']} {row[\'formula\']} "\n            f"({row[\'classification\']}): {row[\'deprioritization_reason\']}"\n        )\n    summary_lines.append("")\n    summary_lines.append("interpretation boundaries:")\n    summary_lines.append("    STRUCTURALLY_PLAUSIBLE does NOT mean an experimentally")\n    summary_lines.append("    reversible Zn cathode.")\n    summary_lines.append("    PLAUSIBLE_WITH_PARTIAL_DEZINCATION does NOT mean partial Zn")\n    summary_lines.append("    extraction has been experimentally observed.")\n    summary_lines.append("    HIGH_RECONSTRUCTION_RISK does NOT mean the material cannot store Zn.")\n    summary_lines.append("    UNRESOLVED does NOT mean poor material performance.")\n    summary_lines.append("    UNRESOLVED is post-provenance scientific uncertainty only; frozen")\n    summary_lines.append("    input/provenance failures abort the run before classification.")\n    summary_lines.append("    All de-zincated structures are UNRELAXED TOPOLOGY /")\n    summary_lines.append("    CHARGE-BALANCE PROXIES; they are never called stable or")\n    summary_lines.append("    experimentally accessible charged phases.")\n    summary_lines.append("")\n    OUT_SUMMARY.write_text("\\n".join(summary_lines), encoding="utf-8")\n    log(f"Saved summary -> {OUT_SUMMARY}")\n\n    # ---- 9. console --------------------------------------------------------------------------------------\n    elapsed = time.perf_counter() - overall_started\n    print("")\n    print("Phase 21B de-zincation structure analysis completed.")\n    print(f"STRUCTURALLY_PLAUSIBLE: {n_sp}")\n    print(f"PLAUSIBLE_WITH_PARTIAL_DEZINCATION: {n_ppd}")\n    print(f"HIGH_RECONSTRUCTION_RISK: {n_hrr}")\n    print(f"UNRESOLVED: {n_un}")\n    print(f"final 3-5 shortlist size: {len(shortlist_rows)}")\n    for row in shortlist_rows:\n        print(f"  {row[\'phase21b_structural_priority_order\']}. {row[\'material_id\']} "\n              f"{row[\'formula_pretty\']} ({row[\'phase21b_classification\']})")\n    print(f"outputs: {OUT_DIR}")\n    print(f"elapsed: {elapsed:.1f} s")\n    return 0\n\n\ndef _combinations(items, r):\n    import itertools\n\n    return list(itertools.combinations(items, r))\n\n\n'


# ===== INLINED validation_sections.py; no runtime module dependency =====
def _baseline_primary_reference_checks(base, archive_root):
    """Compare 18 sample-derived baseline rows with the identified archive CSV.

    R2 uses the retained baseline figure's three-decimal annotation precision.
    RMSE/MAE use original Phase8 sig6 output, including omitted trailing zeros
    in CSV literals. No target/model-specific tuned-CatBoost precision is used.
    """
    import csv
    import hashlib
    import json
    import math
    from pathlib import Path
    root=Path(archive_root).resolve()
    mapping=root/'03_Code/config/data_map.json'
    data_map=json.loads(mapping.read_text(encoding='utf-8'))
    relative=data_map['input/baseline_metrics']
    path=(root/relative).resolve()
    if not path.is_relative_to(root) or path==root:
        raise ValueError('Baseline reference path escapes the frozen archive')
    raw=path.read_bytes();reference_sha=hashlib.sha256(raw).hexdigest()
    with path.open(encoding='utf-8-sig',newline='') as handle:
        references=list(csv.DictReader(handle))
    models={'Ridge','SVR','DecisionTree','RandomForest','ExtraTrees','GradientBoosting','XGBoost','CatBoost','LightGBM'}
    expected={(target,model) for target in ['average_voltage','capacity_grav'] for model in models}
    reference_keys=[(row['target'],row['model']) for row in references]
    actual_keys=[(str(row.target),str(row.model)) for row in base.itertuples(index=False)]
    if len(reference_keys)!=18 or len(set(reference_keys))!=18 or set(reference_keys)!=expected:
        raise ValueError('Frozen baseline metric reference lacks the unique 9-model x 2-target grid')
    if len(actual_keys)!=18 or len(set(actual_keys))!=18 or set(actual_keys)!=expected:
        raise ValueError('Sample-derived baseline metrics lack the unique 9-model x 2-target grid')
    lookup={(str(row.target),str(row.model)):row for row in base.itertuples(index=False)}
    checks=[]
    for source_row,row in enumerate(references,start=2):
        actual=lookup[(row['target'],row['model'])]
        for metric in ['R2','RMSE','MAE']:
            value=float(getattr(actual,metric));reference=float(row[metric])
            if not math.isfinite(value) or not math.isfinite(reference):
                raise ValueError('Nonfinite baseline metric comparison')
            format_spec='.3f' if metric=='R2' else '.6g'
            shown_actual=format(value,format_spec);shown_reference=format(reference,format_spec)
            policy='BASELINE_FIGURE_3_DECIMAL_PLACES' if metric=='R2' else 'ORIGINAL_PHASE8_CSV_6_SIGNIFICANT_DIGITS'
            checks.append(dict(item='baseline_primary_'+row['target']+'_'+row['model']+'_'+metric,
                actual=value,expected=reference,comparison_precision=policy,
                status='PASS' if shown_actual==shown_reference else 'DIFFERENT',
                evidence='IDENTIFIED_ARCHIVE_BASELINE_METRIC_REFERENCE',
                note='Sample predictions recomputed; original baseline values remain comparison targets. R2 figure annotation is .3f; original Phase8 compute_metrics uses sig6, and CSV may omit trailing zeros.',
                reference_relative_path=relative,reference_sha256=reference_sha,reference_csv_row_1based=source_row,
                reference_csv_literal=row[metric],actual_at_reference_precision=shown_actual,
                expected_at_reference_precision=shown_reference,
                phase8_metric_formatting_source='03_Code/Model_Training/08_benchmark_core_models.py::compute_metrics/sig6',
                phase8_original_source_sha256=globals().get('_SCIENCE_STAGE_META',{}).get(8,{}).get('original_source_sha256','NOT_LOADED'),
                R2_display_precision_source='03_Code/plotting/render_figures.py::model_metrics (.3f)'))
    if len(checks)!=54:raise AssertionError('Baseline reference check coverage must be 54')
    return checks


def validate_paper_results(science_root, archive_root, output, mode):
    """Published numbers are comparison targets only, never training objectives."""
    import numpy as np
    import pandas as pd
    s=Path(science_root); output=Path(output); output.mkdir(parents=True,exist_ok=True)
    checks=[]; numerical=[]
    def read(rel):return pd.read_csv(s/rel,encoding='utf-8-sig',float_precision='round_trip',low_memory=False)
    def check(name,actual,expected,decimals=None,evidence='COMPUTED',note=''):
        if decimals is None:passed=actual==expected;policy='EXACT'
        else:passed=round(float(actual),decimals)==round(float(expected),decimals);policy=f'PUBLISHED_{decimals}_DECIMAL_PLACES'
        checks.append(dict(item=name,actual=actual,expected=expected,comparison_precision=policy,
                           status='PASS' if passed else 'DIFFERENT',evidence=evidence,note=note))
    all_data=read('02_Datasets/Features/all_battery_candidate_compatible_features.csv')
    zinc=read('02_Datasets/Features/zinc_battery_candidate_compatible_features.csv')
    cand=read('02_Datasets/Features/zinc_candidates_candidate_compatible_features.csv')
    core=read('02_Datasets/Features/Feature_Sets/core_numeric_features.csv').feature.tolist()
    check('modeling_records',len(all_data),6847);check('Zn_records',len(zinc),434)
    check('non_Zn_records',int(all_data.working_ion.ne('Zn').sum()),6413)
