    check('strict_Zn_test_records',len(strict_test),434)
    check('strict_framework_overlap',len(set(strict_train.group_framework_formula)&set(strict_test.group_framework_formula)),0)
    znfold=read('02_Datasets/Processed/Splits/zn_group_cv_folds.csv')
    check('Zn_CV_frameworks_crossing_folds',int(znfold.groupby('group_framework_formula').cv_fold.nunique().gt(1).sum()),0)
