    truth=all_data.set_index('record_uid')
    def prediction_metrics(rel,grouping,ids=None):
        d=read(rel);out=[]
        for key,g in d.groupby(grouping,sort=False):
            key=(key,) if not isinstance(key,tuple) else key
            labels=dict(zip(grouping,key)); target=labels['target']; yt=g.y_true.to_numpy(float);yp=g.y_pred.to_numpy(float)
            keyname='/'.join(map(str,key))
            check(rel+'/'+keyname+'/unique_ids',bool(g.record_uid.is_unique),True)
            if ids is not None:check(rel+'/'+keyname+'/complete_record_identity',set(g.record_uid)==ids,True)
            matched=truth.loc[g.record_uid,target].to_numpy(float)
            check(rel+'/'+keyname+'/true_target_identity',bool(np.array_equal(yt,matched)),True)
            residual=yt-yp
            row=dict(**labels,n=len(g),R2=float(1-np.sum(residual**2)/np.sum((yt-yt.mean())**2)),
                     RMSE=float(np.sqrt(np.mean(residual**2))),MAE=float(np.mean(np.abs(residual))),
                     source=rel,result_kind='ARCHIVED_MODEL_PREDICTION' if mode=='reproduce' else 'NEW_MODEL_PREDICTION')
            out.append(row);numerical.append(row)
        return pd.DataFrame(out)
    base=prediction_metrics('05_Results/Predictions/Phase8_Benchmark/primary_group_test_predictions.csv',['target','model'],set(test.record_uid))
    check('baseline_model_target_groups',len(base),18)
